INSERT INTO `axioms` (`axiom_id`, `axiom_number`, `section_id`, `title`, `axiom_text`, `formal_latex`, `word_latex`, `motivation`, `independence_note`, `consistency_note`, `operationalization_note`, `source_assumption_id`, `status`, `created_revision_id`) VALUES
(1, 'A1', 30, 'Funktionale Unterscheidbarkeit', 'Innerhalb eines nichtleeren funktionalen Trägerbereichs existiert wenigstens ein Paar funktionaler Gehalte, das in mindestens einem funktionalen Kontext unterschiedliche Wirksamkeiten hervorbringt.', '\\mathcal{F}\\neq\\varnothing,\\qquad \\exists f_i,f_j\\in\\mathcal{F}\\;\\exists c\\in\\mathcal{C}:\\omega_F(f_i,c)\\neq\\omega_F(f_j,c)', '\\mathcal{F}\\neq\\varnothing,\\qquad \\exists f_i,f_j\\in\\mathcal{F}\\;\\exists c\\in\\mathcal{C}:\\omega_F(f_i,c)\\neq\\omega_F(f_j,c)', 'Axiom A1 setzt die minimale Möglichkeit funktionaler Nichtidentität und schließt absolute funktionale Unterschiedslosigkeit als alleinigen Ausgangspunkt des FRZK aus.', 'Axiom A1 wird als erste Grundsetzung nicht aus anderen FRZK-Axiomen abgeleitet.', 'Die Setzung ist mit den in 3.3.1 eingeführten Träger-, Kontext- und Wirksamkeitsbegriffen vereinbar. Abschnitt 3.3.9.3 zeigt die gemeinsame Erfüllbarkeit von A1 bis A7 durch ein konstruiertes funktionales Minimalmodell.', 'Eine spätere Operationalisierung kann über kontextbezogene Differenzindikatoren oder Differenzmaße erfolgen.', NULL, 'accepted', 28),
(2, 'A2', 31, 'Funktionale Relationierbarkeit', 'Zwischen funktional unterscheidbaren Gehalten können funktionale Relationen entstehen.', '\\delta_F(f_i,f_j)=1\\;\\Longrightarrow\\;\\Diamond\\bigl((f_i,f_j)\\in\\mathcal{R}_F\\bigr)', '\\delta_F(f_i,f_j)=1\\;\\Longrightarrow\\;\\Diamond\\bigl((f_i,f_j)\\in\\mathcal{R}_F\\bigr)', 'Funktionale Differenz allein erzeugt noch keine Organisation. Erst die Möglichkeit einer Relation lässt funktionale Gehalte zu einer gemeinsamen Struktur werden.', 'Axiom A2 setzt Relationierbarkeit als Möglichkeit und wird nicht aus Axiom A1 abgeleitet. Axiom A1 liefert lediglich die vorausgesetzte funktionale Unterscheidbarkeit.', 'Die Setzung ist mit Axiom A1 vereinbar, weil nicht jede funktionale Differenz automatisch eine tatsächlich bestehende Relation erzeugt. Abschnitt 3.3.9.3 zeigt die gemeinsame Erfüllbarkeit von A1 bis A7 durch ein konstruiertes funktionales Minimalmodell.', 'Operationalisierbar über binäre Kopplungsindikatoren rho_F und spätere gewichtete Kopplungsmaße kappa_F.', NULL, 'accepted', 29),
(3, 'A3', 32, 'Funktionale Transformierbarkeit', 'Funktionale Gehalte und funktionale Relationen können durch funktionale Operationen in andere funktionale Gehalte oder Relationen überführt werden.', '\\exists O_F\\in\\mathcal{O}_F:\\operatorname{dom}(O_F)\\subseteq\\mathcal{F}\\cup\\mathcal{R}_F', '\\exists O_F\\in\\mathcal{O}_F:\\operatorname{dom}(O_F)\\subseteq\\mathcal{F}\\cup\\mathcal{R}_F', 'Funktionale Relationierbarkeit erzeugt zunächst nur statische Struktur. Entwicklung, Anpassung und Auflösung erfordern die grundsätzliche Möglichkeit funktionaler Transformation.', 'Axiom A3 wird nicht aus Axiom A2 abgeleitet. Axiom A2 stellt lediglich die relationale Struktur bereit, auf die Transformationen wirken können.', 'Das Axiom ist mit A1 und A2 vereinbar, weil Transformationen weder global anwendbar noch eindeutig, umkehrbar, linear oder deterministisch sein müssen. Abschnitt 3.3.9.3 zeigt die gemeinsame Erfüllbarkeit von A1 bis A7 durch ein konstruiertes funktionales Minimalmodell.', 'Operationalisierung über funktionale Operatoren, Definitions- und Bildbereiche, Kompositionen und Zustandsfolgen.', NULL, 'accepted', 30),
(4, 'A4', 33, 'Funktionale Kompatibilität', 'Eine Folge funktionaler Transformationen darf die funktionale Rekonstruierbarkeit der gemeinsamen Organisation nicht vollständig aufheben.', '\\exists\\Psi:\\mathcal{S}^{\\prime}\\rightarrow\\mathcal{S}\\quad\\text{mit}\\quad\\Psi\\circ O_F\\neq\\varnothing', '\\exists\\Psi:\\mathcal{S}^{\\prime}\\rightarrow\\mathcal{S}\\quad\\text{mit}\\quad\\Psi\\circ O_F\\neq\\varnothing', 'Relationierbarkeit und Transformierbarkeit erklären noch nicht, weshalb eine Organisation über Veränderungen hinweg rekonstruierbar bleibt.', 'Axiom A4 wird nicht aus Axiom A3 abgeleitet; A3 begründet nur die Möglichkeit von Transformationen.', 'A4 ist mit A1 bis A3 vereinbar, weil weder Identität noch vollständige Invertierbarkeit gefordert werden. Abschnitt 3.3.9.3 zeigt die gemeinsame Erfüllbarkeit von A1 bis A7 durch ein konstruiertes funktionales Minimalmodell.', 'Operationalisierung über kompatible Operationen, Rekonstruktionsabbildungen, K_F und kappa_C.', NULL, 'accepted', 31),
(10, 'A5', 39, 'Funktionale Kohärenz', 'Eine funktionale Organisation besteht genau dann fort, wenn ihre unterscheidbaren Gehalte, Relationen und Transformationen einen hinreichenden gemeinsamen funktionalen Zusammenhang bilden.', 'C_F(\\mathcal{S})\\geq C_{\\mathrm{krit}}', 'C_F(\\mathcal{S})\\geq C_{\\mathrm{krit}}', 'Kompatibilität allein erklärt noch nicht, weshalb funktionale Organisationen über Transformationsfolgen hinweg stabil bleiben. Axiom A5 führt daher einen messbaren gemeinsamen funktionalen Zusammenhang als Fortbestandsbedingung ein.', 'Axiom A5 ist nicht aus Axiom A4 ableitbar. Axiom A4 sichert Rekonstruierbarkeit, aber nicht den Grad des inneren funktionalen Zusammenhangs.', 'Das Axiom ist mit A1 bis A4 vereinbar, weil Kohärenz weder Identität noch Unveränderlichkeit verlangt. Lokale Veränderungen und begrenzte Kohärenzverluste bleiben zulässig. Abschnitt 3.3.9.3 zeigt die gemeinsame Erfüllbarkeit von A1 bis A7 durch ein konstruiertes funktionales Minimalmodell.', 'Operationalisierung über die Kohärenzabbildung C_F, lokale Teilkohärenzen, funktionale Gewichte, relationale Dichte, Kohärenzänderungen und den kritischen Kohärenzwert C_krit.', NULL, 'accepted', 37),
(11, 'A6', 40, 'Funktionale Zustandsbildung', 'Jede hinreichend kohärente funktionale Organisation kann mindestens einen bestimmten funktionalen Zustand ausbilden.', 'C_F(\\mathcal{S})\\geq C_{\\mathrm{krit}}\\Longrightarrow\\exists z_F\\in\\mathcal{Z}_F', 'C_F(\\mathcal{S})\\geq C_{\\mathrm{krit}}\\Longrightarrow\\exists z_F\\in\\mathcal{Z}_F', 'Die Kohärenz einer Organisation muss sich in mindestens einer konkret bestimmbaren funktionalen Konfiguration realisieren können.', 'Axiom A6 ist nicht mit Axiom A5 identisch. Axiom A5 bestimmt die Kohärenzbedingung; Axiom A6 fordert die Ausbildung mindestens eines konkreten Zustands.', 'Axiom A6 ist mit A1 bis A5 vereinbar und setzt weder Eindeutigkeit noch Determinismus der Zustandsbildung voraus. Abschnitt 3.3.9.3 zeigt die gemeinsame Erfüllbarkeit von A1 bis A7 durch ein konstruiertes funktionales Minimalmodell.', 'Operationalisierung über Zustandsmenge, Zustandsraum, Zulässigkeitsfunktion, Zustandsbildungsfunktion, Wahrscheinlichkeitsverteilung und tragfähige Zustände.', NULL, 'accepted', 38),
(12, 'A7', 41, 'Funktionale Zustandsübergänge', 'Ein funktionaler Zustand kann genau dann in einen anderen funktionalen Zustand übergehen, wenn mindestens eine zulässige funktionale Operation auf den Ausgangszustand wirkt und der daraus hervorgehende Folgezustand dem funktionalen Zustandsraum der Organisation angehört.', 'z_F^{(i)}\\in\\Omega_F(\\mathcal{S})\\land O_{F,k}\\in\\mathcal{O}_F\\land T_F\\left(z_F^{(i)},O_{F,k}\\right)\\in\\Omega_F(\\mathcal{S})', 'z_F^{(i)}\\in\\Omega_F(\\mathcal{S})\\land O_{F,k}\\in\\mathcal{O}_F\\land T_F\\left(z_F^{(i)},O_{F,k}\\right)\\in\\Omega_F(\\mathcal{S})', 'Axiom A7 erweitert die durch Axiom A6 eingeführte Zustandsbildung um die formale Möglichkeit dynamischer Veränderungen zwischen zulässigen funktionalen Zuständen.', 'Axiom A7 ist nicht aus der bloßen Existenz funktionaler Zustände ableitbar. Axiom A6 sichert Zustandsbildung; Axiom A7 setzt zusätzlich die Möglichkeit operationsvermittelter Übergänge.', 'Axiom A7 ist mit A1 bis A6 vereinbar. Es verlangt weder vollständige Reversibilität noch Kohärenzsteigerung, sondern lediglich die funktionale Zulässigkeit von Ausgangszustand, Operation und Folgezustand. Abschnitt 3.3.9.3 zeigt die gemeinsame Erfüllbarkeit von A1 bis A7 durch ein konstruiertes funktionales Minimalmodell.', 'Operationalisierung über T_F, die Übergangsmenge T_F, die Zulässigkeitsfunktion Lambda_F, Kohärenzänderungen, Übergangspfade sowie Reversibilität und Irreversibilität.', NULL, 'accepted', 39);
INSERT INTO `axiom_dependencies` (`axiom_dependency_id`, `axiom_id`, `depends_on_axiom_id`, `dependency_type`, `note`) VALUES
(1, 3, 2, 'extends', 'Axiom A3 erweitert die durch Axiom A2 eröffnete relationale Struktur um Transformierbarkeit.'),
(2, 4, 3, 'extends', 'Axiom A4 erweitert A3 um funktionale Rekonstruierbarkeit.'),
(8, 10, 4, 'extends', 'Axiom A5 erweitert funktionale Rekonstruierbarkeit um einen hinreichenden Grad gemeinsamen funktionalen Zusammenhangs.'),
(9, 11, 10, 'extends', 'Axiom A6 erweitert die Kohärenzbedingung um die Möglichkeit konkreter funktionaler Zustandsbildung.'),
(10, 12, 11, 'extends', 'Axiom A7 erweitert die durch Axiom A6 eingeführte Zustandsbildung um operationsvermittelte Übergänge zwischen funktionalen Zuständen.');
INSERT INTO `corollaries` (`corollary_id`, `corollary_number`, `section_id`, `title`, `statement_text`, `statement_latex`, `word_latex`, `parent_theorem_id`, `parent_lemma_id`, `provenance`, `source_id`, `validation_status`, `created_revision_id`) VALUES
(1, '3.4.1', 52, 'Minimalität der Zustandsdarstellung', 'Eine Darstellung, die eine der Komponenten funktionaler Gehalt, funktionale Relation oder funktionale Operation nicht berücksichtigt, ist im Allgemeinen nicht hinreichend, um sämtliche funktionalen Zustände eindeutig zu unterscheiden.', NULL, NULL, 37, NULL, 'original', NULL, 'checked', 49),
(2, '3.4.2', 55, 'Eindeutige Klassenzugehörigkeit', 'Für jedes z_F aus Omega_F(S) existiert bezüglich eines festgelegten Kriteriums kappa_F genau eine funktionale Zustandsklasse [z_F]_{kappa_F}.', 'forall z_FinOmega_F(mathcal{S});exists!,[z_F]_{kappa_F}', 'forall z_FinOmega_F(mathcal{S});exists!,[z_F]_{kappa_F}', 38, NULL, 'original', NULL, 'checked', 52),
(3, '3.4.3', 57, 'Unzureichendheit der bloßen Zustandsmenge', 'Für eine Zustandsmenge mit mindestens zwei Elementen ist die Zustandsmenge allein nicht hinreichend, um funktionale Organisation eindeutig zu beschreiben.', '\\left|\\Omega_F(\\mathcal{S})\\right|\\geq 2\\Longrightarrow\\Omega_F(\\mathcal{S})\\text{ allein ist nicht hinreichend}', '\\left|\\Omega_F(\\mathcal{S})\\right|\\geq 2\\Longrightarrow\\Omega_F(\\mathcal{S})\\text{ allein ist nicht hinreichend}', 39, NULL, 'original', NULL, 'checked', 54),
(4, '3.4.4', 58, 'Abgeschlossenheit funktionaler Transformationen unter Komposition', 'Die Komposition zweier funktionaler Transformationen derselben Zustandsmenge ist wiederum eine funktionale Transformation.', 'T_F^{(1)},T_F^{(2)}:\\Omega_F(\\mathcal{S})\\to\\Omega_F(\\mathcal{S})\\Longrightarrow T_F^{(2)}\\circ T_F^{(1)}:\\Omega_F(\\mathcal{S})\\to\\Omega_F(\\mathcal{S})', 'T_F^{(1)},T_F^{(2)}:\\Omega_F(\\mathcal{S})\\to\\Omega_F(\\mathcal{S})\\Longrightarrow T_F^{(2)}\\circ T_F^{(1)}:\\Omega_F(\\mathcal{S})\\to\\Omega_F(\\mathcal{S})', 40, NULL, 'original', NULL, 'checked', 55),
(5, '3.4.5', 59, 'Nichtinvertierbarkeit informationsverdichtender Operatoren', 'Ein funktionaler Operator, der mindestens zwei unterschiedliche funktionale Zustände auf denselben Zielzustand abbildet, ist nicht invertierbar.', 'z_F^{(i)}\\neq z_F^{(j)}\\land O_F(z_F^{(i)})=O_F(z_F^{(j)})\\Longrightarrow O_F\\text{ nicht invertierbar}', 'z_F^{(i)}\\neq z_F^{(j)}\\land O_F(z_F^{(i)})=O_F(z_F^{(j)})\\Longrightarrow O_F\\text{ nicht invertierbar}', 41, NULL, 'original', NULL, 'checked', 56),
(6, '3.4.6', 59, 'Gruppe der invertierbaren funktionalen Operatoren', 'Die invertierbaren Elemente des funktionalen Operatorraums bilden bezüglich der Komposition eine Gruppe.', '\\left(\\mathcal{O}_F^{\\times}(\\mathcal{S}),\\circ,\\operatorname{id}_{\\Omega_F}\\right)\\text{ ist eine Gruppe}', '\\left(\\mathcal{O}_F^{\\times}(\\mathcal{S}),\\circ,\\operatorname{id}_{\\Omega_F}\\right)\\text{ ist eine Gruppe}', 42, NULL, 'original', NULL, 'checked', 56),
(7, '3.4.7', 60, 'Nichtbestimmtheit ohne vollständige Operatorfolge', 'Ist nur der Anfangszustand bekannt, nicht aber die vollständige Operatorfolge, so ist ein späterer Zustand im Allgemeinen nicht eindeutig bestimmt.', '\\Phi_F^{[n]}\\neq\\widetilde{\\Phi}_F^{[n]}\\Longrightarrow\\Phi_F^{[n]}(z_F^{(0)})\\neq\\widetilde{\\Phi}_F^{[n]}(z_F^{(0)})', '\\Phi_F^{[n]}\\neq\\widetilde{\\Phi}_F^{[n]}\\Longrightarrow\\Phi_F^{[n]}(z_F^{(0)})\\neq\\widetilde{\\Phi}_F^{[n]}(z_F^{(0)})', 43, NULL, 'original', NULL, 'checked', 57),
(8, '3.4.8', 60, 'Übergangsordnung erzeugt noch keine vollständige Zeitstruktur', 'Die funktionale Übergangsordnung bestimmt innerhalb eines Entwicklungspfads ein Vorher und Nachher, aber noch keine Dauer, Geschwindigkeit oder physikalische Zeit.', 'z_F^{(i)}\\prec_F z_F^{(j)}\\Longrightarrow\\operatorname{Reihenfolge},\\quad\\text{nicht notwendig Dauer}', 'z_F^{(i)}\\prec_F z_F^{(j)}\\Longrightarrow\\operatorname{Reihenfolge},\\quad\\text{nicht notwendig Dauer}', 44, NULL, 'original', NULL, 'checked', 57),
(9, 'Korollar 3.4.5', 59, 'Eindeutigkeit des Gesamtoperators bei fester Reihenfolge', 'Jede endliche, fest geordnete Folge funktionaler Operatoren bestimmt genau einen Gesamtoperator.', 'O_F^{\\ast}=O_{F,n}\\circ O_{F,n-1}\\circ\\cdots\\circ O_{F,1}', 'O_F^{\\ast}=O_{F,n}\\circ O_{F,n-1}\\circ\\cdots\\circ O_{F,1}', 45, NULL, 'original', NULL, 'checked', 61),
(10, 'Korollar 3.4.6', 59, 'Gruppenstruktur der invertierbaren Operatoren', 'Die Menge der invertierbaren funktionalen Operatoren bildet bezüglich der Komposition eine Gruppe.', '(\\mathcal G_F(\\mathcal S),\\circ,I_F)', '(\\mathcal G_F(\\mathcal S),\\circ,I_F)', 46, NULL, 'adapted', 31, 'checked', 61),
(11, 'Korollar 3.4.7', 60, 'Nichtbestimmtheit ohne vollständige Operatorfolge', 'Aus einem Ausgangszustand allein folgt im Allgemeinen keine eindeutige funktionale Entwicklung.', 'O_{F,1}(z_F^{(0)})\\neq O_{F,2}(z_F^{(0)})', 'O_{F,1}(z_F^{(0)})\\neq O_{F,2}(z_F^{(0)})', 47, NULL, 'original', NULL, 'checked', 62),
(12, 'Korollar 3.4.8', 60, 'Übergangsordnung erzeugt noch keine vollständige Zeitstruktur', 'Die funktionale Übergangsordnung bestimmt eine Reihenfolge von Zuständen, aber weder Dauer noch Geschwindigkeit oder gleichmäßige Abstände.', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'z_F^{(i)}\\prec_F z_F^{(j)}', 48, NULL, 'original', NULL, 'checked', 62),
(13, 'Korollar 3.4.9', 61, 'Kohärenz des Gesamtoperators', 'Der Gesamtoperator jedes funktional kohärenten Entwicklungspfads ist kohärenzerhaltend.', 'O_F^{[n]}=O_{F,n}circcdotscirc O_{F,1}inmathcal O_F^{K}(mathcal S)', 'O_F^{[n]}=O_{F,n}circcdotscirc O_{F,1}inmathcal O_F^{K}(mathcal S)', 50, NULL, 'original', NULL, 'checked', 63),
(14, 'Korollar 3.4.10', 62, 'Raumstruktur ohne vorausgesetzte Geometrie', 'Aus einer funktionalen Raumstruktur folgt nicht notwendig eine Metrik, Norm oder ein Koordinatensystem.', '\\mathfrak R_F^{K}(\\mathcal S)\\nRightarrow\\left(\\Omega_F^{K}(\\mathcal S),d_F\\right)', '\\mathfrak R_F^{K}(\\mathcal S)\\nRightarrow\\left(\\Omega_F^{K}(\\mathcal S),d_F\\right)', 52, NULL, 'original', NULL, 'checked', 64),
(15, 'Korollar 3.4.11', 62, 'Metrische Struktur bei reversibler Übergangsordnung', 'Sind sämtliche unmittelbaren Übergänge reversibel und gleich lang, wird die funktionale Übergangsdistanz symmetrisch und damit metrisch.', '\\delta_F(z_F^{(i)},z_F^{(j)})=\\delta_F(z_F^{(j)},z_F^{(i)})', '\\delta_F(z_F^{(i)},z_F^{(j)})=\\delta_F(z_F^{(j)},z_F^{(i)})', 53, NULL, 'original', NULL, 'checked', 64),
(16, 'Korollar 3.4.12', 63, 'Keine funktionale Zeit ohne Zustandsunterscheidung', 'Ohne registrierte nichtidentische Zustandsänderung kann innerhalb der betrachteten Organisation keine unterscheidbare funktionale Zeitordnung rekonstruiert werden.', 'z_F^{(k+1)}=z_F^{(k)}\\;\\forall k\\Longrightarrow\\text{keine unterscheidbare funktionale Zeit}', 'z_F^{(k+1)}=z_F^{(k)}\\;\\forall k\\Longrightarrow\\text{keine unterscheidbare funktionale Zeit}', 55, NULL, 'original', NULL, 'checked', 65),
(17, 'Korollar 3.4.13', 63, 'Additivität gewichteter funktionaler Zeit', 'Die gewichtete funktionale Zeitdifferenz ist entlang eines geordneten Entwicklungspfades additiv.', '\\Delta\\tau_F^{w}(\\zeta_i,\\zeta_k)=\\Delta\\tau_F^{w}(\\zeta_i,\\zeta_j)+\\Delta\\tau_F^{w}(\\zeta_j,\\zeta_k)', '\\Delta\\tau_F^{w}(\\zeta_i,\\zeta_k)=\\Delta\\tau_F^{w}(\\zeta_i,\\zeta_j)+\\Delta\\tau_F^{w}(\\zeta_j,\\zeta_k)', NULL, 22, 'original', NULL, 'checked', 65),
(18, 'Korollar 3.4.14', 64, 'Gemeinsamer Ursprung von Raum und Zeit', 'Jeder nichtidentische kohärenzerhaltende Übergang erzeugt zugleich funktionale Nachbarschaft und funktionale Nachfolge.', '\\text{Operatorwirkung}\\Longrightarrow\\text{Raum und Zeit}', '\\text{Operatorwirkung}\\Longrightarrow\\text{Raum und Zeit}', 58, NULL, 'original', NULL, 'checked', 66),
(19, 'Korollar 3.4.15', 64, 'Lokale Begrenzung funktionaler Zukunft', 'Bei endlicher lokaler Operatorenmenge und deterministischer Operatorwirkung ist die Menge unmittelbarer funktionaler Nachfolger endlich und durch die Zahl der Operatoren begrenzt.', '|\\operatorname{Succ}_F(\\varepsilon_F)|\\leq|\\mathcal O_F^K(\\varepsilon_F)|', '|\\operatorname{Succ}_F(\\varepsilon_F)|\\leq|\\mathcal O_F^K(\\varepsilon_F)|', NULL, NULL, 'original', NULL, 'checked', 66),
(20, 'Korollar 3.4.16', 64, 'Kohärente Raum-Zeit-Komponente', 'Alle von einem kohärenten Ausgangsereignis ausschließlich über kohärenzerhaltende Operatoren erreichbaren Ereignisse bilden eine kohärente Raum-Zeit-Komponente.', '\\mathcal C_{RZ,F}^{K}(\\varepsilon_F^{(0)})', '\\mathcal C_{RZ,F}^{K}(\\varepsilon_F^{(0)})', 60, NULL, 'original', NULL, 'checked', 66),
(22, 'Korollar 3.4.17', 50, 'Dynamik als Erweiterung der Struktur', 'Die Dynamik ergänzt die funktionale Raum-Zeit-Struktur um eine Entwicklungsregel.', '\\mathfrak{RZ}_F+\\mathcal D_F=\\mathfrak{RZ}_F^{dyn}', '\\mathfrak{RZ}_F+\\mathcal D_F=\\mathfrak{RZ}_F^{dyn}', NULL, NULL, 'original', NULL, 'checked', 69),
(23, 'Korollar 3.4.18', 50, 'Emergenz stabiler funktionaler Organisation', 'Unterschiedliche Anfangszustände können durch dieselbe Attraktorstruktur verbunden werden.', '\\mathcal D_F^n(z_F^{(i)}),\\mathcal D_F^n(z_F^{(j)})\\rightarrow\\mathcal A_F', '\\mathcal D_F^n(z_F^{(i)}),\\mathcal D_F^n(z_F^{(j)})\\rightarrow\\mathcal A_F', NULL, NULL, 'original', NULL, 'checked', 70),
(24, 'Korollar 3.4.19', 50, 'Entwicklung durch Instabilität', 'Grundlegende funktionale Veränderungen erfordern das Verlassen einer bisherigen Stabilitätsdomäne.', '\\Delta\\mathcal O_F\\Rightarrow\\Delta\\mathfrak{RZ}_F', '\\Delta\\mathcal O_F\\Rightarrow\\Delta\\mathfrak{RZ}_F', NULL, NULL, 'original', NULL, 'checked', 71),
(25, 'Korollar 3.4.20', 50, 'Emergenz ohne neue Grundelemente', 'Neue funktionale Organisation entsteht durch neue Ordnung vorhandener Elemente.', '\\Delta\\mathcal R_F\\Rightarrow\\Delta\\mathcal O_F\\Rightarrow\\Delta\\mathfrak{RZ}_F', '\\Delta\\mathcal R_F\\Rightarrow\\Delta\\mathcal O_F\\Rightarrow\\Delta\\mathfrak{RZ}_F', NULL, NULL, 'original', NULL, 'checked', 72),
(26, 'Korollar 3.4.22', 50, 'Organisation ist primär relational', 'Die funktionale Organisation eines Systems ergibt sich aus der Struktur seiner Beziehungen.', '\\mathcal O_F=f(\\mathcal R_F)', '\\mathcal O_F=f(\\mathcal R_F)', NULL, NULL, 'original', NULL, 'checked', 73);
INSERT INTO `definitions` (`definition_id`, `definition_number`, `section_id`, `title`, `definition_text`, `formal_latex`, `word_latex`, `provenance`, `source_id`, `assumptions`, `notes`, `validation_status`, `created_revision_id`) VALUES
(1, '3.2.1', 13, 'Menge und Elementbeziehung', 'Eine Menge M ist innerhalb der Mengenlehre ein mathematischer Träger, für dessen mögliche Gegenstände x bestimmt ist, ob x Element von M ist oder nicht. Die Elementbeziehung wird durch x ∈ M, ihre Negation durch x ∉ M bezeichnet.', 'x in M,qquad x \notin M', 'x in M,qquad x \notin M', 'adapted', 71, 'Es wird ein axiomatischer mengentheoretischer Rahmen vorausgesetzt.', 'Die Definition beschreibt die formale Träger- und Zugehörigkeitsstruktur, nicht die funktionale Genese von Elementen.', 'checked', 10),
(2, '3.2.2', 13, 'Teilmenge', 'Eine Menge A heißt Teilmenge einer Menge B, wenn jedes Element von A zugleich Element von B ist.', 'Asubseteq B iff forall x,(xin A\rightarrow xin B)', 'Asubseteq B iff forall x,(xin A\rightarrow xin B)', 'adapted', 71, 'A und B sind Mengen innerhalb desselben axiomatischen Rahmens.', 'Die Teilmengenrelation bildet eine Ordnungsstruktur auf der Potenzmenge.', 'checked', 10),
(3, '3.2.3', 13, 'Potenzmenge', 'Die Potenzmenge einer Menge M ist die Menge sämtlicher Teilmengen von M.', 'mathcal{P}(M)={Amid Asubseteq M}', 'mathcal{P}(M)={Amid Asubseteq M}', 'adapted', 66, 'M ist eine Menge und die Potenzmengenbildung ist im verwendeten Axiomensystem zugelassen.', 'Die Potenzmenge hebt die Beschreibung von Elementen auf die Ebene möglicher Teilmengen.', 'checked', 10),
(4, '3.2.4', 14, 'Binäre Relation', 'Eine binäre Relation R zwischen den Mengen A und B ist eine Teilmenge des kartesischen Produkts A×B. Für a∈A und b∈B gilt aRb genau dann, wenn (a,b)∈R.', 'R\\subseteq A\\times B,\\qquad aRb\\iff(a,b)\\in R', 'R\\subseteq A\\times B,\\qquad aRb\\iff(a,b)\\in R', 'adapted', 75, 'Die beteiligten Trägermengen und kartesischen Produkte sind bereits bestimmt.', 'Literaturgestützte Rekonstruktion des etablierten mathematischen Relationsbegriffs.', 'checked', 11),
(5, '3.2.5', 14, 'Relation auf einer Menge', 'Eine binäre Relation R auf einer Menge M ist eine Teilmenge von M×M.', 'R\\subseteq M\\times M', 'R\\subseteq M\\times M', 'adapted', 75, 'Die beteiligten Trägermengen und kartesischen Produkte sind bereits bestimmt.', 'Literaturgestützte Rekonstruktion des etablierten mathematischen Relationsbegriffs.', 'checked', 11),
(6, '3.2.6', 14, 'n-stellige Relation', 'Für Mengen A_1 bis A_n ist eine n-stellige Relation R eine Teilmenge des kartesischen Produkts A_1×…×A_n.', 'R\\subseteq A_1\\times A_2\\times\\cdots\\times A_n', 'R\\subseteq A_1\\times A_2\\times\\cdots\\times A_n', 'adapted', 73, 'Die beteiligten Trägermengen und kartesischen Produkte sind bereits bestimmt.', 'Literaturgestützte Rekonstruktion des etablierten mathematischen Relationsbegriffs.', 'checked', 11),
(7, '3.2.7', 14, 'Reflexivität', 'Eine Relation R auf M heißt reflexiv, wenn jedes Element zu sich selbst in Relation steht; sie heißt irreflexiv, wenn kein Element zu sich selbst in Relation steht.', '\\forall x\\in M:\\;xRx', '\\forall x\\in M:\\;xRx', 'adapted', 75, 'Die beteiligten Trägermengen und kartesischen Produkte sind bereits bestimmt.', 'Literaturgestützte Rekonstruktion des etablierten mathematischen Relationsbegriffs.', 'checked', 11),
(8, '3.2.8', 14, 'Symmetrie und Antisymmetrie', 'Eine Relation R auf M heißt symmetrisch, wenn aus xRy stets yRx folgt. Sie heißt antisymmetrisch, wenn aus xRy und yRx die Gleichheit x=y folgt.', '\\forall x,y\\in M:\\;xRy\\rightarrow yRx', '\\forall x,y\\in M:\\;xRy\\rightarrow yRx', 'adapted', 75, 'Die beteiligten Trägermengen und kartesischen Produkte sind bereits bestimmt.', 'Literaturgestützte Rekonstruktion des etablierten mathematischen Relationsbegriffs.', 'checked', 11),
(9, '3.2.9', 14, 'Transitivität', 'Eine Relation R auf M heißt transitiv, wenn aus xRy und yRz stets xRz folgt.', '\\forall x,y,z\\in M:\\;(xRy\\land yRz)\\rightarrow xRz', '\\forall x,y,z\\in M:\\;(xRy\\land yRz)\\rightarrow xRz', 'adapted', 75, 'Die beteiligten Trägermengen und kartesischen Produkte sind bereits bestimmt.', 'Literaturgestützte Rekonstruktion des etablierten mathematischen Relationsbegriffs.', 'checked', 11),
(10, '3.2.10', 14, 'Äquivalenzrelation', 'Eine Relation auf M heißt Äquivalenzrelation, wenn sie reflexiv, symmetrisch und transitiv ist.', '\\sim\\;\\text{ist reflexiv, symmetrisch und transitiv}', '\\sim\\;\\text{ist reflexiv, symmetrisch und transitiv}', 'adapted', 71, 'Die beteiligten Trägermengen und kartesischen Produkte sind bereits bestimmt.', 'Literaturgestützte Rekonstruktion des etablierten mathematischen Relationsbegriffs.', 'checked', 11),
(11, '3.2.11', 14, 'Partielle Ordnung', 'Eine Relation auf M heißt partielle Ordnung, wenn sie reflexiv, antisymmetrisch und transitiv ist.', '\\preceq\\;\\text{ist reflexiv, antisymmetrisch und transitiv}', '\\preceq\\;\\text{ist reflexiv, antisymmetrisch und transitiv}', 'adapted', 71, 'Die beteiligten Trägermengen und kartesischen Produkte sind bereits bestimmt.', 'Literaturgestützte Rekonstruktion des etablierten mathematischen Relationsbegriffs.', 'checked', 11),
(12, '3.2.12', 14, 'Umkehrrelation', 'Für R⊆A×B ist die Umkehrrelation R^{-1}⊆B×A durch Vertauschung aller geordneten Paare definiert.', 'R^{-1}=\\{(b,a)\\in B\\times A\\mid(a,b)\\in R\\}', 'R^{-1}=\\{(b,a)\\in B\\times A\\mid(a,b)\\in R\\}', 'adapted', 75, 'Die beteiligten Trägermengen und kartesischen Produkte sind bereits bestimmt.', 'Literaturgestützte Rekonstruktion des etablierten mathematischen Relationsbegriffs.', 'checked', 11),
(13, '3.2.13', 14, 'Relationale Komposition', 'Für R⊆A×B und S⊆B×C enthält S∘R genau diejenigen Paare (a,c), für die ein vermittelndes b∈B mit aRb und bSc existiert.', 'S\\circ R=\\{(a,c)\\in A\\times C\\mid\\exists b\\in B:\\;aRb\\land bSc\\}', 'S\\circ R=\\{(a,c)\\in A\\times C\\mid\\exists b\\in B:\\;aRb\\land bSc\\}', 'adapted', 75, 'Die beteiligten Trägermengen und kartesischen Produkte sind bereits bestimmt.', 'Literaturgestützte Rekonstruktion des etablierten mathematischen Relationsbegriffs.', 'checked', 11),
(14, '3.2.14', 15, 'Algebraische Verknüpfung', 'Sei M eine Menge. Eine zweistellige Verknüpfung auf M ist eine Abbildung von M×M nach M, die jedem geordneten Paar (a,b) genau ein Element a∗b aus M zuordnet.', 'ast:M	imes M\rightarrow M', 'ast:M	imes M\rightarrow M', 'adapted', 77, 'M ist eine nichtleere Menge.', 'Die Definition beschreibt eine innere zweistellige Operation.', 'checked', 12),
(15, '3.2.15', 15, 'Abgeschlossenheit', 'Eine Verknüpfung ∗ heißt auf M abgeschlossen, wenn für alle a,b aus M auch a∗b wieder Element von M ist.', 'forall a,bin M:;aast bin M', 'forall a,bin M:;aast bin M', 'adapted', 77, 'Auf M ist eine zweistellige Verknüpfung definiert.', 'Die Abgeschlossenheit hält sämtliche Operationsergebnisse im Trägerbereich.', 'checked', 12),
(16, '3.2.16', 15, 'Assoziativität', 'Eine Verknüpfung ∗ heißt assoziativ, wenn für alle a,b,c aus M die Gleichheit (a∗b)∗c=a∗(b∗c) gilt.', '(aast b)ast c=aast(bast c)', '(aast b)ast c=aast(bast c)', 'adapted', 77, 'Auf M ist eine abgeschlossene zweistellige Verknüpfung definiert.', 'Die Klammerung längerer Verknüpfungsfolgen verändert das Ergebnis nicht.', 'checked', 12),
(17, '3.2.17', 15, 'Neutrales Element', 'Ein Element e aus M heißt neutrales Element bezüglich ∗, wenn e∗a=a∗e=a für alle a aus M gilt.', 'east a=aast e=a', 'east a=aast e=a', 'adapted', 77, 'Auf M ist eine zweistellige Verknüpfung definiert.', 'Das neutrale Element lässt jedes andere Element bei der Verknüpfung unverändert.', 'checked', 12),
(18, '3.2.18', 15, 'Inverses Element', 'Zu a aus M heißt a^{-1} invers, wenn a∗a^{-1}=a^{-1}∗a=e gilt.', 'aast a^{-1}=a^{-1}ast a=e', 'aast a^{-1}=a^{-1}ast a=e', 'adapted', 77, 'Ein neutrales Element e ist bestimmt.', 'Das inverse Element hebt die Wirkung eines Elements bezüglich der Verknüpfung auf.', 'checked', 12),
(19, '3.2.19', 15, 'Gruppe', 'Ein Paar (M,∗) heißt Gruppe, wenn die Verknüpfung abgeschlossen und assoziativ ist, ein neutrales Element existiert und jedes Element ein Inverses besitzt. Gilt zusätzlich a∗b=b∗a, heißt die Gruppe abelsch.', '(M,ast)', '(M,ast)', 'adapted', 77, 'M ist eine nichtleere Menge mit innerer zweistelliger Verknüpfung.', 'Gruppen abstrahieren invertierbare Operationen und Symmetrien.', 'checked', 12),
(20, '3.2.20', 15, 'Ring', 'Ein Ring ist eine Menge R mit zwei Verknüpfungen + und ·, sodass (R,+) eine abelsche Gruppe bildet, die Multiplikation assoziativ ist und beide Operationen durch die Distributivgesetze verbunden sind.', 'acdot(b+c)=acdot b+acdot c', 'acdot(b+c)=acdot b+acdot c', 'adapted', 77, 'Auf R sind Addition und Multiplikation definiert.', 'Die Definition folgt der im Abschnitt verwendeten vereinfachten Ringfassung.', 'checked', 12),
(21, '3.2.21', 15, 'Körper', 'Ein Körper ist ein Ring, in dem jedes von Null verschiedene Element ein multiplikatives Inverses besitzt.', 'acdot a^{-1}=1', 'acdot a^{-1}=1', 'adapted', 77, 'a ist ein von Null verschiedenes Ringelement.', 'Körper ermöglichen die vier elementaren arithmetischen Operationen unter den üblichen Einschränkungen.', 'checked', 12),
(22, '3.2.22', 16, 'Graph', 'Ein Graph ist ein geordnetes Paar G=(V,E), wobei V die Knotenmenge und E die Kantenmenge bezeichnet.', 'G=(V,E)', 'G=(V,E)', 'adapted', 80, 'V und E sind Mengen.', 'Grunddefinition eines Graphen.', 'checked', 13),
(23, '3.2.23', 16, 'Gerichteter Graph', 'Ein gerichteter Graph ist ein Paar G=(V,E) mit E⊆V×V.', 'E\\subseteq V\\times V', 'E\\subseteq V\\times V', 'adapted', 80, 'V ist eine Knotenmenge.', 'Gerichtete Kanten sind geordnete Paare.', 'checked', 13),
(24, '3.2.24', 16, 'Knotengrad', 'Der Grad eines Knotens ist die Anzahl seiner unmittelbaren Nachbarn; in gerichteten Graphen werden Eingangs- und Ausgangsgrad unterschieden.', '\\deg(v)=\\left|\\left\\{u\\in V\\mid\\{u,v\\}\\in E\\right\\}\\right|', '\\deg(v)=\\left|\\left\\{u\\in V\\mid\\{u,v\\}\\in E\\right\\}\\right|', 'adapted', 80, 'G=(V,E) und v∈V.', 'Lokales Vernetzungsmaß.', 'checked', 13),
(25, '3.2.25', 16, 'Adjazenzmatrix', 'Die Adjazenzmatrix A_G=(a_ij) bildet die Kantenstruktur eines endlichen Graphen binär ab.', '\\mathbf{A}_G=(a_{ij})\\in\\{0,1\\}^{n\\times n}', '\\mathbf{A}_G=(a_{ij})\\in\\{0,1\\}^{n\\times n}', 'adapted', 81, 'V ist endlich und geordnet.', 'Matrixdarstellung der Kantenstruktur.', 'checked', 13),
(26, '3.2.26', 16, 'Kantenzug und Pfad', 'Ein Kantenzug ist eine Folge benachbarter Knoten. Ein Pfad ist ein Kantenzug ohne mehrfach vorkommende Knoten.', 'W=(v_0,v_1,\\ldots,v_k)', 'W=(v_0,v_1,\\ldots,v_k)', 'adapted', 80, 'Die Kantenfolge ist zulässig.', 'Grundlage für Erreichbarkeit und Distanz.', 'checked', 13),
(27, '3.2.27', 16, 'Zusammenhang', 'Ein Graph heißt zusammenhängend, wenn zwischen je zwei Knoten ein Pfad existiert.', '\\forall u,v\\in V\\;\\exists P_{uv}', '\\forall u,v\\in V\\;\\exists P_{uv}', 'adapted', 80, 'G=(V,E).', 'Globale Erreichbarkeitseigenschaft.', 'checked', 13),
(28, '3.2.28', 16, 'Graphendistanz', 'Die Distanz d_G(u,v) ist die minimale Länge eines Pfades von u nach v.', 'd_G(u,v)=\\min\\left\\{\\ell(P)\\mid P\\text{ ist ein Pfad von }u\\text{ nach }v\\right\\}', 'd_G(u,v)=\\min\\left\\{\\ell(P)\\mid P\\text{ ist ein Pfad von }u\\text{ nach }v\\right\\}', 'adapted', 80, 'Zwischen u und v existiert ein Pfad.', 'Strukturelle Entfernung.', 'checked', 13),
(29, '3.2.29', 16, 'Zyklus', 'Ein Zyklus ist ein geschlossener Pfad mit paarweise verschiedenen inneren Knoten.', 'C=(v_0,v_1,\\ldots,v_{k-1},v_0)', 'C=(v_0,v_1,\\ldots,v_{k-1},v_0)', 'adapted', 80, 'Die Kantenfolge ist geschlossen.', 'Geschlossene Verbindungsfolge.', 'checked', 13),
(30, '3.2.30', 16, 'Baum', 'Ein Baum ist ein zusammenhängender ungerichteter Graph ohne Zyklen.', '|E|=|V|-1', '|E|=|V|-1', 'adapted', 80, 'Der Graph ist endlich, ungerichtet und azyklisch.', 'Für endliche Bäume gilt |E|=|V|-1.', 'checked', 13),
(31, '3.2.31', 16, 'Gewichteter Graph', 'Ein gewichteter Graph ist ein Tripel G=(V,E,w) mit einer Gewichtsfunktion w:E→R.', 'w:E\\rightarrow\\mathbb{R}', 'w:E\\rightarrow\\mathbb{R}', 'adapted', 81, 'G=(V,E).', 'Kanten erhalten quantitative Werte.', 'checked', 13),
(32, '3.2.32', 17, 'Funktion', 'Eine Funktion f:A→B ist eine Relation f⊆A×B, die jedem Element a∈A genau ein Element b∈B zuordnet.', 'f:A\rightarrow B,qquadforall ain A;exists!,bin B:(a,b)in f', 'f:A\rightarrow B,qquadforall ain A;exists!,bin B:(a,b)in f', 'adapted', 71, 'A und B sind Mengen.', 'Mengentheoretische Definition einer eindeutigen Zuordnung.', 'checked', 14),
(33, '3.2.33', 17, 'Bildmenge', 'Die Bildmenge f(A) besteht aus allen Elementen des Zielbereichs, die von mindestens einem Element des Definitionsbereichs angenommen werden.', 'f(A)={f(a)mid ain A}', 'f(A)={f(a)mid ain A}', 'adapted', 71, 'f:A→B ist eine Funktion.', 'Die Bildmenge ist im Allgemeinen nur eine Teilmenge des Zielbereichs.', 'checked', 14),
(34, '3.2.34', 17, 'Injektivität', 'Eine Funktion ist injektiv, wenn gleiche Funktionswerte nur von gleichen Argumenten erzeugt werden.', 'f(a_1)=f(a_2)Longrightarrow a_1=a_2', 'f(a_1)=f(a_2)Longrightarrow a_1=a_2', 'adapted', 71, 'f:A→B ist eine Funktion.', 'Verschiedene Elemente des Definitionsbereichs besitzen verschiedene Bilder.', 'checked', 14),
(35, '3.2.35', 17, 'Surjektivität', 'Eine Funktion ist surjektiv, wenn jedes Element des Zielbereichs mindestens ein Urbild besitzt.', 'forall bin B;exists ain A:f(a)=b', 'forall bin B;exists ain A:f(a)=b', 'adapted', 71, 'f:A→B ist eine Funktion.', 'Für eine surjektive Funktion gilt f(A)=B.', 'checked', 14),
(36, '3.2.36', 17, 'Bijektivität', 'Eine Funktion ist bijektiv, wenn sie zugleich injektiv und surjektiv ist.', 'f	ext{ bijektiv}Longleftrightarrow f	ext{ injektiv und surjektiv}', 'f	ext{ bijektiv}Longleftrightarrow f	ext{ injektiv und surjektiv}', 'adapted', 71, 'f:A→B ist eine Funktion.', 'Bijektivität ist die Voraussetzung für eine eindeutige Umkehrfunktion.', 'checked', 14),
(37, '3.2.37', 17, 'Funktionskomposition', 'Für f:A→B und g:B→C ist die Komposition g∘f:A→C durch (g∘f)(a)=g(f(a)) definiert.', '(gcirc f)(a)=g(f(a))', '(gcirc f)(a)=g(f(a))', 'adapted', 71, 'Der Zielbereich von f entspricht dem Definitionsbereich von g.', 'Die Komposition beschreibt eine Folge eindeutiger Transformationen.', 'checked', 14),
(38, '3.2.38', 17, 'Identitätsabbildung', 'Die Identitätsabbildung id_A:A→A ordnet jedem Element a∈A sich selbst zu.', 'operatorname{id}_A(a)=a', 'operatorname{id}_A(a)=a', 'adapted', 71, 'A ist eine Menge.', 'Die Identität wirkt bezüglich der Funktionskomposition neutral.', 'checked', 14),
(51, '3.2.39', 18, 'Vektorraum', 'Ein Vektorraum über einem Körper K ist eine Menge V mit einer Vektoraddition und einer Skalarmultiplikation, welche die acht Vektorraumaxiome erfüllen.', '+:V	imes V\rightarrow V,qquadcdot:K	imes V\rightarrow V', '+:V	imes V\rightarrow V,qquadcdot:K	imes V\rightarrow V', 'adapted', 93, 'K ist ein Körper; V ist eine nichtleere Menge.', 'Die Definition umfasst Abgeschlossenheit, Assoziativität und Kommutativität der Addition, Nullvektor, additive Inverse, beide Distributivgesetze, Verträglichkeit der Skalarmultiplikation und Einheitswirkung.', 'checked', 17),
(52, '3.2.40', 18, 'Linearkombination', 'Eine Linearkombination der Vektoren v_1 bis v_n ist eine endliche Summe skalarer Vielfacher dieser Vektoren.', 'sum_{i=1}^{n}lambda_i v_i', 'sum_{i=1}^{n}lambda_i v_i', 'adapted', 93, 'v_i∈V und λ_i∈K.', 'Linearkombinationen verbinden Vektoraddition und Skalarmultiplikation.', 'checked', 17),
(53, '3.2.41', 18, 'Linearer Spann', 'Der lineare Spann einer Teilmenge M eines Vektorraums ist die Menge aller endlichen Linearkombinationen von Elementen aus M.', 'operatorname{span}(M)=left{sum_{i=1}^{n}lambda_i v_imid v_iin M\right}', 'operatorname{span}(M)=left{sum_{i=1}^{n}lambda_i v_imid v_iin M\right}', 'adapted', 93, 'M⊆V.', 'Der Spann ist der kleinste Untervektorraum, der M enthält.', 'checked', 17),
(54, '3.2.42', 18, 'Lineare Unabhängigkeit', 'Vektoren v_1 bis v_n heißen linear unabhängig, wenn nur die triviale Linearkombination den Nullvektor ergibt.', 'sum_{i=1}^{n}lambda_i v_i=0Longrightarrowlambda_i=0quad(i=1,ldots,n)', 'sum_{i=1}^{n}lambda_i v_i=0Longrightarrowlambda_i=0quad(i=1,ldots,n)', 'adapted', 93, 'v_i∈V und λ_i∈K.', 'Keiner der Vektoren kann als Linearkombination der übrigen dargestellt werden.', 'checked', 17),
(55, '3.2.43', 18, 'Basis', 'Eine Basis eines Vektorraums ist eine linear unabhängige Menge, deren linearer Spann den gesamten Vektorraum erzeugt.', 'V=operatorname{span}{e_1,ldots,e_n}', 'V=operatorname{span}{e_1,ldots,e_n}', 'adapted', 93, 'V ist endlichdimensional, sofern eine endliche Basis betrachtet wird.', 'Jeder Vektor besitzt bezüglich einer Basis eine eindeutige Koordinatendarstellung.', 'checked', 17),
(56, '3.2.44', 18, 'Dimension', 'Die Dimension eines endlichdimensionalen Vektorraums ist die Anzahl der Elemente einer Basis.', 'dim(V)=n', 'dim(V)=n', 'adapted', 93, 'V besitzt eine endliche Basis.', 'Alle Basen eines endlichdimensionalen Vektorraums besitzen dieselbe Anzahl von Elementen.', 'checked', 17),
(57, '3.2.45', 19, 'Lineare Abbildung', 'Eine Abbildung T von V nach W heißt linear, wenn sie Vektoraddition und Skalarmultiplikation erhält.', 'T:V\rightarrow W,quad T(u+v)=T(u)+T(v),quad T(lambda v)=lambda T(v)', 'T:V\rightarrow W,quad T(u+v)=T(u)+T(v),quad T(lambda v)=lambda T(v)', 'adapted', 96, 'V und W sind Vektorräume über demselben Körper K.', 'Additivität und Homogenität können zur Erhaltung beliebiger Linearkombinationen zusammengefasst werden.', 'checked', 18),
(58, '3.2.46', 19, 'Kern einer linearen Abbildung', 'Der Kern einer linearen Abbildung ist die Menge aller Vektoren des Ausgangsraums, die auf den Nullvektor des Zielraums abgebildet werden.', 'ker(T)=left{vin Vmid T(v)=0_W\right}', 'ker(T)=left{vin Vmid T(v)=0_W\right}', 'adapted', 96, 'T:V→W ist linear.', 'Der Kern beschreibt die unter der Abbildung ausgelöschten Richtungen.', 'checked', 18),
(59, '3.2.47', 19, 'Bild einer linearen Abbildung', 'Das Bild einer linearen Abbildung enthält alle durch die Abbildung erreichbaren Vektoren des Zielraums.', 'operatorname{im}(T)=left{T(v)mid vin V\right}', 'operatorname{im}(T)=left{T(v)mid vin V\right}', 'adapted', 96, 'T:V→W ist linear.', 'Das Bild ist ein Untervektorraum des Zielraums.', 'checked', 18),
(60, '3.2.48', 19, 'Rang und Nullität', 'Der Rang einer linearen Abbildung ist die Dimension ihres Bildes; ihre Nullität ist die Dimension ihres Kerns.', 'operatorname{rang}(T)=dim(operatorname{im}(T)),quadoperatorname{null}(T)=dim(ker(T))', 'operatorname{rang}(T)=dim(operatorname{im}(T)),quadoperatorname{null}(T)=dim(ker(T))', 'adapted', 96, 'Kern und Bild sind endlichdimensional.', 'Rang und Nullität zerlegen im Dimensionssatz die Dimension des Ausgangsraums.', 'checked', 18),
(61, '3.2.49', 19, 'Darstellungsmatrix einer linearen Abbildung', 'Die Darstellungsmatrix einer linearen Abbildung enthält spaltenweise die Koordinaten der Bilder der Basisvektoren des Ausgangsraums bezüglich einer Basis des Zielraums.', '[T]_{Cleftarrow B}=(a_{ij})', '[T]_{Cleftarrow B}=(a_{ij})', 'adapted', 96, 'B ist eine Basis von V und C eine Basis von W.', 'Die Matrix hängt von den gewählten Basen ab, die lineare Abbildung selbst nicht.', 'checked', 18),
(62, '3.2.50', 19, 'Linearer Operator', 'Ein linearer Operator ist eine lineare Abbildung eines Vektorraums in sich selbst.', 'T:V\rightarrow V', 'T:V\rightarrow V', 'adapted', 96, 'V ist ein Vektorraum.', 'Ausgangsraum und Zielraum stimmen überein.', 'checked', 18),
(63, '3.2.51', 19, 'Invertierbarer linearer Operator', 'Ein linearer Operator heißt invertierbar, wenn ein linearer inverser Operator existiert, dessen beidseitige Komposition mit T die Identität ergibt.', 'T^{-1}circ T=Tcirc T^{-1}=operatorname{id}_V', 'T^{-1}circ T=Tcirc T^{-1}=operatorname{id}_V', 'adapted', 96, 'T:V→V ist linear.', 'Invertierbarkeit ermöglicht die eindeutige Rekonstruktion des Ausgangsvektors.', 'checked', 18),
(64, '3.2.52', 20, 'Skalarprodukt', 'Ein Skalarprodukt auf einem reellen Vektorraum ist eine symmetrische, lineare und positiv definite Abbildung von V×V nach R.', 'langlecdot,cdot\rangle:V	imes V\rightarrowmathbb{R}', 'langlecdot,cdot\rangle:V	imes V\rightarrowmathbb{R}', 'adapted', 98, 'V ist ein reeller Vektorraum.', 'Die Linearität wird im reellen Fall im ersten Argument formuliert; aus der Symmetrie folgt sie auch im zweiten Argument.', 'checked', 19),
(65, '3.2.53', 20, 'Euklidisches Skalarprodukt', 'Das Standard-Skalarprodukt auf R^n ist die Summe der komponentenweisen Produkte.', 'langle u,v\rangle=sum_{i=1}^{n}u_iv_i', 'langle u,v\rangle=sum_{i=1}^{n}u_iv_i', 'adapted', 98, 'u,v∈R^n.', 'Das euklidische Skalarprodukt induziert die euklidische Norm.', 'checked', 19),
(66, '3.2.54', 20, 'Norm', 'Die durch ein Skalarprodukt induzierte Norm eines Vektors ist die Quadratwurzel seines Skalarprodukts mit sich selbst.', '|v|=sqrt{langle v,v\rangle}', '|v|=sqrt{langle v,v\rangle}', 'adapted', 98, 'V ist ein Skalarproduktraum.', 'Die Norm beschreibt die Größe beziehungsweise Länge eines Vektors.', 'checked', 19),
(67, '3.2.55', 20, 'Winkel zwischen zwei Vektoren', 'Der Winkel zwischen zwei von Null verschiedenen Vektoren wird über den Quotienten aus Skalarprodukt und Produkt ihrer Normen bestimmt.', 'cos	heta=frac{langle u,v\rangle}{|u||v|}', 'cos	heta=frac{langle u,v\rangle}{|u||v|}', 'adapted', 98, 'u≠0 und v≠0.', 'Die Wohldefiniertheit folgt aus der Cauchy-Schwarz-Ungleichung.', 'checked', 19),
(68, '3.2.56', 20, 'Orthogonalität', 'Zwei Vektoren heißen orthogonal, wenn ihr Skalarprodukt gleich Null ist.', 'langle u,v\rangle=0', 'langle u,v\rangle=0', 'adapted', 98, 'u und v gehören demselben Skalarproduktraum an.', 'Orthogonale Vektoren besitzen keinen gegenseitigen Projektionsanteil.', 'checked', 19),
(69, '3.2.57', 20, 'Metrik', 'Eine Metrik ist eine nichtnegative, definite und symmetrische Abstandsfunktion, welche die Dreiecksungleichung erfüllt.', 'd:V	imes V\rightarrowmathbb{R}', 'd:V	imes V\rightarrowmathbb{R}', 'adapted', 98, 'V ist eine nichtleere Menge beziehungsweise ein Vektorraum.', 'Die Metrik beschreibt Abstände unabhängig davon, ob sie durch eine Norm induziert wird.', 'checked', 19),
(70, '3.2.58', 20, 'Euklidische Metrik', 'Die durch eine Norm induzierte Abstandsfunktion ist der Abstand der Differenz zweier Vektoren vom Nullvektor.', 'd(u,v)=|u-v|', 'd(u,v)=|u-v|', 'adapted', 98, 'V ist ein normierter Vektorraum.', 'Im euklidischen Raum wird die Norm durch das Standardskalarprodukt erzeugt.', 'checked', 19),
(71, '3.2.59', 20, 'Orthogonale Projektion', 'Die orthogonale Projektion von v auf die von u erzeugte Richtung ist der mit dem normierten Skalarproduktkoeffizienten skalierte Vektor u.', 'operatorname{proj}_{u}(v)=frac{langle u,v\rangle}{langle u,u\rangle}u', 'operatorname{proj}_{u}(v)=frac{langle u,v\rangle}{langle u,u\rangle}u', 'adapted', 98, 'u≠0.', 'Die Projektion zerlegt v in einen Anteil parallel zu u und einen orthogonalen Rest.', 'checked', 19),
(72, '3.2.60', 21, 'Eigenvektor', 'Ein von Null verschiedener Vektor v heißt Eigenvektor eines linearen Operators T, wenn ein Skalar λ existiert, sodass T(v)=λv gilt.', 'v\neq0land T(v)=lambda v', 'v\neq0land T(v)=lambda v', 'adapted', 101, 'T:V→V ist linear und v∈V.', 'Die Richtung des Eigenvektors bleibt unter der Transformation erhalten.', 'checked', 20),
(73, '3.2.61', 21, 'Eigenwert', 'Der Skalar λ in der Gleichung T(v)=λv heißt Eigenwert des Operators T zum Eigenvektor v.', 'T(v)=lambda v', 'T(v)=lambda v', 'adapted', 101, 'v ist ein Eigenvektor von T.', 'Der Eigenwert beschreibt die Skalierung in der invarianten Richtung.', 'checked', 20),
(74, '3.2.62', 21, 'Eigenraum', 'Der Eigenraum zum Eigenwert λ ist der Kern des Operators T-λI.', 'E_lambda=ker(T-lambda I)', 'E_lambda=ker(T-lambda I)', 'adapted', 101, 'λ ist ein Eigenwert von T.', 'Der Eigenraum enthält den Nullvektor und sämtliche Eigenvektoren zum Eigenwert λ.', 'checked', 20),
(75, '3.2.63', 21, 'Spektrum', 'Das Spektrum eines endlichdimensionalen Operators ist die Menge aller Skalare λ, für die T-λI nicht invertierbar ist beziehungsweise die charakteristische Gleichung erfüllt wird.', 'sigma(T)={lambdain Kmiddet(T-lambda I)=0}', 'sigma(T)={lambdain Kmiddet(T-lambda I)=0}', 'adapted', 101, 'V ist endlichdimensional.', 'Die determinantengestützte Form gilt in endlicher Dimension.', 'checked', 20),
(76, '3.2.64', 21, 'Algebraische Vielfachheit', 'Die algebraische Vielfachheit eines Eigenwertes ist seine Vielfachheit als Nullstelle des charakteristischen Polynoms.', 'm_lambda^{(a)}=operatorname{ord}_{lambda}chi_T', 'm_lambda^{(a)}=operatorname{ord}_{lambda}chi_T', 'adapted', 101, 'χ_T ist das charakteristische Polynom von T.', 'Die algebraische Vielfachheit berücksichtigt die Nullstellenordnung.', 'checked', 20),
(77, '3.2.65', 21, 'Geometrische Vielfachheit', 'Die geometrische Vielfachheit eines Eigenwertes ist die Dimension seines Eigenraums.', 'm_lambda^{(g)}=dim(E_lambda)', 'm_lambda^{(g)}=dim(E_lambda)', 'adapted', 101, 'λ ist ein Eigenwert von T.', 'Sie ist mindestens eins und höchstens so groß wie die algebraische Vielfachheit.', 'checked', 20),
(78, '3.2.66', 21, 'Diagonalform', 'Ein diagonalisierbarer Operator besitzt bezüglich einer Eigenvektorbasis eine Darstellung T=PDP^{-1}, wobei D die Eigenwerte auf der Hauptdiagonalen enthält.', 'T=PDP^{-1}', 'T=PDP^{-1}', 'adapted', 101, 'P ist invertierbar und seine Spalten bilden eine Eigenvektorbasis.', 'D ist eine Diagonalmatrix.', 'checked', 20),
(79, '3.2.67', 21, 'Invarianter Unterraum', 'Ein Unterraum U von V heißt unter T invariant, wenn T(U) eine Teilmenge von U ist.', 'T(U)subseteq U', 'T(U)subseteq U', 'adapted', 101, 'U⊆V ist ein Untervektorraum und T:V→V ist linear.', 'Ein Eigenraum ist ein spezieller invarianter Unterraum.', 'checked', 20),
(80, '3.2.68', 22, 'Bilinearform', 'Eine Bilinearform auf einem Vektorraum V über K ist eine Abbildung B:V×V→K, die in beiden Argumenten linear ist.', 'B:V\\times V\\rightarrow K', 'B:V\\times V\\rightarrow K', 'adapted', 102, 'V ist ein Vektorraum über dem Körper K.', 'Bilinearität gilt separat in beiden Argumenten.', 'checked', 21),
(81, '3.2.69', 22, 'Symmetrische Bilinearform', 'Eine Bilinearform B heißt symmetrisch, wenn B(u,v)=B(v,u) für alle u,v∈V gilt.', 'B(u,v)=B(v,u)', 'B(u,v)=B(v,u)', 'adapted', 103, 'B ist eine Bilinearform.', 'Symmetrie beschreibt reziproke Wechselwirkung.', 'checked', 21),
(82, '3.2.70', 22, 'Schiefsymmetrische Bilinearform', 'Eine Bilinearform B heißt schiefsymmetrisch, wenn B(u,v)=-B(v,u) für alle u,v∈V gilt.', 'B(u,v)=-B(v,u)', 'B(u,v)=-B(v,u)', 'adapted', 103, 'B ist eine Bilinearform.', 'Über Körpern mit Charakteristik ungleich zwei folgt B(v,v)=0.', 'checked', 21),
(83, '3.2.71', 22, 'Quadratische Form', 'Eine quadratische Form Q ist die einem Vektor v zugeordnete skalare Größe Q(v)=B(v,v), wobei B symmetrisch bilinear ist.', 'Q(v)=B(v,v)', 'Q(v)=B(v,v)', 'adapted', 103, 'B ist eine symmetrische Bilinearform.', 'Quadratische Formen bewerten einzelne Zustände.', 'checked', 21),
(84, '3.2.72', 22, 'Quadratische Matrixdarstellung', 'Bezüglich einer Basis besitzt eine quadratische Form die Darstellung Q(v)=v^TAv mit symmetrischer Matrix A.', 'Q(v)=v^{T}Av', 'Q(v)=v^{T}Av', 'adapted', 103, 'Eine Basis von V ist gewählt.', 'Der symmetrische Anteil von A bestimmt die quadratische Form.', 'checked', 21),
(85, '3.2.73', 22, 'Positive Definitheit', 'Eine quadratische Form Q heißt positiv definit, wenn Q(v)>0 für jeden Vektor v≠0 gilt.', 'Q(v)>0\\quad\\forall v\\neq0', 'Q(v)>0\\quad\\forall v\\neq0', 'adapted', 103, 'V ist ein reeller Vektorraum.', 'Positive Definitheit erzeugt eine strikt positive Zustandsbewertung.', 'checked', 21),
(86, '3.2.74', 22, 'Positive Semidefinitheit', 'Eine quadratische Form Q heißt positiv semidefinit, wenn Q(v)≥0 für alle v∈V gilt.', 'Q(v)\\geq0', 'Q(v)\\geq0', 'adapted', 103, 'V ist ein reeller Vektorraum.', 'Nichttriviale Nullrichtungen sind zulässig.', 'checked', 21),
(87, '3.2.75', 22, 'Energieform', 'Eine Energieform ist eine positiv definite quadratische Form E(v)=v^TAv, die jedem Zustand eine skalare Energiegröße zuordnet.', 'E(v)=v^{T}Av', 'E(v)=v^{T}Av', '', 102, 'A ist symmetrisch und positiv definit.', 'Die Definition bereitet spätere Stabilitäts- und Kohärenzfunktionen vor.', 'checked', 21),
(88, '3.2.76', 23, 'Orthogonale Projektion', 'Ein linearer Operator P:V→V heißt orthogonale Projektion, wenn P²=P und P^T=P gelten.', 'P:V\rightarrow V,quad P^2=P,quad P^T=P', 'P:V\rightarrow V,quad P^2=P,quad P^T=P', 'adapted', 105, 'V ist ein reeller Skalarproduktraum.', 'Idempotenz und Selbstadjungiertheit charakterisieren die orthogonale Projektion.', 'checked', 22),
(89, '3.2.77', 23, 'Projektionsmatrix', 'Eine Matrix A heißt Projektionsmatrix, wenn A²=A gilt. Ist zusätzlich A^T=A, beschreibt sie eine orthogonale Projektion.', 'A^2=A', 'A^2=A', 'adapted', 105, 'A ist eine quadratische Matrix.', 'Symmetrie unterscheidet orthogonale von schiefen Projektionen.', 'checked', 22),
(90, '3.2.78', 23, 'Orthogonalkomplement', 'Das Orthogonalkomplement U^⊥ eines Unterraums U enthält alle Vektoren, die zu jedem Vektor aus U orthogonal sind.', 'U^perp={vin Vmidlangle v,u\rangle=0 forall uin U}', 'U^perp={vin Vmidlangle v,u\rangle=0 forall uin U}', 'adapted', 105, 'U ist ein Unterraum eines Skalarproduktraums V.', 'Das Orthogonalkomplement ist selbst ein Unterraum.', 'checked', 22),
(91, '3.2.79', 23, 'Gram-Schmidt-Orthogonalisierung', 'Das Gram-Schmidt-Verfahren erzeugt aus linear unabhängigen Vektoren rekursiv ein orthogonales beziehungsweise nach Normierung orthonormales System.', 'u_k=v_k-sum_{i=1}^{k-1}frac{langle v_k,u_i\rangle}{langle u_i,u_i\rangle}u_i', 'u_k=v_k-sum_{i=1}^{k-1}frac{langle v_k,u_i\rangle}{langle u_i,u_i\rangle}u_i', 'adapted', 104, 'v_1,...,v_n sind linear unabhängig.', 'Nach anschließender Normierung entsteht eine Orthonormalbasis.', 'checked', 22),
(92, '3.2.80', 23, 'Funktionale Separation', 'Eine funktionale Separation ist im FRZK die orthogonale Zerlegung eines funktionalen Zustandsraums in unabhängig analysierbare Funktionsanteile.', 'V_F=igoplus_{i=1}^{m}U_i,quad U_iperp U_j 	ext{für} i\neq j', 'V_F=igoplus_{i=1}^{m}U_i,quad U_iperp U_j 	ext{für} i\neq j', 'original', NULL, 'V_F ist ein funktionaler Zustandsraum mit Skalarprodukt.', 'FRZK-spezifische Arbeitsdefinition als Grundlage späterer Resonanz-, Kohärenz- und Attraktoranalysen.', 'checked', 22),
(93, '3.2.81', 24, 'Eigenwert', 'Für einen linearen Operator A:V→V heißt λ Eigenwert, wenn ein von Null verschiedener Vektor v existiert, für den Av=λv gilt.', 'A:V\rightarrow V,quad Av=lambda v,quad v\neq 0', 'A:V\rightarrow V,quad Av=lambda v,quad v\neq 0', 'adapted', 97, 'A ist ein linearer Operator auf V.', 'Der Vektor v heißt Eigenvektor zum Eigenwert λ.', 'checked', 23),
(94, '3.2.82', 24, 'Eigenraum', 'Der Eigenraum E_λ ist die Menge aller Vektoren, die durch A mit dem Faktor λ skaliert werden, einschließlich des Nullvektors.', 'E_lambda={vin Vmid Av=lambda v}', 'E_lambda={vin Vmid Av=lambda v}', 'adapted', 97, 'λ ist ein Eigenwert von A.', 'Der Eigenraum entspricht dem Kern von A-λI.', 'checked', 23),
(95, '3.2.83', 24, 'Spektrum', 'Das Spektrum σ(A) ist die Menge aller Skalare λ, für die A-λI nicht invertierbar ist. Im endlichdimensionalen Fall entspricht es der Menge der Eigenwerte.', 'sigma(A)={lambdamid A-lambda I 	ext{ist nicht invertierbar}}', 'sigma(A)={lambdamid A-lambda I 	ext{ist nicht invertierbar}}', 'adapted', 106, 'A ist ein linearer Operator.', 'Die im Text verwendete endliche Darstellung {λ1,...,λn} ist ein Spezialfall.', 'checked', 23),
(96, '3.2.84', 24, 'Spektralzerlegung', 'Eine Spektralzerlegung stellt einen selbstadjungierten Operator als Summe seiner Eigenwerte, gewichtet mit den zugehörigen orthogonalen Projektoren, dar.', 'A=sum_ilambda_iP_i', 'A=sum_ilambda_iP_i', 'adapted', 106, 'A ist im endlichdimensionalen Fall reell symmetrisch beziehungsweise selbstadjungiert.', 'Die Projektoren P_i projizieren auf die Eigenräume E_i.', 'checked', 23),
(97, '3.2.85', 24, 'Dominanter Eigenwert', 'Ein dominanter Eigenwert ist ein Eigenwert mit maximalem Betrag innerhalb des Spektrums.', '|lambda_{max}|=max_i|lambda_i|', '|lambda_{max}|=max_i|lambda_i|', 'adapted', 106, 'Das Spektrum ist endlich oder besitzt einen betragsmäßig maximalen Eigenwert.', 'Bei eindeutiger Dominanz bestimmt der zugehörige Eigenraum häufig das asymptotische Verhalten.', 'checked', 23),
(98, '3.2.86', 24, 'Funktionales Spektrum', 'Im FRZK bezeichnet das funktionale Spektrum die Menge aller Eigenwerte eines funktionalen Operators, deren Eigenräume stabile funktionale Zustände, Resonanzrichtungen oder Attraktoren repräsentieren.', 'sigma_F(mathcal{A})={lambda_imidmathcal{A}v_i=lambda_iv_i}', 'sigma_F(mathcal{A})={lambda_imidmathcal{A}v_i=lambda_iv_i}', 'original', NULL, '𝒜 ist ein funktionaler Operator auf einem funktionalen Zustandsraum.', 'FRZK-spezifische Definition und Übergang zur axiomatischen Beschreibung in Kapitel 3.3.', 'checked', 23),
(104, '3.3.1', 29, 'Funktionaler Gehalt', 'Ein funktionaler Gehalt bezeichnet dasjenige, was innerhalb des Modells in einer für andere Gehalte oder für eine entstehende Organisation relevanten Weise wirksam werden kann. Er ist weder als physikalisches Teilchen noch als geometrischer Punkt vorausgesetzt.', 'f_i in mathcal{F}', 'f_iinmathcal{F}', 'original', NULL, 'Es wird lediglich die Möglichkeit funktionaler Wirksamkeit vorausgesetzt.', 'Prämathematischer Grundbegriff; keine ontologische Behauptung über abgeschlossene Objekte.', 'checked', 27),
(105, '3.3.2', 29, 'Qualitative funktionale Unterscheidung', 'Die qualitative funktionale Unterscheidung hält fest, ob zwei funktionale Gehalte innerhalb des Modells funktional unterschieden werden oder nicht.', 'delta_F:mathcal{F}timesmathcal{F}rightarrow{0,1}', 'delta_F:mathcal{F}	imesmathcal{F}\rightarrow{0,1}', 'original', NULL, 'Es wird kein metrischer Abstand vorausgesetzt.', 'Die binäre Form bildet ausschließlich die minimale qualitative Unterscheidung ab.', 'checked', 27),
(106, '3.3.3', 29, 'Funktionales Differenzmaß', 'Ein funktionales Differenzmaß ordnet zwei funktionalen Gehalten einen nichtnegativen Wert als möglichen Grad ihrer funktionalen Verschiedenheit zu, ohne an dieser Stelle bereits sämtliche Metrikeigenschaften zu fordern.', 'd_F:mathcal{F}timesmathcal{F}rightarrowmathbb{R}_{geq 0}', 'd_F:mathcal{F}	imesmathcal{F}\rightarrowmathbb{R}_{geq 0}', 'original', NULL, 'Symmetrie, Dreiecksungleichung und positive Definitheit werden nicht vorausgesetzt.', 'Vorstruktur für die mathematische Rekonstruktion in Kapitel 3.4.', 'draft', 27),
(107, '3.3.4', 29, 'Funktionale Wirksamkeit', 'Die funktionale Wirksamkeit beschreibt, wie ein funktionaler Gehalt innerhalb eines funktionalen Kontextes wirksam wird.', 'omega_F:mathcal{F}timesmathcal{C}rightarrowmathcal{W}', 'omega_F:mathcal{F}	imesmathcal{C}\rightarrowmathcal{W}', 'original', NULL, 'Der Kontextbereich und der Wirkungsbereich werden zunächst formal offen gehalten.', 'Bereitet eine relationale und kontextabhängige Rekonstruktion funktionaler Identität vor.', 'checked', 27),
(108, '3.3.5', 29, 'Aktuell wirksame Teilstruktur', 'Die aktuell wirksame Teilstruktur umfasst diejenigen funktionalen Gehalte des möglichen Trägerbereichs, die innerhalb des betrachteten funktionalen Zusammenhangs tatsächlich wirksam sind.', 'mathcal{F}_A subseteq mathcal{F}', 'mathcal{F}_Asubseteqmathcal{F}', 'original', NULL, 'Zwischen formaler Möglichkeit und aktueller Realisierung wird unterschieden.', 'Verhindert die Gleichsetzung aller formal möglichen mit tatsächlich realisierten Strukturen.', 'checked', 27),
(109, '3.4.1', 52, 'Funktionaler Zustand', 'Ein funktionaler Zustand z_F einer funktionalen Organisation S ist eine bestimmte, axiomatisch zulässige Konfiguration ihrer funktionalen Gehalte, Relationen und Operationen.', 'z_F:=chi_F(mathcal{S})quad	ext{mit}quadLambda_Fleft(chi_F(mathcal{S})\right)=1', 'z_F:=chi_F(mathcal{S})quad	ext{mit}quadLambda_Fleft(chi_F(mathcal{S})\right)=1', 'original', NULL, 'Axiome zu funktionalem Gehalt, Relation, Operation und Zustandsbildung; Gleichungen (3.645) und (3.646).', 'Zentrale eigene Definition des ersten mathematisch rekonstruierten Grundobjekts des FRZK.', 'checked', 49),
(110, '3.4.2', 52, 'Identität funktionaler Zustände', 'Zwei funktionale Zustände sind genau dann identisch, wenn ihre funktionalen Gehalte, funktionalen Relationen und funktionalen Operationen jeweils übereinstimmen.', 'z_F^{(i)}=z_F^{(j)}Longleftrightarrow(mathcal{F}_{mathcal{S}}^{(i)}=mathcal{F}_{mathcal{S}}^{(j)})land(mathcal{R}_{mathcal{S}}^{(i)}=mathcal{R}_{mathcal{S}}^{(j)})land(mathcal{O}_{mathcal{S}}^{(i)}=mathcal{O}_{mathcal{S}}^{(j)})', 'z_F^{(i)}=z_F^{(j)}Longleftrightarrow(mathcal{F}_{mathcal{S}}^{(i)}=mathcal{F}_{mathcal{S}}^{(j)})land(mathcal{R}_{mathcal{S}}^{(i)}=mathcal{R}_{mathcal{S}}^{(j)})land(mathcal{O}_{mathcal{S}}^{(i)}=mathcal{O}_{mathcal{S}}^{(j)})', 'original', NULL, 'Definition 3.4.1 und Komponentendarstellung aus Gleichung (3.652).', 'Komponentenweise Identitätsbedingung für funktionale Zustände.', 'checked', 49),
(113, '3.4.3', 55, 'Funktionale Äquivalenz', 'Zwei funktionale Zustände heißen bezüglich eines festgelegten funktionalen Kriteriums kappa_F funktional äquivalent, wenn ihre durch kappa_F bestimmten Merkmalswerte übereinstimmen.', 'kappa_Fleft(z_F^{(i)}\right)=kappa_Fleft(z_F^{(j)}\right)', 'kappa_Fleft(z_F^{(i)}\right)=kappa_Fleft(z_F^{(j)}\right)', 'original', NULL, 'Funktionale Zustandsmenge aus Abschnitt 3.4.1 und Merkmalsabbildung aus Gleichung (3.656).', 'Eigene Definition einer kriteriumsabhängigen funktionalen Äquivalenz.', 'checked', 52),
(114, '3.4.4', 55, 'Funktionale Zustandsklasse', 'Die funktionale Zustandsklasse eines Zustands z_F bezüglich der Relation sim_F ist die Menge aller Zustände der funktionalen Zustandsmenge, die zu z_F funktional äquivalent sind.', '[z_F]_{sim_F}=left{z_F^{\\prime}inOmega_F(mathcal{S})middle|z_F^{\\prime}sim_F z_F\right}', '[z_F]_{sim_F}=left{z_F^{\\prime}inOmega_F(mathcal{S})middle|z_F^{\\prime}sim_F z_F\right}', 'original', NULL, 'Definition 3.4.3 und Lemma 3.4.2.', 'Eigene funktionale Spezifikation der Äquivalenzklasse innerhalb der rekonstruierten Zustandsmenge.', 'checked', 52),
(118, '3.4.5', 57, 'Funktionale Relation', 'Eine funktionale Relation R_F auf der Zustandsmenge ist die Menge aller geordneten Zustandspaare, für die die relationale Prüffunktion den Wert 1 annimmt.', 'R_F:=\\left\\{\\left(z_F^{(i)},z_F^{(j)}\\right)\\in\\Omega_F(\\mathcal{S})\\times\\Omega_F(\\mathcal{S})\\middle|\\rho_F\\left(z_F^{(i)},z_F^{(j)}\\right)=1\\right\\}', 'R_F:=\\left\\{\\left(z_F^{(i)},z_F^{(j)}\\right)\\in\\Omega_F(\\mathcal{S})\\times\\Omega_F(\\mathcal{S})\\middle|\\rho_F\\left(z_F^{(i)},z_F^{(j)}\\right)=1\\right\\}', 'original', NULL, 'Definition funktionaler Zustände und relationale Prüffunktion.', 'Eigene funktionale Spezifikation einer binären Relation.', 'checked', 54),
(119, '3.4.6', 57, 'Funktionale Zustandsstruktur', 'Die geordnete Struktur aus funktionaler Zustandsmenge und funktionaler Relation heißt funktionale Zustandsstruktur der Organisation.', '\\mathfrak{Z}_F(\\mathcal{S}):=\\left(\\Omega_F(\\mathcal{S}),R_F\\right)', '\\mathfrak{Z}_F(\\mathcal{S}):=\\left(\\Omega_F(\\mathcal{S}),R_F\\right)', 'original', NULL, 'Definition 3.4.5.', 'Eigene strukturelle Zusammenführung von Zustandsmenge und Relation.', 'checked', 54),
(120, '3.4.7', 57, 'Relational eingebundener Zustand', 'Ein funktionaler Zustand heißt relational eingebunden, wenn mindestens eine ein- oder ausgehende funktionale Relation existiert.', 'R_F^{+}(z_F)\\cup R_F^{-}(z_F)\\neq\\varnothing', 'R_F^{+}(z_F)\\cup R_F^{-}(z_F)\\neq\\varnothing', 'original', NULL, 'Definitionen 3.4.5 und 3.4.6.', 'Eigene funktionale Spezifikation relationaler Einbindung.', 'checked', 54),
(121, '3.4.8', 58, 'Funktionale Transformation', 'Eine funktionale Transformation T_F ist eine Abbildung der funktionalen Zustandsmenge in sich selbst, die jedem funktionalen Ausgangszustand genau einen funktionalen Zielzustand zuordnet.', 'T_F:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S}),\\qquad z_F^{\\prime}=T_F(z_F)', 'T_F:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S}),\\qquad z_F^{\\prime}=T_F(z_F)', 'original', NULL, 'Die funktionale Zustandsmenge aus Abschnitt 3.4.1 ist bestimmt.', 'Eigene funktionale Spezifikation einer eindeutigen internen Zustandszuordnung.', 'checked', 55),
(122, '3.4.9', 58, 'Transformationsrelation', 'Die durch eine funktionale Transformation T_F erzeugte Menge aller geordneten Paare aus Ausgangszustand und eindeutig zugeordnetem Zielzustand heißt Transformationsrelation von T_F.', 'R_{T_F}:=\\left\\{\\left(z_F,T_F(z_F)\\right)\\middle|z_F\\in\\Omega_F(\\mathcal{S})\\right\\}', 'R_{T_F}:=\\left\\{\\left(z_F,T_F(z_F)\\right)\\middle|z_F\\in\\Omega_F(\\mathcal{S})\\right\\}', 'original', NULL, 'Definition 3.4.8 und die funktionale Relation aus Abschnitt 3.4.3.', 'Eigene Verbindung zwischen funktionaler Abbildung und induzierter Relation.', 'checked', 55),
(123, '3.4.10', 58, 'Funktionaler Fixpunkt', 'Ein Zustand z_F^* heißt funktionaler Fixpunkt der Transformation T_F, wenn er durch T_F auf sich selbst abgebildet wird.', 'z_F^{*}\\in\\Omega_F(\\mathcal{S}),\\qquad T_F\\left(z_F^{*}\\right)=z_F^{*}', 'z_F^{*}\\in\\Omega_F(\\mathcal{S}),\\qquad T_F\\left(z_F^{*}\\right)=z_F^{*}', 'original', NULL, 'Definition 3.4.8.', 'Die Fixpunktbedingung behauptet noch keine dynamische Stabilität.', 'checked', 55),
(124, '3.4.11', 59, 'Funktionaler Operator', 'Ein funktionaler Operator ist eine wohldefinierte Abbildung des funktionalen Zustandsraumes in sich selbst, die jedem funktionalen Zustand genau einen funktionalen Folgezustand zuordnet.', 'O_F:\\Omega_F(\\mathcal{S})\\rightarrow\\Omega_F(\\mathcal{S})', 'O_F:\\Omega_F(\\mathcal{S})\\rightarrow\\Omega_F(\\mathcal{S})', 'original', NULL, 'Der funktionale Zustandsraum aus Abschnitt 3.4.2 ist wohldefiniert. Jede zulässige Operatorwirkung führt erneut zu einem Zustand dieses Raumes.', 'Originäre FRZK-spezifische Übertragung des allgemeinen mathematischen Operatorbegriffs. Der allgemeine Operatorbegriff wird durch Rudin [11] und Conway [35] eingeordnet.', 'checked', 60),
(125, '3.4.12', 59, 'Funktionale Operatormenge', 'Die funktionale Operatormenge einer Organisation ist die Menge aller zulässigen funktionalen Operatoren, die den funktionalen Zustandsraum in sich selbst abbilden.', '\\mathcal O_F(\\mathcal S)=\\left\\{O_F\\middle|O_F:\\Omega_F(\\mathcal S)\\rightarrow\\Omega_F(\\mathcal S)\\right\\}', '\\mathcal O_F(\\mathcal S)=\\left\\{O_F\\middle|O_F:\\Omega_F(\\mathcal S)\\rightarrow\\Omega_F(\\mathcal S)\\right\\}', 'original', NULL, 'Definition 3.4.11.', 'FRZK-spezifische Operatormenge ohne vorausgesetzte Norm oder Topologie.', 'checked', 61),
(126, '3.4.13', 59, 'Komposition funktionaler Operatoren', 'Die Komposition zweier funktionaler Operatoren ist ihre geordnete Hintereinanderausführung; der rechts stehende Operator wirkt zuerst.', '\\left(O_{F,2}\\circ O_{F,1}\\right)(z_F)=O_{F,2}\\left(O_{F,1}(z_F)\\right)', '\\left(O_{F,2}\\circ O_{F,1}\\right)(z_F)=O_{F,2}\\left(O_{F,1}(z_F)\\right)', 'adapted', 31, 'Beide Operatoren gehören zu derselben funktionalen Operatormenge.', 'Übertragung der klassischen Funktionskomposition auf funktionale Zustände.', 'checked', 61),
(127, '3.4.14', 59, 'Identität und Invertierbarkeit funktionaler Operatoren', 'Der funktionale Identitätsoperator lässt jeden Zustand unverändert. Ein funktionaler Operator ist invertierbar, wenn ein beidseitiger inverser Operator existiert.', 'I_F(z_F)=z_F,\\quad O_F^{-1}\\circ O_F=O_F\\circ O_F^{-1}=I_F', 'I_F(z_F)=z_F,\\quad O_F^{-1}\\circ O_F=O_F\\circ O_F^{-1}=I_F', 'adapted', 31, 'Komposition funktionaler Operatoren.', 'Algebraische Standardbegriffe, auf den funktionalen Zustandsraum übertragen.', 'checked', 61),
(134, '3.4.15', 60, 'Funktionaler Übergang', 'Ein funktionaler Übergang ist das geordnete Tripel aus Ausgangszustand, funktionalem Operator und dem durch dessen Wirkung erzeugten Folgezustand.', '\\tau_F=\\left(z_F,O_F,z_F\\prime\\right),\\quad z_F\\prime=O_F(z_F)', '\\tau_F=\\left(z_F,O_F,z_F\\prime\\right),\\quad z_F\\prime=O_F(z_F)', 'original', NULL, 'Definition 3.4.11 und funktionaler Zustandsraum.', 'Der Pfeil bezeichnet eine gerichtete Zuordnung, noch keine physikalische Zeit.', 'checked', 62),
(135, '3.4.16', 60, 'Funktionale Übergangsmenge', 'Die funktionale Übergangsmenge enthält sämtliche zulässigen konkreten Anwendungen funktionaler Operatoren auf funktionale Zustände.', '\\mathcal T_F(\\mathcal S)=\\left\\{(z_F,O_F,z_F\\prime)\\middle|z_F\\prime=O_F(z_F)\\right\\}', '\\mathcal T_F(\\mathcal S)=\\left\\{(z_F,O_F,z_F\\prime)\\middle|z_F\\prime=O_F(z_F)\\right\\}', 'original', NULL, 'Definition 3.4.15.', 'Abgrenzung zwischen allgemeiner Operatorregel und konkreter Operatoranwendung.', 'checked', 62),
(136, '3.4.17', 60, 'Funktionale Operatorfolge', 'Eine funktionale Operatorfolge ist ein endliches geordnetes Tupel funktionaler Operatoren derselben Organisation.', '\\boldsymbol O_F^{(n)}=\\left(O_{F,1},\\ldots,O_{F,n}\\right)', '\\boldsymbol O_F^{(n)}=\\left(O_{F,1},\\ldots,O_{F,n}\\right)', 'adapted', 31, 'Funktionale Operatormenge und Komposition.', 'Die Reihenfolge ist wegen möglicher Nichtkommutativität wesentlich.', 'checked', 62),
(137, '3.4.18', 60, 'Funktionale Zustandsfolge', 'Die funktionale Zustandsfolge ist die durch eine Operatorfolge aus einem gegebenen Ausgangszustand rekursiv erzeugte geordnete Folge funktionaler Zustände.', '\\boldsymbol z_F^{(n)}=\\left(z_F^{(0)},z_F^{(1)},\\ldots,z_F^{(n)}\\right)', '\\boldsymbol z_F^{(n)}=\\left(z_F^{(0)},z_F^{(1)},\\ldots,z_F^{(n)}\\right)', 'adapted', 40, 'Ausgangszustand und vollständige Operatorfolge.', 'Übertragung der Trajektorienidee auf funktionale Organisationszustände.', 'checked', 62),
(138, '3.4.19', 60, 'Funktionaler Entwicklungspfad', 'Ein funktionaler Entwicklungspfad ist die geordnete alternierende Folge von funktionalen Zuständen und den jeweils zwischen ihnen wirkenden Operatoren.', '\\mathcal P_F^{(n)}=\\left(z_F^{(0)},O_{F,1},z_F^{(1)},\\ldots,O_{F,n},z_F^{(n)}\\right)', '\\mathcal P_F^{(n)}=\\left(z_F^{(0)},O_{F,1},z_F^{(1)},\\ldots,O_{F,n},z_F^{(n)}\\right)', 'adapted', 47, 'Definitionen 3.4.15 bis 3.4.18.', 'Graphentheoretischer Pfadbegriff mit operatorbeschrifteten Übergängen.', 'checked', 62),
(139, '3.4.20', 60, 'Funktionale Übergangsordnung', 'Die funktionale Übergangsordnung ordnet Zustände desselben Entwicklungspfads anhand ihrer Position in der durch Operatoranwendungen erzeugten Zustandsfolge.', 'z_F^{(i)}\\preceq_F z_F^{(j)}\\Longleftrightarrow i\\leq j', 'z_F^{(i)}\\preceq_F z_F^{(j)}\\Longleftrightarrow i\\leq j', 'adapted', 31, 'Ein festgelegter funktionaler Entwicklungspfad.', 'Die Ordnung ist noch keine metrische oder physikalische Zeitstruktur.', 'checked', 62),
(140, '3.4.21', 61, 'Kohärenztragende Relationsstruktur', 'Eine kohärenztragende Relationsstruktur ist eine nichtleere Teilmenge der funktionalen Relationen einer Organisation, deren Erhaltung als Kohärenzbedingung festgelegt wird.', 'mathcal R_F^{K}(mathcal S)subseteqmathcal R_F(mathcal S),quadmathcal R_F^{K}(mathcal S)\neqvarnothing', 'mathcal R_F^{K}(mathcal S)subseteqmathcal R_F(mathcal S),quadmathcal R_F^{K}(mathcal S)\neqvarnothing', 'original', NULL, 'Eine funktionale Organisation und ihre Relationsmenge sind gegeben.', 'Die sachliche Auswahl kohärenztragender Relationen ist Teil der jeweiligen Modellierung.', 'checked', 63),
(141, '3.4.22', 61, 'Funktionale Relationserhaltung', 'Eine kohärenztragende Relation gilt unter einer Operatorwirkung als funktional erhalten, wenn im Folgezustand eine zu ihr funktional äquivalente Relation existiert.', 'r_F^{prime}sim_F r_F', 'r_F^{prime}sim_F r_F', 'original', NULL, 'Funktionale Äquivalenz und kohärenztragende Relationsstruktur.', 'Strenge Identität ist nicht erforderlich.', 'checked', 63),
(142, '3.4.23', 61, 'Kohärenzerhaltender Operator', 'Ein funktionaler Operator ist kohärenzerhaltend, wenn er jede im Ausgangszustand realisierte kohärenztragende Relation durch eine funktional äquivalente Relation im Folgezustand fortführt.', 'forall r_Finmathcal R_F^{K}(mathcal S):r_Fsubseteq z_FLongrightarrowexists r_F^{prime}subseteq O_F(z_F):r_F^{prime}sim_F r_F', 'forall r_Finmathcal R_F^{K}(mathcal S):r_Fsubseteq z_FLongrightarrowexists r_F^{prime}subseteq O_F(z_F):r_F^{prime}sim_F r_F', 'original', NULL, 'Definitionen 3.4.21 und 3.4.22.', 'Kohärenzerhaltung wird relativ zur gewählten Relationsstruktur bestimmt.', 'checked', 63),
(143, '3.4.24', 61, 'Funktional kohärenter Zustand', 'Ein funktionaler Zustand ist bezüglich einer kohärenztragenden Relationsstruktur kohärent, wenn sämtliche darin geforderten Relationen im Zustand realisiert sind.', 'forall r_Finmathcal R_F^{K}(mathcal S):r_Fsubseteq z_F', 'forall r_Finmathcal R_F^{K}(mathcal S):r_Fsubseteq z_F', 'original', NULL, 'Definition 3.4.21.', 'Kohärenz ist keine vom Organisationsbezug unabhängige Zustandseigenschaft.', 'checked', 63),
(144, '3.4.25', 61, 'Funktional kohärenter Entwicklungspfad', 'Ein funktionaler Entwicklungspfad ist kohärent, wenn sein Ausgangszustand kohärent ist und jeder Operator der Folge kohärenzerhaltend wirkt.', 'z_F^{(0)}inOmega_F^{K}(mathcal S),quad O_{F,k}inmathcal O_F^{K}(mathcal S)', 'z_F^{(0)}inOmega_F^{K}(mathcal S),quad O_{F,k}inmathcal O_F^{K}(mathcal S)', 'original', NULL, 'Definition 3.4.19 sowie Definitionen 3.4.23 und 3.4.24.', 'Lokale Kohärenzerhaltung wird auf vollständige Pfade erweitert.', 'checked', 63);
INSERT INTO `definitions` (`definition_id`, `definition_number`, `section_id`, `title`, `definition_text`, `formal_latex`, `word_latex`, `provenance`, `source_id`, `assumptions`, `notes`, `validation_status`, `created_revision_id`) VALUES
(145, '3.4.26', 61, 'Funktionaler Kohärenzbruch', 'Ein funktionaler Kohärenzbruch liegt vor, wenn ein kohärenter Ausgangszustand durch einen Übergang in einen nicht kohärenten Folgezustand überführt wird.', 'z_FinOmega_F^{K}(mathcal S)land z_F^{prime}\notinOmega_F^{K}(mathcal S)', 'z_FinOmega_F^{K}(mathcal S)land z_F^{prime}\notinOmega_F^{K}(mathcal S)', 'original', NULL, 'Definitionen 3.4.22 bis 3.4.25.', 'Mindestens eine kohärenztragende Relation wird nicht funktional äquivalent fortgeführt.', 'checked', 63),
(146, 'Definition 3.4.27', 62, 'Funktionale Erreichbarkeit', 'Ein kohärenter Zustand ist funktional erreichbar, wenn er durch eine endliche Folge kohärenzerhaltender Operatoren aus einem anderen kohärenten Zustand hervorgeht.', 'z_F^{(i)}\\leadsto_F z_F^{(j)}', 'z_F^{(i)}\\leadsto_F z_F^{(j)}', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 64),
(147, 'Definition 3.4.28', 62, 'Wechselseitige funktionale Erreichbarkeit', 'Zwei kohärente Zustände sind wechselseitig funktional erreichbar, wenn beide jeweils vom anderen erreichbar sind.', 'z_F^{(i)}\\leftrightsquigarrow_F z_F^{(j)}', 'z_F^{(i)}\\leftrightsquigarrow_F z_F^{(j)}', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 64),
(148, 'Definition 3.4.29', 62, 'Funktionale Zusammenhangskomponente', 'Die Äquivalenzklasse eines Zustands bezüglich der wechselseitigen funktionalen Erreichbarkeit heißt funktionale Zusammenhangskomponente.', '[z_F]_{\\leftrightsquigarrow_F}', '[z_F]_{\\leftrightsquigarrow_F}', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 64),
(149, 'Definition 3.4.30', 62, 'Unmittelbare funktionale Erreichbarkeit', 'Ein Zustand ist unmittelbar erreichbar, wenn ein einzelner kohärenzerhaltender Operator ihn erzeugt.', 'z_F\\to_F^{K}z_F^{\\prime}', 'z_F\\to_F^{K}z_F^{\\prime}', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 64),
(150, 'Definition 3.4.31', 62, 'Gerichtete funktionale Nachbarschaft', 'Die ausgehende beziehungsweise eingehende Nachbarschaft enthält die in einem Schritt erreichbaren Folgezustände beziehungsweise Vorgängerzustände.', '\\mathcal N_F^{+}(z_F),\\mathcal N_F^{-}(z_F)', '\\mathcal N_F^{+}(z_F),\\mathcal N_F^{-}(z_F)', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 64),
(151, 'Definition 3.4.32', 62, 'Funktionale Raumstruktur', 'Die funktionale Raumstruktur ist der kohärente Zustandsraum zusammen mit seiner Erreichbarkeits- oder unmittelbaren Übergangsrelation.', '\\mathfrak R_F^{K}(\\mathcal S)=\\left(\\Omega_F^{K}(\\mathcal S),\\leadsto_F\\right)', '\\mathfrak R_F^{K}(\\mathcal S)=\\left(\\Omega_F^{K}(\\mathcal S),\\leadsto_F\\right)', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 64),
(152, 'Definition 3.4.33', 62, 'Länge eines funktionalen Entwicklungspfads', 'Die funktionale Pfadlänge ist die Anzahl der Operatorwirkungen eines endlichen Entwicklungspfads.', '\\ell_F(\\mathcal P_F^{(n)})=n', '\\ell_F(\\mathcal P_F^{(n)})=n', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 64),
(153, 'Definition 3.4.34', 62, 'Funktionale Übergangsdistanz', 'Die funktionale Übergangsdistanz ist die minimale Länge aller gerichteten funktionalen Pfade zwischen zwei Zuständen.', '\\delta_F(z_F^{(i)},z_F^{(j)})', '\\delta_F(z_F^{(i)},z_F^{(j)})', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 64),
(154, 'Definition 3.4.35', 62, 'Funktionale Übergangsrichtung', 'Die funktionale Übergangsrichtung ist die durch einen Operator erzeugte funktionale Differenz zwischen Ausgangs- und Folgezustand.', '\\vec{\\rho}_F(z_F,O_F)=\\Delta_F(z_F,O_F(z_F))', '\\vec{\\rho}_F(z_F,O_F)=\\Delta_F(z_F,O_F(z_F))', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 64),
(155, 'Definition 3.4.36', 63, 'Unmittelbare funktionale Nachfolge', 'Ein kohärenter Zustand ist unmittelbarer funktionaler Nachfolger eines anderen, wenn er durch einen kohärenzerhaltenden Operator erzeugt wird und vom Ausgangszustand verschieden ist.', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 65),
(156, 'Definition 3.4.37', 63, 'Funktionale Vorgängerrelation', 'Ein Zustand ist funktionaler Vorgänger eines anderen, wenn zwischen beiden die unmittelbare Nachfolgerrelation besteht.', '\\operatorname{Pred}_F(z_F),\\operatorname{Succ}_F(z_F)', '\\operatorname{Pred}_F(z_F),\\operatorname{Succ}_F(z_F)', 'original', NULL, 'Kohärenter Zustandsraum und kohärenzerhaltende Operatoren.', NULL, 'checked', 65),
(157, 'Definition 3.4.38', 63, 'Funktionale Vorordnung', 'Ein Zustand ist funktional früher als ein anderer, wenn eine endliche Folge nichtidentischer kohärenzerhaltender Übergänge zwischen ihnen existiert.', 'z_F^{(i)}\\prec_F^{*}z_F^{(j)}', 'z_F^{(i)}\\prec_F^{*}z_F^{(j)}', 'original', NULL, 'Unmittelbare funktionale Nachfolge.', NULL, 'checked', 65),
(158, 'Definition 3.4.39', 63, 'Funktionaler Zyklus', 'Ein funktionaler Zyklus ist eine endliche Folge nichtidentischer Nachfolgeübergänge, die erneut den Ausgangszustand erreicht.', '\\mathcal C_F=(z_F^{(0)},\\ldots,z_F^{(n)}),\\;z_F^{(0)}=z_F^{(n)}', '\\mathcal C_F=(z_F^{(0)},\\ldots,z_F^{(n)}),\\;z_F^{(0)}=z_F^{(n)}', 'original', NULL, 'Funktionale Vorordnung und kohärenzerhaltende Übergänge.', NULL, 'checked', 65),
(159, 'Definition 3.4.40', 63, 'Azyklischer funktionaler Bereich', 'Ein kohärenter Zustandsbereich ist azyklisch, wenn kein Zustand über einen nichtleeren funktionalen Pfad zu sich selbst zurückkehrt.', '\\Omega_F^{A}(\\mathcal S)\\subseteq\\Omega_F^{K}(\\mathcal S)', '\\Omega_F^{A}(\\mathcal S)\\subseteq\\Omega_F^{K}(\\mathcal S)', 'original', NULL, 'Funktionale Vorordnung.', NULL, 'checked', 65),
(160, 'Definition 3.4.41', 63, 'Funktionale Zustandsinstanz', 'Eine funktionale Zustandsinstanz verbindet einen Zustand mit seiner Position innerhalb eines bestimmten Entwicklungspfads.', '\\zeta_F^{(k)}=(z_F^{(k)},k)', '\\zeta_F^{(k)}=(z_F^{(k)},k)', 'original', NULL, 'Geordneter funktionaler Entwicklungspfad.', NULL, 'checked', 65),
(161, 'Definition 3.4.42', 63, 'Instanzielle funktionale Vorordnung', 'Zustandsinstanzen desselben Entwicklungspfads werden entsprechend ihrer Positionsindizes streng oder reflexiv geordnet.', '\\zeta_F^{(i)}\\triangleleft_F\\zeta_F^{(j)}\\Longleftrightarrow i<j', '\\zeta_F^{(i)}\\triangleleft_F\\zeta_F^{(j)}\\Longleftrightarrow i<j', 'original', NULL, 'Funktionale Zustandsinstanzen.', NULL, 'checked', 65),
(162, 'Definition 3.4.43', 63, 'Funktionale Zeitstruktur eines Entwicklungspfads', 'Die funktionale Zeitstruktur ist die geordnete Menge der Zustandsinstanzen eines Entwicklungspfads.', '\\mathfrak T_F(\\mathcal P_F^{(n)})=(\\mathcal Z_F(\\mathcal P_F^{(n)}),\\unlhd_F)', '\\mathfrak T_F(\\mathcal P_F^{(n)})=(\\mathcal Z_F(\\mathcal P_F^{(n)}),\\unlhd_F)', 'original', NULL, 'Funktionale Zustandsinstanzen und instanzielle Vorordnung.', NULL, 'checked', 65),
(163, 'Definition 3.4.44', 63, 'Diskrete funktionale Zeitdifferenz', 'Die diskrete funktionale Zeitdifferenz ist die Anzahl der Übergangsschritte zwischen zwei geordneten Zustandsinstanzen desselben Pfades.', '\\Delta\\tau_F(\\zeta_F^{(i)},\\zeta_F^{(j)})=j-i', '\\Delta\\tau_F(\\zeta_F^{(i)},\\zeta_F^{(j)})=j-i', 'original', NULL, 'Funktionale Zeitstruktur eines Entwicklungspfads.', NULL, 'checked', 65),
(164, 'Definition 3.4.45', 63, 'Funktionales Übergangsgewicht', 'Ein funktionales Übergangsgewicht ordnet einer ausgeführten Operatorwirkung in einem Zustand einen nichtnegativen Wert zu.', 'w_F:\\mathcal O_F^{K}(\\mathcal S)\\times\\Omega_F^{K}(\\mathcal S)\\to\\mathbb R_{\\geq0}', 'w_F:\\mathcal O_F^{K}(\\mathcal S)\\times\\Omega_F^{K}(\\mathcal S)\\to\\mathbb R_{\\geq0}', 'original', NULL, 'Kohärenzerhaltende Operatoren und funktionale Zustände.', NULL, 'checked', 65),
(165, 'Definition 3.4.46', 63, 'Gewichtete funktionale Zeitdifferenz', 'Die gewichtete funktionale Zeitdifferenz ist die Summe der Übergangsgewichte zwischen zwei Zustandsinstanzen.', '\\Delta\\tau_F^{w}=\\sum w_F(O_F,z_F)', '\\Delta\\tau_F^{w}=\\sum w_F(O_F,z_F)', 'original', NULL, 'Funktionales Übergangsgewicht und geordneter Entwicklungspfad.', NULL, 'checked', 65),
(166, 'Definition 3.4.47', 63, 'Funktionale Unvergleichbarkeit', 'Zwei Zustände sind funktional unvergleichbar, wenn in keiner Richtung eine funktionale Vorordnung besteht.', 'z_F^{(i)}\\parallel_F z_F^{(j)}', 'z_F^{(i)}\\parallel_F z_F^{(j)}', 'original', NULL, 'Partielle funktionale Vorordnung.', NULL, 'checked', 65),
(167, 'Definition 3.4.48', 63, 'Funktionaler Zeitschnitt', 'Ein funktionaler Zeitschnitt ist eine Menge paarweise funktional unvergleichbarer Zustände.', '\\Sigma_F\\subseteq\\Omega_F^{K}(\\mathcal S)', '\\Sigma_F\\subseteq\\Omega_F^{K}(\\mathcal S)', 'original', NULL, 'Funktionale Unvergleichbarkeit und partielle Ordnung.', NULL, 'checked', 65),
(168, 'Definition 3.4.49', 63, 'Funktionale Zeitrichtung', 'Die funktionale Zeitrichtung ist die gerichtete Ordnung vom funktionalen Vorgänger zum funktionalen Nachfolger.', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'original', NULL, 'Funktionale Nachfolge und Vorordnung.', NULL, 'checked', 65),
(169, 'Definition 3.4.50', 64, 'Funktionales Raum-Zeit-Ereignis', 'Ein funktionales Raum-Zeit-Ereignis verbindet einen funktionalen Zustand mit seiner konkreten Zustandsinstanz innerhalb eines Entwicklungspfads.', '\\varepsilon_F^{(k)}=\\left(z_F^{(k)},\\zeta_F^{(k)}\\right)', '\\varepsilon_F^{(k)}=\\left(z_F^{(k)},\\zeta_F^{(k)}\\right)', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(170, 'Definition 3.4.51', 64, 'Unmittelbare funktionale Raum-Zeit-Nachbarschaft', 'Zwei Ereignisse sind unmittelbar funktional raum-zeitlich benachbart, wenn ihre Zustände unmittelbar funktional aufeinanderfolgen und ihre Instanzindizes sich um eins unterscheiden.', '\\varepsilon_F^{(i)}\\blacktriangleright_F\\varepsilon_F^{(j)}', '\\varepsilon_F^{(i)}\\blacktriangleright_F\\varepsilon_F^{(j)}', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(171, 'Definition 3.4.52', 64, 'Funktionaler Raum-Zeit-Pfad', 'Ein funktionaler Raum-Zeit-Pfad ist eine endliche Folge unmittelbar benachbarter funktionaler Raum-Zeit-Ereignisse.', '\\Gamma_F^{(n)}=\\left(\\varepsilon_F^{(0)},\\ldots,\\varepsilon_F^{(n)}\\right)', '\\Gamma_F^{(n)}=\\left(\\varepsilon_F^{(0)},\\ldots,\\varepsilon_F^{(n)}\\right)', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(172, 'Definition 3.4.53', 64, 'Gewichtete funktionale Raum-Zeit-Pfadlänge', 'Die gewichtete Raum-Zeit-Pfadlänge ist die Summe der Gewichte aller Operatorwirkungen entlang eines Raum-Zeit-Pfads.', 'L_F^{w}(\\Gamma_F^{(n)})=\\sum_{k=0}^{n-1}w_F(O_{F,k+1},z_F^{(k)})', 'L_F^{w}(\\Gamma_F^{(n)})=\\sum_{k=0}^{n-1}w_F(O_{F,k+1},z_F^{(k)})', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(173, 'Definition 3.4.54', 64, 'Funktionale Raum-Zeit-Struktur', 'Eine funktionale Raum-Zeit-Struktur vereinigt Ereignismenge, gerichtete Nachbarschaft, Erreichbarkeit, Vorordnung und optionale Übergangsgewichtung.', '\\mathfrak{RZ}_F=(\\mathcal E_F,\\blacktriangleright_F,\\leadsto_F,\\preceq_F,w_F)', '\\mathfrak{RZ}_F=(\\mathcal E_F,\\blacktriangleright_F,\\leadsto_F,\\preceq_F,w_F)', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(174, 'Definition 3.4.55', 64, 'Gerichteter funktionaler Raum-Zeit-Abstand', 'Der gerichtete funktionale Raum-Zeit-Abstand ist das Infimum der gewichteten Längen aller gerichteten Raum-Zeit-Pfade zwischen zwei Ereignissen.', 'd_{RZ,F}(\\varepsilon_i,\\varepsilon_j)=\\inf_{\\Gamma_F}L_F^w(\\Gamma_F)', 'd_{RZ,F}(\\varepsilon_i,\\varepsilon_j)=\\inf_{\\Gamma_F}L_F^w(\\Gamma_F)', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(175, 'Definition 3.4.56', 64, 'Funktionaler Zukunftskegel', 'Der funktionale Zukunftskegel enthält alle Ereignisse, die funktional nach einem gegebenen Ereignis liegen.', 'J_F^+(\\varepsilon_F)=\\{\\varepsilon_F\'\\in\\mathcal E_F\\mid\\varepsilon_F\\preceq_F\\varepsilon_F\'\\}', 'J_F^+(\\varepsilon_F)=\\{\\varepsilon_F\'\\in\\mathcal E_F\\mid\\varepsilon_F\\preceq_F\\varepsilon_F\'\\}', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(176, 'Definition 3.4.57', 64, 'Funktionaler Vergangenheitskegel', 'Der funktionale Vergangenheitskegel enthält alle Ereignisse, die funktional vor einem gegebenen Ereignis liegen.', 'J_F^-(\\varepsilon_F)=\\{\\varepsilon_F\'\\in\\mathcal E_F\\mid\\varepsilon_F\'\\preceq_F\\varepsilon_F\\}', 'J_F^-(\\varepsilon_F)=\\{\\varepsilon_F\'\\in\\mathcal E_F\\mid\\varepsilon_F\'\\preceq_F\\varepsilon_F\\}', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(177, 'Definition 3.4.58', 64, 'Funktionale Gleichzeitigkeit', 'Zwei Ereignisse sind funktional gleichzeitig, wenn sie zu demselben funktionalen Zeitschnitt gehören und funktional unvergleichbar sind.', '\\varepsilon_F^{(i)}\\sim_{\\tau_F}\\varepsilon_F^{(j)}', '\\varepsilon_F^{(i)}\\sim_{\\tau_F}\\varepsilon_F^{(j)}', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(178, 'Definition 3.4.59', 64, 'Kohärenter funktionaler Raum-Zeit-Pfad', 'Ein Raum-Zeit-Pfad ist kohärent, wenn jeder Übergang durch einen kohärenzerhaltenden Operator erzeugt wird und alle Zustände kohärent bleiben.', 'O_{F,k}\\in\\mathcal O_F^K(\\mathcal S)', 'O_{F,k}\\in\\mathcal O_F^K(\\mathcal S)', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(179, 'Definition 3.4.60', 64, 'Lokale funktionale Raum-Zeit-Struktur', 'Eine lokale funktionale Raum-Zeit-Struktur ist die Einschränkung einer Raum-Zeit-Struktur auf eine ausgewählte lokale Ereignismenge.', '\\mathfrak{RZ}_F^{\\mathrm{lok}}=\\mathfrak{RZ}_F|_{\\mathcal E_F^{\\mathrm{lok}}}', '\\mathfrak{RZ}_F^{\\mathrm{lok}}=\\mathfrak{RZ}_F|_{\\mathcal E_F^{\\mathrm{lok}}}', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(180, 'Definition 3.4.61', 64, 'Globale funktionale Raum-Zeit-Struktur', 'Die globale funktionale Raum-Zeit-Struktur ist die Vereinigung aller lokalen Ereigniskomponenten und ihrer zulässigen Übergänge.', '\\mathfrak{RZ}_F^{\\mathrm{glob}}=\\bigcup_{\\alpha\\in A}\\mathfrak{RZ}_{F,\\alpha}^{\\mathrm{lok}}', '\\mathfrak{RZ}_F^{\\mathrm{glob}}=\\bigcup_{\\alpha\\in A}\\mathfrak{RZ}_{F,\\alpha}^{\\mathrm{lok}}', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(181, 'Definition 3.4.62', 64, 'Funktionaler Raum-Zeit-Isomorphismus', 'Ein funktionaler Raum-Zeit-Isomorphismus ist eine bijektive Abbildung, welche Nachbarschaft, Vorordnung und gegebenenfalls Übergangsgewichte erhält.', '\\Phi_F:\\mathcal E_F\\to\\mathcal E_F\'', '\\Phi_F:\\mathcal E_F\\to\\mathcal E_F\'', 'original', NULL, 'Abschnitte 3.4.6 bis 3.4.9.', 'FRZK-spezifische Rekonstruktion.', 'checked', 66),
(182, 'Definition 3.4.63', 50, 'Funktionale Operatorsequenz', 'Eine funktionale Operatorsequenz ist eine geordnete Folge zulässiger funktionaler Operatoren.', '\\mathcal O_F^{(n)}=(O_{F,1},...,O_{F,n})', '\\mathcal O_F^{(n)}=(O_{F,1},...,O_{F,n})', 'original', NULL, 'Zulässige Operatoren.', 'Grundlage funktionaler Dynamik.', 'checked', 67),
(183, 'Definition 3.4.64', 50, 'Funktionale Trajektorie', 'Eine funktionale Trajektorie ist eine geordnete Folge funktionaler Zustände.', '\\gamma_F^{(n)}=(z_F^{(0)},...,z_F^{(n)})', '\\gamma_F^{(n)}=(z_F^{(0)},...,z_F^{(n)})', 'original', NULL, 'Operatorsequenz vorhanden.', 'Verbindung von Dynamik und Raum-Zeit.', 'checked', 67),
(187, 'Definition 3.4.65', 50, 'Funktionaler Dynamikoperator', 'Der funktionale Dynamikoperator ist eine Abbildung des funktionalen Zustandsraums auf sich selbst.', '\\mathcal D_F:\\Omega_F(\\mathcal S)\\rightarrow\\Omega_F(\\mathcal S)', '\\mathcal D_F:\\Omega_F(\\mathcal S)\\rightarrow\\Omega_F(\\mathcal S)', 'original', NULL, 'Funktionaler Zustandsraum vorhanden.', 'Grundlage der dynamischen Erweiterung.', 'checked', 69),
(188, 'Definition 3.4.66', 50, 'Kohärenzerhaltender Dynamikoperator', 'Ein Dynamikoperator heißt kohärenzerhaltend, wenn kohärente Zustände in kohärente Zustände überführt werden.', 'z_F\\in\\Omega_F^K\\Rightarrow\\mathcal D_F(z_F)\\in\\Omega_F^K', 'z_F\\in\\Omega_F^K\\Rightarrow\\mathcal D_F(z_F)\\in\\Omega_F^K', 'original', NULL, 'Kohärenter Zustandsraum.', 'Erweiterung der Operator-Kohärenz.', 'checked', 69),
(189, 'Definition 3.4.67', 50, 'Dynamische funktionale Raum-Zeit-Struktur', 'Eine funktionale Raum-Zeit-Struktur mit Dynamikoperator wird als dynamische funktionale Raum-Zeit-Struktur bezeichnet.', '\\mathfrak{RZ}_F^{dyn}=(\\mathfrak{RZ}_F,\\mathcal D_F)', '\\mathfrak{RZ}_F^{dyn}=(\\mathfrak{RZ}_F,\\mathcal D_F)', 'original', NULL, 'Existenz einer funktionalen Raum-Zeit-Struktur.', 'Verbindung von Struktur und Entwicklung.', 'checked', 69),
(190, 'Definition 3.4.68', 50, 'Funktionale Stabilität', 'Ein funktionaler Zustand bleibt stabil, wenn seine Entwicklung innerhalb derselben funktionalen Kohärenzklasse verbleibt.', 'z_F^{(k)}\\in[z_F]_{\\sim_F}\\Rightarrow z_F^{(k+n)}\\in[z_F]_{\\sim_F}', 'z_F^{(k)}\\in[z_F]_{\\sim_F}\\Rightarrow z_F^{(k+n)}\\in[z_F]_{\\sim_F}', 'original', NULL, 'Funktionale Äquivalenzrelation.', 'Stabilität als Strukturerhaltung.', 'checked', 70),
(191, 'Definition 3.4.69', 50, 'Kohärenzstabiler Dynamikbereich', 'Ein Bereich heißt kohärenzstabil, wenn er durch den Dynamikoperator invariant bleibt.', '\\mathcal D_F(\\mathcal B_F)\\subseteq\\mathcal B_F', '\\mathcal D_F(\\mathcal B_F)\\subseteq\\mathcal B_F', 'original', NULL, 'Dynamikoperator definiert.', 'Invarianter Entwicklungsbereich.', 'checked', 70),
(192, 'Definition 3.4.70', 50, 'Funktionaler Attraktor', 'Eine funktionale Zustandsmenge ist Attraktor, wenn Entwicklungen aus einem Einzugsbereich langfristig in diese Menge führen.', '\\lim_{n\\rightarrow\\infty}\\mathcal D_F^n(z_F)\\in\\mathcal A_F', '\\lim_{n\\rightarrow\\infty}\\mathcal D_F^n(z_F)\\in\\mathcal A_F', 'original', NULL, 'Dynamikoperator vorhanden.', 'Erweiterung klassischer Attraktorkonzepte.', 'checked', 70),
(193, 'Definition 3.4.71', 50, 'Funktionale Instabilität', 'Ein Zustand ist funktional instabil, wenn seine Entwicklung seine bisherige Kohärenzklasse verlässt.', 'z_F\\in[z_F]_{\\sim_F}\\land\\mathcal D_F(z_F)\\notin[z_F]_{\\sim_F}', 'z_F\\in[z_F]_{\\sim_F}\\land\\mathcal D_F(z_F)\\notin[z_F]_{\\sim_F}', 'original', NULL, 'Kohärenzklasse definiert.', 'Grundlage funktionaler Übergänge.', 'checked', 71),
(194, 'Definition 3.4.72', 50, 'Funktionale Stabilitätsdomäne', 'Eine Stabilitätsdomäne ist ein unter dem Dynamikoperator invariantes Zustandsgebiet.', '\\mathcal D_F(\\mathcal S_F^{stab})\\subseteq\\mathcal S_F^{stab}', '\\mathcal D_F(\\mathcal S_F^{stab})\\subseteq\\mathcal S_F^{stab}', 'original', NULL, 'Dynamikoperator vorhanden.', 'Stabilitätsbereich.', 'checked', 71),
(195, 'Definition 3.4.73', 50, 'Funktionaler Übergangszustand', 'Ein Übergangszustand ermöglicht mehrere zukünftige funktionale Organisationsformen.', '\\Omega_F^{trans}', '\\Omega_F^{trans}', 'original', NULL, 'Mehrere Attraktoren möglich.', 'Übergangsbereich.', 'checked', 71),
(196, 'Definition 3.4.74', 50, 'Funktionaler Kipppunkt', 'Ein Kipppunkt ist ein Zustand, bei dem kleine Änderungen der Operatorbedingungen zu unterschiedlichen langfristigen Attraktoren führen.', 'z_F^{crit}', 'z_F^{crit}', 'original', NULL, 'Dynamische Entwicklung vorhanden.', 'Grenze verschiedener Entwicklungsregime.', 'checked', 71),
(197, 'Definition 3.4.75', 50, 'Funktionale Emergenz', 'Eine funktionale Eigenschaft entsteht aus der Kopplung mehrerer funktionaler Strukturen.', 'E_F(\\mathfrak{RZ}_{F}^{glob})\\neq\\sum_{\\alpha}E_F(\\mathfrak{RZ}_{F,\\alpha})', 'E_F(\\mathfrak{RZ}_{F}^{glob})\\neq\\sum_{\\alpha}E_F(\\mathfrak{RZ}_{F,\\alpha})', 'original', NULL, 'Mehrere gekoppelte Strukturen.', 'Neue Organisationsebene.', 'checked', 72),
(198, 'Definition 3.4.76', 50, 'Funktionale Kopplungsstruktur', 'Eine Kopplungsstruktur beschreibt zusätzliche Relationen zwischen funktionalen Strukturen.', '\\mathcal C_F\\subset\\mathcal R_F', '\\mathcal C_F\\subset\\mathcal R_F', 'original', NULL, 'Funktionale Relationen vorhanden.', 'Grundlage funktionaler Emergenz.', 'checked', 72),
(199, 'Definition 3.4.81', 50, 'Vollständige funktionale Raum-Zeit-Struktur', 'Eine vollständige funktionale Raum-Zeit-Struktur verbindet Zustandsraum, Ereignisse, Relationen, Dynamik und Kopplungsstruktur.', '\\mathfrak{FRZ}_F=(\\Omega_F,\\mathcal E_F,\\mathcal R_F,\\mathcal D_F,\\mathcal C_F)', '\\mathfrak{FRZ}_F=(\\Omega_F,\\mathcal E_F,\\mathcal R_F,\\mathcal D_F,\\mathcal C_F)', 'original', NULL, 'Funktionaler Zustandsraum, Relationen und Dynamikoperator vorhanden.', 'Abschlussdefinition Kapitel 3.4.', 'checked', 73),
(200, '', 98, 'Funktionale Operatorenkaskade', 'Eine funktionale Operatorenkaskade bezeichnet eine geordnete Folge zulässiger Transformationen.', NULL, NULL, 'original', NULL, NULL, NULL, 'draft', 93),
(202, 'D-3.7.2-1', 101, 'Operatoren σ, M, R, E', 'Definition der Operatoren innerhalb der funktionalen Operatorenkaskade: Selektionsoperator σ, Mapping-Operator M, Transformationsoperator R, Emergenzoperator E.', NULL, NULL, 'original', NULL, NULL, NULL, 'draft', 96),
(204, 'D-3.7.3-1', 103, 'Parametrisierung und Zustandsübergänge', 'Die Operatoren der Kaskade werden parametrisiert, und jeder Zustandsübergang wird rekursiv aus dem vorherigen Zustand berechnet. Dies ermöglicht Simulation und dynamische Analyse.', NULL, NULL, 'original', NULL, NULL, NULL, 'draft', 98),
(205, 'D-3.7.4-1', 104, 'Algorithmische Umsetzung', 'Die Operatorenkaskade wird algorithmisch umgesetzt, indem jeder Operator sukzessive auf den aktuellen Zustand angewendet wird. Dies ermöglicht Simulation, Analyse und Validierung der Zustandsentwicklung.', NULL, NULL, 'original', NULL, NULL, NULL, 'draft', 99),
(206, 'D-3.7.5-1', 105, 'Kohärenzfunktion', 'Kohärenzfunktion K bewertet jeden Zustand S_t der Operatorenkaskade. Ein Wert K(S_t)=1 entspricht maximaler Kohärenz; K(S_t)=0 zeigt Verlust der funktionalen Organisation.', NULL, NULL, 'original', NULL, NULL, NULL, 'draft', 100),
(207, 'D-3.7.6-1', 106, 'Python-Operatorenkaskade', 'Die Python-Implementierung simuliert die Operatorenkaskade Schritt für Schritt: S0 initialisieren, σ, M, R, E in Reihenfolge anwenden, Kohärenz prüfen, Endzustand speichern.', NULL, NULL, 'original', NULL, NULL, NULL, 'draft', 101),
(208, 'D-3.7.7-1', 107, 'Validierungsfunktion der Operatorenkaskade', 'Die Validierungsfunktion V überprüft, ob ein Folgezustand S_{t+1} die minimale Kohärenz erfüllt und alle Relationen intakt sind. V(S_{t+1})=1 bedeutet gültig, V(S_{t+1})=0 bedeutet inkonsistent.', NULL, NULL, 'original', NULL, NULL, NULL, 'draft', 102),
(209, 'D-3.7.8-1', 108, 'Zusammenfassung der Operatorenkaskade', 'Die Operatorenkaskade fasst alle vorherigen Schritte zusammen: Iterative Anwendung von σ, M, R, E, inklusive Kohärenzprüfung K(S_{t+1}) und Validierung V(S_{t+1}).', NULL, NULL, 'original', NULL, NULL, NULL, 'draft', 103),
(210, 'D-3.8-1', 109, 'Simulation der Operatorenkaskade', 'Simulation der Operatorenkaskade zur Analyse der dynamischen Entwicklung funktionaler Zustände, inkl. Kohärenzprüfung und Emergenzvalidierung.', NULL, NULL, 'original', NULL, NULL, NULL, 'draft', 104),
(211, '3.8.3.1', 112, 'Parameterraum der Operatorenkaskade', 'Der Parameterraum Theta umfasst sämtliche operatorbezogenen Teilvektoren, die einen Simulationslauf der Operatorenkaskade bestimmen.', '\\Theta=\\left(\\theta_{\\sigma},\\theta_M,\\theta_R,\\theta_E\\right)', '\\Theta=\\left(\\theta_{\\sigma},\\theta_M,\\theta_R,\\theta_E\\right)', 'original', NULL, 'Die Operatoren sigma, M, R und E sind bereits definiert.', 'Definition zur formalen Trennung der vier operatorbezogenen Parametergruppen.', 'draft', 107),
(212, '3.8.3.2', 112, 'Simulationskonfiguration', 'Eine Simulationskonfiguration Sigma besteht aus dem Anfangszustand, dem vollständigen Parameterraum, der minimalen Kohärenz, der numerischen Konvergenzschranke und der maximalen Iterationszahl.', '\\Sigma=\\left(S_0,\\Theta,\\kappa_{\\min},\\varepsilon,T_{\\max}\\right)', '\\Sigma=\\left(S_0,\\Theta,\\kappa_{\\min},\\varepsilon,T_{\\max}\\right)', 'original', NULL, 'Alle Bestandteile der Konfiguration sind vor Beginn des Simulationslaufs eindeutig festgelegt.', 'Die Definition bildet die Grundlage der Reproduzierbarkeit.', 'draft', 107),
(213, '3.8.3.3', 112, 'Zulässiger Parameterraum', 'Der zulässige Parameterraum Omega_Theta enthält genau diejenigen Parametrisierungen, welche die für das Modell festgelegten Definitions-, Werte- und Gültigkeitsbedingungen erfüllen.', '\\Theta\\in\\Omega_{\\Theta}', '\\Theta\\in\\Omega_{\\Theta}', 'adapted', 129, 'Für jeden Einzelparameter ist ein zulässiger Wertebereich definiert.', 'Literaturgestützte Einordnung numerischer Zulässigkeits- und Stabilitätsbedingungen.', 'draft', 107),
(214, '3.8.3.4', 112, 'Reproduzierbare Parametrisierung', 'Eine Parametrisierung heißt reproduzierbar, wenn identische Simulationskonfigurationen bei deterministischer Operatorenkaskade dieselbe Zustandstrajektorie erzeugen.', '\\Sigma_1=\\Sigma_2\\Longrightarrow\\Gamma_1=\\Gamma_2', '\\Sigma_1=\\Sigma_2\\Longrightarrow\\Gamma_1=\\Gamma_2', 'original', NULL, 'Die Operatorenkaskade ist deterministisch und verwendet keine nicht dokumentierten Zustands- oder Zufallsgrößen.', 'Bei stochastischen Erweiterungen muss zusätzlich der Zufallsstartwert dokumentiert werden.', 'draft', 107),
(218, '3.8.4.1', 113, 'Zielgrößenvektor', 'Der Zielgrößenvektor fasst die zur Bewertung eines Simulationslaufs verwendeten Endgrößen Kohärenz, Referenzabweichung, Konvergenz, Iterationszahl und Validität zusammen.', '\\mathbf{Y}(\\Sigma)=\\left(K_T,D_T,C_T,N_T,V_T\\right)', '\\mathbf{Y}(\\Sigma)=\\left(K_T,D_T,C_T,N_T,V_T\\right)', 'original', NULL, 'Die fünf Zielgrößen sind für jeden ausgewerteten Simulationslauf definiert.', 'Grundlage des vergleichenden Versuchsdesigns.', 'draft', 108),
(219, '3.8.4.2', 113, 'Baseline-Szenario', 'Das Baseline-Szenario ist eine methodisch festgelegte Referenzkonfiguration, gegenüber der sämtliche kontrollierten Varianten verglichen werden.', '\\Sigma^{(0)}=\\left(S_0,\\Theta^{(0)},\\kappa_{\\min}^{(0)},\\varepsilon^{(0)},T_{\\max}^{(0)}\\right)', '\\Sigma^{(0)}=\\left(S_0,\\Theta^{(0)},\\kappa_{\\min}^{(0)},\\varepsilon^{(0)},T_{\\max}^{(0)}\\right)', 'original', NULL, 'Die Referenzwerte aller Komponenten sind vollständig dokumentiert.', 'Das Baseline-Szenario ist kein empirisch bestätigter Normalzustand.', 'draft', 108),
(220, '3.8.4.3', 113, 'Grenzszenario', 'Ein Grenzszenario liegt vor, wenn mindestens ein Parameter einen unteren oder oberen Rand seines zulässigen Intervalls annimmt.', '\\theta_i\\in\\left\\{\\inf I_i,\\sup I_i\\right\\}', '\\theta_i\\in\\left\\{\\inf I_i,\\sup I_i\\right\\}', 'adapted', 131, 'Das zulässige Intervall I_i ist bestimmt und nicht leer.', 'Dient der Prüfung des Modellverhaltens an Randwerten.', 'draft', 108),
(221, '3.8.4.4', 113, 'Fehlerszenario', 'Ein Fehlerszenario liegt vor, wenn die vollständige Parametrisierung den zulässigen Parameterraum verlässt.', '\\Theta\\notin\\Omega_{\\Theta}', '\\Theta\\notin\\Omega_{\\Theta}', 'original', NULL, 'Der zulässige Parameterraum Omega_Theta wurde zuvor definiert.', 'Ein Fehlerszenario darf nicht als regulärer Modelllauf interpretiert werden.', 'draft', 108),
(222, '3.8.4.5', 113, 'Versuchsmenge', 'Die Versuchsmenge enthält die Baseline-Konfiguration sowie alle Einzelparameter-, Mehrparameter-, Grenz-, Fehler- und Anfangswertszenarien.', '\\mathcal{E}=\\left\\{\\Sigma^{(0)},\\Sigma_i^{(\\delta)},\\Sigma_{ij}^{(\\delta_i,\\delta_j)},\\Sigma^{(\\mathrm{G})},\\Sigma^{(\\mathrm{F})},\\Sigma^{(\\mathrm{A})}\\right\\}', '\\mathcal{E}=\\left\\{\\Sigma^{(0)},\\Sigma_i^{(\\delta)},\\Sigma_{ij}^{(\\delta_i,\\delta_j)},\\Sigma^{(\\mathrm{G})},\\Sigma^{(\\mathrm{F})},\\Sigma^{(\\mathrm{A})}\\right\\}', 'original', NULL, 'Jede Konfiguration der Versuchsmenge besitzt eine eindeutige Kennung und vollständige Dokumentation.', 'Zusammenfassung des vollständigen experimentellen Designs.', 'draft', 108),
(225, '3.8.5.1', 114, 'Bewertungsvektor', 'Der Bewertungsvektor fasst Kohärenz, Konvergenz, Robustheit, Sensitivität, Validität und Emergenz eines Simulationslaufs zusammen.', '\\mathbf{B}=\\left(K,C,R,S,V,E\\right)', '\\mathbf{B}=\\left(K,C,R,S,V,E\\right)', 'original', NULL, 'Alle sechs Bewertungsgrößen sind definiert oder als nicht auswertbar gekennzeichnet.', 'Übergeordnete Zusammenfassung der Bewertungsmetriken.', 'draft', 109),
(226, '3.8.5.2', 114, 'Robustheitsmaß', 'Das Robustheitsmaß bewertet die Unempfindlichkeit einer Trajektorie gegenüber einer festgelegten kleinen Änderung der Eingangsbedingungen.', 'R=1-\\frac{d_\\Gamma(\\Gamma,\\Gamma^{(\\delta)})}{d_{\\max}}', 'R=1-\\frac{d_\\Gamma(\\Gamma,\\Gamma^{(\\delta)})}{d_{\\max}}', 'original', 133, 'Der Trajektorienabstand ist normiert und d_max ist positiv.', 'Hohe Werte kennzeichnen geringe Abweichung.', 'draft', 109),
(227, '3.8.5.3', 114, 'Sensitivitätsmaß', 'Das Sensitivitätsmaß beschreibt die Trajektorienänderung pro Größe der zugrunde liegenden Parameteränderung.', 'S=\\frac{d_\\Gamma(\\Gamma,\\Gamma+\\Delta\\Gamma)}{\\|\\Delta\\Theta\\|}', 'S=\\frac{d_\\Gamma(\\Gamma,\\Gamma+\\Delta\\Gamma)}{\\|\\Delta\\Theta\\|}', 'adapted', 133, 'Die Parameteränderung ist von null verschieden.', 'Große Werte kennzeichnen empfindliche Parameterbereiche.', 'draft', 109),
(228, '3.8.5.4', 114, 'Formale Validität', 'Die formale Validität ist genau dann eins, wenn die Parametrisierung innerhalb des zulässigen Parameterraums liegt.', 'V=\\begin{cases}1,&\\Theta\\in\\Omega_\\Theta\\\\0,&\\Theta\\notin\\Omega_\\Theta\\end{cases}', 'V=\\begin{cases}1,&\\Theta\\in\\Omega_\\Theta\\\\0,&\\Theta\\notin\\Omega_\\Theta\\end{cases}', 'original', NULL, 'Omega_Theta ist vollständig festgelegt.', 'Ungültige Simulationen werden nicht wissenschaftlich interpretiert.', 'draft', 109),
(229, '3.8.5.5', 114, 'Emergenzmaß', 'Das Emergenzmaß beschreibt die zeitbezogene Veränderung des Organisationsgrades.', 'E=\\frac{\\Delta O}{\\Delta t}', 'E=\\frac{\\Delta O}{\\Delta t}', 'original', NULL, 'Der Organisationsgrad O und das Zeitintervall sind definiert.', 'Eine Emergenzschwelle wird gesondert festgelegt.', 'draft', 109),
(230, '3.8.5.6', 114, 'Gesamtqualitätsindex', 'Der Gesamtqualitätsindex ist die gewichtete Summe der sechs Bewertungsgrößen.', 'Q=w_KK+w_CC+w_RR+w_SS+w_VV+w_EE', 'Q=w_KK+w_CC+w_RR+w_SS+w_VV+w_EE', 'original', 132, 'Die Gewichtungen sind nichtnegativ, summieren sich zu eins und die Metriken sind vergleichbar skaliert.', 'Die konkrete Gewichtung muss vor der Ergebnisinterpretation festgelegt werden.', 'draft', 109),
(232, '3.8.6.1', 115, 'Modulmenge', 'Die Modulmenge enthält Parametrisierung, Operatorenkaskade, Zustandsverwaltung, Kohärenzbewertung, Validierung und Auswertung.', '\\mathcal{M}=\\left\\{M_\\Sigma,M_O,M_S,M_K,M_V,M_A\\right\\}', '\\mathcal{M}=\\left\\{M_\\Sigma,M_O,M_S,M_K,M_V,M_A\\right\\}', 'adapted', 134, 'Jedes Modul besitzt klar definierte Ein- und Ausgaben.', 'Grundlage der modularen Implementierungsarchitektur.', 'draft', 110),
(233, '3.8.6.2', 115, 'Zustandsverlauf', 'Der Zustandsverlauf ist die geordnete Folge sämtlicher während einer Simulation erzeugten Zustände.', '\\mathcal{S}=\\left(S_0,S_1,\\ldots,S_T\\right)', '\\mathcal{S}=\\left(S_0,S_1,\\ldots,S_T\\right)', 'original', NULL, 'Zwischenzustände werden nicht verworfen.', 'Ermöglicht vollständige Rekonstruktion.', 'draft', 110),
(234, '3.8.6.3', 115, 'Operatorprotokoll', 'Ein Operatorprotokoll enthält Iterationsindex, Operator, Eingabezustand und Ausgabezustand.', 'L_i=\\left(t,O_i,S_t,S_{t+1}\\right)', 'L_i=\\left(t,O_i,S_t,S_{t+1}\\right)', 'original', 135, 'Jeder Operatoraufruf erhält einen eindeutigen Protokolleintrag.', 'Dient der Nachvollziehbarkeit einzelner Rechenschritte.', 'draft', 110),
(235, '3.8.6.4', 115, 'Simulationsprotokoll', 'Das Simulationsprotokoll ist die geordnete Folge aller Operatorprotokolle eines Simulationslaufs.', '\\mathcal{L}=\\left(L_1,L_2,\\ldots,L_n\\right)', '\\mathcal{L}=\\left(L_1,L_2,\\ldots,L_n\\right)', 'original', 135, 'Alle Operatoraufrufe werden protokolliert.', 'Wissenschaftliche Rekonstruktionsgrundlage.', 'draft', 110),
(236, '3.8.6.5', 115, 'Fehlerklassen', 'Fehler werden in Parameterfehler, Validierungsfehler, Operatorfehler und Rechenfehler unterteilt.', 'F=\\left\\{F_P,F_V,F_O,F_R\\right\\}', 'F=\\left\\{F_P,F_V,F_O,F_R\\right\\}', 'adapted', 135, 'Jeder Fehler ist mindestens einer Klasse zuordenbar.', 'Grundlage kontrollierter Fehlerbehandlung.', 'draft', 110),
(237, '3.8.6.6', 115, 'Erweiterungsabbildung', 'Die Modulmenge kann durch ein neues Modul erweitert werden, ohne die bestehende Kernarchitektur zu verändern.', '\\mathcal{M}^{\\prime}=\\mathcal{M}\\cup\\left\\{M_{\\mathrm{neu}}\\right\\}', '\\mathcal{M}^{\\prime}=\\mathcal{M}\\cup\\left\\{M_{\\mathrm{neu}}\\right\\}', 'adapted', 134, 'Das neue Modul erfüllt die festgelegten Schnittstellenbedingungen.', 'Formale Darstellung der Erweiterbarkeit.', 'draft', 110),
(239, '3.8.7.1', 116, 'Prüfstruktur', 'Die Prüfstruktur umfasst Einzeloperatorprüfung, Integrationsprüfung, Reproduzierbarkeitsprüfung, Grenz- und Fehlerprüfung, Modellvalidierung sowie externe Referenzprüfung.', '\\mathcal{P}=\\left\\{P_U,P_I,P_R,P_G,P_M,P_E\\right\\}', '\\mathcal{P}=\\left\\{P_U,P_I,P_R,P_G,P_M,P_E\\right\\}', 'adapted', 137, 'Alle Prüfbereiche werden getrennt dokumentiert.', 'Übergeordnete Prüfstruktur.', 'draft', 111),
(240, '3.8.7.2', 116, 'Operator-Testfallmenge', 'Menge aus Eingabezuständen und unabhängig bestimmten Referenzzuständen.', '\\mathcal{T}_i=\\left\\{\\left(S_{i,1}^{\\mathrm{in}},S_{i,1}^{\\mathrm{ref}}\\right),\\ldots,\\left(S_{i,n}^{\\mathrm{in}},S_{i,n}^{\\mathrm{ref}}\\right)\\right\\}', '\\mathcal{T}_i=\\left\\{\\left(S_{i,1}^{\\mathrm{in}},S_{i,1}^{\\mathrm{ref}}\\right),\\ldots,\\left(S_{i,n}^{\\mathrm{in}},S_{i,n}^{\\mathrm{ref}}\\right)\\right\\}', 'original', 136, 'Referenzzustände sind unabhängig bestimmt.', 'Grundlage der Einzeloperatorprüfung.', 'draft', 111),
(241, '3.8.7.3', 116, 'Invariante', 'Eine Invariante ist eine mathematisch begründete Eigenschaft, die bei einem festgelegten Übergang erhalten bleibt.', 'I_k(S_{t+1})=I_k(S_t)', 'I_k(S_{t+1})=I_k(S_t)', 'adapted', 136, 'Die Erhaltung wurde mathematisch begründet.', 'Numerische Toleranzen sind möglich.', 'draft', 111),
(242, '3.8.7.4', 116, 'Validierungsebenen', 'Die Modellvalidierung wird in formale, interne und externe Validierung unterteilt.', '\\mathcal{V}=\\left\\{V_{\\mathrm{formal}},V_{\\mathrm{intern}},V_{\\mathrm{extern}}\\right\\}', '\\mathcal{V}=\\left\\{V_{\\mathrm{formal}},V_{\\mathrm{intern}},V_{\\mathrm{extern}}\\right\\}', 'adapted', 137, 'Die Ebenen werden nicht gleichgesetzt.', 'Methodische Trennung der Validierung.', 'draft', 111),
(243, '3.8.7.5', 116, 'Prüfstatusvektor', 'Der Prüfstatusvektor enthält die Ergebnisse der sechs Prüfbereiche.', 'Z_P=\\left(z_U,z_I,z_R,z_G,z_M,z_E\\right)', 'Z_P=\\left(z_U,z_I,z_R,z_G,z_M,z_E\\right)', 'original', NULL, 'Jeder Teilstatus ist eindeutig bestimmt.', 'Kompakte Dokumentation des Prüfstands.', 'draft', 111),
(244, '3.8.7.6', 116, 'Dreistufiger Teilstatus', 'Ein Teilstatus ist nicht bestanden, bestanden oder unbestimmt.', 'z_i\\in\\left\\{0,1,u\\right\\}', 'z_i\\in\\left\\{0,1,u\\right\\}', 'original', NULL, 'Die Bedeutungen von 0, 1 und u sind dokumentiert.', 'u ist nicht gleich bestanden.', 'draft', 111),
(245, '3.8.7.7', 116, 'Vollständige technische Verifikation', 'Die technische Verifikation ist vollständig, wenn Einzeloperator-, Integrations-, Reproduzierbarkeits- und Grenzprüfung bestanden sind.', 'z_U=z_I=z_R=z_G=1', 'z_U=z_I=z_R=z_G=1', 'original', 136, 'Alle vier Prüfklassen wurden ausgeführt.', 'Externe Validierung bleibt getrennt.', 'draft', 111),
(246, '3.8.8.1', 117, 'Vollständiger Laufdatensatz', 'Der vollständige Laufdatensatz verbindet Kennung, Konfiguration, Anfangszustand, Operatorenkaskade, Trajektorie, Protokoll, Prüfstatus, Bewertung und Ausführungsumgebung.', 'D_{mathrm{run}}=left(I_{mathrm{run}},Sigma,S_0,mathcal{O},Gamma,mathcal{L},Z_P,B,M_{mathrm{env}}\right)', 'D_{mathrm{run}}=left(I_{mathrm{run}},Sigma,S_0,mathcal{O},Gamma,mathcal{L},Z_P,B,M_{mathrm{env}}\right)', 'original', NULL, 'Alle Bestandteile beziehen sich auf denselben Simulationslauf.', 'Zentrales Datenobjekt des Abschnitts.', 'draft', 112),
(247, '3.8.8.2', 117, 'Laufkennung', 'Deterministische Kennung aus Konfiguration, Anfangszustand, Operator- und Implementierungsversion sowie Umgebungsmetadaten.', 'I_{mathrm{run}}=Hleft(Sigma,S_0,V_{mathcal{O}},V_{mathrm{impl}},M_{mathrm{env}}\right)', 'I_{mathrm{run}}=Hleft(Sigma,S_0,V_{mathcal{O}},V_{mathrm{impl}},M_{mathrm{env}}\right)', 'adapted', 139, 'Die Hashbildung erfolgt kanonisch.', 'Ermöglicht eindeutige Zuordnung.', 'draft', 112),
(248, '3.8.8.3', 117, 'Operatorversionspaar', 'Ein Operator wird mathematisch und implementierungstechnisch getrennt versioniert.', 'V_i=left(V_i^{mathrm{math}},V_i^{mathrm{impl}}\right)', 'V_i=left(V_i^{mathrm{math}},V_i^{mathrm{impl}}\right)', 'adapted', 139, 'Beide Versionen sind dokumentiert.', 'Trennung von Modell- und Softwareänderung.', 'draft', 112),
(249, '3.8.8.4', 117, 'Operatorereignis', 'Ein Operatorereignis dokumentiert Lauf, Iteration, Operator, Version, Eingabe- und Ausgabezustand, Dauer und Status.', 'E_{i,t}=left(I_{mathrm{run}},t,i,V_i,S_t,S_{t+1},	au_{i,t},Z_{i,t}\right)', 'E_{i,t}=left(I_{mathrm{run}},t,i,V_i,S_t,S_{t+1},	au_{i,t},Z_{i,t}\right)', 'original', NULL, 'Der Operatoraufruf ist eindeutig identifizierbar.', 'Grundlage vollständiger Laufrekonstruktion.', 'draft', 112),
(250, '3.8.8.5', 117, 'Umgebungsmetadaten', 'Die Ausführungsumgebung umfasst Betriebssystem, Laufzeit, Bibliotheken, numerische Einstellungen und relevante Hardware.', 'M_{mathrm{env}}=left(V_{mathrm{os}},V_{mathrm{runtime}},V_{mathrm{lib}},A_{mathrm{num}},H_{mathrm{sys}}\right)', 'M_{mathrm{env}}=left(V_{mathrm{os}},V_{mathrm{runtime}},V_{mathrm{lib}},A_{mathrm{num}},H_{mathrm{sys}}\right)', 'adapted', 139, 'Relevante Umgebungsmerkmale werden vollständig erfasst.', 'Unterstützt technische Reproduzierbarkeit.', 'draft', 112),
(251, '3.8.8.6', 117, 'Revisionseintrag', 'Ein Revisionseintrag dokumentiert Kennung, Zeitpunkt, verantwortliche Instanz, Objekt, alten und neuen Wert sowie Begründung.', 'R_j=left(I_{R_j},t_j,u_j,o_j,v_j^{mathrm{alt}},v_j^{mathrm{neu}},b_j\right)', 'R_j=left(I_{R_j},t_j,u_j,o_j,v_j^{mathrm{alt}},v_j^{mathrm{neu}},b_j\right)', 'adapted', 138, 'Frühere Revisionen werden nicht überschrieben.', 'Herkunfts- und Änderungsprotokoll.', 'draft', 112),
(252, '3.8.8.7', 117, 'Reproduktionspaket', 'Das Reproduktionspaket enthält alle Informationen zur unabhängigen Wiederholung eines Simulationslaufs.', 'P_{mathrm{rep}}=left(Sigma,S_0,V_{mathcal{O}},V_{mathrm{impl}},M_{mathrm{env}},D_{mathrm{ref}},C_{mathrm{exec}}\right)', 'P_{mathrm{rep}}=left(Sigma,S_0,V_{mathcal{O}},V_{mathrm{impl}},M_{mathrm{env}},D_{mathrm{ref}},C_{mathrm{exec}}\right)', 'adapted', 139, 'Keine undokumentierten Zusatzinformationen sind erforderlich.', 'Grundlage unabhängiger Reproduktion.', 'draft', 112),
(253, '3.8.8.8', 117, 'Vollständigkeitsvektor', 'Der Vollständigkeitsvektor bildet das Vorhandensein aller erforderlichen Laufkomponenten binär ab.', 'C_D=left(c_I,c_Sigma,c_S,c_O,c_Gamma,c_L,c_P,c_B,c_M\right)', 'C_D=left(c_I,c_Sigma,c_S,c_O,c_Gamma,c_L,c_P,c_B,c_M\right)', 'original', NULL, 'Jede Komponente ist eindeutig prüfbar.', 'Freigabekriterium für Laufdatensätze.', 'draft', 112),
(261, '3.8.10.1', 119, 'Parameterraum', 'Der Parameterraum ist die Menge aller zulässigen Parametervektoren der Operatorenkaskade.', '\\mathcal{P}=\\left\\{\\Theta\\right\\}\\subseteq\\mathbb{R}^{n}', '\\mathcal{P}=\\left\\{\\Theta\\right\\}\\subseteq\\mathbb{R}^{n}', 'original', NULL, 'Die Parameterkomponenten und ihre zulässigen Wertebereiche sind festgelegt.', 'Grundlage der systematischen Parametervariation.', 'draft', 114),
(262, '3.8.10.2', 119, 'Lokale Sensitivität', 'Die lokale Sensitivität beschreibt die Änderung einer Trajektorie oder Bewertungsgröße gegenüber einer lokalen Änderung eines einzelnen Parameters.', 'S_i=\\frac{\\partial Q}{\\partial\\theta_i}', 'S_i=\\frac{\\partial Q}{\\partial\\theta_i}', 'original', NULL, 'Die übrigen Parameter werden lokal konstant gehalten.', 'Für numerische Berechnungen wird eine Differenzenapproximation verwendet.', 'draft', 114),
(263, '3.8.10.3', 119, 'Globale Sensitivität', 'Die globale Sensitivität beschreibt den über den untersuchten Parameterbereich wirksamen Einfluss eines Parameters auf die Varianz der Bewertungsgröße.', 'S_i^{\\mathrm{glob}}=\\operatorname{Var}\\left(Q\\mid\\theta_i\\right)', 'S_i^{\\mathrm{glob}}=\\operatorname{Var}\\left(Q\\mid\\theta_i\\right)', 'original', NULL, 'Der untersuchte Parameterbereich und das Stichprobendesign sind festgelegt.', 'Nichtlineare und bereichsabhängige Einflüsse werden berücksichtigt.', 'draft', 114),
(264, '3.8.10.4', 119, 'Robuster Parameterbereich', 'Ein robuster Parameterbereich enthält Parameterkonfigurationen, deren benachbarte Variationen nur geringe Trajektorienabweichungen erzeugen.', 'R=\\left\\{\\Theta\\in\\mathcal{P}\\mid D_{\\Gamma}<\\varepsilon_R\\right\\}', 'R=\\left\\{\\Theta\\in\\mathcal{P}\\mid D_{\\Gamma}<\\varepsilon_R\\right\\}', 'original', NULL, 'Die Trajektoriendistanz und der Robustheitsschwellenwert sind definiert.', 'Robustheit ist an die verwendete Distanzfunktion gebunden.', 'draft', 114),
(265, '3.8.10.5', 119, 'Kritischer Parameterbereich', 'Der kritische Parameterbereich ist das Komplement des robusten Parameterbereichs innerhalb des untersuchten Parameterraums.', 'C=\\mathcal{P}\\setminus R', 'C=\\mathcal{P}\\setminus R', 'original', NULL, 'Robuste und kritische Bereiche werden innerhalb desselben Parameterraums bestimmt.', 'Kritische Bereiche können Übergänge und hohe Sensitivitäten enthalten.', 'draft', 114),
(266, '3.8.10.6', 119, 'Robustheitsindex', 'Der Robustheitsindex normiert die Trajektorienabweichung auf das Intervall von null bis eins.', 'I_R=1-\\frac{D_{\\Gamma}}{D_{\\max}}', 'I_R=1-\\frac{D_{\\Gamma}}{D_{\\max}}', 'original', NULL, 'Es gilt 0\\le D_{\\Gamma}\\le D_{\\max}.', 'Hohe Werte kennzeichnen robuste Parameterkonfigurationen.', 'draft', 114),
(267, '3.8.10.7', 119, 'Kritikalitätsindex', 'Der Kritikalitätsindex ist das Komplement des Robustheitsindex.', 'I_C=1-I_R', 'I_C=1-I_R', 'original', NULL, 'Der Robustheitsindex liegt im Intervall von null bis eins.', 'Hohe Werte kennzeichnen kritische Parameterkonfigurationen.', 'draft', 114),
(268, '3.8.10.8', 119, 'Stabilitätslandschaft', 'Die Stabilitätslandschaft verbindet den Parameterraum mit einer darauf definierten Bewertungsabbildung.', 'L=\\left(\\mathcal{P},M\\right)', 'L=\\left(\\mathcal{P},M\\right)', 'original', NULL, 'Die Bewertungsfunktion ist für jeden untersuchten Parameterpunkt definiert.', 'Grundlage für die kartographische Darstellung stabiler und kritischer Regionen.', 'draft', 114),
(269, '3.8.11.1', 120, 'Simulationsstudie', 'Eine Simulationsstudie ist eine geordnete, versionierte und auswertbare Menge von Simulationsläufen.', '\\mathcal{S}_{\\mathrm{sim}}=\\left\\{\\mathcal{R}_1,\\ldots,\\mathcal{R}_N\\right\\}', '\\mathcal{S}_{\\mathrm{sim}}=\\left\\{\\mathcal{R}_1,\\ldots,\\mathcal{R}_N\\right\\}', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(270, '3.8.11.2', 120, 'Simulationslaufobjekt', 'Ein Simulationslaufobjekt verbindet Parametrisierung, Anfangszustand, Operatorenkonfiguration, Zufallszustand, Trajektorie, Merkmale und Status.', '\\mathcal{R}_i=\\left(\\Theta_i,S_{0,i},\\mathcal{O}_i,\\xi_i,\\Gamma_i,F_{\\Gamma_i},Z_i\\right)', '\\mathcal{R}_i=\\left(\\Theta_i,S_{0,i},\\mathcal{O}_i,\\xi_i,\\Gamma_i,F_{\\Gamma_i},Z_i\\right)', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(271, '3.8.11.3', 120, 'Versuchsplan', 'Der Versuchsplan ist die endliche Menge der innerhalb einer Studie untersuchten Parameterpunkte.', '\\mathcal{D}\\subseteq\\mathcal{P}', '\\mathcal{D}\\subseteq\\mathcal{P}', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(272, '3.8.11.4', 120, 'Wiederholungsgruppe', 'Eine Wiederholungsgruppe enthält Simulationsläufe mit demselben Parameterpunkt und kontrolliert variierten oder identischen Zufallszuständen.', 'G_{\\Theta_j}=\\left\\{\\mathcal{R}_{j,1},\\ldots,\\mathcal{R}_{j,n_{\\xi}}\\right\\}', 'G_{\\Theta_j}=\\left\\{\\mathcal{R}_{j,1},\\ldots,\\mathcal{R}_{j,n_{\\xi}}\\right\\}', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(273, '3.8.11.5', 120, 'Auswertbare Laufmenge', 'Die auswertbare Laufmenge enthält ausschließlich abgeschlossene und validierte Simulationsläufe.', '\\mathcal{S}_{\\mathrm{eval}}\\subseteq\\mathcal{S}_{\\mathrm{sim}}', '\\mathcal{S}_{\\mathrm{eval}}\\subseteq\\mathcal{S}_{\\mathrm{sim}}', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(274, '3.8.11.6', 120, 'Vollständigkeitsindex', 'Der Vollständigkeitsindex ist das Verhältnis abgeschlossener zu geplanten Simulationsläufen.', 'I_{\\mathrm{complete}}=\\frac{N_{\\mathrm{completed}}}{N_{\\mathrm{planned}}}', 'I_{\\mathrm{complete}}=\\frac{N_{\\mathrm{completed}}}{N_{\\mathrm{planned}}}', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(275, '3.8.11.7', 120, 'Validitätsindex', 'Der Validitätsindex ist das Verhältnis valider zu abgeschlossenen Simulationsläufen.', 'I_{\\mathrm{valid}}=\\frac{N_{\\mathrm{valid}}}{N_{\\mathrm{completed}}}', 'I_{\\mathrm{valid}}=\\frac{N_{\\mathrm{valid}}}{N_{\\mathrm{completed}}}', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(276, '3.8.11.8', 120, 'Abdeckungsindex', 'Der Abdeckungsindex beschreibt den durch die untersuchten Parameterpunkte repräsentierten Anteil des vorgesehenen Parameterraums.', 'I_{\\mathrm{coverage}}\\in[0,1]', 'I_{\\mathrm{coverage}}\\in[0,1]', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(277, '3.8.11.9', 120, 'Reproduzierbarkeitsindex', 'Der Reproduzierbarkeitsindex bewertet die Übereinstimmung wiederholter Läufe mit identischer Konfiguration.', 'I_{\\mathrm{reprod}}\\in[0,1]', 'I_{\\mathrm{reprod}}\\in[0,1]', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(278, '3.8.11.10', 120, 'Studienstatusvektor', 'Der Studienstatusvektor verbindet Vollständigkeit, Validität, Reproduzierbarkeit, Abdeckung und Interpretationsstatus.', 'Z_{\\mathrm{study}}=\\left(I_{\\mathrm{complete}},I_{\\mathrm{valid}},I_{\\mathrm{reprod}},I_{\\mathrm{coverage}},I_{\\mathrm{interpret}}\\right)', 'Z_{\\mathrm{study}}=\\left(I_{\\mathrm{complete}},I_{\\mathrm{valid}},I_{\\mathrm{reprod}},I_{\\mathrm{coverage}},I_{\\mathrm{interpret}}\\right)', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(279, '3.8.11.11', 120, 'Studienergebnisobjekt', 'Das Studienergebnisobjekt führt Status, Merkmale, Verteilungen, robuste und kritische Bereiche, Cluster, Anomalien und Interpretationen zusammen.', 'E_{\\mathrm{study}}=\\left(Z_{\\mathrm{study}},\\overline{F}_{\\Gamma},\\Sigma_F,P_K,P_A,R,C,\\mathcal{G},\\mathcal{A},\\mathcal{I}\\right)', 'E_{\\mathrm{study}}=\\left(Z_{\\mathrm{study}},\\overline{F}_{\\Gamma},\\Sigma_F,P_K,P_A,R,C,\\mathcal{G},\\mathcal{A},\\mathcal{I}\\right)', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(280, '3.8.11.12', 120, 'Studienfreigabe', 'Eine Studie wird freigegeben, wenn die Mindestanforderungen an Vollständigkeit, Validität, Reproduzierbarkeit, Abdeckung und Interpretation erfüllt sind.', 'z_{\\mathrm{release}}=1', 'z_{\\mathrm{release}}=1', 'original', NULL, 'Die im Abschnitt festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.11.', 'draft', 115),
(284, '3.8.9.1', 121, 'Trajektorienvergleichsvektor', 'Der Vergleichsvektor verbindet globale, lokale, endzustandsbezogene, operatorische, phasenbezogene und metrische Abweichungen.', 'C_{Gamma}left(Gamma_a,Gamma_b\right)=left(D_{mathrm{glob}},D_{mathrm{lok}},D_{mathrm{end}},D_{mathrm{op}},D_{mathrm{phase}},D_{mathrm{metric}}\right)', 'C_{Gamma}left(Gamma_a,Gamma_b\right)=left(D_{mathrm{glob}},D_{mathrm{lok}},D_{mathrm{end}},D_{mathrm{op}},D_{mathrm{phase}},D_{mathrm{metric}}\right)', 'original', NULL, 'Alle Komponenten beziehen sich auf dasselbe Trajektorienpaar.', 'Zentrale Vergleichsstruktur.', 'draft', 116);
INSERT INTO `definitions` (`definition_id`, `definition_number`, `section_id`, `title`, `definition_text`, `formal_latex`, `word_latex`, `provenance`, `source_id`, `assumptions`, `notes`, `validation_status`, `created_revision_id`) VALUES
(285, '3.8.9.2', 121, 'Normierte Trajektorie', 'Eine normierte Trajektorie bildet einen Lauf auf das normierte Zeitintervall von null bis eins ab.', 'widetilde{Gamma}=left{widetilde{S}(lambda)mid0lelambdale1\right}', 'widetilde{Gamma}=left{widetilde{S}(lambda)mid0lelambdale1\right}', 'adapted', 140, 'Die Interpolation ist dokumentiert.', 'Vergleich unterschiedlich langer Läufe.', 'draft', 116),
(286, '3.8.9.3', 121, 'Lokale Abweichungsfunktion', 'Die lokale Abweichungsfunktion beschreibt die Zustandsdistanz zweier Trajektorien zu jedem normierten Zeitpunkt.', 'delta_{a,b}(lambda)=d_Sleft(widetilde{S}_a(lambda),widetilde{S}_b(lambda)\right)', 'delta_{a,b}(lambda)=d_Sleft(widetilde{S}_a(lambda),widetilde{S}_b(lambda)\right)', 'original', NULL, 'Die Zustände sind vergleichbar skaliert.', 'Lokalisierung kritischer Abweichungsphasen.', 'draft', 116),
(287, '3.8.9.4', 121, 'Phasenzerlegung', 'Eine Trajektorie wird als geordnete Folge funktionaler Entwicklungsphasen beschrieben.', 'Phi(Gamma)=left(phi_1,phi_2,ldots,phi_q\right)', 'Phi(Gamma)=left(phi_1,phi_2,ldots,phi_q\right)', 'original', NULL, 'Phasengrenzen werden nach dokumentierten Kriterien bestimmt.', 'Grundlage des Phasenvergleichs.', 'draft', 116),
(288, '3.8.9.5', 121, 'Trajektorienmerkmalsvektor', 'Der Trajektorienmerkmalsvektor verbindet Laufdauer, Pfadlänge, Mittelwerte funktionaler Metriken, Phasenanzahl, kritische Übergänge und Gesamtbewertung.', 'F_{Gamma}=left(T,D_{mathrm{path}},K_{mathrm{mean}},C_{mathrm{mean}},R_{mathrm{mean}},S_{mathrm{mean}},N_{phi},N_{mathrm{crit}},Q\right)', 'F_{Gamma}=left(T,D_{mathrm{path}},K_{mathrm{mean}},C_{mathrm{mean}},R_{mathrm{mean}},S_{mathrm{mean}},N_{phi},N_{mathrm{crit}},Q\right)', 'original', NULL, 'Alle Merkmale wurden konsistent berechnet.', 'Grundlage der Klassifikation.', 'draft', 116),
(289, '3.8.9.6', 121, 'Trajektorienklassen', 'Trajektorien werden analytisch als stabil, konvergierend, oszillierend, divergierend, kritisch oder unbestimmt klassifiziert.', 'mathcal{K}_{Gamma}=left{K_{mathrm{stab}},K_{mathrm{conv}},K_{mathrm{osc}},K_{mathrm{div}},K_{mathrm{crit}},K_{mathrm{ind}}\right}', 'mathcal{K}_{Gamma}=left{K_{mathrm{stab}},K_{mathrm{conv}},K_{mathrm{osc}},K_{mathrm{div}},K_{mathrm{crit}},K_{mathrm{ind}}\right}', 'original', NULL, 'Klassenregeln und Schwellenwerte sind dokumentiert.', 'Keine ontologische Festlegung.', 'draft', 116),
(290, '3.8.9.7', 121, 'Kritischer Übergangsindikator', 'Der kritische Übergangsindikator kombiniert Zustandsänderung sowie Änderungen von Kohärenz, Kontinuität und Reproduzierbarkeit.', 'J_t=w_1left|Delta S_t\right|+w_2left|Delta K_t\right|+w_3left|Delta C_t\right|+w_4left|Delta R_t\right|', 'J_t=w_1left|Delta S_t\right|+w_2left|Delta K_t\right|+w_3left|Delta C_t\right|+w_4left|Delta R_t\right|', 'original', NULL, 'Die Gewichte summieren sich zu eins.', 'Mehrkriterielle Übergangserkennung.', 'draft', 116),
(291, '3.8.9.8', 121, 'Repräsentative Trajektorie', 'Die repräsentative Trajektorie eines Clusters ist das Medoid mit minimaler Gesamtdistanz zu allen übrigen Clustermitgliedern.', 'Gamma_j^{mathrm{rep}}=operatorname*{arg,min}_{Gamma_ain G_j}sum_{Gamma_bin G_j}d_{Gamma}left(Gamma_a,Gamma_b\right)', 'Gamma_j^{mathrm{rep}}=operatorname*{arg,min}_{Gamma_ain G_j}sum_{Gamma_bin G_j}d_{Gamma}left(Gamma_a,Gamma_b\right)', 'adapted', 141, 'Das Cluster ist nicht leer.', 'Reale statt künstlich gemittelte Trajektorie.', 'draft', 116),
(292, '3.8.9.9', 121, 'Interpretationsstatusvektor', 'Der Interpretationsstatus dokumentiert Klassifikation, Clusterzuordnung, Phasenerkennung, Ursachenanalyse und wissenschaftliche Validierung.', 'Z_{mathrm{int}}=left(z_{mathrm{class}},z_{mathrm{cluster}},z_{mathrm{phase}},z_{mathrm{cause}},z_{mathrm{valid}}\right)', 'Z_{mathrm{int}}=left(z_{mathrm{class}},z_{mathrm{cluster}},z_{mathrm{phase}},z_{mathrm{cause}},z_{mathrm{valid}}\right)', 'original', NULL, 'Jede Komponente ist eindeutig bewertet.', 'Trennt Interpretation und Validierung.', 'draft', 116),
(299, '3.8.12.1', 122, 'Simulationsarchitektur', 'Die Simulationsarchitektur ist das formale Gesamtsystem aus mathematischem Modell, Parameterraum, Operatorenkaskade, Simulationsstudien und empirischer Vergleichsbasis.', '\\mathcal{A}_{\\mathrm{sim}}=\\left(\\mathcal{M},\\mathcal{P},\\mathcal{O},\\mathcal{S},\\mathcal{E}\\right)', '\\mathcal{A}_{\\mathrm{sim}}=\\left(\\mathcal{M},\\mathcal{P},\\mathcal{O},\\mathcal{S},\\mathcal{E}\\right)', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(300, '3.8.12.2', 122, 'Modellgültigkeitsbereich', 'Der Modellgültigkeitsbereich ist die Teilmenge des betrachteten Bereiches, in der sämtliche Modellannahmen gleichzeitig gelten und das Modell definiert ist.', '\\Omega_{\\mathrm{valid}}\\subseteq\\Omega', '\\Omega_{\\mathrm{valid}}\\subseteq\\Omega', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(301, '3.8.12.3', 122, 'Gültiger Parameterbereich', 'Der gültige Parameterbereich ist die Teilmenge des mathematischen Parameterraums, deren Werte theoretisch, physikalisch oder empirisch interpretierbar sind.', '\\mathcal{P}_{\\mathrm{valid}}\\subseteq\\mathcal{P}', '\\mathcal{P}_{\\mathrm{valid}}\\subseteq\\mathcal{P}', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(302, '3.8.12.4', 122, 'Empirische Anschlussabbildung', 'Die empirische Anschlussabbildung ordnet einer Simulationstrajektorie eine empirisch vergleichbare Beobachtungsrepräsentation zu.', '\\Phi:\\Gamma\\longrightarrow E', '\\Phi:\\Gamma\\longrightarrow E', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(303, '3.8.12.5', 122, 'Funktionale empirische Übereinstimmung', 'Funktionale empirische Übereinstimmung liegt vor, wenn die Merkmale einer Simulationstrajektorie näherungsweise mit den Merkmalen empirischer Beobachtungen übereinstimmen.', 'F_{\\Gamma}\\approx F_E', 'F_{\\Gamma}\\approx F_E', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(304, '3.8.12.6', 122, 'Modellgrenze', 'Die Modellgrenze ist der Rand des gültigen Modellbereiches, an dem mindestens eine Voraussetzung des Modells ihre Gültigkeit verliert oder nicht mehr hinreichend überprüft werden kann.', '\\partial\\Omega_{\\mathrm{valid}}=\\overline{\\Omega_{\\mathrm{valid}}}\\setminus\\operatorname{int}\\left(\\Omega_{\\mathrm{valid}}\\right)', '\\partial\\Omega_{\\mathrm{valid}}=\\overline{\\Omega_{\\mathrm{valid}}}\\setminus\\operatorname{int}\\left(\\Omega_{\\mathrm{valid}}\\right)', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(305, '3.8.12.7', 122, 'Interpretierbare Trajektorienmenge', 'Die interpretierbare Trajektorienmenge enthält nur berechenbare Trajektorien, die vollständig im gültigen Zustandsbereich liegen und mit zulässigen Parametern erzeugt wurden.', '\\mathcal{G}_{\\mathrm{interpret}}=\\left\\{\\Gamma\\in\\mathcal{G}_{\\mathrm{calc}}\\mid\\Gamma\\subseteq\\Omega_{\\mathrm{valid}}\\land\\Theta\\in\\mathcal{P}_{\\mathrm{valid}}\\right\\}', '\\mathcal{G}_{\\mathrm{interpret}}=\\left\\{\\Gamma\\in\\mathcal{G}_{\\mathrm{calc}}\\mid\\Gamma\\subseteq\\Omega_{\\mathrm{valid}}\\land\\Theta\\in\\mathcal{P}_{\\mathrm{valid}}\\right\\}', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(306, '3.8.12.8', 122, 'Strukturelle Restmenge', 'Die strukturelle Restmenge umfasst diejenigen realitätsrelevanten Merkmale, die in der gewählten Modellstruktur nicht abgebildet werden.', '\\mathcal{F}_{\\mathrm{res}}=\\mathcal{F}_{\\mathrm{real}}\\setminus\\mathcal{F}_{\\mathrm{model}}', '\\mathcal{F}_{\\mathrm{res}}=\\mathcal{F}_{\\mathrm{real}}\\setminus\\mathcal{F}_{\\mathrm{model}}', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(307, '3.8.12.9', 122, 'Numerische Stabilität', 'Eine numerische Simulation gilt innerhalb einer vorgegebenen Toleranz als stabil, wenn die Distanz zwischen exakter Modelltrajektorie und numerischer Approximation die Toleranz nicht überschreitet.', 'D_{\\Gamma}\\left(\\Gamma,\\widehat{\\Gamma}\\right)\\le\\varepsilon_{\\mathrm{tol}}', 'D_{\\Gamma}\\left(\\Gamma,\\widehat{\\Gamma}\\right)\\le\\varepsilon_{\\mathrm{tol}}', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(308, '3.8.12.10', 122, 'Äquifinalität', 'Äquifinalität liegt vor, wenn unterschiedliche Parametervektoren hinreichend ähnliche Simulationstrajektorien erzeugen.', '\\Theta_a\\neq\\Theta_b\\land D_{\\Gamma}\\left(\\Gamma(\\Theta_a),\\Gamma(\\Theta_b)\\right)\\le\\varepsilon_{\\Gamma}', '\\Theta_a\\neq\\Theta_b\\land D_{\\Gamma}\\left(\\Gamma(\\Theta_a),\\Gamma(\\Theta_b)\\right)\\le\\varepsilon_{\\Gamma}', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(309, '3.8.12.11', 122, 'Identifizierbarkeit', 'Eine Parametrisierung ist eindeutig identifizierbar, wenn genau ein gültiger Parametervektor die beobachtete Trajektorie innerhalb der festgelegten Toleranz reproduziert.', '\\left|\\mathcal{P}_{\\mathrm{eq}}\\left(\\Gamma^{*}\\right)\\right|=1', '\\left|\\mathcal{P}_{\\mathrm{eq}}\\left(\\Gamma^{*}\\right)\\right|=1', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(310, '3.8.12.12', 122, 'Modellinterne Kausalität', 'Modellinterne Kausalität bezeichnet die innerhalb der Simulation definierte gerichtete Übergangslogik und ist von empirisch bestätigter Kausalität zu unterscheiden.', '\\mathcal{C}_{\\mathrm{model}}\\neq\\mathcal{C}_{\\mathrm{emp}}', '\\mathcal{C}_{\\mathrm{model}}\\neq\\mathcal{C}_{\\mathrm{emp}}', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(311, '3.8.12.13', 122, 'Skaleninvarianz', 'Skaleninvarianz liegt vor, wenn die wesentlichen funktionalen Eigenschaften einer Trajektorie unter einer Skalenübertragung näherungsweise erhalten bleiben.', 'F\\left(T_{\\lambda_a\\rightarrow\\lambda_b}(\\Gamma)\\right)\\approx F(\\Gamma)', 'F\\left(T_{\\lambda_a\\rightarrow\\lambda_b}(\\Gamma)\\right)\\approx F(\\Gamma)', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(312, '3.8.12.14', 122, 'Gesamtunsicherheit', 'Die Gesamtunsicherheit setzt sich aus Daten-, Parameter-, Struktur-, numerischer und interpretativer Unsicherheit zusammen.', 'U_{\\mathrm{total}}=U_{\\mathrm{data}}+U_{\\mathrm{param}}+U_{\\mathrm{struct}}+U_{\\mathrm{num}}+U_{\\mathrm{interpret}}', 'U_{\\mathrm{total}}=U_{\\mathrm{data}}+U_{\\mathrm{param}}+U_{\\mathrm{struct}}+U_{\\mathrm{num}}+U_{\\mathrm{interpret}}', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(313, '3.8.12.15', 122, 'Vertrauensindex', 'Der Vertrauensindex ist das Komplement der auf das Einheitsintervall normierten Gesamtunsicherheit.', 'I_{\\mathrm{confidence}}=1-\\widehat{U}_{\\mathrm{total}}', 'I_{\\mathrm{confidence}}=1-\\widehat{U}_{\\mathrm{total}}', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(314, '3.8.12.16', 122, 'Gültigkeitsstatus', 'Der Gültigkeitsstatus verbindet formale Konsistenz, Bereichsgültigkeit, Parametergültigkeit, numerische Stabilität, empirische Anschlussfähigkeit, Identifizierbarkeit und wissenschaftliche Absicherung.', 'Z_{\\mathrm{valid}}=\\left(I_{\\mathrm{formal}},I_{\\mathrm{domain}},I_{\\mathrm{param}},I_{\\mathrm{num}},I_{\\mathrm{emp}},I_{\\mathrm{ident}},I_{\\mathrm{confidence}}\\right)', 'Z_{\\mathrm{valid}}=\\left(I_{\\mathrm{formal}},I_{\\mathrm{domain}},I_{\\mathrm{param}},I_{\\mathrm{num}},I_{\\mathrm{emp}},I_{\\mathrm{ident}},I_{\\mathrm{confidence}}\\right)', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117),
(315, '3.8.12.17', 122, 'Interpretationsstatus', 'Der Interpretationsstatus ist genau dann eins, wenn sämtliche für die Studie festgelegten Mindestbedingungen erfüllt sind.', 'z_{\\mathrm{interpret}}=\\prod_{k\\in\\mathcal{K}_{\\mathrm{valid}}}\\mathbf{1}\\left[I_k\\ge\\varepsilon_k\\right]', 'z_{\\mathrm{interpret}}=\\prod_{k\\in\\mathcal{K}_{\\mathrm{valid}}}\\mathbf{1}\\left[I_k\\ge\\varepsilon_k\\right]', 'original', NULL, 'Die im Abschnitt 3.8.12 festgelegten Voraussetzungen gelten.', 'Definition aus Abschnitt 3.8.12.', 'draft', 117);
INSERT INTO `dissertation_sections` (`section_id`, `parent_section_id`, `section_code`, `title`, `chapter_no`, `section_order`, `status`, `is_original_contribution`, `notes`, `created_at`, `updated_at`) VALUES
(1, NULL, '3', 'Funktionales Raum-Zeit-Kohärenzsystem – Theoretische Grundlagen', 3, 3.0000, 'final', 0, 'Übergeordnete Kapitelüberschrift des vollständig neu aufgebauten Kapitels 3.', '2026-07-17 07:16:55', '2026-07-17 07:16:55'),
(2, 1, '3.1', 'Grundlagen der funktionalen Beschreibung von Raum und Zeit', 3, 3.1000, 'final', 0, 'Grundlagenabschnitt des vollständig neu aufgebauten Kapitels 3.', '2026-07-17 07:16:56', '2026-07-17 07:16:56'),
(3, 2, '3.1.0', 'Einleitung', 3, 3.1001, 'final', 0, 'Vollständige Neufassung. Der Abschnitt grenzt den funktionalen Ausgangspunkt des FRZK von klassischen und quantengravitativen Raum-Zeit-Konzeptionen ab.', '2026-07-17 07:16:56', '2026-07-17 07:16:56'),
(4, 2, '3.1.1', 'Das Nichts als mathematischer Ausgangspunkt', 3, 3.1100, 'final', 1, 'Vollständige Neufassung. Der Abschnitt grenzt das absolute Nichts von mathematisch und physikalisch strukturierten Formen der Leere ab und leitet funktionale Unterscheidbarkeit als minimale Voraussetzung mathematischer Beschreibung her.', '2026-07-17 07:17:13', '2026-07-17 07:17:13'),
(5, 2, '3.1.2', 'Philosophische Grundlagen', 3, 3.1200, 'final', 1, 'Vollständige Neufassung. Systematische Untersuchung philosophischer Begriffe von Sein, Nichtsein, Differenz, Relation, Prozess, Raum, Zeit, Erkenntnis und Information als Grundlage des FRZK.', '2026-07-17 07:17:37', '2026-07-17 07:17:37'),
(6, 2, '3.1.3', 'Physikalische Grundlagen', 3, 3.1300, 'final', 0, 'Analyse klassischer, relativistischer, quantenmechanischer und emergenter Raum-Zeit-Konzeptionen. Klare Trennung zwischen mathematischer Rekonstruktion und physikalischem Geltungsanspruch.', '2026-07-17 10:57:01', '2026-07-17 10:57:01'),
(7, 2, '3.1.4', 'Erkenntnistheoretische Grundlagen', 3, 3.1400, 'final', 0, 'Erkenntnistheoretische Abgrenzung von Konstruktion, Modell, Interpretation, empirischer Geltung und Ontologie.', '2026-07-17 11:19:14', '2026-07-17 11:19:14'),
(8, 2, '3.1.5', 'Methodologische Konsequenzen für das Funktionale Raum-Zeit-Kohärenzsystem', 3, 3.1500, 'final', 1, 'Festlegung der methodologischen Arbeitsregeln des FRZK: schrittweiser Aufbau, Vermeidung verdeckter Voraussetzungen, Trennung von mathematischer Konstruktion und empirischer Interpretation, Strukturerhaltung, Modularisierung, Versionierung und Vorrang der mathematischen Rekonstruktion.', '2026-07-17 15:19:42', '2026-07-17 15:19:42'),
(9, 2, '3.1.6', 'Funktion statt Objekt – Paradigmenwechsel moderner Wissenschaft', 3, 3.1600, 'final', 1, 'Begründung des methodischen Übergangs von vorausgesetzten Objekten zu funktionaler Wirksamkeit, relationaler Bestimmung, Prozessualität, Rekursivität und funktionaler Stabilisierung.', '2026-07-18 04:49:51', '2026-07-18 04:49:51'),
(10, 2, '3.1.7', 'Forschungsstand, Forschungslücke und wissenschaftliche Zielsetzung', 3, 3.1700, 'final', 1, 'Zusammenführung des Forschungsstandes.', '2026-07-18 04:55:37', '2026-07-18 04:55:37'),
(11, 1, '3.2', 'Mathematische Grundlagen', 3, 3.2000, 'final', 0, 'Mathematische Brücke zwischen den wissenschaftstheoretischen Grundlagen aus Kapitel 3.1 und der axiomatischen Grundlegung in Kapitel 3.3. Der Abschnitt rekonstruiert den etablierten mathematischen Forschungsstand, ohne die eigene FRZK-Mathematik vorwegzunehmen. Kapitel 3.2 ist mit Abschnitt 3.2.13 redaktionell abgeschlossen. Nächste freie Literaturnummer: [103]. Nächste freie Gleichungsnummer: (3.354).', '2026-07-18 05:28:52', '2026-07-18 15:05:27'),
(12, 11, '3.2.0', 'Einleitung', 3, 3.2001, 'final', 0, 'Die Einleitung bestimmt Kapitel 3.2 als mathematischen Forschungsstandsabschnitt. Sie erläutert den Übergang von der wissenschaftstheoretischen Grundlegung zu den etablierten mathematischen Strukturbegriffen und macht sichtbar, dass mathematische Theorien Mengen, Relationen, Funktionen, Operatoren, Zustandsräume und weitere Strukturen regelmäßig bereits voraussetzen. Die eigene FRZK-Axiomatik und mathematische Rekonstruktion bleiben den Kapiteln 3.3 und 3.4 vorbehalten.', '2026-07-18 05:28:53', '2026-07-18 05:28:53'),
(13, 11, '3.2.1', 'Mengen als Grundlage mathematischer Modellbildung', 3, 3.2100, 'final', 0, 'Der Abschnitt rekonstruiert die Mengenlehre als formale Trägerstruktur moderner Mathematik. Behandelt werden Elementbeziehung, Extensionalität, Teilmengen, Potenzmengen, Cantors Satz, geordnete Paare und kartesische Produkte. Die Leistungsfähigkeit der Mengenlehre wird von der weiterführenden Frage nach Entstehung, Auswahl und funktionaler Wirksamkeit mathematischer Strukturen abgegrenzt.', '2026-07-18 06:03:45', '2026-07-18 06:03:45'),
(14, 11, '3.2.2', 'Relationen als Beschreibung mathematischer Zusammenhänge', 3, 3.2200, 'final', 0, 'Der Abschnitt rekonstruiert Relationen als Auswahl geordneter Tupel aus kartesischen Produkten. Behandelt werden Relationseigenschaften, Äquivalenzen, Ordnungen, Umkehrung, Komposition, Hüllen und Matrixdarstellungen. Die Darstellung bleibt Forschungsstand und nimmt keine FRZK-Axiomatik vorweg.', '2026-07-18 06:16:56', '2026-07-18 06:16:56'),
(15, 11, '3.2.3', 'Algebraische Strukturen als Träger mathematischer Operationen', 3, 3.2300, 'final', 0, 'Der Abschnitt rekonstruiert algebraische Strukturen als Mengen mit inneren Verknüpfungen. Behandelt werden Abgeschlossenheit, Assoziativität, neutrales und inverses Element sowie Gruppen, Ringe und Körper. Die Darstellung bleibt mathematischer Forschungsstand und bereitet den späteren Übergang zu funktionalen Operationen vor.', '2026-07-18 06:51:13', '2026-07-18 06:51:13'),
(16, 11, '3.2.4', 'Graphen und Netzwerke als Darstellung relationaler Gesamtstrukturen', 3, 3.2400, 'final', 0, 'Der Abschnitt rekonstruiert Graphen als relationale Gesamtstrukturen und behandelt gerichtete sowie ungerichtete Graphen, Grade, Adjazenzmatrizen, Pfade, Zusammenhang, Distanz, Zyklen, Bäume, gewichtete Graphen, Gradverteilungen, Clusterkoeffizienten und Gradzentralität.', '2026-07-18 07:43:11', '2026-07-18 07:43:11'),
(17, 11, '3.2.5', 'Funktionen und Abbildungen als formale Beschreibung eindeutiger Zuordnungen', 3, 3.2500, 'final', 0, 'Der Abschnitt rekonstruiert Funktionen als eindeutige Relationen zwischen Mengen. Behandelt werden Definitions- und Zielbereich, Bildmenge, Injektivität, Surjektivität, Bijektivität, Umkehrfunktion, Komposition und Identitätsabbildung. Die Darstellung bleibt mathematischer Forschungsstand.', '2026-07-18 08:59:33', '2026-07-18 08:59:33'),
(18, 11, '3.2.6', 'Vektorräume als mathematische Beschreibung linearer Zustandsräume', 3, 3.2600, 'final', 0, 'Der Abschnitt führt Vektorräume über die Vektoraddition und Skalarmultiplikation ein. Behandelt werden die acht Vektorraumaxiome, Nullvektor und additives Inverses, Linearkombination, linearer Spann, lineare Unabhängigkeit, Basis und Dimension.', '2026-07-18 11:15:45', '2026-07-18 11:15:45'),
(19, 11, '3.2.7', 'Lineare Abbildungen, Matrizen und Operatoren', 3, 3.2700, 'final', 0, 'Der Abschnitt behandelt lineare Abbildungen, Kern, Bild, Rang, Nullität, Darstellungsmatrizen, lineare Operatoren, Komposition und Invertierbarkeit.', '2026-07-18 11:39:48', '2026-07-18 11:39:48'),
(20, 11, '3.2.8', 'Skalarprodukte, Normen und Metriken als mathematische Beschreibung von Ähnlichkeit und Abstand', 3, 3.2800, 'final', 0, 'Der Abschnitt führt Skalarprodukte, Normen, Winkel, Orthogonalität, Metriken und orthogonale Projektionen als mathematische Grundlage von Ähnlichkeit, Länge und Abstand ein.', '2026-07-18 12:14:42', '2026-07-18 12:14:42'),
(21, 11, '3.2.9', 'Eigenwerte, Eigenvektoren und Invarianz funktionaler Zustände', 3, 3.2900, 'final', 0, 'Der Abschnitt führt Eigenwerte, Eigenvektoren, Eigenräume, Spektren, Vielfachheiten, Diagonalisierung sowie invariante Unterräume als Grundlage stabiler Transformationsrichtungen ein.', '2026-07-18 13:41:23', '2026-07-18 13:41:23'),
(22, 11, '3.2.10', 'Bilinearformen und quadratische Formen als mathematische Beschreibung funktionaler Energie- und Bewertungsstrukturen', 3, 3.2100, 'final', 0, 'Mathematische Grundlage für Wechselwirkungs-, Bewertungs-, Energie- und Stabilitätsstrukturen.', '2026-07-18 14:07:53', '2026-07-18 14:07:53'),
(23, 11, '3.2.11', 'Orthogonale Projektionen und Zerlegungen als Grundlage funktionaler Separation', 3, 3.2110, 'final', 1, 'Der Abschnitt führt orthogonale Projektionen und Zerlegungen als mathematische Grundlage funktionaler Separation ein.', '2026-07-18 14:41:25', '2026-07-18 14:41:25'),
(24, 11, '3.2.12', 'Spektraltheorie als mathematische Grundlage funktionaler Zustandsräume', 3, 3.2120, 'final', 1, 'Der Abschnitt schließt die mathematischen Grundlagen mit der spektralen Beschreibung linearer Operatoren und dem FRZK-spezifischen funktionalen Spektrum ab.', '2026-07-18 14:51:07', '2026-07-18 14:51:07'),
(25, 11, '3.2.13', 'Zusammenfassung und mathematische Einordnung', 3, 3.2130, 'final', 0, 'Zusammenfassungs- und Übergangsabschnitt. Er ordnet die mathematischen Grundlagen des Kapitels 3.2 in das FRZK ein und führt ohne neue mathematische Objekte zur Axiomatik des Kapitels 3.3.', '2026-07-18 15:05:26', '2026-07-18 15:05:26'),
(26, 1, '3.3', 'Axiomatische Grundlagen des Funktionalen Raum-Zeit-Kohärenzsystems', 3, 3.0000, 'draft', 1, 'Kompletter Neustart von Kapitel 3.3.', '2026-07-19 05:56:26', '2026-07-19 05:56:26'),
(27, 26, '3.3.0', 'Einleitung', 3, 0.0000, 'draft', 1, 'Methodischer Übergang von Kapitel 3.2 zur FRZK-Axiomatik.', '2026-07-19 05:56:26', '2026-07-19 05:56:26'),
(29, 26, '3.3.1', 'Prämathematische Grundbegriffe und formaler Ausgangspunkt', 3, 3.3010, 'final', 1, 'Einführung des funktionalen Trägerbereichs, der qualitativen Unterscheidung, eines möglichen Differenzmaßes, der kontextabhängigen Wirksamkeit und der aktuell wirksamen Teilstruktur.', '2026-07-19 07:37:27', '2026-07-19 07:37:27'),
(30, 26, '3.3.2', 'Axiom A1 – Funktionale Unterscheidbarkeit', 3, 3.3020, 'final', 1, 'Formulierung der minimalen funktionalen Unterscheidbarkeit, einschließlich Kontextabhängigkeit, funktionaler Nichtunterscheidbarkeit und Proposition zur Notwendigkeit funktionaler Differenz.', '2026-07-19 08:04:23', '2026-07-19 08:04:23'),
(31, 26, '3.3.3', 'Axiom A2 – Funktionale Relationierbarkeit', 3, 3.3030, 'final', 1, 'Formulierung der Möglichkeit funktionaler Relationierung, Einführung der Relationsmenge, qualitativer und gewichteter Kopplung sowie Proposition zur Entstehung funktionaler Struktur.', '2026-07-19 08:16:47', '2026-07-19 08:16:47'),
(32, 26, '3.3.4', 'Axiom A3 – Funktionale Transformierbarkeit', 3, 3.3040, 'final', 1, 'Einführung funktionaler Operationen, Transformationen von Gehalten und Relationen, Definitions- und Bildbereichen, Komposition, Nichtdeterminismus und funktionalen Zustandsfolgen.', '2026-07-19 10:34:32', '2026-07-19 10:34:32'),
(33, 26, '3.3.5', 'Axiom A4 – Funktionale Kompatibilität', 3, 3.3050, 'final', 1, 'Kompatible Operationen, funktionale Rekonstruierbarkeit, Kompatibilitätsoperator und Kompatibilitätsgrad.', '2026-07-19 11:00:26', '2026-07-19 11:00:26'),
(39, 26, '3.3.6', 'Axiom A5 – Funktionale Kohärenz', 3, 3.3060, 'final', 1, 'Einführung funktionaler Kohärenz, lokaler und globaler Kohärenz, gewichteter Aggregation, relationaler Dichte, Transformationseffekten und kritischem Kohärenzwert.', '2026-07-19 12:13:24', '2026-07-19 12:13:24'),
(40, 26, '3.3.7', 'Axiom A6 – Funktionale Zustandsbildung', 3, 3.3070, 'final', 1, 'Einführung funktionaler Zustände, Zustandsräume, Zulässigkeit, deterministischer und nichtdeterministischer Zustandsbildung sowie tragfähiger Zustände.', '2026-07-19 13:01:58', '2026-07-19 13:01:58'),
(41, 26, '3.3.8', 'Axiom A7 – Funktionale Zustandsübergänge', 3, 3.3080, 'final', 1, 'Einführung funktionaler Übergangsabbildungen, Übergangszulässigkeit, tragfähiger Übergänge, Übergangspfade sowie reversibler und irreversibler Zustandsübergänge.', '2026-07-19 13:26:03', '2026-07-19 13:26:03'),
(42, 26, '3.3.9', 'Logische Konsequenzen des Axiomensystems', 3, 3.3090, 'draft', 1, 'Sammelabschnitt zur Ableitung logischer Konsequenzen, Unabhängigkeit, Konsistenz und weiterer Eigenschaften des FRZK-Axiomensystems.', '2026-07-19 15:36:45', '2026-07-19 15:36:45'),
(43, 42, '3.3.9.1', 'Möglichkeit funktionaler Dynamik', 3, 3.3091, 'final', 1, 'Logische Ableitung eines funktionalen Dynamikraums aus den Axiomen A1 bis A7.', '2026-07-19 15:36:45', '2026-07-19 15:36:45'),
(44, 42, '3.3.9.2', 'Eigenständigkeit der Axiome', 3, 3.3092, 'final', 1, 'Untersuchung der funktionalen Nichtreduzierbarkeit und schwachen Unabhängigkeit der Axiome A1 bis A7.', '2026-07-19 15:36:45', '2026-07-19 15:36:45'),
(45, 42, '3.3.9.3', 'Innere Konsistenz des Axiomensystems', 3, 3.3093, 'final', 1, 'Untersuchung der gemeinsamen Erfüllbarkeit der Axiome A1 bis A7 durch ein konstruiertes Minimalmodell.', '2026-07-19 17:09:21', '2026-07-19 17:09:21'),
(46, 42, '3.3.9.4', 'Verhältnis von Axiomen, Definitionen und abgeleiteten Aussagen', 3, 3.3094, 'final', 1, 'Formale Trennung von Grundsetzungen, Begriffsbestimmungen und abgeleiteten Aussagen sowie Einführung eines azyklischen Abhängigkeitsgraphen.', '2026-07-20 03:04:19', '2026-07-20 03:04:19'),
(47, 42, '3.3.9.5', 'Reichweite und Grenzen der Vollständigkeit', 3, 3.3095, 'final', 1, 'Differenzierung begrifflicher, funktionaler, formallogischer und zielbezogener Vollständigkeit.', '2026-07-20 03:15:14', '2026-07-20 03:15:14'),
(48, 42, '3.3.9.6', 'Metatheoretischer Abschluss des Axiomensystems', 3, 3.3096, 'final', 1, 'Zusammenführung von Unabhängigkeit, Konsistenz, Hierarchie und zielbezogener Vollständigkeit.', '2026-07-20 03:47:38', '2026-07-20 03:47:38'),
(49, 26, '3.3.10', 'Zusammenfassung und Übergang zur mathematischen Rekonstruktion', 3, 3.3100, 'final', 1, 'Redaktioneller und formaler Abschluss von Kapitel 3.3 sowie Überleitung zu Kapitel 3.4.', '2026-07-20 04:12:50', '2026-07-20 04:12:50'),
(50, 1, '3.4', 'Mathematische Rekonstruktion funktionaler Organisation', 3, 3.4000, 'final', 1, 'Kapitel zur schrittweisen mathematischen Rekonstruktion der aus den Axiomen des FRZK ableitbaren Strukturen. Raum und Zeit werden nicht vorausgesetzt, sondern als Ergebnisse funktionaler Organisation hergeleitet. Kapitel 3.4 abgeschlossen. Mathematische Rekonstruktion funktionaler Organisation vollständig dokumentiert. Dynamik, Stabilität, Instabilität, Emergenz und Selbstorganisation integriert.', '2026-07-20 05:06:05', '2026-07-21 06:32:22'),
(51, 50, '3.4.0', 'Einleitung', 3, 3.4001, 'final', 1, 'Einleitung in die mathematische Rekonstruktion des FRZK. Der Abschnitt bestimmt die Ableitung einer mathematischen Struktur aus dem Axiomensystem als zentrale Aufgabe und legt den rekursiven Aufbau der Rekonstruktion fest.', '2026-07-20 05:06:05', '2026-07-20 05:06:05'),
(52, 50, '3.4.1', 'Funktionaler Zustand', 3, 3.4010, 'final', 1, 'Rekonstruktion des funktionalen Zustands aus funktionalen Gehalten, Relationen und Operationen; Herleitung der Zustandsmenge, Identitätsbedingung, Unterscheidbarkeit und Minimalität der Zustandsdarstellung.', '2026-07-20 05:17:03', '2026-07-20 05:17:03'),
(55, 50, '3.4.2', 'Klassen funktionaler Zustände', 3, 3.4020, 'final', 1, 'Rekonstruktion funktionaler Äquivalenz, funktionaler Zustandsklassen und der Quotientenmenge; Nachweis der Äquivalenzeigenschaften, der Partition der Zustandsmenge und der eindeutigen Klassenzugehörigkeit.', '2026-07-20 05:34:21', '2026-07-20 05:34:21'),
(57, 50, '3.4.3', 'Funktionale Relationen', 3, 3.4030, 'final', 1, 'Rekonstruktion funktionaler Relationen, gerichteter Zustandspaare, funktionaler Zustandsstrukturen, relationaler Einbindung und der Notwendigkeit nichtleerer Relationierung.', '2026-07-20 06:13:01', '2026-07-20 06:13:01'),
(58, 50, '3.4.4', 'Funktionale Transformationen', 3, 3.4040, 'final', 1, 'Rekonstruktion eindeutiger funktionaler Zustandszuordnungen, der induzierten Transformationsrelation, funktionaler Fixpunkte sowie der Komposition und Identität funktionaler Transformationen.', '2026-07-20 06:25:31', '2026-07-20 06:25:31'),
(59, 50, '3.4.5', 'Funktionale Operatoren', 3, 3.4050, 'review', 1, 'Literaturgestützte vollständige Revision: funktionale Operatormenge, Komposition, Assoziativität, Identität, Invertierbarkeit, Monoid- und Gruppenstruktur.', '2026-07-20 07:26:08', '2026-07-20 13:06:02'),
(60, 50, '3.4.6', 'Funktionale Übergänge und Operatorfolgen', 3, 3.4060, 'review', 1, 'Vollständige literaturgestützte Revision: Übergänge, Operatorfolgen, Zustandsfolgen, Entwicklungspfade und Übergangsordnung.', '2026-07-20 07:44:33', '2026-07-20 13:22:16'),
(61, 50, '3.4.7', 'Funktionale Kohärenz von Zuständen und Entwicklungspfaden', 3, 3.4700, 'review', 1, 'Vollständige literaturgestützte Revision: kohärenztragende Relationen, Relationserhaltung, kohärente Zustände, kohärenzerhaltende Operatoren, kohärente Pfade und Kohärenzbruch.', '2026-07-20 14:05:47', '2026-07-20 14:05:47'),
(62, 50, '3.4.8', 'Rekonstruktion funktionaler Raumstrukturen', 3, 3.4800, 'review', 1, 'Vollständige literaturgestützte Revision: Erreichbarkeit, Zusammenhang, Nachbarschaft, Raumstruktur, Distanz und Richtung.', '2026-07-20 14:47:19', '2026-07-20 14:47:19'),
(63, 50, '3.4.9', 'Rekonstruktion funktionaler Zeitstrukturen', 3, 3.4900, 'review', 1, 'Vollständige literaturgestützte Revision: Nachfolge, Vorordnung, Zyklen, Zustandsinstanzen, Zeitdifferenzen, Zeitschnitte und Irreversibilität.', '2026-07-20 15:45:29', '2026-07-20 15:45:29'),
(64, 50, '3.4.10', 'Rekonstruktion funktionaler Raum-Zeit-Strukturen', 3, 3.4100, 'review', 1, 'Zusammenführung funktionaler Raum- und Zeitstrukturen zu einer gemeinsamen Ereignis-, Pfad-, Ordnungs- und Kohärenzstruktur.', '2026-07-21 04:10:20', '2026-07-21 04:10:20'),
(65, NULL, '3.5', 'Mathematische Erweiterung funktionaler Organisation und ihre Anwendung', 3, 5.0000, 'final', 1, 'Kapitel 3.5 vollständig abgeschlossen. Abschnitte 3.5.1-3.5.8 dokumentiert.', '2026-07-21 20:48:46', '2026-07-21 21:18:39'),
(66, 65, '3.5.0', 'Einleitung', 3, 5.0000, 'final', 1, 'Einführung der Erweiterung von funktionalen Organisationen auf gekoppelte Systeme', '2026-07-21 20:48:46', '2026-07-21 20:48:46'),
