(202, '3.312', 21, 'Eigenwertgleichung', 'T(v)=lambda v', 'T(v)=lambda v', 'Ein Eigenvektor behält unter T seine Richtung und wird mit λ skaliert.', 'definition', 'adapted', 101, NULL, 'v≠0.', 'checked', 20),
(203, '3.313', 21, 'Eigenraum', 'E_lambda=ker(T-lambda I)', 'E_lambda=ker(T-lambda I)', 'Der Eigenraum ist der Kern des verschobenen Operators T-λI.', 'definition', 'adapted', 101, NULL, 'λ ist ein Eigenwert.', 'checked', 20),
(204, '3.314', 21, 'Charakteristische Gleichung', 'det(T-lambda I)=0', 'det(T-lambda I)=0', 'Die Eigenwerte sind Nullstellen des charakteristischen Polynoms.', 'theorem', 'adapted', 101, NULL, 'V ist endlichdimensional.', 'checked', 20),
(205, '3.315', 21, 'Spektrum', 'sigma(T)={lambdain Kmiddet(T-lambda I)=0}', 'sigma(T)={lambdain Kmiddet(T-lambda I)=0}', 'Das Spektrum enthält sämtliche Eigenwerte des Operators.', 'definition', 'adapted', 101, NULL, 'V ist endlichdimensional.', 'checked', 20),
(206, '3.316', 21, 'Geometrische Vielfachheit', 'dim(E_lambda)', 'dim(E_lambda)', 'Die Dimension des Eigenraums ist die geometrische Vielfachheit.', 'definition', 'adapted', 101, NULL, 'λ ist ein Eigenwert.', 'checked', 20),
(207, '3.317', 21, 'Schranken der geometrischen Vielfachheit', '1leqdim(E_lambda)leq m_lambda', '1leqdim(E_lambda)leq m_lambda', 'Die geometrische Vielfachheit liegt zwischen eins und der algebraischen Vielfachheit.', 'theorem', 'adapted', 101, NULL, 'm_λ bezeichnet die algebraische Vielfachheit.', 'checked', 20),
(208, '3.318', 21, 'Ähnlichkeit zur Diagonalform', 'T=PDP^{-1}', 'T=PDP^{-1}', 'Ein diagonalisierbarer Operator ist zu einer Diagonalmatrix ähnlich.', 'theorem', 'adapted', 101, NULL, 'P ist invertierbar.', 'checked', 20),
(209, '3.319', 21, 'Diagonalmatrix der Eigenwerte', 'D=operatorname{diag}(lambda_1,ldots,lambda_n)', 'D=operatorname{diag}(lambda_1,ldots,lambda_n)', 'Die Diagonalmatrix enthält die Eigenwerte auf der Hauptdiagonalen.', 'definition', 'adapted', 101, NULL, 'T besitzt eine Eigenvektorbasis.', 'checked', 20),
(210, '3.320', 21, 'Spurformel', 'operatorname{tr}(T)=sum_ilambda_i', 'operatorname{tr}(T)=sum_ilambda_i', 'Die Spur entspricht der Summe der Eigenwerte mit algebraischer Vielfachheit.', 'theorem', 'adapted', 101, NULL, 'Das charakteristische Polynom zerfällt.', 'checked', 20),
(211, '3.321', 21, 'Determinantenformel', 'det(T)=prod_ilambda_i', 'det(T)=prod_ilambda_i', 'Die Determinante entspricht dem Produkt der Eigenwerte mit algebraischer Vielfachheit.', 'theorem', 'adapted', 101, NULL, 'Das charakteristische Polynom zerfällt.', 'checked', 20),
(212, '3.322', 21, 'Invarianter Unterraum', 'T(U)subseteq U', 'T(U)subseteq U', 'Der Operator führt jeden Vektor des Unterraums U wieder in U.', 'definition', 'adapted', 101, NULL, 'U ist ein Untervektorraum von V.', 'checked', 20),
(213, '3.323', 22, 'Abbildung einer Bilinearform', 'B:V\\times V\\rightarrow K', 'B:V\\times V\\rightarrow K', 'Eine Bilinearform bildet zwei Vektoren auf einen Skalar ab.', 'definition', 'adapted', 102, NULL, 'V ist ein Vektorraum über K.', 'checked', 21),
(214, '3.324', 22, 'Linearität im ersten Argument', 'B(\\lambda u+\\mu v,w)=\\lambda B(u,w)+\\mu B(v,w)', 'B(\\lambda u+\\mu v,w)=\\lambda B(u,w)+\\mu B(v,w)', 'Die Bilinearform ist im ersten Argument linear.', 'axiom', 'adapted', 102, NULL, 'u,v,w∈V und λ,μ∈K.', 'checked', 21),
(215, '3.325', 22, 'Linearität im zweiten Argument', 'B(u,\\lambda v+\\mu w)=\\lambda B(u,v)+\\mu B(u,w)', 'B(u,\\lambda v+\\mu w)=\\lambda B(u,v)+\\mu B(u,w)', 'Die Bilinearform ist im zweiten Argument linear.', 'axiom', 'adapted', 102, NULL, 'u,v,w∈V und λ,μ∈K.', 'checked', 21),
(216, '3.326', 22, 'Symmetrie', 'B(u,v)=B(v,u)', 'B(u,v)=B(v,u)', 'Die Argumente einer symmetrischen Bilinearform können vertauscht werden.', 'definition', 'adapted', 103, NULL, 'B ist bilinear.', 'checked', 21),
(217, '3.327', 22, 'Schiefsymmetrie', 'B(u,v)=-B(v,u)', 'B(u,v)=-B(v,u)', 'Beim Vertauschen der Argumente ändert sich das Vorzeichen.', 'definition', 'adapted', 103, NULL, 'B ist bilinear.', 'checked', 21),
(218, '3.328', 22, 'Quadratische Form aus Bilinearform', 'Q(v)=B(v,v)', 'Q(v)=B(v,v)', 'Eine quadratische Form bewertet einen Vektor durch Einsetzen in beide Argumente.', 'definition', 'adapted', 103, NULL, 'B ist symmetrisch bilinear.', 'checked', 21),
(219, '3.329', 22, 'Matrixdarstellung der Bilinearform', 'B(u,v)=u^{T}Av', 'B(u,v)=u^{T}Av', 'Die Bilinearform wird bezüglich einer Basis durch eine Matrix dargestellt.', 'theorem', 'adapted', 102, NULL, 'V ist endlichdimensional.', 'checked', 21);
INSERT INTO `equations` (`equation_id`, `equation_number`, `section_id`, `title`, `equation_latex`, `word_latex`, `plain_description`, `equation_type`, `provenance`, `source_id`, `derivation`, `assumptions`, `validation_status`, `created_revision_id`) VALUES
(220, '3.330', 22, 'Matrixdarstellung der quadratischen Form', 'Q(v)=v^{T}Av', 'Q(v)=v^{T}Av', 'Die quadratische Form wird durch dieselbe Matrix in beiden Vektorargumenten dargestellt.', 'definition', 'adapted', 103, NULL, 'A ist symmetrisch.', 'checked', 21),
(221, '3.331', 22, 'Positive Definitheit', 'Q(v)>0\\quad\\forall v\\neq0', 'Q(v)>0\\quad\\forall v\\neq0', 'Jeder von Null verschiedene Zustand besitzt einen strikt positiven Wert.', 'definition', 'adapted', 103, NULL, 'V ist reell.', 'checked', 21),
(222, '3.332', 22, 'Positive Semidefinitheit', 'Q(v)\\geq0', 'Q(v)\\geq0', 'Die quadratische Form nimmt keine negativen Werte an.', 'definition', 'adapted', 103, NULL, 'V ist reell.', 'checked', 21),
(223, '3.333', 22, 'Energieform', 'E(v)=v^{T}Av', 'E(v)=v^{T}Av', 'Die Energieform ordnet einem Zustand eine skalare Energie zu.', 'definition', '', 102, NULL, 'A ist symmetrisch positiv definit.', 'checked', 21),
(224, '3.334', 22, 'Minimum der Energieform', 'v=0', 'v=0', 'Das eindeutige Minimum einer positiv definiten Energieform liegt im Nullvektor.', 'theorem', 'adapted', 102, NULL, 'A ist positiv definit.', 'checked', 21),
(225, '3.335', 23, 'Abbildung einer Projektion', 'P:V\rightarrow V', 'P:V\rightarrow V', 'Die Projektion ist ein linearer Operator auf dem Zustandsraum.', 'definition', 'adapted', 105, NULL, 'V ist ein Skalarproduktraum.', 'checked', 22),
(226, '3.336', 23, 'Idempotenz der Projektion', 'P^2=P', 'P^2=P', 'Eine erneute Projektion verändert das bereits projizierte Ergebnis nicht.', 'definition', 'adapted', 105, NULL, 'P ist linear.', 'checked', 22),
(227, '3.337', 23, 'Symmetrie der orthogonalen Projektion', 'P^T=P', 'P^T=P', 'Die Projektionsmatrix ist symmetrisch.', 'definition', 'adapted', 105, NULL, 'Endlichdimensionale reelle Darstellung.', 'checked', 22),
(228, '3.338', 23, 'Projektionszerlegung', 'v=Pv+(I-P)v', 'v=Pv+(I-P)v', 'Ein Vektor zerfällt in projizierten und orthogonalen Anteil.', 'theorem', 'adapted', 105, NULL, 'P ist eine orthogonale Projektion.', 'checked', 22),
(229, '3.339', 23, 'Projektionsmatrix', 'A^2=A', 'A^2=A', 'Eine Projektionsmatrix ist idempotent.', 'definition', 'adapted', 105, NULL, 'A ist quadratisch.', 'checked', 22),
(230, '3.340', 23, 'Symmetrische Projektionsmatrix', 'A^T=A', 'A^T=A', 'Eine orthogonale Projektionsmatrix ist symmetrisch.', 'definition', 'adapted', 105, NULL, 'A beschreibt eine orthogonale Projektion.', 'checked', 22),
(231, '3.341', 23, 'Beste Approximation', '|v-Pv|=min_{uin U}|v-u|', '|v-Pv|=min_{uin U}|v-u|', 'Der projizierte Vektor ist die beste Approximation innerhalb des Unterraums U.', 'theorem', 'adapted', 105, NULL, 'U ist abgeschlossen.', 'checked', 22),
(232, '3.342', 23, 'Orthogonalkomplement', 'U^perp={vin Vmidlangle v,u\rangle=0 forall uin U}', 'U^perp={vin Vmidlangle v,u\rangle=0 forall uin U}', 'Das Orthogonalkomplement enthält alle zu U orthogonalen Vektoren.', 'definition', 'adapted', 105, NULL, 'U ist ein Unterraum von V.', 'checked', 22),
(233, '3.343', 23, 'Orthogonale direkte Summe', 'V=Uoplus U^perp', 'V=Uoplus U^perp', 'Der Zustandsraum zerfällt in einen Unterraum und dessen Orthogonalkomplement.', 'theorem', 'adapted', 105, NULL, 'U ist abgeschlossen.', 'checked', 22),
(234, '3.344', 23, 'Gram-Schmidt-Rekursion', 'u_k=v_k-sum_{i=1}^{k-1}frac{langle v_k,u_i\rangle}{langle u_i,u_i\rangle}u_i', 'u_k=v_k-sum_{i=1}^{k-1}frac{langle v_k,u_i\rangle}{langle u_i,u_i\rangle}u_i', 'Die Rekursion entfernt aus v_k sämtliche Komponenten entlang der zuvor konstruierten Richtungen.', 'definition', 'adapted', 104, NULL, 'v_1,...,v_n sind linear unabhängig.', 'checked', 22),
(235, '3.345', 24, 'Linearer Operator', 'A:V\rightarrow V', 'A:V\rightarrow V', 'A bildet den Zustandsraum V linear auf sich selbst ab.', 'definition', 'adapted', 97, NULL, 'V ist ein Vektorraum.', 'checked', 23),
(236, '3.346', 24, 'Eigenwertgleichung', 'Av=lambda v', 'Av=lambda v', 'Ein Eigenvektor wird durch A lediglich skaliert.', 'definition', 'adapted', 97, NULL, 'v ist von Null verschieden.', 'checked', 23),
(237, '3.347', 24, 'Eigenraum', 'E_lambda={vin Vmid Av=lambda v}', 'E_lambda={vin Vmid Av=lambda v}', 'Der Eigenraum enthält alle Eigenvektoren zum Eigenwert λ und den Nullvektor.', 'definition', 'adapted', 97, NULL, 'λ ist ein Eigenwert.', 'checked', 23),
(238, '3.348', 24, 'Charakteristische Gleichung', 'det(A-lambda I)=0', 'det(A-lambda I)=0', 'Die Eigenwerte sind die Nullstellen des charakteristischen Polynoms.', 'theorem', 'adapted', 97, NULL, 'A ist quadratisch.', 'checked', 23),
(239, '3.349', 24, 'Endlichdimensionales Spektrum', 'sigma(A)={lambda_1,ldots,lambda_n}', 'sigma(A)={lambda_1,ldots,lambda_n}', 'Das Spektrum wird im endlichdimensionalen Fall als Menge der Eigenwerte dargestellt.', 'definition', 'adapted', 106, NULL, 'A besitzt endlich viele Eigenwerte.', 'checked', 23),
(240, '3.350', 24, 'Orthogonale Diagonalisierung', 'A=QLambda Q^T', 'A=QLambda Q^T', 'Eine reelle symmetrische Matrix wird durch eine orthogonale Basis diagonalisiert.', 'theorem', 'adapted', 106, NULL, 'A ist reell und symmetrisch.', 'checked', 23),
(241, '3.351', 24, 'Spektralzerlegung', 'A=sum_ilambda_iP_i', 'A=sum_ilambda_iP_i', 'Der Operator wird als gewichtete Summe orthogonaler Projektoren dargestellt.', 'definition', 'adapted', 106, NULL, 'A ist selbstadjungiert und besitzt eine diskrete Spektralzerlegung.', 'checked', 23),
(242, '3.352', 24, 'Orthogonalität verschiedener Eigenräume', 'lambda_i\neqlambda_jRightarrow E_iperp E_j', 'lambda_i\neqlambda_jRightarrow E_iperp E_j', 'Eigenräume verschiedener Eigenwerte sind bei selbstadjungierten Operatoren orthogonal.', 'theorem', 'adapted', 106, NULL, 'A ist selbstadjungiert.', 'checked', 23),
(243, '3.353', 24, 'Dominanter Eigenwert', '|lambda_{max}|=max_i|lambda_i|', '|lambda_{max}|=max_i|lambda_i|', 'Der dominante Eigenwert besitzt den größten Betrag innerhalb des Spektrums.', 'definition', 'adapted', 106, NULL, 'Das Maximum existiert.', 'checked', 23),
(247, '3.354', 29, 'Funktionaler Trägerbereich', '\\mathcal{F}=\\{f_i\\mid i\\in I\\}', '\\mathcal{F}=\\{f_i\\mid i\\in I\\}', 'Der funktionale Trägerbereich enthält die durch eine Indexmenge bezeichneten funktionalen Gehalte.', 'definition', 'original', NULL, 'Formaler Ausgangspunkt für die weitere Axiomatik.', 'Die Schreibweise behauptet keine ontologisch abgeschlossenen Objekte.', 'checked', 27),
(248, '3.355', 29, 'Qualitative Unterscheidungsabbildung', '\\delta_F:\\mathcal{F}\\times\\mathcal{F}\\rightarrow\\{0,1\\}', '\\delta_F:\\mathcal{F}\\times\\mathcal{F}\\rightarrow\\{0,1\\}', 'Die Abbildung ordnet einem Paar funktionaler Gehalte den Wert null oder eins für Nichtunterscheidbarkeit beziehungsweise Unterscheidbarkeit zu.', 'definition', 'original', NULL, 'Minimalform einer qualitativen funktionalen Unterscheidung.', 'Es wird kein Distanzmaß vorausgesetzt.', 'checked', 27),
(249, '3.356', 29, 'Fallunterscheidung der qualitativen Differenz', '\\delta_F(f_i,f_j)=\\begin{cases}0,&\\text{wenn }f_i\\text{ und }f_j\\text{ funktional nicht unterschieden werden},\\\\1,&\\text{wenn }f_i\\text{ und }f_j\\text{ funktional unterschieden werden}\\end{cases}', '\\delta_F(f_i,f_j)=\\begin{cases}0,&\\text{wenn }f_i\\text{ und }f_j\\text{ funktional nicht unterschieden werden},\\\\1,&\\text{wenn }f_i\\text{ und }f_j\\text{ funktional unterschieden werden}\\end{cases}', 'Explizite Fallunterscheidung für die qualitative funktionale Unterscheidung.', 'definition', 'original', NULL, 'Aus Gleichung (3.355) konkretisierte Wertzuordnung.', 'Die Unterscheidung bleibt binär und qualitativ.', 'checked', 27),
(250, '3.357', 29, 'Allgemeines funktionales Differenzmaß', 'd_F:\\mathcal{F}\\times\\mathcal{F}\\rightarrow\\mathbb{R}_{\\geq 0}', 'd_F:\\mathcal{F}\\times\\mathcal{F}\\rightarrow\\mathbb{R}_{\\geq 0}', 'Mögliche quantitative Zuordnung eines nichtnegativen funktionalen Differenzwertes.', 'metric', 'original', NULL, 'Verallgemeinerung der qualitativen Unterscheidung für eine spätere quantitative Rekonstruktion.', 'Metrikeigenschaften werden noch nicht gefordert.', 'draft', 27),
(251, '3.358', 29, 'Kontextabhängige funktionale Wirksamkeit', '\\omega_F:\\mathcal{F}\\times\\mathcal{C}\\rightarrow\\mathcal{W}', '\\omega_F:\\mathcal{F}\\times\\mathcal{C}\\rightarrow\\mathcal{W}', 'Die Wirksamkeitsabbildung ordnet einem funktionalen Gehalt in einem Kontext einen Wirkungswert zu.', 'definition', 'original', NULL, 'Formale Verbindung eines funktionalen Gehalts mit Kontext und Wirkung.', 'Die Bereiche C und W bleiben zunächst abstrakt.', 'checked', 27),
(252, '3.359', 29, 'Kontextabhängige Wirkungsdifferenz', '\\omega_F(f_i,c)\\neq\\omega_F(f_j,c)', '\\omega_F(f_i,c)\\neq\\omega_F(f_j,c)', 'Zwei funktionale Gehalte entfalten innerhalb desselben Kontextes unterschiedliche Wirkungen.', 'model', 'original', NULL, 'Konkretisierung der funktionalen Nichtidentität über die Wirksamkeitsabbildung.', 'Beide Gehalte werden im selben Kontext betrachtet.', 'checked', 27),
(253, '3.360', 29, 'Unterscheidbarkeit durch Wirkungsdifferenz', '\\delta_F(f_i,f_j)=1\\quad\\Longleftrightarrow\\quad\\exists c\\in\\mathcal{C}:\\omega_F(f_i,c)\\neq\\omega_F(f_j,c)', '\\delta_F(f_i,f_j)=1\\quad\\Longleftrightarrow\\quad\\exists c\\in\\mathcal{C}:\\omega_F(f_i,c)\\neq\\omega_F(f_j,c)', 'Funktionale Gehalte gelten genau dann als unterscheidbar, wenn wenigstens ein Kontext existiert, in dem ihre Wirkungen voneinander abweichen.', 'model', 'original', NULL, 'Verknüpft die qualitative Unterscheidungsabbildung mit der kontextabhängigen Wirksamkeit.', 'Der Kontextbereich ist eine formale Vorstruktur und wird später rekonstruiert.', 'draft', 27),
(254, '3.361', 29, 'Aktuell wirksame Teilstruktur', '\\mathcal{F}_A\\subseteq\\mathcal{F}', '\\mathcal{F}_A\\subseteq\\mathcal{F}', 'Die aktuell wirksamen funktionalen Gehalte bilden eine Teilmenge des möglichen funktionalen Trägerbereichs.', 'definition', 'original', NULL, 'Formale Trennung zwischen möglicher und aktuell realisierter funktionaler Struktur.', 'Nicht jeder formal mögliche Gehalt muss aktuell wirksam sein.', 'checked', 27),
(255, '3.362', 30, 'Nichtleerheit des funktionalen Trägerbereichs', '\\mathcal{F}\\neq\\varnothing', '\\mathcal{F}\\neq\\varnothing', 'Der funktionale Trägerbereich ist nicht leer.', 'axiom', 'original', NULL, 'Erster formaler Bestandteil von Axiom A1.', 'Der in 3.3.1 eingeführte Trägerbereich wird vorausgesetzt.', 'checked', 28),
(256, '3.363', 30, 'Kontextbezogene funktionale Nichtidentität', '\\exists f_i,f_j\\in\\mathcal{F}\\;\\exists c\\in\\mathcal{C}:\\omega_F(f_i,c)\\neq\\omega_F(f_j,c)', '\\exists f_i,f_j\\in\\mathcal{F}\\;\\exists c\\in\\mathcal{C}:\\omega_F(f_i,c)\\neq\\omega_F(f_j,c)', 'Mindestens zwei funktionale Gehalte wirken in wenigstens einem Kontext verschieden.', 'axiom', 'original', NULL, 'Zweiter formaler Bestandteil von Axiom A1.', 'Funktionaler Trägerbereich, Kontextbereich und Wirksamkeitsabbildung sind eingeführt.', 'checked', 28),
(257, '3.364', 30, 'Unterscheidbarkeit über die qualitative Unterscheidungsfunktion', '\\exists f_i,f_j\\in\\mathcal{F}:\\delta_F(f_i,f_j)=1', '\\exists f_i,f_j\\in\\mathcal{F}:\\delta_F(f_i,f_j)=1', 'Es existiert mindestens ein funktional unterscheidbares Paar.', 'axiom', 'original', NULL, 'Äquivalente Kurzform von Gleichung (3.363).', 'Definition von delta_F aus 3.3.1.', 'checked', 28),
(258, '3.365', 30, 'Minimale Mächtigkeit des Trägerbereichs', '\\left|\\mathcal{F}\\right|\\geq 2', '\\left|\\mathcal{F}\\right|\\geq 2', 'Der Trägerbereich besitzt mindestens zwei unterscheidbare Repräsentanten.', 'derived', 'original', NULL, 'Folgerung aus Axiom A1 bei elementweiser Repräsentation funktionaler Unterschiede.', 'Unterschiedliche Wirksamkeiten werden durch unterschiedliche Repräsentanten abgebildet.', 'checked', 28),
(259, '3.366', 30, 'Selbst-Nichtunterscheidung', '\\delta_F(f_i,f_i)=0\\qquad\\forall f_i\\in\\mathcal{F}', '\\delta_F(f_i,f_i)=0\\qquad\\forall f_i\\in\\mathcal{F}', 'Ein funktionaler Gehalt wird in derselben Repräsentation nicht von sich selbst unterschieden.', 'definition', 'original', NULL, 'Konsistenzbedingung der qualitativen Unterscheidungsfunktion.', 'Dieselbe Repräsentation und derselbe Betrachtungsrahmen werden vorausgesetzt.', 'checked', 28),
(260, '3.367', 30, 'Nichtgeltung formaler Verschiedenheit als hinreichende Bedingung', 'f_i\\neq f_j\\;\\not\\Rightarrow\\;\\delta_F(f_i,f_j)=1', 'f_i\\neq f_j\\;\\not\\Rightarrow\\;\\delta_F(f_i,f_j)=1', 'Formal verschiedene Repräsentanten müssen nicht funktional unterscheidbar sein.', 'derived', 'original', NULL, 'Abgrenzung formaler Verschiedenheit von funktionaler Verschiedenheit.', 'Kontextabhängige Wirksamkeit wird zugelassen.', 'checked', 28),
(261, '3.368', 30, 'Funktionale Nichtunterscheidbarkeit', 'f_i\\sim_F f_j\\quad\\Longleftrightarrow\\quad\\delta_F(f_i,f_j)=0', 'f_i\\sim_F f_j\\quad\\Longleftrightarrow\\quad\\delta_F(f_i,f_j)=0', 'Zwei Gehalte sind funktional nicht unterscheidbar, wenn delta_F den Wert null annimmt.', 'definition', 'original', NULL, 'Einführung der vorläufigen Relation funktionaler Nichtunterscheidbarkeit.', 'Symmetrie und Transitivität werden noch nicht vorausgesetzt.', 'checked', 28),
(262, '3.369', 30, 'Kontextbezogene Unterscheidungsfunktion', '\\delta_F^{(c)}:\\mathcal{F}\\times\\mathcal{F}\\rightarrow\\{0,1\\}', '\\delta_F^{(c)}:\\mathcal{F}\\times\\mathcal{F}\\rightarrow\\{0,1\\}', 'Die qualitative Unterscheidungsfunktion wird auf einen bestimmten Kontext bezogen.', 'definition', 'original', NULL, 'Präzisierung der in 3.3.1 eingeführten Unterscheidungsfunktion.', 'Ein Kontext c aus dem Kontextbereich C ist gewählt.', 'checked', 28),
(263, '3.370', 30, 'Kontextbezogene Wirksamkeitsdifferenz', '\\delta_F^{(c)}(f_i,f_j)=1\\quad\\Longleftrightarrow\\quad\\omega_F(f_i,c)\\neq\\omega_F(f_j,c)', '\\delta_F^{(c)}(f_i,f_j)=1\\quad\\Longleftrightarrow\\quad\\omega_F(f_i,c)\\neq\\omega_F(f_j,c)', 'Kontextbezogene Unterscheidbarkeit liegt genau bei verschiedener Wirksamkeit vor.', 'definition', 'original', NULL, 'Verknüpfung von kontextbezogener Unterscheidung und Wirksamkeit.', 'delta_F^(c) und omega_F sind definiert.', 'checked', 28),
(264, '3.371', 30, 'Globale Unterscheidung aus Kontexten', '\\delta_F(f_i,f_j)=\\max_{c\\in\\mathcal{C}}\\delta_F^{(c)}(f_i,f_j)', '\\delta_F(f_i,f_j)=\\max_{c\\in\\mathcal{C}}\\delta_F^{(c)}(f_i,f_j)', 'Globale Unterscheidbarkeit liegt vor, sobald mindestens ein Kontext eine Differenz ausweist.', 'derived', 'original', NULL, 'Aggregation der binären kontextbezogenen Unterscheidungswerte.', 'Für den betrachteten Kontextbereich ist ein Maximum definiert; andernfalls ist später ein Supremum zu verwenden.', 'draft', 28),
(265, '3.372', 30, 'Voraussetzung vollständiger funktionaler Homogenität', '\\forall f_i,f_j\\in\\mathcal{F}\\;\\forall c\\in\\mathcal{C}:\\omega_F(f_i,c)=\\omega_F(f_j,c)', '\\forall f_i,f_j\\in\\mathcal{F}\\;\\forall c\\in\\mathcal{C}:\\omega_F(f_i,c)=\\omega_F(f_j,c)', 'Alle funktionalen Gehalte wirken in allen Kontexten gleich.', 'schema', 'original', NULL, 'Negativer Grenzfall für Proposition 3.3.1.', 'Trägerbereich, Kontextbereich und Wirksamkeitsabbildung sind definiert.', 'checked', 28),
(266, '3.373', 30, 'Folge vollständiger funktionaler Homogenität', '\\forall f_i,f_j\\in\\mathcal{F}:\\delta_F(f_i,f_j)=0', '\\forall f_i,f_j\\in\\mathcal{F}:\\delta_F(f_i,f_j)=0', 'Bei vollständiger Wirkungsgleichheit existiert keine intern bestimmbare Differenzstruktur.', 'derived', 'original', NULL, 'Folgt aus Gleichung (3.372) und der Definition von delta_F.', 'Gleichung (3.372) gilt.', 'checked', 28),
(267, '3.374', 31, 'Menge funktionaler Relationen', '\\mathcal{R}_F\\subseteq\\mathcal{F}\\times\\mathcal{F}', '\\mathcal{R}_F\\subseteq\\mathcal{F}\\times\\mathcal{F}', 'Die Menge funktionaler Relationen ist eine Teilmenge des kartesischen Produkts des funktionalen Trägerbereichs mit sich selbst.', 'definition', 'original', NULL, 'Formale Einführung der Relationsmenge auf Grundlage von Axiom A2.', 'Der funktionale Trägerbereich F ist in Abschnitt 3.3.1 eingeführt.', 'checked', 29),
(268, '3.375', 31, 'Bestehende funktionale Relation', '(f_i,f_j)\\in\\mathcal{R}_F', '(f_i,f_j)\\in\\mathcal{R}_F', 'Zwischen den funktionalen Gehalten f_i und f_j besteht eine funktionale Relation.', 'definition', 'original', NULL, 'Elementschreibweise der in Gleichung (3.374) eingeführten Relationsmenge.', 'Die Relationsmenge R_F ist definiert.', 'checked', 29),
(269, '3.376', 31, 'Unterscheidbarkeit relational gekoppelter Gehalte', '(f_i,f_j)\\in\\mathcal{R}_F\\Longrightarrow\\delta_F(f_i,f_j)=1', '(f_i,f_j)\\in\\mathcal{R}_F\\Longrightarrow\\delta_F(f_i,f_j)=1', 'Eine funktionale Relation setzt im Modell funktional unterscheidbare Gehalte voraus.', 'axiom', 'original', NULL, 'Formale Präzisierung der Bindung von Axiom A2 an Axiom A1.', 'Axiom A1 und die Unterscheidungsfunktion delta_F gelten.', 'checked', 29),
