(718, '3.683', 57, 'Erfüllung relationaler Bedingungen', '\\rho_F\\left(z_F^{(i)},z_F^{(j)}\\right)=1\\Longleftrightarrow\\left(z_F^{(i)},z_F^{(j)}\\right)\\models\\mathcal{C}_R', '\\rho_F\\left(z_F^{(i)},z_F^{(j)}\\right)=1\\Longleftrightarrow\\left(z_F^{(i)},z_F^{(j)}\\right)\\models\\mathcal{C}_R', 'Positive Prüffunktion genau bei Erfüllung der relationalen Zulässigkeitsbedingungen.', 'definition', 'original', NULL, 'Spezifikation über die Bedingungsmenge C_R.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(719, '3.684', 57, 'Reflexivitätsbedingung', '\\forall z_F\\in\\Omega_F(\\mathcal{S}):\\left(z_F,z_F\\right)\\in R_F', '\\forall z_F\\in\\Omega_F(\\mathcal{S}):\\left(z_F,z_F\\right)\\in R_F', 'Formale Bedingung der Reflexivität.', 'lemma', 'original', NULL, 'Im Allgemeinen nicht notwendig erfüllt.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(720, '3.685', 57, 'Symmetriebedingung', '\\left(z_F^{(i)},z_F^{(j)}\\right)\\in R_F\\Longrightarrow\\left(z_F^{(j)},z_F^{(i)}\\right)\\in R_F', '\\left(z_F^{(i)},z_F^{(j)}\\right)\\in R_F\\Longrightarrow\\left(z_F^{(j)},z_F^{(i)}\\right)\\in R_F', 'Formale Bedingung der Symmetrie.', 'lemma', 'original', NULL, 'Im Allgemeinen nicht notwendig erfüllt.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(721, '3.686', 57, 'Transitivitätsbedingung', '\\left(z_F^{(i)},z_F^{(j)}\\right)\\in R_F\\land\\left(z_F^{(j)},z_F^{(k)}\\right)\\in R_F\\Longrightarrow\\left(z_F^{(i)},z_F^{(k)}\\right)\\in R_F', '\\left(z_F^{(i)},z_F^{(j)}\\right)\\in R_F\\land\\left(z_F^{(j)},z_F^{(k)}\\right)\\in R_F\\Longrightarrow\\left(z_F^{(i)},z_F^{(k)}\\right)\\in R_F', 'Formale Bedingung der Transitivität.', 'lemma', 'original', NULL, 'Im Allgemeinen nicht notwendig erfüllt.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(722, '3.687', 57, 'Gegebene funktionale Relation', '\\rho_F\\left(z_F^{(i)},z_F^{(j)}\\right)=1', '\\rho_F\\left(z_F^{(i)},z_F^{(j)}\\right)=1', 'Ausgangsbedingung im Beweis von Lemma 3.4.3.', 'lemma', 'original', NULL, 'Positive relationale Prüfung.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(723, '3.688', 57, 'Nicht erzwungene Selbstrelation', '\\rho_F\\left(z_F^{(i)},z_F^{(i)}\\right)=1', '\\rho_F\\left(z_F^{(i)},z_F^{(i)}\\right)=1', 'Reflexivität folgt nicht aus einer einzelnen positiven Relation.', 'lemma', 'original', NULL, 'Gegenstand des Nichtnotwendigkeitsnachweises.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(724, '3.689', 57, 'Nicht erzwungene Umkehrrelation', '\\rho_F\\left(z_F^{(j)},z_F^{(i)}\\right)=1', '\\rho_F\\left(z_F^{(j)},z_F^{(i)}\\right)=1', 'Symmetrie folgt nicht aus einer einzelnen positiven Relation.', 'lemma', 'original', NULL, 'Gegenstand des Nichtnotwendigkeitsnachweises.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(725, '3.690', 57, 'Zwei aufeinanderfolgende Relationen', '\\rho_F\\left(z_F^{(i)},z_F^{(j)}\\right)=1\\quad\\text{und}\\quad\\rho_F\\left(z_F^{(j)},z_F^{(k)}\\right)=1', '\\rho_F\\left(z_F^{(i)},z_F^{(j)}\\right)=1\\quad\\text{und}\\quad\\rho_F\\left(z_F^{(j)},z_F^{(k)}\\right)=1', 'Voraussetzung einer möglichen Transitivität.', 'lemma', 'original', NULL, 'Zwei positive relationale Prüfungen.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(726, '3.691', 57, 'Nicht erzwungene transitive Relation', '\\rho_F\\left(z_F^{(i)},z_F^{(k)}\\right)=1', '\\rho_F\\left(z_F^{(i)},z_F^{(k)}\\right)=1', 'Transitivität folgt nicht ohne Zusatzbedingungen.', 'lemma', 'original', NULL, 'Gegenstand des Nichtnotwendigkeitsnachweises.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(727, '3.692', 57, 'Ausgehende Relationsmenge', 'R_F^{+}(z_F)=\\left\\{z_F^{\\prime}\\in\\Omega_F(\\mathcal{S})\\middle|\\left(z_F,z_F^{\\prime}\\right)\\in R_F\\right\\}', 'R_F^{+}(z_F)=\\left\\{z_F^{\\prime}\\in\\Omega_F(\\mathcal{S})\\middle|\\left(z_F,z_F^{\\prime}\\right)\\in R_F\\right\\}', 'Menge aller vom Zustand aus funktional erreichbaren Zustände.', 'definition', 'original', NULL, 'Eigene Definition der ausgehenden Relationsmenge.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(728, '3.693', 57, 'Eingehende Relationsmenge', 'R_F^{-}(z_F)=\\left\\{z_F^{\\prime}\\in\\Omega_F(\\mathcal{S})\\middle|\\left(z_F^{\\prime},z_F\\right)\\in R_F\\right\\}', 'R_F^{-}(z_F)=\\left\\{z_F^{\\prime}\\in\\Omega_F(\\mathcal{S})\\middle|\\left(z_F^{\\prime},z_F\\right)\\in R_F\\right\\}', 'Menge aller funktionalen Vorgängerzustände.', 'definition', 'original', NULL, 'Eigene Definition der eingehenden Relationsmenge.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(729, '3.694', 57, 'Relationale Einbindung', 'R_F^{+}(z_F)\\cup R_F^{-}(z_F)\\neq\\varnothing', 'R_F^{+}(z_F)\\cup R_F^{-}(z_F)\\neq\\varnothing', 'Ein Zustand ist relational eingebunden, wenn mindestens eine ein- oder ausgehende Relation existiert.', 'definition', 'original', NULL, 'Definition 3.4.7.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(730, '3.695', 57, 'Relationale Isolation', 'R_F^{+}(z_F)=R_F^{-}(z_F)=\\varnothing', 'R_F^{+}(z_F)=R_F^{-}(z_F)=\\varnothing', 'Ein Zustand besitzt weder ein- noch ausgehende funktionale Relationen.', 'definition', 'original', NULL, 'Kennzeichnung relationaler Isolation.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(731, '3.696', 57, 'Nichtleere funktionale Relation', 'R_F\\neq\\varnothing', 'R_F\\neq\\varnothing', 'Notwendige Bedingung einer nichttrivialen funktionalen Zustandsstruktur.', 'theorem', 'original', NULL, 'Kernaussage von Satz 3.4.3.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(732, '3.697', 57, 'Mindestens zwei Zustände', '\\left|\\Omega_F(\\mathcal{S})\\right|\\geq 2', '\\left|\\Omega_F(\\mathcal{S})\\right|\\geq 2', 'Voraussetzung des Satzes über nichttriviale Relationierung.', 'theorem', 'original', NULL, 'Mindestens zwei Elemente in der Zustandsmenge.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(733, '3.698', 57, 'Unrelationierte Zustandsstruktur', '\\mathfrak{Z}_F(\\mathcal{S})=\\left(\\Omega_F(\\mathcal{S}),\\varnothing\\right)', '\\mathfrak{Z}_F(\\mathcal{S})=\\left(\\Omega_F(\\mathcal{S}),\\varnothing\\right)', 'Struktur mit mehreren Zuständen, aber ohne funktionale Relation.', 'theorem', 'original', NULL, 'Fall R_F gleich leer.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(734, '3.699', 57, 'Existierendes Relationselement', '\\left(z_F^{(i)},z_F^{(j)}\\right)\\in R_F', '\\left(z_F^{(i)},z_F^{(j)}\\right)\\in R_F', 'Existenz mindestens eines funktional relationierten Zustandspaares.', 'theorem', 'original', NULL, 'Folgerung aus R_F ungleich leer.', 'Abschnitt 3.4.3 und vorausgehende Rekonstruktion.', 'checked', 54),
(735, '3.700', 58, 'Funktionale Zustandsmenge', '\\Omega_F(\\mathcal{S})', '\\Omega_F(\\mathcal{S})', 'Zustandsmenge der betrachteten funktionalen Organisation.', 'definition', 'original', NULL, 'Aus Abschnitt 3.4.1 übernommen.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(736, '3.701', 58, 'Allgemeine funktionale Zustandszuordnung', 'T_F:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'T_F:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'Abbildung der funktionalen Zustandsmenge in sich selbst.', 'definition', 'original', NULL, 'Vorbereitung der Transformationsdefinition.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(737, '3.702', 58, 'Funktionale Transformation', 'T_F:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'T_F:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'Formale Definition einer funktionalen Transformation.', 'definition', 'original', NULL, 'Definition 3.4.8.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(738, '3.703', 58, 'Bild eines funktionalen Zustands', 'z_F^{\\prime}=T_F(z_F)', 'z_F^{\\prime}=T_F(z_F)', 'Der Zielzustand ist das Bild des Ausgangszustands unter T_F.', 'definition', 'original', NULL, 'Definition 3.4.8.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(739, '3.704', 58, 'Funktionale Abgeschlossenheit', 'z_F\\in\\Omega_F(\\mathcal{S})\\Longrightarrow T_F(z_F)\\in\\Omega_F(\\mathcal{S})', 'z_F\\in\\Omega_F(\\mathcal{S})\\Longrightarrow T_F(z_F)\\in\\Omega_F(\\mathcal{S})', 'Interne Transformationen verlassen die zulässige Zustandsmenge nicht.', 'derived', 'original', NULL, 'Aus Definition 3.4.8.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(740, '3.705', 58, 'Transformiertes Zustandspaar', '\\left(z_F,T_F(z_F)\\right)', '\\left(z_F,T_F(z_F)\\right)', 'Geordnetes Paar aus Ausgangs- und Zielzustand.', 'definition', 'original', NULL, 'Verbindung zwischen Transformation und Relation.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(741, '3.706', 58, 'Transformationsrelation', 'R_{T_F}:=\\left\\{\\left(z_F,T_F(z_F)\\right)\\middle|z_F\\in\\Omega_F(\\mathcal{S})\\right\\}', 'R_{T_F}:=\\left\\{\\left(z_F,T_F(z_F)\\right)\\middle|z_F\\in\\Omega_F(\\mathcal{S})\\right\\}', 'Von einer funktionalen Transformation induzierte Relation.', 'definition', 'original', NULL, 'Definition 3.4.9.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(742, '3.707', 58, 'Transformationsrelation als Teilmenge', 'R_{T_F}\\subseteq\\Omega_F(\\mathcal{S})\\times\\Omega_F(\\mathcal{S})', 'R_{T_F}\\subseteq\\Omega_F(\\mathcal{S})\\times\\Omega_F(\\mathcal{S})', 'Die Transformationsrelation liegt im kartesischen Produkt der Zustandsmenge.', 'derived', 'original', NULL, 'Aus Definition 3.4.9.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55);
INSERT INTO `equations` (`equation_id`, `equation_number`, `section_id`, `title`, `equation_latex`, `word_latex`, `plain_description`, `equation_type`, `provenance`, `source_id`, `derivation`, `assumptions`, `validation_status`, `created_revision_id`) VALUES
(743, '3.708', 58, 'Eindeutigkeit der Transformation', 'T_F(z_F)=z_F^{\\prime}\\land T_F(z_F)=z_F^{\\prime\\prime}\\Longrightarrow z_F^{\\prime}=z_F^{\\prime\\prime}', 'T_F(z_F)=z_F^{\\prime}\\land T_F(z_F)=z_F^{\\prime\\prime}\\Longrightarrow z_F^{\\prime}=z_F^{\\prime\\prime}', 'Ein Ausgangszustand besitzt unter T_F genau ein Bild.', 'definition', 'original', NULL, 'Abbildungseigenschaft.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(744, '3.709', 58, 'Transformation im Lemma', 'T_F:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'T_F:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'Voraussetzung von Lemma 3.4.4.', 'lemma', 'original', NULL, 'Funktionale Transformation.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(745, '3.710', 58, 'Relationselement einer Transformation', '\\left(z_F,T_F(z_F)\\right)\\in\\Omega_F(\\mathcal{S})\\times\\Omega_F(\\mathcal{S})', '\\left(z_F,T_F(z_F)\\right)\\in\\Omega_F(\\mathcal{S})\\times\\Omega_F(\\mathcal{S})', 'Jede Transformation erzeugt ein geordnetes Zustandspaar im Zustandsprodukt.', 'lemma', 'original', NULL, 'Beweis zu Lemma 3.4.4.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(746, '3.711', 58, 'Menge möglicher Zielzustände', 'R_F^{+}(z_F)=\\left\\{z_F^{\\prime}\\in\\Omega_F(\\mathcal{S})\\middle|\\left(z_F,z_F^{\\prime}\\right)\\in R_F\\right\\}', 'R_F^{+}(z_F)=\\left\\{z_F^{\\prime}\\in\\Omega_F(\\mathcal{S})\\middle|\\left(z_F,z_F^{\\prime}\\right)\\in R_F\\right\\}', 'Menge der von einem Zustand aus relational möglichen Zielzustände.', 'definition', 'original', NULL, 'Aus Abschnitt 3.4.3 weitergeführt.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(747, '3.712', 58, 'Transformierbarkeit einer Relation', 'T_F:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'T_F:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'Durch eine eindeutige Relation bestimmte Transformation.', 'theorem', 'original', NULL, 'Satz 3.4.4.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(748, '3.713', 58, 'Relationiertes Ausgangs-Ziel-Paar', '\\left(z_F,z_F^{\\prime}\\right)\\in R_F', '\\left(z_F,z_F^{\\prime}\\right)\\in R_F', 'Ein Zielzustand steht mit dem Ausgangszustand in funktionaler Relation.', 'theorem', 'original', NULL, 'Kriterium von Satz 3.4.4.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(749, '3.714', 58, 'Eindeutigkeitskriterium', '\\forall z_F\\in\\Omega_F(\\mathcal{S}):\\left|R_F^{+}(z_F)\\right|=1', '\\forall z_F\\in\\Omega_F(\\mathcal{S}):\\left|R_F^{+}(z_F)\\right|=1', 'Jeder Ausgangszustand besitzt genau einen relationalen Zielzustand.', 'theorem', 'original', NULL, 'Äquivalentes Kriterium von Satz 3.4.4.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(750, '3.715', 58, 'Einelementige Zielmenge', '\\left|R_F^{+}(z_F)\\right|=1', '\\left|R_F^{+}(z_F)\\right|=1', 'Die ausgehende Relationsmenge enthält genau ein Element.', 'theorem', 'original', NULL, 'Erste Beweisrichtung von Satz 3.4.4.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(751, '3.716', 58, 'Existierendes Relationspaar', '\\left(z_F,z_F^{\\prime}\\right)\\in R_F', '\\left(z_F,z_F^{\\prime}\\right)\\in R_F', 'Voraussetzung der umgekehrten Beweisrichtung.', 'theorem', 'original', NULL, 'Zweite Beweisrichtung von Satz 3.4.4.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(752, '3.717', 58, 'Aus Relation definierte Transformation', 'T_F(z_F):=z_F^{\\prime}', 'T_F(z_F):=z_F^{\\prime}', 'Eindeutige Definition der Transformation aus der Relation.', 'theorem', 'original', NULL, 'Konstruktion im Beweis von Satz 3.4.4.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(753, '3.718', 58, 'Invarianzbedingung', 'T_F(z_F)=z_F', 'T_F(z_F)=z_F', 'Ein Zustand bleibt unter der Transformation unverändert.', 'definition', 'original', NULL, 'Vorbereitung der Fixpunktdefinition.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(754, '3.719', 58, 'Funktionaler Fixpunkt als Zustand', 'z_F^{*}\\in\\Omega_F(\\mathcal{S})', 'z_F^{*}\\in\\Omega_F(\\mathcal{S})', 'Ein Fixpunkt gehört zur funktionalen Zustandsmenge.', 'definition', 'original', NULL, 'Definition 3.4.10.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(755, '3.720', 58, 'Fixpunktgleichung', 'T_F\\left(z_F^{*}\\right)=z_F^{*}', 'T_F\\left(z_F^{*}\\right)=z_F^{*}', 'Ein Fixpunkt wird durch die Transformation auf sich selbst abgebildet.', 'definition', 'original', NULL, 'Definition 3.4.10.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(756, '3.721', 58, 'Fixpunktmenge', '\\operatorname{Fix}(T_F):=\\left\\{z_F\\in\\Omega_F(\\mathcal{S})\\middle|T_F(z_F)=z_F\\right\\}', '\\operatorname{Fix}(T_F):=\\left\\{z_F\\in\\Omega_F(\\mathcal{S})\\middle|T_F(z_F)=z_F\\right\\}', 'Menge aller funktionalen Fixpunkte der Transformation.', 'definition', 'original', NULL, 'Definition 3.4.10.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(757, '3.722', 58, 'Zwei funktionale Transformationen', 'T_F^{(1)},T_F^{(2)}:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'T_F^{(1)},T_F^{(2)}:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'Zwei Transformationen derselben funktionalen Zustandsmenge.', 'definition', 'original', NULL, 'Vorbereitung der Komposition.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(758, '3.723', 58, 'Komposition funktionaler Transformationen', '\\left(T_F^{(2)}\\circ T_F^{(1)}\\right)(z_F)=T_F^{(2)}\\left(T_F^{(1)}(z_F)\\right)', '\\left(T_F^{(2)}\\circ T_F^{(1)}\\right)(z_F)=T_F^{(2)}\\left(T_F^{(1)}(z_F)\\right)', 'Nacheinanderausführung zweier funktionaler Transformationen.', 'definition', 'original', NULL, 'Kompositionsdefinition.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(759, '3.724', 58, 'Abgeschlossenheit der Komposition', 'T_F^{(2)}\\circ T_F^{(1)}:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'T_F^{(2)}\\circ T_F^{(1)}:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'Die Komposition bildet die Zustandsmenge erneut in sich selbst ab.', 'derived', 'original', NULL, 'Korollar 3.4.4.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(760, '3.725', 58, 'Bild unter erster Transformation', 'T_F^{(1)}(z_F)\\in\\Omega_F(\\mathcal{S})', 'T_F^{(1)}(z_F)\\in\\Omega_F(\\mathcal{S})', 'Das Ergebnis der ersten Transformation liegt in der Zustandsmenge.', '', 'original', NULL, 'Begründung zu Korollar 3.4.4.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(761, '3.726', 58, 'Bild unter der Komposition', 'T_F^{(2)}\\left(T_F^{(1)}(z_F)\\right)\\in\\Omega_F(\\mathcal{S})', 'T_F^{(2)}\\left(T_F^{(1)}(z_F)\\right)\\in\\Omega_F(\\mathcal{S})', 'Auch das Ergebnis der zweiten Transformation liegt in der Zustandsmenge.', '', 'original', NULL, 'Begründung zu Korollar 3.4.4.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(762, '3.727', 58, 'Identitätstransformation', '\\operatorname{id}_{\\Omega_F}:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', '\\operatorname{id}_{\\Omega_F}:\\Omega_F(\\mathcal{S})\\longrightarrow\\Omega_F(\\mathcal{S})', 'Neutrale Transformation der funktionalen Zustandsmenge.', 'definition', 'original', NULL, 'Einführung der Identitätsabbildung.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(763, '3.728', 58, 'Wirkung der Identität', '\\operatorname{id}_{\\Omega_F}(z_F)=z_F', '\\operatorname{id}_{\\Omega_F}(z_F)=z_F', 'Die Identität lässt jeden Zustand unverändert.', 'definition', 'original', NULL, 'Definition der Identitätsabbildung.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(764, '3.729', 58, 'Neutralität der Identität', 'T_F\\circ\\operatorname{id}_{\\Omega_F}=\\operatorname{id}_{\\Omega_F}\\circ T_F=T_F', 'T_F\\circ\\operatorname{id}_{\\Omega_F}=\\operatorname{id}_{\\Omega_F}\\circ T_F=T_F', 'Die Identität ist neutrales Element der Transformationskomposition.', 'derived', 'original', NULL, 'Aus der Identitätsdefinition.', 'Abschnitt 3.4.4 und vorausgehende Rekonstruktion.', 'checked', 55),
(765, '3.730', 59, 'Allgemeiner Operator', 'O:X\\rightarrow Y', 'O:X\\rightarrow Y', 'Allgemeine Darstellung eines Operators als wohldefinierte Abbildung vom Definitionsbereich X in den Zielbereich Y.', 'definition', 'literature', 11, 'Übernahme des allgemeinen Abbildungs- und Operatorbegriffs als mathematische Grundlage der FRZK-spezifischen Rekonstruktion.', 'X und Y sind wohldefinierte mathematische Bereiche.', 'checked', 60),
