(866, '3.831', 61, 'Bedingung der Kohärenzerhaltung', '\\forall r_F\\in\\mathcal R_F^{K}(\\mathcal S):\\quad r_F\\subseteq z_F\\Longrightarrow\\exists r_F^{\\prime}\\subseteq O_F(z_F):\\;r_F^{\\prime}\\sim_F r_F', '\\forall r_F\\in\\mathcal R_F^{K}(\\mathcal S):\\quad r_F\\subseteq z_F\\Longrightarrow\\exists r_F^{\\prime}\\subseteq O_F(z_F):\\;r_F^{\\prime}\\sim_F r_F', 'Jede realisierte kohärenztragende Relation wird funktional äquivalent fortgeführt.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.7.', 'Die Definitionen und Sätze der Abschnitte 3.4.4 bis 3.4.6 werden vorausgesetzt.', 'checked', 63),
(867, '3.832', 61, 'Menge kohärenzerhaltender Operatoren', '\\mathcal O_F^{K}(\\mathcal S)=\\left\\{O_F\\in\\mathcal O_F(\\mathcal S)\\middle|O_F\\text{ erhält }\\mathcal R_F^{K}(\\mathcal S)\\right\\}', '\\mathcal O_F^{K}(\\mathcal S)=\\left\\{O_F\\in\\mathcal O_F(\\mathcal S)\\middle|O_F\\text{ erhält }\\mathcal R_F^{K}(\\mathcal S)\\right\\}', 'Menge aller Operatoren, welche die kohärenztragende Relationsstruktur erhalten.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.7.', 'Die Definitionen und Sätze der Abschnitte 3.4.4 bis 3.4.6 werden vorausgesetzt.', 'checked', 63),
(868, '3.833', 61, 'Teilmengenbeziehung kohärenzerhaltender Operatoren', '\\mathcal O_F^{K}(\\mathcal S)\\subseteq\\mathcal O_F(\\mathcal S)', '\\mathcal O_F^{K}(\\mathcal S)\\subseteq\\mathcal O_F(\\mathcal S)', 'Jeder kohärenzerhaltende Operator ist ein funktionaler Operator.', 'derived', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.7.', 'Die Definitionen und Sätze der Abschnitte 3.4.4 bis 3.4.6 werden vorausgesetzt.', 'checked', 63),
(869, '3.834', 61, 'Funktionaler Zustand', 'z_F\\in\\Omega_F(\\mathcal S)', 'z_F\\in\\Omega_F(\\mathcal S)', 'Ein kohärenter Zustand gehört zum funktionalen Zustandsraum.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.7.', 'Die Definitionen und Sätze der Abschnitte 3.4.4 bis 3.4.6 werden vorausgesetzt.', 'checked', 63),
(870, '3.835', 61, 'Bedingung funktionaler Zustandskohärenz', '\\forall r_F\\in\\mathcal R_F^{K}(\\mathcal S):\\quad r_F\\subseteq z_F', '\\forall r_F\\in\\mathcal R_F^{K}(\\mathcal S):\\quad r_F\\subseteq z_F', 'Alle kohärenztragenden Relationen sind im Zustand realisiert.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.7.', 'Die Definitionen und Sätze der Abschnitte 3.4.4 bis 3.4.6 werden vorausgesetzt.', 'checked', 63),
(871, '3.836', 61, 'Menge funktional kohärenter Zustände', '\\Omega_F^{K}(\\mathcal S)=\\left\\{z_F\\in\\Omega_F(\\mathcal S)\\middle|\\forall r_F\\in\\mathcal R_F^{K}(\\mathcal S):r_F\\subseteq z_F\\right\\}', '\\Omega_F^{K}(\\mathcal S)=\\left\\{z_F\\in\\Omega_F(\\mathcal S)\\middle|\\forall r_F\\in\\mathcal R_F^{K}(\\mathcal S):r_F\\subseteq z_F\\right\\}', 'Der kohärente Bereich des funktionalen Zustandsraumes.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.7.', 'Die Definitionen und Sätze der Abschnitte 3.4.4 bis 3.4.6 werden vorausgesetzt.', 'checked', 63),
