(954, '3.919', 62, 'Unmittelbarer Übergang zur Richtungsdefinition', 'z_F\\xrightarrow{\\,O_F\\,}z_F^{\\prime}', 'z_F\\xrightarrow{\\,O_F\\,}z_F^{\\prime}', 'Ausgangssituation für die funktionale Übergangsrichtung.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.8.', 'Die Definitionen und Sätze der Abschnitte 3.4.6 und 3.4.7 werden vorausgesetzt.', 'checked', 64),
(955, '3.920', 62, 'Funktionale Übergangsrichtung', '\\vec{\\rho}_F\\left(z_F,O_F\\right)=\\Delta_F\\left(z_F,O_F(z_F)\\right)', '\\vec{\\rho}_F\\left(z_F,O_F\\right)=\\Delta_F\\left(z_F,O_F(z_F)\\right)', 'Funktionale Differenz zwischen Ausgangs- und Folgezustand.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.8.', 'Die Definitionen und Sätze der Abschnitte 3.4.6 und 3.4.7 werden vorausgesetzt.', 'checked', 64),
(956, '3.921', 62, 'Richtung der Identitätswirkung', '\\vec{\\rho}_F\\left(z_F,I_F\\right)=\\Delta_F(z_F,z_F)', '\\vec{\\rho}_F\\left(z_F,I_F\\right)=\\Delta_F(z_F,z_F)', 'Übergangsrichtung des Identitätsoperators.', 'derived', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.8.', 'Die Definitionen und Sätze der Abschnitte 3.4.6 und 3.4.7 werden vorausgesetzt.', 'checked', 64),
(957, '3.922', 62, 'Nullrichtung der Identitätswirkung', '\\vec{\\rho}_F\\left(z_F,I_F\\right)=\\vec{0}_F', '\\vec{\\rho}_F\\left(z_F,I_F\\right)=\\vec{0}_F', 'Bei vorhandener Nullstruktur besitzt die Identitätswirkung die Nullrichtung.', 'derived', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.8.', 'Die Definitionen und Sätze der Abschnitte 3.4.6 und 3.4.7 werden vorausgesetzt.', 'checked', 64),
(958, '3.923', 62, 'Richtungserhaltende Nullskalierung', '0\\cdot\\vec{\\rho}_F', '0\\cdot\\vec{\\rho}_F', 'Skalierung einer gespeicherten Richtung mit null ohne explizite Löschung.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.8.', 'Die Definitionen und Sätze der Abschnitte 3.4.6 und 3.4.7 werden vorausgesetzt.', 'checked', 64),
(959, '3.924', 62, 'Explizite Nullung des Richtungsobjekts', '\\operatorname{Null}_F\\left(\\vec{\\rho}_F\\right)=\\vec{0}_F', '\\operatorname{Null}_F\\left(\\vec{\\rho}_F\\right)=\\vec{0}_F', 'Explizite Löschung der funktionalen Richtungsinformation.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.8.', 'Die Definitionen und Sätze der Abschnitte 3.4.6 und 3.4.7 werden vorausgesetzt.', 'checked', 64),
(960, '3.925', 63, 'Kohärente Zustände der Zeitrekonstruktion', 'z_F^{(i)},z_F^{(j)}\\in\\Omega_F^{K}(\\mathcal S)', 'z_F^{(i)},z_F^{(j)}\\in\\Omega_F^{K}(\\mathcal S)', 'Ausgangs- und Folgezustand gehören zum kohärenten Zustandsraum.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(961, '3.926', 63, 'Operatorische Erzeugung des Nachfolgezustands', 'z_F^{(j)}=O_F\\left(z_F^{(i)}\\right)', 'z_F^{(j)}=O_F\\left(z_F^{(i)}\\right)', 'Der Nachfolgezustand entsteht durch einen kohärenzerhaltenden Operator.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(962, '3.927', 63, 'Nichtidentität des Nachfolgezustands', 'z_F^{(j)}\\neq z_F^{(i)}', 'z_F^{(j)}\\neq z_F^{(i)}', 'Die unmittelbare Nachfolge setzt eine tatsächliche Zustandsänderung voraus.', 'other', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(963, '3.928', 63, 'Notation unmittelbarer funktionaler Nachfolge', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'Notation für unmittelbare funktionale Nachfolge.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(964, '3.929', 63, 'Vorgängerbeziehung', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'Der erste Zustand ist unmittelbarer funktionaler Vorgänger des zweiten.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(965, '3.930', 63, 'Menge funktionaler Vorgänger', '\\operatorname{Pred}_F\\left(z_F^{(j)}\\right)=\\left\\{z_F^{(i)}\\in\\Omega_F^{K}(\\mathcal S)\\middle|z_F^{(i)}\\prec_F z_F^{(j)}\\right\\}', '\\operatorname{Pred}_F\\left(z_F^{(j)}\\right)=\\left\\{z_F^{(i)}\\in\\Omega_F^{K}(\\mathcal S)\\middle|z_F^{(i)}\\prec_F z_F^{(j)}\\right\\}', 'Menge aller unmittelbaren funktionalen Vorgänger.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(966, '3.931', 63, 'Menge funktionaler Nachfolger', '\\operatorname{Succ}_F\\left(z_F^{(i)}\\right)=\\left\\{z_F^{(j)}\\in\\Omega_F^{K}(\\mathcal S)\\middle|z_F^{(i)}\\prec_F z_F^{(j)}\\right\\}', '\\operatorname{Succ}_F\\left(z_F^{(i)}\\right)=\\left\\{z_F^{(j)}\\in\\Omega_F^{K}(\\mathcal S)\\middle|z_F^{(i)}\\prec_F z_F^{(j)}\\right\\}', 'Menge aller unmittelbaren funktionalen Nachfolger.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(967, '3.932', 63, 'Gerichtete Nachfolge', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'z_F^{(i)}\\prec_F z_F^{(j)}', 'Gerichtete unmittelbare Nachfolge vom Vorgänger zum Nachfolger.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(968, '3.933', 63, 'Fehlende automatische Umkehrung', 'z_F^{(j)}\\prec_F z_F^{(i)}', 'z_F^{(j)}\\prec_F z_F^{(i)}', 'Die umgekehrte Nachfolge folgt nicht automatisch.', 'other', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(969, '3.934', 63, 'Funktionale Vorordnung', 'z_F^{(i)}\\prec_F^{*} z_F^{(j)}', 'z_F^{(i)}\\prec_F^{*} z_F^{(j)}', 'Notation für mittelbare funktionale Vorordnung.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(970, '3.935', 63, 'Transitive Hülle der Nachfolge', '\\prec_F^{*}=\\left(\\prec_F\\right)^{+}', '\\prec_F^{*}=\\left(\\prec_F\\right)^{+}', 'Die funktionale Vorordnung ist die transitive nichtreflexive Hülle.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(971, '3.936', 63, 'Funktionales Früher', 'z_F^{(i)}\\prec_F^{*} z_F^{(j)}', 'z_F^{(i)}\\prec_F^{*} z_F^{(j)}', 'Der erste Zustand ist funktional früher als der zweite.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(972, '3.937', 63, 'Reflexive funktionale Vorordnung', 'z_F^{(i)}\\preceq_F z_F^{(j)}\\Longleftrightarrow z_F^{(i)}=z_F^{(j)}\\lor z_F^{(i)}\\prec_F^{*} z_F^{(j)}', 'z_F^{(i)}\\preceq_F z_F^{(j)}\\Longleftrightarrow z_F^{(i)}=z_F^{(j)}\\lor z_F^{(i)}\\prec_F^{*} z_F^{(j)}', 'Reflexive Erweiterung der funktionalen Vorordnung.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(973, '3.938', 63, 'Erste Voraussetzung der Transitivität', 'z_F^{(i)}\\prec_F^{*} z_F^{(j)}', 'z_F^{(i)}\\prec_F^{*} z_F^{(j)}', 'Erster Teilpfad der Transitivitätsaussage.', 'other', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(974, '3.939', 63, 'Zweite Voraussetzung der Transitivität', 'z_F^{(j)}\\prec_F^{*} z_F^{(k)}', 'z_F^{(j)}\\prec_F^{*} z_F^{(k)}', 'Zweiter Teilpfad der Transitivitätsaussage.', 'other', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(975, '3.940', 63, 'Transitive Schlussfolgerung', 'z_F^{(i)}\\prec_F^{*} z_F^{(k)}', 'z_F^{(i)}\\prec_F^{*} z_F^{(k)}', 'Verkettung der Teilpfade erzeugt eine funktionale Vorordnung.', 'lemma', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(976, '3.941', 63, 'Funktionaler Zyklus als Zustandsfolge', '\\mathcal C_F=\\left(z_F^{(0)},z_F^{(1)},\\ldots,z_F^{(n)}\\right)', '\\mathcal C_F=\\left(z_F^{(0)},z_F^{(1)},\\ldots,z_F^{(n)}\\right)', 'Endliche Zustandsfolge eines funktionalen Zyklus.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(977, '3.942', 63, 'Rückkehr zum Ausgangszustand', 'z_F^{(0)}=z_F^{(n)}', 'z_F^{(0)}=z_F^{(n)}', 'Ein funktionaler Zyklus endet im Ausgangszustand.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(978, '3.943', 63, 'Nachfolge innerhalb eines Zyklus', 'z_F^{(k)}\\prec_F z_F^{(k+1)}', 'z_F^{(k)}\\prec_F z_F^{(k+1)}', 'Jeder Zyklusschritt ist eine unmittelbare nichtidentische Nachfolge.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65);
INSERT INTO `equations` (`equation_id`, `equation_number`, `section_id`, `title`, `equation_latex`, `word_latex`, `plain_description`, `equation_type`, `provenance`, `source_id`, `derivation`, `assumptions`, `validation_status`, `created_revision_id`) VALUES
(979, '3.944', 63, 'Azyklischer funktionaler Bereich', '\\Omega_F^{A}(\\mathcal S)\\subseteq\\Omega_F^{K}(\\mathcal S)', '\\Omega_F^{A}(\\mathcal S)\\subseteq\\Omega_F^{K}(\\mathcal S)', 'Ein azyklischer Bereich ist Teilmenge des kohärenten Zustandsraums.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(980, '3.945', 63, 'Ausschluss funktionaler Selbstvorordnung', 'z_F\\prec_F^{*} z_F', 'z_F\\prec_F^{*} z_F', 'Die Azyklizitätsbedingung schließt nichtleere Rückkehrpfade aus.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(981, '3.946', 63, 'Erste Ordnungsannahme', 'z_F^{(i)}\\preceq_F z_F^{(j)}', 'z_F^{(i)}\\preceq_F z_F^{(j)}', 'Erste Annahme zur Antisymmetrie.', 'other', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(982, '3.947', 63, 'Zweite Ordnungsannahme', 'z_F^{(j)}\\preceq_F z_F^{(i)}', 'z_F^{(j)}\\preceq_F z_F^{(i)}', 'Zweite Annahme zur Antisymmetrie.', 'other', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(983, '3.948', 63, 'Antisymmetrische Identität', 'z_F^{(i)}=z_F^{(j)}', 'z_F^{(i)}=z_F^{(j)}', 'In azyklischen Bereichen erzwingt wechselseitige Vorordnung Zustandsidentität.', 'theorem', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(984, '3.949', 63, 'Funktionale Zustandsinstanz', '\\zeta_F^{(k)}=\\left(z_F^{(k)},k\\right)', '\\zeta_F^{(k)}=\\left(z_F^{(k)},k\\right)', 'Ein Zustand wird mit seiner Pfadposition zu einer Zustandsinstanz verbunden.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(985, '3.950', 63, 'Wiederholung desselben Zustands', 'z_F^{(i)}=z_F^{(j)}', 'z_F^{(i)}=z_F^{(j)}', 'Ein funktionaler Zustand kann innerhalb eines Pfades wiederholt auftreten.', 'other', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(986, '3.951', 63, 'Unterschiedliche Instanzen desselben Zustands', '\\zeta_F^{(i)}\\neq\\zeta_F^{(j)},\\qquad i\\neq j', '\\zeta_F^{(i)}\\neq\\zeta_F^{(j)},\\qquad i\\neq j', 'Gleiche Zustände an verschiedenen Pfadpositionen sind verschiedene Instanzen.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(987, '3.952', 63, 'Strikte instanzielle Vorordnung', '\\zeta_F^{(i)}\\triangleleft_F\\zeta_F^{(j)}\\Longleftrightarrow i<j', '\\zeta_F^{(i)}\\triangleleft_F\\zeta_F^{(j)}\\Longleftrightarrow i<j', 'Strikte Ordnung von Zustandsinstanzen anhand ihrer Position.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(988, '3.953', 63, 'Reflexive instanzielle Vorordnung', '\\zeta_F^{(i)}\\unlhd_F\\zeta_F^{(j)}\\Longleftrightarrow i\\leq j', '\\zeta_F^{(i)}\\unlhd_F\\zeta_F^{(j)}\\Longleftrightarrow i\\leq j', 'Reflexive Ordnung von Zustandsinstanzen.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(989, '3.954', 63, 'Funktionaler Entwicklungspfad', '\\mathcal P_F^{(n)}=\\left(z_F^{(0)},O_{F,1},z_F^{(1)},\\ldots,O_{F,n},z_F^{(n)}\\right)', '\\mathcal P_F^{(n)}=\\left(z_F^{(0)},O_{F,1},z_F^{(1)},\\ldots,O_{F,n},z_F^{(n)}\\right)', 'Entwicklungspfad als Grundlage der funktionalen Zeitstruktur.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(990, '3.955', 63, 'Menge der Zustandsinstanzen', '\\mathcal Z_F\\left(\\mathcal P_F^{(n)}\\right)=\\left\\{\\zeta_F^{(0)},\\zeta_F^{(1)},\\ldots,\\zeta_F^{(n)}\\right\\}', '\\mathcal Z_F\\left(\\mathcal P_F^{(n)}\\right)=\\left\\{\\zeta_F^{(0)},\\zeta_F^{(1)},\\ldots,\\zeta_F^{(n)}\\right\\}', 'Menge aller Zustandsinstanzen eines Entwicklungspfades.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(991, '3.956', 63, 'Funktionale Zeitstruktur', '\\mathfrak T_F\\left(\\mathcal P_F^{(n)}\\right)=\\left(\\mathcal Z_F\\left(\\mathcal P_F^{(n)}\\right),\\unlhd_F\\right)', '\\mathfrak T_F\\left(\\mathcal P_F^{(n)}\\right)=\\left(\\mathcal Z_F\\left(\\mathcal P_F^{(n)}\\right),\\unlhd_F\\right)', 'Zeitstruktur als geordnete Menge der Zustandsinstanzen.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(992, '3.957', 63, 'Nichtidentischer funktionaler Übergang', 'z_F^{(0)}\\prec_F z_F^{(1)}', 'z_F^{(0)}\\prec_F z_F^{(1)}', 'Mindestens ein nichtidentischer Übergang begründet eine nichttriviale Zeitstruktur.', 'other', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(993, '3.958', 63, 'Erste Zustandsinstanz', '\\zeta_F^{(0)}=\\left(z_F^{(0)},0\\right)', '\\zeta_F^{(0)}=\\left(z_F^{(0)},0\\right)', 'Ausgangsinstanz des Übergangs.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
(994, '3.959', 63, 'Zweite Zustandsinstanz', '\\zeta_F^{(1)}=\\left(z_F^{(1)},1\\right)', '\\zeta_F^{(1)}=\\left(z_F^{(1)},1\\right)', 'Nachfolgeinstanz des Übergangs.', 'definition', 'original', NULL, 'Literaturgestützte Rekonstruktion in Abschnitt 3.4.9.', 'Die funktionalen Zustands-, Kohärenz-, Raum- und Operatorstrukturen der Abschnitte 3.4.6 bis 3.4.8 werden vorausgesetzt.', 'checked', 65),
