(1436, '3.1452', 120, 'Streuung einer Laufgruppe', '\\sigma_{\\Theta_j}=\\sqrt{\\frac{1}{n_{\\xi}-1}\\sum_{r=1}^{n_{\\xi}}\\left(Q_{j,r}-\\overline{Q}_{\\Theta_j}\\right)^2}', '\\sigma_{\\Theta_j}=\\sqrt{\\frac{1}{n_{\\xi}-1}\\sum_{r=1}^{n_{\\xi}}\\left(Q_{j,r}-\\overline{Q}_{\\Theta_j}\\right)^2}', 'Streuung der Ergebnisse innerhalb einer Wiederholungsgruppe.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1437, '3.1453', 120, 'Laufstatusmenge', 'z_{\\mathrm{run}}\\in\\left\\{z_{\\mathrm{planned}},z_{\\mathrm{running}},z_{\\mathrm{completed}},z_{\\mathrm{failed}},z_{\\mathrm{invalid}}\\right\\}', 'z_{\\mathrm{run}}\\in\\left\\{z_{\\mathrm{planned}},z_{\\mathrm{running}},z_{\\mathrm{completed}},z_{\\mathrm{failed}},z_{\\mathrm{invalid}}\\right\\}', 'Zulässige technische Laufstatus.', 'definition', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1438, '3.1454', 120, 'Auswertbarkeitsbedingung', 'z_{\\mathrm{run}}=z_{\\mathrm{completed}}\\land z_{\\mathrm{valid}}=1', 'z_{\\mathrm{run}}=z_{\\mathrm{completed}}\\land z_{\\mathrm{valid}}=1', 'Bedingung für die Aufnahme eines Laufs in die Auswertung.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1439, '3.1455', 120, 'Auswertbare Laufmenge', '\\mathcal{S}_{\\mathrm{eval}}=\\left\\{\\mathcal{R}_i\\in\\mathcal{S}_{\\mathrm{sim}}\\mid z_{\\mathrm{run},i}=z_{\\mathrm{completed}}\\land z_{\\mathrm{valid},i}=1\\right\\}', '\\mathcal{S}_{\\mathrm{eval}}=\\left\\{\\mathcal{R}_i\\in\\mathcal{S}_{\\mathrm{sim}}\\mid z_{\\mathrm{run},i}=z_{\\mathrm{completed}}\\land z_{\\mathrm{valid},i}=1\\right\\}', 'Menge abgeschlossener und valider Läufe.', 'definition', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1440, '3.1456', 120, 'Vollständigkeitsindex', 'I_{\\mathrm{complete}}=\\frac{N_{\\mathrm{completed}}}{N_{\\mathrm{planned}}}', 'I_{\\mathrm{complete}}=\\frac{N_{\\mathrm{completed}}}{N_{\\mathrm{planned}}}', 'Anteil abgeschlossener an geplanten Läufen.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1441, '3.1457', 120, 'Wertebereich des Vollständigkeitsindex', '0\\le I_{\\mathrm{complete}}\\le1', '0\\le I_{\\mathrm{complete}}\\le1', 'Zulässiger Wertebereich des Vollständigkeitsindex.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1442, '3.1458', 120, 'Vollständige Studie', 'I_{\\mathrm{complete}}=1', 'I_{\\mathrm{complete}}=1', 'Bedingung einer vollständig durchgeführten Studie.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1443, '3.1459', 120, 'Validitätsindex', 'I_{\\mathrm{valid}}=\\frac{N_{\\mathrm{valid}}}{N_{\\mathrm{completed}}}', 'I_{\\mathrm{valid}}=\\frac{N_{\\mathrm{valid}}}{N_{\\mathrm{completed}}}', 'Anteil valider an abgeschlossenen Läufen.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1444, '3.1460', 120, 'Studienstatusvektor', 'Z_{\\mathrm{study}}=\\left(I_{\\mathrm{complete}},I_{\\mathrm{valid}},I_{\\mathrm{reprod}},I_{\\mathrm{coverage}},I_{\\mathrm{interpret}}\\right)', 'Z_{\\mathrm{study}}=\\left(I_{\\mathrm{complete}},I_{\\mathrm{valid}},I_{\\mathrm{reprod}},I_{\\mathrm{coverage}},I_{\\mathrm{interpret}}\\right)', 'Zusammengefasster Status einer Simulationsstudie.', 'definition', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1445, '3.1461', 120, 'Kontinuierlicher Abdeckungsindex', 'I_{\\mathrm{coverage}}=\\frac{V_{\\mathrm{covered}}}{V_{\\mathcal{P}_{\\mathrm{study}}}}', 'I_{\\mathrm{coverage}}=\\frac{V_{\\mathrm{covered}}}{V_{\\mathcal{P}_{\\mathrm{study}}}}', 'Abdeckung eines kontinuierlichen Parameterraums.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1446, '3.1462', 120, 'Diskreter Abdeckungsindex', 'I_{\\mathrm{coverage}}=\\frac{N_{\\mathrm{tested}}}{N_{\\mathrm{possible}}}', 'I_{\\mathrm{coverage}}=\\frac{N_{\\mathrm{tested}}}{N_{\\mathrm{possible}}}', 'Abdeckung eines diskreten Parameterraums.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1447, '3.1463', 120, 'Mittlerer Trajektorienmerkmalsvektor', '\\overline{F}_{\\Gamma}=\\frac{1}{N_{\\mathrm{eval}}}\\sum_{i=1}^{N_{\\mathrm{eval}}}F_{\\Gamma_i}', '\\overline{F}_{\\Gamma}=\\frac{1}{N_{\\mathrm{eval}}}\\sum_{i=1}^{N_{\\mathrm{eval}}}F_{\\Gamma_i}', 'Mittelwert der Trajektorienmerkmalsvektoren.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1448, '3.1464', 120, 'Kovarianzmatrix der Trajektorienmerkmale', '\\Sigma_F=\\frac{1}{N_{\\mathrm{eval}}-1}\\sum_{i=1}^{N_{\\mathrm{eval}}}\\left(F_{\\Gamma_i}-\\overline{F}_{\\Gamma}\\right)\\left(F_{\\Gamma_i}-\\overline{F}_{\\Gamma}\\right)^{\\mathsf{T}}', '\\Sigma_F=\\frac{1}{N_{\\mathrm{eval}}-1}\\sum_{i=1}^{N_{\\mathrm{eval}}}\\left(F_{\\Gamma_i}-\\overline{F}_{\\Gamma}\\right)\\left(F_{\\Gamma_i}-\\overline{F}_{\\Gamma}\\right)^{\\mathsf{T}}', 'Empirische Kovarianzmatrix der Trajektorienmerkmale.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1449, '3.1465', 120, 'Absolute Klassenhäufigkeit', 'N_{K_j}=\\sum_{i=1}^{N_{\\mathrm{eval}}}\\mathbf{1}\\left[\\kappa(F_{\\Gamma_i})=K_j\\right]', 'N_{K_j}=\\sum_{i=1}^{N_{\\mathrm{eval}}}\\mathbf{1}\\left[\\kappa(F_{\\Gamma_i})=K_j\\right]', 'Absolute Häufigkeit einer funktionalen Klasse.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1450, '3.1466', 120, 'Relative Klassenhäufigkeit', 'p_{K_j}=\\frac{N_{K_j}}{N_{\\mathrm{eval}}}', 'p_{K_j}=\\frac{N_{K_j}}{N_{\\mathrm{eval}}}', 'Relative Häufigkeit einer funktionalen Klasse.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1451, '3.1467', 120, 'Normierung der Klassenhäufigkeiten', '\\sum_{j=1}^{r}p_{K_j}=1', '\\sum_{j=1}^{r}p_{K_j}=1', 'Normierungsbedingung der Klassenverteilung.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1452, '3.1468', 120, 'Empirische Attraktorhäufigkeit', 'p(A_j)=\\frac{N(A_j)}{N_{\\mathrm{eval}}}', 'p(A_j)=\\frac{N(A_j)}{N_{\\mathrm{eval}}}', 'Relative Häufigkeit eines Attraktors.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
(1453, '3.1469', 120, 'Bedingte Attraktorhäufigkeit', 'p(A_j\\mid B)=\\frac{N(A_j\\cap B)}{N(B)}', 'p(A_j\\mid B)=\\frac{N(A_j\\cap B)}{N(B)}', 'Attraktorhäufigkeit innerhalb eines Parameterbereichs.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.11.', 'Die im Abschnitt festgelegten Bedingungen der Simulationsstudie gelten.', 'draft', 115),
