(1568, '3.1500', 122, 'Äquifinalitätsbedingung', '\\Theta_a\\neq\\Theta_b\\quad\\land\\quad D_{\\Gamma}\\left(\\Gamma(\\Theta_a),\\Gamma(\\Theta_b)\\right)\\le\\varepsilon_{\\Gamma}', '\\Theta_a\\neq\\Theta_b\\quad\\land\\quad D_{\\Gamma}\\left(\\Gamma(\\Theta_a),\\Gamma(\\Theta_b)\\right)\\le\\varepsilon_{\\Gamma}', 'Unterschiedliche Parameter erzeugen hinreichend ähnliche Trajektorien.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1569, '3.1501', 122, 'Äquivalente Parametermenge', '\\mathcal{P}_{\\mathrm{eq}}\\left(\\Gamma^{*}\\right)=\\left\\{\\Theta\\in\\mathcal{P}_{\\mathrm{valid}}\\mid D_{\\Gamma}\\left(\\Gamma(\\Theta),\\Gamma^{*}\\right)\\le\\varepsilon_{\\Gamma}\\right\\}', '\\mathcal{P}_{\\mathrm{eq}}\\left(\\Gamma^{*}\\right)=\\left\\{\\Theta\\in\\mathcal{P}_{\\mathrm{valid}}\\mid D_{\\Gamma}\\left(\\Gamma(\\Theta),\\Gamma^{*}\\right)\\le\\varepsilon_{\\Gamma}\\right\\}', 'Menge aller zur Zieltrajektorie äquivalenten Parametrisierungen.', 'definition', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1570, '3.1502', 122, 'Eindeutige Identifizierbarkeit', '\\left|\\mathcal{P}_{\\mathrm{eq}}\\left(\\Gamma^{*}\\right)\\right|=1', '\\left|\\mathcal{P}_{\\mathrm{eq}}\\left(\\Gamma^{*}\\right)\\right|=1', 'Bedingung einer eindeutig identifizierbaren Parametrisierung.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1571, '3.1503', 122, 'Modellinterner Zustandsübergang', 'S_{t+1}=\\mathcal{O}_{\\Theta}\\left(S_t\\right)', 'S_{t+1}=\\mathcal{O}_{\\Theta}\\left(S_t\\right)', 'Parametrisierter Zustandsübergang innerhalb der Simulation.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1572, '3.1504', 122, 'Trennung von Modell- und empirischer Kausalität', '\\mathcal{C}_{\\mathrm{model}}\\neq\\mathcal{C}_{\\mathrm{emp}}', '\\mathcal{C}_{\\mathrm{model}}\\neq\\mathcal{C}_{\\mathrm{emp}}', 'Modellinterne Übergangslogik ist nicht automatisch empirische Kausalität.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1573, '3.1505', 122, 'Empirische Anschlussfähigkeit der Kausalstruktur', '\\Phi\\left(\\mathcal{C}_{\\mathrm{model}}\\right)\\approx\\mathcal{C}_{\\mathrm{emp}}', '\\Phi\\left(\\mathcal{C}_{\\mathrm{model}}\\right)\\approx\\mathcal{C}_{\\mathrm{emp}}', 'Näherungsweise Übereinstimmung von Modell- und empirischer Kausalstruktur.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1574, '3.1506', 122, 'Skalenabhängige Modellrepräsentation', '\\mathcal{M}_{\\lambda}', '\\mathcal{M}_{\\lambda}', 'Modellrepräsentation auf der Skala lambda.', 'definition', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1575, '3.1507', 122, 'Skalentransformation', 'T_{\\lambda_a\\rightarrow\\lambda_b}:\\mathcal{M}_{\\lambda_a}\\longrightarrow\\mathcal{M}_{\\lambda_b}', 'T_{\\lambda_a\\rightarrow\\lambda_b}:\\mathcal{M}_{\\lambda_a}\\longrightarrow\\mathcal{M}_{\\lambda_b}', 'Abbildung zwischen Modellrepräsentationen unterschiedlicher Skalen.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1576, '3.1508', 122, 'Skaleninvarianz', 'F\\left(T_{\\lambda_a\\rightarrow\\lambda_b}(\\Gamma)\\right)\\approx F(\\Gamma)', 'F\\left(T_{\\lambda_a\\rightarrow\\lambda_b}(\\Gamma)\\right)\\approx F(\\Gamma)', 'Erhaltung wesentlicher funktionaler Eigenschaften unter Skalenübertragung.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1577, '3.1509', 122, 'Gesamtunsicherheit', 'U_{\\mathrm{total}}=U_{\\mathrm{data}}+U_{\\mathrm{param}}+U_{\\mathrm{struct}}+U_{\\mathrm{num}}+U_{\\mathrm{interpret}}', 'U_{\\mathrm{total}}=U_{\\mathrm{data}}+U_{\\mathrm{param}}+U_{\\mathrm{struct}}+U_{\\mathrm{num}}+U_{\\mathrm{interpret}}', 'Konzeptionelle Zerlegung der Gesamtunsicherheit.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1578, '3.1510', 122, 'Vertrauensindex', 'I_{\\mathrm{confidence}}=1-\\widehat{U}_{\\mathrm{total}}', 'I_{\\mathrm{confidence}}=1-\\widehat{U}_{\\mathrm{total}}', 'Komplement der normierten Gesamtunsicherheit.', 'metric', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1579, '3.1511', 122, 'Wertebereich des Vertrauensindex', '0\\le I_{\\mathrm{confidence}}\\le1', '0\\le I_{\\mathrm{confidence}}\\le1', 'Zulässiger Wertebereich des Vertrauensindex.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1580, '3.1512', 122, 'Gültigkeitsstatusvektor', 'Z_{\\mathrm{valid}}=\\left(I_{\\mathrm{formal}},I_{\\mathrm{domain}},I_{\\mathrm{param}},I_{\\mathrm{num}},I_{\\mathrm{emp}},I_{\\mathrm{ident}},I_{\\mathrm{confidence}}\\right)', 'Z_{\\mathrm{valid}}=\\left(I_{\\mathrm{formal}},I_{\\mathrm{domain}},I_{\\mathrm{param}},I_{\\mathrm{num}},I_{\\mathrm{emp}},I_{\\mathrm{ident}},I_{\\mathrm{confidence}}\\right)', 'Zusammengefasster Gültigkeitsstatus eines Simulationslaufs.', 'definition', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1581, '3.1513', 122, 'Mindestbedingungen der Interpretierbarkeit', 'I_k\\ge\\varepsilon_k\\qquad\\text{für alle }k\\in\\mathcal{K}_{\\mathrm{valid}}', 'I_k\\ge\\varepsilon_k\\qquad\\text{für alle }k\\in\\mathcal{K}_{\\mathrm{valid}}', 'Mindestbedingungen für alle relevanten Gültigkeitskomponenten.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1582, '3.1514', 122, 'Binärer Interpretationsstatus', 'z_{\\mathrm{interpret}}=\\prod_{k\\in\\mathcal{K}_{\\mathrm{valid}}}\\mathbf{1}\\left[I_k\\ge\\varepsilon_k\\right]', 'z_{\\mathrm{interpret}}=\\prod_{k\\in\\mathcal{K}_{\\mathrm{valid}}}\\mathbf{1}\\left[I_k\\ge\\varepsilon_k\\right]', 'Verknüpfung sämtlicher Gültigkeitsbedingungen.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1583, '3.1515', 122, 'Freigegebene Interpretation', 'z_{\\mathrm{interpret}}=1', 'z_{\\mathrm{interpret}}=1', 'Kennzeichnung eines interpretierbaren Simulationslaufs.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117),
(1584, '3.1516', 122, 'Methodische Prüfreihenfolge', '\\text{Konsistenz}\\Longrightarrow\\text{Bereichsgültigkeit}\\Longrightarrow\\text{numerische Stabilität}\\Longrightarrow\\text{Identifizierbarkeit}\\Longrightarrow\\text{empirische Anschlussfähigkeit}\\Longrightarrow\\text{Interpretation}', '\\text{Konsistenz}\\Longrightarrow\\text{Bereichsgültigkeit}\\Longrightarrow\\text{numerische Stabilität}\\Longrightarrow\\text{Identifizierbarkeit}\\Longrightarrow\\text{empirische Anschlussfähigkeit}\\Longrightarrow\\text{Interpretation}', 'Reihenfolge der methodischen Gesamtprüfung.', '', 'original', NULL, 'Herleitung gemäß Abschnitt 3.8.12.', 'Die im Abschnitt festgelegten Gültigkeits-, Unsicherheits- und Interpretationsbedingungen gelten.', 'draft', 117);
