INSERT INTO `lemmas` (`lemma_id`, `lemma_number`, `section_id`, `title`, `statement_text`, `statement_latex`, `word_latex`, `provenance`, `source_id`, `assumptions`, `validation_status`, `created_revision_id`) VALUES
(1, '3.4.1', 52, 'Nichtleere Zustandsmenge', 'Erfüllt eine funktionale Organisation S die Bedingung C_F(S) >= C_krit, dann ist ihre funktionale Zustandsmenge nicht leer.', 'C_F(mathcal{S})geq C_{mathrm{krit}}LongrightarrowOmega_F(mathcal{S})\neqvarnothing', 'C_F(mathcal{S})geq C_{mathrm{krit}}LongrightarrowOmega_F(mathcal{S})\neqvarnothing', 'original', NULL, 'Axiom A6, Definition 3.4.1 und Gleichung (3.649).', 'checked', 49),
(4, '3.4.2', 55, 'Äquivalenzeigenschaften', 'Die durch die Gleichheit der Merkmalswerte einer Abbildung kappa_F definierte Relation sim_F ist reflexiv, symmetrisch und transitiv und damit eine Äquivalenzrelation auf Omega_F(S).', 'sim_F	ext{ ist reflexiv, symmetrisch und transitiv auf }Omega_F(mathcal{S})', 'sim_F	ext{ ist reflexiv, symmetrisch und transitiv auf }Omega_F(mathcal{S})', 'original', NULL, 'Definition 3.4.3 und die Eigenschaften der Gleichheitsrelation auf K_F.', 'checked', 52),
(5, '3.4.3', 57, 'Nichtnotwendigkeit klassischer Relationseigenschaften', 'Aus der Definition einer funktionalen Relation folgen Reflexivität, Symmetrie und Transitivität nicht notwendig.', '\\neg(\\mathrm{reflexiv}\\land\\mathrm{symmetrisch}\\land\\mathrm{transitiv})\\text{ ohne Zusatzbedingungen}', '\\neg(\\mathrm{reflexiv}\\land\\mathrm{symmetrisch}\\land\\mathrm{transitiv})\\text{ ohne Zusatzbedingungen}', 'original', NULL, 'Definition 3.4.5.', 'checked', 54),
(6, '3.4.4', 58, 'Jede funktionale Transformation induziert eine funktionale Relation', 'Für jede funktionale Transformation existiert eine durch sie eindeutig bestimmte Transformationsrelation.', 'T_F:\\Omega_F(\\mathcal{S})\\to\\Omega_F(\\mathcal{S})\\Longrightarrow\\exists!\\,R_{T_F}=\\left\\{\\left(z_F,T_F(z_F)\\right)\\middle|z_F\\in\\Omega_F(\\mathcal{S})\\right\\}', 'T_F:\\Omega_F(\\mathcal{S})\\to\\Omega_F(\\mathcal{S})\\Longrightarrow\\exists!\\,R_{T_F}=\\left\\{\\left(z_F,T_F(z_F)\\right)\\middle|z_F\\in\\Omega_F(\\mathcal{S})\\right\\}', 'original', NULL, 'Definitionen 3.4.8 und 3.4.9.', 'checked', 55),
(7, '3.4.5', 59, 'Abgeschlossenheit des funktionalen Operatorraums unter Komposition', 'Die Komposition zweier funktionaler Operatoren derselben Zustandsmenge ist wiederum ein funktionaler Operator.', 'O_F^{(1)},O_F^{(2)}\\in\\mathcal{O}_F(\\mathcal{S})\\Longrightarrow O_F^{(2)}\\circ O_F^{(1)}\\in\\mathcal{O}_F(\\mathcal{S})', 'O_F^{(1)},O_F^{(2)}\\in\\mathcal{O}_F(\\mathcal{S})\\Longrightarrow O_F^{(2)}\\circ O_F^{(1)}\\in\\mathcal{O}_F(\\mathcal{S})', 'original', NULL, 'Definitionen 3.4.11 und 3.4.12.', 'checked', 56),
(8, '3.4.6', 60, 'Jede endliche Operatorfolge erzeugt eine funktionale Transformation', 'Jede endliche Folge funktionaler Operatoren bestimmt durch Komposition eine eindeutig bestimmte funktionale Transformation.', '\\mathbf{O}_F^{[n]}=\\left(O_F^{(0)},\\dots,O_F^{(n-1)}\\right)\\Longrightarrow\\Phi_F^{[n]}\\in\\mathcal{T}_F(\\mathcal{S})', '\\mathbf{O}_F^{[n]}=\\left(O_F^{(0)},\\dots,O_F^{(n-1)}\\right)\\Longrightarrow\\Phi_F^{[n]}\\in\\mathcal{T}_F(\\mathcal{S})', 'original', NULL, 'Lemma 3.4.5 und Definition 3.4.17.', 'checked', 57),
(9, '3.4.7', 60, 'Transitivität der funktionalen Übergangsordnung', 'Die funktionale Übergangsordnung ist innerhalb eines gegebenen Entwicklungspfads transitiv.', 'z_F^{(i)}\\prec_F z_F^{(j)}\\land z_F^{(j)}\\prec_F z_F^{(k)}\\Longrightarrow z_F^{(i)}\\prec_F z_F^{(k)}', 'z_F^{(i)}\\prec_F z_F^{(j)}\\land z_F^{(j)}\\prec_F z_F^{(k)}\\Longrightarrow z_F^{(i)}\\prec_F z_F^{(k)}', 'original', NULL, 'Definition 3.4.20 und Transitivität der natürlichen Indexordnung.', 'checked', 57),
(10, 'Lemma 3.4.4', 59, 'Abgeschlossenheit funktionaler Operatorwirkungen', 'Für jeden funktionalen Operator und jeden funktionalen Zustand liegt das Ergebnis der Operatorwirkung wiederum im funktionalen Zustandsraum.', 'O_F(z_F)\\in\\Omega_F(\\mathcal S)', 'O_F(z_F)\\in\\Omega_F(\\mathcal S)', 'original', NULL, 'Definition 3.4.11.', 'checked', 61),
(11, 'Lemma 3.4.5', 59, 'Abgeschlossenheit der Operatorkomposition', 'Die Komposition zweier funktionaler Operatoren derselben Organisation ist erneut ein funktionaler Operator dieser Organisation.', 'O_{F,1},O_{F,2}\\in\\mathcal O_F(\\mathcal S)\\Longrightarrow O_{F,2}\\circ O_{F,1}\\in\\mathcal O_F(\\mathcal S)', 'O_{F,1},O_{F,2}\\in\\mathcal O_F(\\mathcal S)\\Longrightarrow O_{F,2}\\circ O_{F,1}\\in\\mathcal O_F(\\mathcal S)', 'original', NULL, 'Definitionen 3.4.11 bis 3.4.13.', 'checked', 61),
(12, 'Lemma 3.4.6', 60, 'Jede endliche Operatorfolge erzeugt eine funktionale Transformation', 'Für jede endliche funktionale Operatorfolge existiert ein Gesamtoperator in der funktionalen Operatormenge, der die Wirkung der gesamten Folge beschreibt.', 'O_F^{[n]}\\in\\mathcal O_F(\\mathcal S)', 'O_F^{[n]}\\in\\mathcal O_F(\\mathcal S)', 'original', NULL, 'Abgeschlossenheit und Assoziativität der Operatorkomposition.', 'checked', 62),
(13, 'Lemma 3.4.7', 60, 'Transitivität der funktionalen Übergangsordnung', 'Die funktionale Übergangsordnung ist entlang eines festgelegten Entwicklungspfads transitiv.', 'z_F^{(i)}\\preceq_F z_F^{(j)}\\land z_F^{(j)}\\preceq_F z_F^{(k)}\\Longrightarrow z_F^{(i)}\\preceq_F z_F^{(k)}', 'z_F^{(i)}\\preceq_F z_F^{(j)}\\land z_F^{(j)}\\preceq_F z_F^{(k)}\\Longrightarrow z_F^{(i)}\\preceq_F z_F^{(k)}', 'adapted', 31, 'Definition 3.4.20.', 'checked', 62),
(14, 'Lemma 3.4.8', 61, 'Erhaltung kohärenter Zustände durch kohärenzerhaltende Operatoren', 'Jeder kohärenzerhaltende Operator bildet einen kohärenten Zustand auf einen kohärenten Folgezustand ab.', 'z_FinOmega_F^{K}(mathcal S)land O_Finmathcal O_F^{K}(mathcal S)Longrightarrow O_F(z_F)inOmega_F^{K}(mathcal S)', 'z_FinOmega_F^{K}(mathcal S)land O_Finmathcal O_F^{K}(mathcal S)Longrightarrow O_F(z_F)inOmega_F^{K}(mathcal S)', 'original', NULL, 'Definitionen 3.4.23 und 3.4.24.', 'checked', 63),
(15, 'Lemma 3.4.9', 61, 'Abgeschlossenheit kohärenzerhaltender Operatorkompositionen', 'Die Komposition zweier kohärenzerhaltender Operatoren ist wiederum kohärenzerhaltend.', 'O_{F,1},O_{F,2}inmathcal O_F^{K}(mathcal S)Longrightarrow O_{F,2}circ O_{F,1}inmathcal O_F^{K}(mathcal S)', 'O_{F,1},O_{F,2}inmathcal O_F^{K}(mathcal S)Longrightarrow O_{F,2}circ O_{F,1}inmathcal O_F^{K}(mathcal S)', 'original', NULL, 'Lemma 3.4.8 und Abgeschlossenheit der funktionalen Operatormenge.', 'checked', 63),
(16, 'Lemma 3.4.10', 62, 'Reflexivität der funktionalen Erreichbarkeit', 'Jeder kohärente Zustand ist von sich selbst funktional erreichbar.', 'z_F\\leadsto_F z_F', 'z_F\\leadsto_F z_F', 'original', NULL, 'Definitionen 3.4.27 bis 3.4.34.', 'checked', 64),
(17, 'Lemma 3.4.11', 62, 'Transitivität der funktionalen Erreichbarkeit', 'Funktionale Erreichbarkeit ist unter der Verkettung kohärenzerhaltender Pfade transitiv.', 'z_F^{(i)}\\leadsto_F z_F^{(j)}\\land z_F^{(j)}\\leadsto_F z_F^{(k)}\\Longrightarrow z_F^{(i)}\\leadsto_F z_F^{(k)}', 'z_F^{(i)}\\leadsto_F z_F^{(j)}\\land z_F^{(j)}\\leadsto_F z_F^{(k)}\\Longrightarrow z_F^{(i)}\\leadsto_F z_F^{(k)}', 'original', NULL, 'Definitionen 3.4.27 bis 3.4.34.', 'checked', 64),
(18, 'Lemma 3.4.12', 62, 'Äquivalenzrelation der wechselseitigen Erreichbarkeit', 'Wechselseitige funktionale Erreichbarkeit ist reflexiv, symmetrisch und transitiv.', '\\leftrightsquigarrow_F\\text{ ist eine Äquivalenzrelation}', '\\leftrightsquigarrow_F\\text{ ist eine Äquivalenzrelation}', 'original', NULL, 'Definitionen 3.4.27 bis 3.4.34.', 'checked', 64),
(19, 'Lemma 3.4.13', 62, 'Dreiecksungleichung der funktionalen Übergangsdistanz', 'Die minimale funktionale Pfadlänge erfüllt die Dreiecksungleichung.', '\\delta_F(z_F^{(i)},z_F^{(k)})\\leq\\delta_F(z_F^{(i)},z_F^{(j)})+\\delta_F(z_F^{(j)},z_F^{(k)})', '\\delta_F(z_F^{(i)},z_F^{(k)})\\leq\\delta_F(z_F^{(i)},z_F^{(j)})+\\delta_F(z_F^{(j)},z_F^{(k)})', 'original', NULL, 'Definitionen 3.4.27 bis 3.4.34.', 'checked', 64),
(20, 'Lemma 3.4.14', 63, 'Transitivität der funktionalen Vorordnung', 'Die Verkettung zweier endlicher nichtidentischer Nachfolgepfade erzeugt erneut einen endlichen Nachfolgepfad.', 'z_F^{(i)}\\prec_F^{*}z_F^{(j)}\\land z_F^{(j)}\\prec_F^{*}z_F^{(k)}\\Longrightarrow z_F^{(i)}\\prec_F^{*}z_F^{(k)}', 'z_F^{(i)}\\prec_F^{*}z_F^{(j)}\\land z_F^{(j)}\\prec_F^{*}z_F^{(k)}\\Longrightarrow z_F^{(i)}\\prec_F^{*}z_F^{(k)}', 'original', NULL, 'Definition 3.4.38.', 'checked', 65),
(21, 'Lemma 3.4.15', 63, 'Lineare Ordnung der Zustandsinstanzen eines Pfades', 'Die reflexive instanzielle Vorordnung bildet auf den Zustandsinstanzen eines endlichen Entwicklungspfads eine lineare Ordnung.', '(\\mathcal Z_F(\\mathcal P_F^{(n)}),\\unlhd_F)', '(\\mathcal Z_F(\\mathcal P_F^{(n)}),\\unlhd_F)', 'adapted', 31, 'Definitionen 3.4.41 und 3.4.42.', 'checked', 65),
(22, 'Lemma 3.4.16', 63, 'Additivität der diskreten funktionalen Zeitdifferenz', 'Diskrete Zeitdifferenzen addieren sich entlang geordneter Zwischeninstanzen.', '\\Delta\\tau_F(\\zeta_i,\\zeta_k)=\\Delta\\tau_F(\\zeta_i,\\zeta_j)+\\Delta\\tau_F(\\zeta_j,\\zeta_k)', '\\Delta\\tau_F(\\zeta_i,\\zeta_k)=\\Delta\\tau_F(\\zeta_i,\\zeta_j)+\\Delta\\tau_F(\\zeta_j,\\zeta_k)', 'original', NULL, 'Definition 3.4.44 und i\\leq j\\leq k.', 'checked', 65),
(23, 'Lemma 3.4.17', 64, 'Gerichtete Raum-Zeit-Nachbarschaft', 'Aus einer unmittelbaren funktionalen Raum-Zeit-Nachbarschaft folgt im Allgemeinen nicht ihre Umkehrung.', '\\varepsilon_i\\blacktriangleright_F\\varepsilon_j\\nRightarrow\\varepsilon_j\\blacktriangleright_F\\varepsilon_i', '\\varepsilon_i\\blacktriangleright_F\\varepsilon_j\\nRightarrow\\varepsilon_j\\blacktriangleright_F\\varepsilon_i', 'original', NULL, 'Definition 3.4.51.', 'checked', 66),
(24, 'Lemma 3.4.18', 64, 'Dreiecksungleichung des gerichteten Raum-Zeit-Abstands', 'Der gerichtete funktionale Raum-Zeit-Abstand erfüllt die Dreiecksungleichung.', 'd_{RZ,F}(\\varepsilon_i,\\varepsilon_k)\\leq d_{RZ,F}(\\varepsilon_i,\\varepsilon_j)+d_{RZ,F}(\\varepsilon_j,\\varepsilon_k)', 'd_{RZ,F}(\\varepsilon_i,\\varepsilon_k)\\leq d_{RZ,F}(\\varepsilon_i,\\varepsilon_j)+d_{RZ,F}(\\varepsilon_j,\\varepsilon_k)', 'adapted', 47, 'Definition 3.4.55 und additive Pfadlängen.', 'checked', 66),
(25, 'Lemma 3.4.19', 64, 'Abhängigkeit funktionaler Gleichzeitigkeit vom Zeitschnitt', 'Die Zuordnung funktional unvergleichbarer Ereignisse zu einem gemeinsamen Zeitschnitt ist im Allgemeinen nicht eindeutig.', '\\varepsilon_i\\parallel_F\\varepsilon_j', '\\varepsilon_i\\parallel_F\\varepsilon_j', 'adapted', 31, 'Partielle Ordnung und Antiketten.', 'checked', 66),
(26, 'Lemma 3.4.20', 50, 'Jede funktionale Trajektorie erzeugt einen Raum-Zeit-Pfad', 'Für jede funktionale Trajektorie existiert eine zugehörige Ereignistrajektorie.', '\\gamma_F^{(n)}\\Rightarrow\\Gamma_F^{(n)}', '\\gamma_F^{(n)}\\Rightarrow\\Gamma_F^{(n)}', 'original', NULL, 'Definitionen 3.4.50 und 3.4.64.', 'checked', 67),
(28, 'Lemma 3.4.21', 50, 'Verkettung kohärenzerhaltender Operatoren', 'Sind alle Operatoren einer Sequenz kohärenzerhaltend, dann ist auch der Dynamikoperator kohärenzerhaltend.', 'O_{F,i}\\in\\mathcal O_F^K\\Rightarrow\\mathcal D_F\\in\\mathcal O_F^K', 'O_{F,i}\\in\\mathcal O_F^K\\Rightarrow\\mathcal D_F\\in\\mathcal O_F^K', 'original', NULL, 'Definition 3.4.66.', 'checked', 69),
(29, 'Lemma 3.4.22', 50, 'Invarianz kohärenzstabiler Bereiche', 'Ist ein Bereich unter dem Dynamikoperator invariant, verbleibt jede dort gestartete Trajektorie innerhalb dieses Bereiches.', '\\mathcal D_F(\\mathcal B_F)\\subseteq\\mathcal B_F', '\\mathcal D_F(\\mathcal B_F)\\subseteq\\mathcal B_F', 'original', NULL, 'Definition 3.4.69.', 'checked', 70),
(30, 'Lemma 3.4.23', 50, 'Instabilität ermöglicht Strukturwechsel', 'Das Verlassen einer Kohärenzklasse ermöglicht den Übergang in eine neue stabile Organisationsform.', '\\mathcal D_F(z_F)\\notin[z_F]_{\\sim_F}\\Rightarrow[z_F^{\\prime}]_{\\sim_F}', '\\mathcal D_F(z_F)\\notin[z_F]_{\\sim_F}\\Rightarrow[z_F^{\\prime}]_{\\sim_F}', 'original', NULL, 'Definition 3.4.71.', 'checked', 71),
(31, 'Lemma 3.4.24', 50, 'Neue Eigenschaften durch Kopplung', 'Gekoppelte funktionale Strukturen können eine neue gemeinsame Organisationsstruktur bilden.', '\\mathfrak{RZ}_{F}^{new}\\supset\\mathfrak{RZ}_{F,1}\\cup\\mathfrak{RZ}_{F,2}', '\\mathfrak{RZ}_{F}^{new}\\supset\\mathfrak{RZ}_{F,1}\\cup\\mathfrak{RZ}_{F,2}', 'original', NULL, 'Kopplungsrelationen vorhanden.', 'checked', 72),
(32, 'Lemma 3.4.26', 50, 'Rekonstruierbarkeit funktionaler Raum-Zeit', 'Aus funktionalem Zustandsraum, Relationsstruktur und Dynamikoperator kann eine dynamische funktionale Raum-Zeit-Struktur rekonstruiert werden.', '\\left(\\Omega_F,\\mathcal R_F,\\mathcal D_F\\right)\\Rightarrow\\mathfrak{RZ}_F^{dyn}', '\\left(\\Omega_F,\\mathcal R_F,\\mathcal D_F\\right)\\Rightarrow\\mathfrak{RZ}_F^{dyn}', 'original', NULL, 'Definition funktionaler Relationen.', 'checked', 73);
INSERT INTO `object_source_links` (`object_source_link_id`, `object_type`, `object_id`, `source_id`, `usage_type`, `note`) VALUES
(1, 'axiom', 1, 23, 'historical_context', 'Spencer-Brown dient als wissenschaftshistorischer Anschluss zur elementaren Rolle der Unterscheidung; Axiom A1 ist eine eigenständige FRZK-Setzung.'),
(2, 'axiom', 1, 113, 'supporting_source', 'Shannon stützt die wissenschaftliche Einordnung unterscheidbarer Möglichkeiten als Voraussetzung formaler Information; Axiom A1 bleibt originäre FRZK-Setzung.'),
(3, 'axiom', 2, 114, 'historical_context', 'Birkhoff dient der mathematischen Einordnung relationaler Ordnungsstrukturen. Axiom A2 bleibt eine eigenständige FRZK-Setzung.'),
(4, 'proposition', 2, 81, 'supporting_source', 'Newman stützt die Darstellung relationaler Strukturen als Graphen und Netzwerke.'),
(5, 'axiom', 3, 57, 'historical_context', 'Eilenberg und Mac Lane dienen der mathematischen Einordnung von Abbildungen und Komposition. Axiom A3 bleibt eine eigenständige FRZK-Setzung.');
INSERT INTO `proofs` (`proof_id`, `proof_number`, `section_id`, `theorem_id`, `lemma_id`, `corollary_id`, `title`, `proof_text`, `proof_latex`, `proof_method`, `provenance`, `source_id`, `validation_status`, `created_revision_id`) VALUES
(1, '3.2.1-P', 13, 1, NULL, NULL, 'Diagonalbeweis zu Cantors Satz', 'Angenommen, es existiere eine surjektive Abbildung f von M auf P(M). Es sei D die Menge aller x aus M, für die x nicht Element von f(x) ist. Wegen D ⊆ M gilt D ∈ P(M). Aus der angenommenen Surjektivität folgt ein d ∈ M mit f(d)=D. Dann gilt d ∈ D genau dann, wenn d ∉ f(d), also genau dann, wenn d ∉ D. Dieser Widerspruch widerlegt die angenommene Surjektivität.', 'D={xin Mmid x\notin f(x)},qquad din Diff d\notin f(d)iff d\notin D', 'contradiction', 'adapted', 66, 'checked', 10),
(2, '3.2.2-P', 14, 2, NULL, NULL, 'Beweis der Korrespondenz zwischen Äquivalenzrelationen und Partitionen', 'Die Äquivalenzklassen überdecken wegen der Reflexivität die gesamte Menge. Schneiden sich zwei Klassen, folgen aus Symmetrie und Transitivität ihre Gleichheit; sie sind daher identisch oder disjunkt. Umgekehrt definiert die gemeinsame Zugehörigkeit zu genau einem Block einer Partition eine reflexive, symmetrische und transitive Relation.', 'xsim_{mathcal C}yiffexists Cinmathcal C:;xin Cland yin C', 'equivalence', 'adapted', 71, 'checked', 11),
(3, '3.2.3-P', 14, 3, NULL, NULL, 'Beweis der Assoziativität relationaler Komposition', 'Die elementweise Auflösung beider Kompositionen führt jeweils auf dieselbe Existenzbedingung: Es existieren b und c mit (a,b)∈R, (b,c)∈S und (c,d)∈T. Daher sind beide Relationen extensional gleich.', '(a,d)in Tcirc(Scirc R)iffexists bexists c:;(a,b)in Rland(b,c)in Sland(c,d)in Tiff(a,d)in(Tcirc S)circ R', 'direct', 'adapted', 75, 'checked', 11),
(4, '3.2.4-P', 16, 4, NULL, NULL, 'Beweis des Handschlaglemmas', 'Jede ungerichtete Kante besitzt zwei Endknoten und wird in der Summe der Knotengrade genau zweimal gezählt.', '\\sum_{v\\in V}\\deg(v)=2|E|', '', 'literature', 80, 'checked', 13),
(5, '3.2.5-P', 16, 5, NULL, NULL, 'Beweis der Eindeutigkeit der Pfade in einem Baum', 'Der Zusammenhang sichert die Existenz eines Pfades. Zwei verschiedene Pfade zwischen denselben Knoten würden einen Zyklus erzeugen und damit der Azyklizität widersprechen.', '\\forall u,v\\in V,\\;u\\neq v:\\;\\exists!\\,P_{uv}', 'contradiction', 'literature', 80, 'checked', 13),
(6, '3.2.6-P', 17, 6, NULL, NULL, 'Beweis zur Existenz der Umkehrfunktion', 'Ist f bijektiv, besitzt jedes b∈B genau ein Urbild a∈A. Die Zuordnung b↦a ist daher eindeutig und definiert f^{-1}. Existiert umgekehrt f^{-1}, kann kein b ohne Urbild bleiben und kein b zwei verschiedene Urbilder besitzen. Somit ist f surjektiv und injektiv, also bijektiv.', 'f^{-1}	ext{ existiert}Longleftrightarrow f	ext{ ist bijektiv}', 'equivalence', 'adapted', 71, 'checked', 14),
(7, '3.2.7-P', 17, 7, NULL, NULL, 'Beweis der Assoziativität der Funktionskomposition', 'Für jedes a∈A gilt [h∘(g∘f)](a)=h(g(f(a)))=[(h∘g)∘f](a). Da beide Kompositionen für jedes Argument denselben Wert liefern, sind sie als Funktionen identisch.', '[hcirc(gcirc f)](a)=h(g(f(a)))=[(hcirc g)circ f](a)', 'direct', 'adapted', 71, 'checked', 14),
(8, '3.2.8-P', 18, 12, NULL, NULL, 'Beweis der Eindeutigkeit des Nullvektors', 'Seien 0_1 und 0_2 zwei additive neutrale Elemente. Wegen der Neutralität von 0_2 gilt 0_1=0_1+0_2. Wegen der Neutralität von 0_1 gilt zugleich 0_1+0_2=0_2. Daher ist 0_1=0_2.', '0_1=0_1+0_2=0_2', 'direct', 'adapted', 93, 'checked', 17),
(9, '3.2.9-P', 18, 13, NULL, NULL, 'Beweis der Eindeutigkeit des inversen Vektors', 'Seien x und y zwei additive Inverse desselben Vektors v. Dann folgt x=x+0=x+(v+y)=(x+v)+y=0+y=y. Somit stimmen beide inversen Vektoren überein.', 'x=x+0=x+(v+y)=(x+v)+y=0+y=y', 'direct', 'adapted', 93, 'checked', 17),
(10, '3.2.10-P', 19, 14, NULL, NULL, 'Beweis der Erhaltung des Nullvektors', 'Für jeden Vektor v gilt 0_V=0_Kv. Aus der Homogenität folgt T(0_V)=T(0_Kv)=0_KT(v)=0_W.', 'T(0_V)=T(0_Kv)=0_KT(v)=0_W', 'direct', 'adapted', 96, 'checked', 18),
(11, '3.2.11-P', 19, 15, NULL, NULL, 'Beweis der Untervektorraumeigenschaft von Kern und Bild', 'Der Nullvektor liegt im Kern. Jede Linearkombination zweier Kernelemente wird erneut auf den Nullvektor abgebildet. Für zwei Bildelemente x=T(u) und y=T(v) ist jede Linearkombination λx+μy gleich T(λu+μv) und liegt daher wieder im Bild.', 'T(lambda u+mu v)=lambda T(u)+mu T(v)=0_W,quadlambda x+mu y=T(lambda u+mu v)', 'direct', 'adapted', 96, 'checked', 18),
(12, '3.2.14-P', 20, 18, NULL, NULL, 'Beweis der Cauchy-Schwarz-Ungleichung', 'Für v=0 ist die Aussage unmittelbar erfüllt. Für v≠0 ist die positive Definitheit auf u-λv mit λ=<u,v>/<v,v> anzuwenden. Aus 0≤<u-λv,u-λv>=<u,u>-|<u,v>|²/<v,v> folgt |<u,v>|²≤<u,u><v,v> und damit nach Wurzelziehen die Behauptung.', '0leqleftlangle u-frac{langle u,v\rangle}{langle v,v\rangle}v,u-frac{langle u,v\rangle}{langle v,v\rangle}v\right\rangle=langle u,u\rangle-frac{|langle u,v\rangle|^2}{langle v,v\rangle}', 'direct', 'adapted', 98, 'checked', 19),
(13, '3.2.15-P', 20, 19, NULL, NULL, 'Beweis der Dreiecksungleichung', 'Aus der Definition der induzierten Norm folgt ||u+v||²=||u||²+2<u,v>+||v||². Mit der Cauchy-Schwarz-Ungleichung wird der mittlere Term durch 2||u||||v|| abgeschätzt. Damit gilt ||u+v||²≤(||u||+||v||)². Da beide Seiten nichtnegativ sind, folgt nach Wurzelziehen die Dreiecksungleichung.', '|u+v|^2=|u|^2+2langle u,v\rangle+|v|^2leq(|u|+|v|)^2', 'direct', 'adapted', 98, 'checked', 19),
(14, '3.2.16-P', 21, 20, NULL, NULL, 'Beweis der charakteristischen Gleichung', 'λ ist genau dann Eigenwert, wenn ein Vektor v≠0 mit (T-λI)v=0 existiert. Dies ist genau dann der Fall, wenn der Kern von T-λI nichttrivial ist. In endlicher Dimension ist dies äquivalent zur Nichtinvertierbarkeit von T-λI und damit zu det(T-λI)=0.', 'lambdainsigma(T)Longleftrightarrowker(T-lambda I)\neq{0}Longleftrightarrow T-lambda I	ext{ nicht invertierbar}Longleftrightarrowdet(T-lambda I)=0', 'equivalence', 'adapted', 101, 'checked', 20),
(15, '3.2.17-P', 21, 21, NULL, NULL, 'Beweis der linearen Unabhängigkeit', 'Der Beweis erfolgt durch Induktion über die Anzahl der Eigenvektoren. Wird eine minimale lineare Relation mit T transformiert und anschließend das λ_k-fache der ursprünglichen Relation subtrahiert, entsteht eine Relation zwischen k-1 Eigenvektoren mit Faktoren λ_i-λ_k. Wegen der Verschiedenheit der Eigenwerte und der Induktionsannahme verschwinden alle Koeffizienten.', 'sum_{i=1}^{k}a_iv_i=0Rightarrowsum_{i=1}^{k-1}a_i(lambda_i-lambda_k)v_i=0Rightarrow a_1=cdots=a_k=0', 'induction', 'adapted', 101, 'checked', 20),
(16, '3.2.18-P', 21, 22, NULL, NULL, 'Beweis der Charakterisierung der Diagonalisierbarkeit', 'Besitzt T eine Eigenvektorbasis, so ist seine Darstellung bezüglich dieser Basis diagonal. Ist T umgekehrt diagonal darstellbar, so bestehen die Basisvektoren der zugehörigen Basis aus Eigenvektoren. Die Dimension der direkten Summe der Eigenräume entspricht dann der Zahl der Basisvektoren und damit dim(V).', 'T=PDP^{-1}Longleftrightarrow V=igoplus_{lambdainsigma(T)}E_lambda', 'equivalence', 'adapted', 101, 'checked', 20),
(17, '3.2.19-P', 21, 23, NULL, NULL, 'Beweis der Spurformel', 'Über einem Zerfällungskörper ist die Matrixdarstellung von T zu einer oberen Dreiecksmatrix ähnlich, deren Diagonaleinträge die Eigenwerte mit algebraischer Vielfachheit sind. Die Spur ist unter Ähnlichkeit invariant und entspricht der Summe der Diagonaleinträge.', 'operatorname{tr}(T)=operatorname{tr}(P^{-1}TP)=sum_ilambda_i', 'direct', 'adapted', 101, 'checked', 20),
(18, '3.2.20-P', 21, 24, NULL, NULL, 'Beweis der Determinantenformel', 'Über einem Zerfällungskörper ist T zu einer oberen Dreiecksmatrix mit den Eigenwerten auf der Diagonalen ähnlich. Die Determinante ist unter Ähnlichkeit invariant und für Dreiecksmatrizen gleich dem Produkt der Diagonaleinträge.', 'det(T)=det(P^{-1}TP)=prod_ilambda_i', 'direct', 'adapted', 101, 'checked', 20),
(19, '3.2.21-P', 22, 25, NULL, NULL, 'Beweis der Matrixdarstellung', 'Sei e_1,...,e_n eine Basis von V und A=(a_ij) mit a_ij=B(e_i,e_j). Für u=Σ_i u_i e_i und v=Σ_j v_j e_j liefert die Bilinearität B(u,v)=Σ_iΣ_j u_i a_ij v_j=u^TAv. Die Koeffizienten a_ij sind eindeutig bestimmt.', 'a_{ij}=B(e_i,e_j)Rightarrow B(u,v)=sum_{i,j}u_i a_{ij}v_j=u^{T}Av', 'direct', 'adapted', 102, 'checked', 21),
(20, '3.2.22-P', 22, 26, NULL, NULL, 'Beweisskizze zu Sylvesters Trägheitsgesetz', 'Ein regulärer Basiswechsel transformiert A durch Kongruenz zu P^TAP. Die maximalen Dimensionen positiver und negativer Unterräume bleiben unter invertiblen Abbildungen erhalten. Damit sind n_+, n_- und n_0 invariant.', 'Amapsto P^{T}AP,quad Pin GL(n,mathbb{R})Rightarrow(n_+,n_-,n_0)	ext{ invariant}', '', 'adapted', 103, 'checked', 21),
(21, '3.2.23-P', 22, 27, NULL, NULL, 'Beweis des Zusammenhangs mit Skalarprodukten', 'Die Axiome eines reellen Skalarprodukts enthalten Bilinearität, Symmetrie und positive Definitheit. Umgekehrt erfüllt jede Bilinearform mit diesen Eigenschaften genau die Skalarproduktaxiome.', 'B	ext{ bilinear, symmetrisch, positiv definit}Longleftrightarrow B=langlecdot,cdot\rangle', 'equivalence', 'adapted', 102, 'checked', 21),
(22, '3.2.24-P', 22, 28, NULL, NULL, 'Beweis des eindeutigen Minimums', 'Aus positiver Definitheit folgt E(v)=v^TAv>0 für alle v≠0. Für v=0 gilt E(0)=0. Null ist daher der eindeutige globale Minimierer.', 'v\neq0Rightarrow v^{T}Av>0,quad E(0)=0', 'direct', 'adapted', 102, 'checked', 21),
(23, '3.2.25-P', 23, 29, NULL, NULL, 'Beweis der Projektionszerlegung', 'Aus I=P+(I-P) folgt v=Pv+(I-P)v. Wegen P(I-P)=P-P²=0 liegt (I-P)v im Kern von P, während Pv im Bild von P liegt. Für eine orthogonale Projektion sind Bild und Kern orthogonal. Die Eindeutigkeit folgt aus dem trivialen Schnitt von Bild und Kern.', 'I=P+(I-P),quad P(I-P)=0', 'direct', 'adapted', 105, 'checked', 22),
(24, '3.2.26-P', 23, 30, NULL, NULL, 'Beweis der besten Approximation', 'Für jedes u∈U gilt v-u=(v-Pv)+(Pv-u). Dabei ist v-Pv orthogonal zu U und damit zu Pv-u. Der Satz des Pythagoras liefert ||v-u||²=||v-Pv||²+||Pv-u||²≥||v-Pv||². Gleichheit gilt nur für u=Pv.', '|v-u|^2=|v-Pv|^2+|Pv-u|^2', '', 'adapted', 105, 'checked', 22),
(25, '3.2.27-P', 23, 31, NULL, NULL, 'Beweis der orthogonalen direkten Summe', 'Nach dem Projektionssatz besitzt jeder Vektor v eine eindeutige Darstellung v=u+w mit u∈U und w∈U^⊥. Da U∩U^⊥={0} gilt, ist die Summe direkt.', 'v=u+w,quad uin U,quad win U^perp,quad Ucap U^perp={0}', '', 'adapted', 105, 'checked', 22),
(26, '3.2.28-P', 23, 32, NULL, NULL, 'Beweis der Existenz einer Orthonormalbasis', 'Ausgehend von einer beliebigen Basis erzeugt das Gram-Schmidt-Verfahren schrittweise orthogonale, von Null verschiedene Vektoren. Durch Normierung entstehen orthonormale Vektoren, die wegen der Dreiecksstruktur des Verfahrens denselben Raum aufspannen.', 'e_k=frac{u_k}{|u_k|}', 'construction', 'adapted', 104, 'checked', 22),
(27, '3.2.29-P', 24, 33, NULL, NULL, 'Beweis zum charakteristischen Polynom', 'Aus Av=λv folgt (A-λI)v=0. Da v nicht der Nullvektor ist, besitzt A-λI einen nichttrivialen Kern und ist daher nicht invertierbar. Für quadratische Matrizen ist dies äquivalent zu det(A-λI)=0. Umgekehrt erzeugt eine verschwindende Determinante einen nichttrivialen Kern und damit einen Eigenvektor.', '(A-lambda I)v=0Longleftrightarrowdet(A-lambda I)=0', 'equivalence', 'adapted', 97, 'checked', 23),
(28, '3.2.30-P', 24, 34, NULL, NULL, 'Beweisskizze zum Spektralsatz', 'Eine reelle symmetrische Matrix besitzt ausschließlich reelle Eigenwerte. Eigenvektoren zu verschiedenen Eigenwerten sind orthogonal. Innerhalb mehrfacher Eigenräume kann eine Orthonormalbasis gewählt werden. Die Gesamtheit dieser Basisvektoren bildet die orthogonale Matrix Q; die zugehörigen Eigenwerte bilden die Diagonalmatrix Λ.', 'Q^TAQ=LambdaLongleftrightarrow A=QLambda Q^T', '', 'adapted', 106, 'checked', 23),
(29, '3.2.31-P', 24, 35, NULL, NULL, 'Beweis der Orthogonalität verschiedener Eigenräume', 'Für Av_i=λ_i v_i und Av_j=λ_j v_j gilt wegen der Symmetrie von A: λ_i⟨v_i,v_j⟩=⟨Av_i,v_j⟩=⟨v_i,Av_j⟩=λ_j⟨v_i,v_j⟩. Aus λ_i≠λ_j folgt daher ⟨v_i,v_j⟩=0.', '(lambda_i-lambda_j)langle v_i,v_j\rangle=0', '', 'adapted', 106, 'checked', 23),
(30, '3.2.32-P', 24, 36, NULL, NULL, 'Beweis des spektralen Langzeitverhaltens', 'Der Anfangsvektor wird in Eigenvektoren zerlegt. Nach n Iterationen wird jede Komponente mit λ_i^n gewichtet. Ist |λ_max| strikt größer als der Betrag aller übrigen Eigenwerte, verschwinden deren relative Beiträge gegenüber der dominanten Komponente. Die normierte Richtung konvergiert daher gegen den dominanten Eigenraum.', 'A^nv=sum_i c_ilambda_i^nv_i', '', 'adapted', 106, 'checked', 23),
(31, 'B-3.4.1-L1', 52, NULL, 1, NULL, 'Beweis zu Lemma 3.4.1', 'Nach Axiom A6 folgt aus der Kohärenzbedingung die Existenz mindestens eines funktionalen Zustands z_F. Nach Definition 3.4.1 ist jeder funktionale Zustand eine zulässige Konfiguration und gehört daher zur Menge Omega_F(S). Diese Menge enthält folglich mindestens ein Element und ist nicht leer.', 'C_F(mathcal{S})geq C_{mathrm{krit}}Rightarrowexists z_FinOmega_F(mathcal{S})RightarrowOmega_F(mathcal{S})\neqvarnothing', 'direct', 'original', NULL, 'checked', 49),
(32, 'B-3.4.1-S1', 52, 37, NULL, NULL, 'Beweis zu Satz 3.4.1', 'Nach Definition 3.4.2 sind zwei funktionale Zustände genau dann identisch, wenn alle drei Komponenten paarweise übereinstimmen. Die Negation dieser Konjunktion ist nach den De-Morgan-Regeln genau dann erfüllt, wenn mindestens eine der drei Komponenten nicht übereinstimmt. Damit folgt die behauptete Äquivalenz.', '\neg(Aland Bland C)Longleftrightarrow(\neg Alor\neg Blor\neg C)', 'equivalence', 'original', NULL, 'checked', 49),
(33, 'B-3.4.1-K1', 52, NULL, NULL, 1, 'Begründung zu Korollar 3.4.1', 'Nach Satz 3.4.1 genügt bereits die Abweichung einer einzigen Zustandskomponente, damit zwei Zustände verschieden sind. Wird eine Komponente aus der Darstellung entfernt, kann eine Abweichung in genau dieser Komponente nicht mehr erkannt werden. Die reduzierte Darstellung ist daher im Allgemeinen nicht injektiv bezüglich der Menge funktionaler Zustände.', NULL, 'direct', 'original', NULL, 'checked', 49),
(34, 'B-3.4.2-L1', 55, NULL, 4, NULL, 'Beweis zu Lemma 3.4.2', 'Für jeden Zustand ist der Merkmalswert mit sich selbst identisch; daher ist die Relation reflexiv. Aus der Symmetrie der Gleichheit folgt, dass aus kappa_F(z_i)=kappa_F(z_j) auch kappa_F(z_j)=kappa_F(z_i) folgt; daher ist die Relation symmetrisch. Aus kappa_F(z_i)=kappa_F(z_j) und kappa_F(z_j)=kappa_F(z_k) folgt durch Transitivität der Gleichheit kappa_F(z_i)=kappa_F(z_k); daher ist die Relation transitiv. Somit ist sim_F eine Äquivalenzrelation.', '	ext{Reflexivität}land	ext{Symmetrie}land	ext{Transitivität}Rightarrowsim_F	ext{ ist Äquivalenzrelation}', 'direct', 'original', NULL, 'checked', 52),
(35, 'B-3.4.2-S1', 55, 38, NULL, NULL, 'Beweis zu Satz 3.4.2', 'Aufgrund der Reflexivität gehört jeder Zustand zu seiner eigenen Äquivalenzklasse, sodass die Vereinigung aller Klassen die gesamte Zustandsmenge überdeckt. Besitzen zwei Klassen ein gemeinsames Element, ist dieses Element zu beiden Repräsentanten äquivalent. Aus Symmetrie und Transitivität folgt die Äquivalenz der Repräsentanten und damit die Identität beider Klassen. Verschiedene Klassen sind folglich disjunkt. Überdeckung und paarweise Disjunktheit zeigen, dass die Klassen eine Partition bilden.', 'igcup[z_F]_{sim_F}=Omega_F(mathcal{S})landleft([z_i]_{sim_F}\neq[z_j]_{sim_F}Rightarrow[z_i]_{sim_F}cap[z_j]_{sim_F}=varnothing\right)', '', 'original', NULL, 'checked', 52),
(36, 'B-3.4.2-K1', 55, NULL, NULL, 2, 'Begründung zu Korollar 3.4.2', 'Nach Satz 3.4.2 bilden die funktionalen Äquivalenzklassen eine Partition der Zustandsmenge. Eine Partition überdeckt die Grundmenge vollständig und ihre Teilmengen sind paarweise disjunkt. Daher gehört jeder funktionale Zustand bezüglich des festgelegten Kriteriums genau einer funktionalen Zustandsklasse an.', 'forall z_FinOmega_F(mathcal{S});exists!,[z_F]_{kappa_F}', 'direct', 'original', NULL, 'checked', 52),
(37, 'B-3.4.3-L1', 57, NULL, 5, NULL, 'Beweis zu Lemma 3.4.3', 'Die Zugehörigkeit eines geordneten Zustandspaares zu R_F wird ausschließlich durch den Wert der Prüffunktion rho_F bestimmt. Aus einer einzelnen positiven Prüfung folgen weder die Selbstrelation, noch die umgekehrte Relation, noch bei zwei aufeinanderfolgenden Relationen die direkte Relation zwischen erstem und drittem Zustand. Reflexivität, Symmetrie und Transitivität erfordern daher zusätzliche Bedingungen.', '\\rho_F(i,j)=1\\not\\Rightarrow\\rho_F(i,i)=1,\\rho_F(j,i)=1;\\quad\\rho_F(i,j)=\\rho_F(j,k)=1\\not\\Rightarrow\\rho_F(i,k)=1', 'direct', 'original', NULL, 'checked', 54),
(38, 'B-3.4.3-S1', 57, 39, NULL, NULL, 'Beweis zu Satz 3.4.3', 'Ist R_F leer, enthält die Zustandsstruktur trotz mindestens zweier Zustände kein funktional relationiertes Paar und beschreibt nur eine unverbundene Menge zulässiger Konfigurationen. Ist R_F nicht leer, existiert mindestens ein geordnetes funktional relationiertes Zustandspaar. Erst dadurch besitzt die Zustandsmenge eine nichtleere relationale Struktur.', 'R_F=\\varnothing\\Rightarrow\\mathfrak{Z}_F=(\\Omega_F,\\varnothing);\\quad R_F\\neq\\varnothing\\Rightarrow\\exists(z_i,z_j)\\in R_F', 'direct', 'original', NULL, 'checked', 54),
(39, 'B-3.4.3-K1', 57, NULL, NULL, 3, 'Begründung zu Korollar 3.4.3', 'Dieselbe Zustandsmenge kann mit einer leeren oder einer nichtleeren funktionalen Relation verbunden werden. Da dadurch verschiedene funktionale Zustandsstrukturen entstehen, bestimmt die Zustandsmenge allein die Organisation nicht eindeutig.', '(\\Omega_F,R_F^{(1)})\\neq(\\Omega_F,R_F^{(2)})\\text{ für }R_F^{(1)}\\neq R_F^{(2)}', 'direct', 'original', NULL, 'checked', 54),
(40, 'B-3.4.4-L1', 58, NULL, 6, NULL, 'Beweis zu Lemma 3.4.4', 'Jeder funktionale Zustand besitzt unter T_F genau ein Bild innerhalb derselben Zustandsmenge. Deshalb ist für jeden Ausgangszustand genau ein geordnetes Paar aus Ausgangs- und Zielzustand bestimmt. Die Menge aller dieser Paare ist die eindeutig durch T_F festgelegte Transformationsrelation.', '\\forall z_F\\in\\Omega_F(\\mathcal{S})\\;\\exists!\\,T_F(z_F)\\in\\Omega_F(\\mathcal{S})\\Longrightarrow\\exists!\\,R_{T_F}', 'direct', 'original', NULL, 'checked', 55),
(41, 'B-3.4.4-S1', 58, 40, NULL, NULL, 'Beweis zu Satz 3.4.4', 'Ist R_F die Transformationsrelation einer funktionalen Transformation, enthält R_F^{+}(z_F) für jeden Ausgangszustand genau das eine Bild T_F(z_F). Gilt umgekehrt für jeden Zustand, dass R_F^{+}(z_F) genau ein Element enthält, kann dieses eindeutige Element als T_F(z_F) definiert werden. Dadurch entsteht eine eindeutige Abbildung der Zustandsmenge in sich selbst.', 'R_F=R_{T_F}\\Longrightarrow\\forall z_F:\\left|R_F^{+}(z_F)\\right|=1;\\qquad\\forall z_F:\\left|R_F^{+}(z_F)\\right|=1\\Longrightarrow T_F(z_F):=z_F^{\\prime}', 'equivalence', 'original', NULL, 'checked', 55),
(42, 'B-3.4.4-K1', 58, NULL, NULL, 4, 'Begründung zu Korollar 3.4.4', 'Die erste Transformation bildet jeden Zustand in die funktionale Zustandsmenge ab. Deshalb kann die zweite Transformation auf das Ergebnis angewendet werden und liefert erneut genau einen Zustand derselben Zustandsmenge. Die Komposition erfüllt damit die Definition einer funktionalen Transformation.', 'T_F^{(1)}(z_F)\\in\\Omega_F(\\mathcal{S})\\Longrightarrow T_F^{(2)}\\left(T_F^{(1)}(z_F)\\right)\\in\\Omega_F(\\mathcal{S})', 'direct', 'original', NULL, 'checked', 55),
(43, 'B-3.4.5-L1', 59, NULL, 7, NULL, 'Beweis zu Lemma 3.4.5', 'Der erste Operator bildet jeden Zustand in die funktionale Zustandsmenge ab. Das Ergebnis liegt daher im Definitionsbereich des zweiten Operators, der es erneut eindeutig in die Zustandsmenge abbildet. Somit ist die Komposition wiederum ein funktionaler Operator.', 'O_F^{(1)}(z_F)\\in\\Omega_F(\\mathcal{S})\\Longrightarrow O_F^{(2)}(O_F^{(1)}(z_F))\\in\\Omega_F(\\mathcal{S})', 'direct', 'original', NULL, 'checked', 56),
(44, 'B-3.4.5-S1', 59, 41, NULL, NULL, 'Beweis zu Satz 3.4.5', 'Aus der Existenz eines beidseitigen inversen Operators folgen Injektivität und Surjektivität. Umgekehrt definiert eine bijektive Abbildung für jeden Zielzustand genau ein Urbild und damit einen eindeutigen inversen Operator.', 'O_F\\text{ invertierbar}\\Longrightarrow O_F\\text{ bijektiv};\\qquad O_F\\text{ bijektiv}\\Longrightarrow\\exists O_F^{-1}', 'equivalence', 'original', NULL, 'checked', 56),
(45, 'B-3.4.5-K1', 59, NULL, NULL, 5, 'Begründung zu Korollar 3.4.5', 'Werden zwei unterschiedliche Zustände auf dasselbe Bild abgebildet, ist der Operator nicht injektiv. Nach Satz 3.4.5 ist er daher nicht invertierbar.', 'z_F^{(i)}\\neq z_F^{(j)}\\land O_F(z_F^{(i)})=O_F(z_F^{(j)})\\Longrightarrow O_F\\text{ nicht injektiv}', 'direct', 'original', NULL, 'checked', 56),
(46, 'B-3.4.5-S2', 59, 42, NULL, NULL, 'Beweis zu Satz 3.4.6', 'Der Operatorraum ist nach Lemma 3.4.5 unter Komposition abgeschlossen. Die Abbildungskomposition ist assoziativ, und die Identität ist ein neutrales Element. Damit sind die Monoidaxiome erfüllt.', '\\operatorname{Abgeschlossenheit}\\land\\operatorname{Assoziativitaet}\\land\\operatorname{Identitaet}\\Longrightarrow\\operatorname{Monoid}', 'direct', 'original', NULL, 'checked', 56),
(47, 'B-3.4.5-K2', 59, NULL, NULL, 6, 'Begründung zu Korollar 3.4.6', 'Die Komposition bijektiver Operatoren ist bijektiv, die Identität ist bijektiv, und zu jedem invertierbaren Operator gehört eine inverse Abbildung. Zusammen mit der Assoziativität sind damit die Gruppenaxiome erfüllt.', 'O_F^{(1)},O_F^{(2)}\\in\\mathcal{O}_F^{\\times}\\Longrightarrow O_F^{(2)}\\circ O_F^{(1)}\\in\\mathcal{O}_F^{\\times}', 'direct', 'original', NULL, 'checked', 56),
(48, 'B-3.4.6-L1', 60, NULL, 8, NULL, 'Beweis zu Lemma 3.4.6', 'Jeder funktionale Operator bildet die Zustandsmenge in sich selbst ab. Da der Operatorraum unter Komposition abgeschlossen ist, ist auch die endliche Komposition aller Folgenelemente ein funktionaler Operator und erzeugt eine eindeutig bestimmte funktionale Transformation.', 'O_F^{(n-1)}\\circ\\dots\\circ O_F^{(0)}\\in\\mathcal{O}_F(\\mathcal{S})\\Longrightarrow\\Phi_F^{[n]}\\in\\mathcal{T}_F(\\mathcal{S})', 'induction', 'original', NULL, 'checked', 57),
(49, 'B-3.4.6-S1', 60, 43, NULL, NULL, 'Beweis zu Satz 3.4.7', 'Der erste Folgezustand ist durch den ersten Operator eindeutig bestimmt. Ist ein Zustand der Folge eindeutig bestimmt, erzeugt der nächste Operator wiederum genau einen Nachfolgezustand. Durch vollständige Induktion ist die gesamte Zustandsfolge eindeutig bestimmt.', 'z_F^{(1)}=O_F^{(0)}(z_F^{(0)}),\\qquad z_F^{(k+1)}=O_F^{(k)}(z_F^{(k)})', 'induction', 'original', NULL, 'checked', 57),
(50, 'B-3.4.6-K1', 60, NULL, NULL, 7, 'Begründung zu Korollar 3.4.7', 'Unterschiedliche zulässige Operatorfolgen können unterschiedliche Gesamttransformationen und damit für denselben Anfangszustand verschiedene Endzustände erzeugen. Ohne vollständige Operatorfolge ist die Entwicklung daher im Allgemeinen nicht eindeutig.', '\\Phi_F^{[n]}\\neq\\widetilde{\\Phi}_F^{[n]}\\Longrightarrow\\Phi_F^{[n]}(z_F^{(0)})\\neq\\widetilde{\\Phi}_F^{[n]}(z_F^{(0)})', 'direct', 'original', NULL, 'checked', 57),
(51, 'B-3.4.6-L2', 60, NULL, 9, NULL, 'Beweis zu Lemma 3.4.7', 'Die funktionale Übergangsordnung wird durch die natürliche Ordnung der Indizes definiert. Aus i kleiner j und j kleiner k folgt wegen der Transitivität der natürlichen Ordnung i kleiner k. Daher ist auch die funktionale Übergangsordnung transitiv.', 'i<j\\land j<k\\Longrightarrow i<k\\Longrightarrow z_F^{(i)}\\prec_F z_F^{(k)}', 'direct', 'original', NULL, 'checked', 57),
(52, 'B-3.4.6-S2', 60, 44, NULL, NULL, 'Beweis zu Satz 3.4.8', 'Irreflexivität folgt daraus, dass kein Index kleiner als er selbst ist. Asymmetrie folgt daraus, dass aus i kleiner j nicht zugleich j kleiner i gelten kann. Die Transitivität wurde in Lemma 3.4.7 gezeigt. Damit liegt eine strikte Ordnung vor.', 'i\\nless i,\\qquad i<j\\Longrightarrow j\\nless i,\\qquad i<j\\land j<k\\Longrightarrow i<k', 'direct', 'original', NULL, 'checked', 57),
(53, 'B-3.4.6-K2', 60, NULL, NULL, 8, 'Begründung zu Korollar 3.4.8', 'Die Übergangsordnung wird ausschließlich aus der Reihenfolge diskreter Indexpositionen gebildet. Sie enthält weder eine Abbildung in eine metrische Zeitmenge noch ein Maß für die Dauer zwischen Zuständen.', 'z_F^{(i)}\\prec_F z_F^{(j)}\\Longrightarrow i<j,\\qquad\\text{keine metrische Dauer bestimmt}', 'direct', 'original', NULL, 'checked', 57),
(54, 'Bew. 3.4.5-R1', 59, NULL, 10, NULL, 'Beweis zu Lemma 3.4.4', 'Da jeder funktionale Operator definitionsgemäß den funktionalen Zustandsraum in sich selbst abbildet, gehört das Bild jedes zulässigen Ausgangszustandes erneut zum Zustandsraum.', NULL, 'direct', 'original', NULL, 'checked', 61),
(55, 'Bew. 3.4.5-R2', 59, NULL, 11, NULL, 'Beweis zu Lemma 3.4.5', 'Die erste Operatorwirkung erzeugt einen Zustand im Zustandsraum. Auf diesen ist der zweite Operator definiert und erzeugt wiederum einen Zustand desselben Raumes. Damit ist die Komposition eine Selbstabbildung.', NULL, 'direct', 'original', NULL, 'checked', 61),
(56, 'Bew. 3.4.5-R3', 59, 45, NULL, NULL, 'Beweis zu Satz 3.4.5', 'Beide Klammerungen ordnen jedem Ausgangszustand denselben Zustand O_{F,3}(O_{F,2}(O_{F,1}(z_F))) zu. Daher sind die zusammengesetzten Operatoren gleich.', NULL, 'direct', 'adapted', 31, 'checked', 61),
(57, 'Bew. 3.4.5-R4', 59, 46, NULL, NULL, 'Beweis zu Satz 3.4.6', 'Die Operatormenge ist unter Komposition abgeschlossen, die Komposition ist assoziativ und der Identitätsoperator ist ein beidseitig neutrales Element. Damit sind die Monoidaxiome erfüllt.', NULL, 'direct', 'adapted', 31, 'checked', 61),
(58, 'Bew. 3.4.5-R5', 59, NULL, NULL, 9, 'Begründung zu Korollar 3.4.5', 'Die Assoziativität beseitigt jede Abhängigkeit von der Klammerung. Bei festgehaltener Reihenfolge besitzt die endliche Operatorfolge daher eine eindeutig bestimmte Gesamtwirkung.', NULL, 'direct', 'original', NULL, 'checked', 61),
(59, 'Bew. 3.4.5-R6', 59, NULL, NULL, 10, 'Begründung zu Korollar 3.4.6', 'Die invertierbaren Operatoren sind unter Komposition abgeschlossen, enthalten die Identität und zu jedem Element das inverse Element; die Assoziativität wird von der gesamten Operatormenge übernommen.', NULL, 'direct', 'adapted', 31, 'checked', 61),
(60, 'Bew. 3.4.6-R1', 60, NULL, 12, NULL, 'Beweis zu Lemma 3.4.6', 'Der Basisfall n=1 ist unmittelbar erfüllt. Unter der Induktionsannahme gehört der Gesamtoperator einer Folge der Länge n zur Operatormenge. Seine Komposition mit dem nächsten funktionalen Operator gehört wegen der Abgeschlossenheit erneut zur Operatormenge.', 'O_F^{[n+1]}=O_{F,n+1}\\circ O_F^{[n]}', 'induction', 'original', NULL, 'checked', 62),
(61, 'Bew. 3.4.6-R2', 60, 47, NULL, NULL, 'Beweis zu Satz 3.4.7', 'Jeder funktionale Operator ordnet jedem gegebenen Zustand genau einen Folgezustand zu. Durch rekursive Anwendung der vollständig angegebenen Operatorfolge ist daher jedes Folgenglied und damit die gesamte Zustandsfolge eindeutig bestimmt.', NULL, 'induction', 'original', NULL, 'checked', 62),
(62, 'Bew. 3.4.6-R3', 60, NULL, NULL, 11, 'Begründung zu Korollar 3.4.7', 'Sind auf denselben Ausgangszustand mehrere funktionale Operatoren anwendbar und erzeugen diese verschiedene Bilder, ist ohne Auswahl der Operatorfolge keine eindeutige Entwicklung bestimmt.', NULL, 'construction', 'original', NULL, 'checked', 62),
(63, 'Bew. 3.4.6-R4', 60, NULL, 13, NULL, 'Beweis zu Lemma 3.4.7', 'Aus i kleiner oder gleich j und j kleiner oder gleich k folgt aufgrund der Transitivität der natürlichen Ordnung i kleiner oder gleich k. Nach Definition der funktionalen Übergangsordnung folgt die Behauptung.', NULL, 'direct', 'adapted', 31, 'checked', 62),
(64, 'Bew. 3.4.6-R5', 60, 48, NULL, NULL, 'Beweis zu Satz 3.4.8', 'Irreflexivität, Transitivität und Vergleichbarkeit folgen unmittelbar aus der strikten linearen Ordnung der Pfadindizes. Die vorausgesetzte paarweise Verschiedenheit der Zustände überträgt diese Ordnung eindeutig auf die Zustände selbst.', NULL, 'direct', 'adapted', 31, 'checked', 62),
(65, 'Bew. 3.4.6-R6', 60, NULL, NULL, 12, 'Begründung zu Korollar 3.4.8', 'Die Relation präzisiert ausschließlich die Reihenfolge der Pfadpositionen. Da keine Maßfunktion für Übergangsdauern definiert ist, folgt daraus keine vollständige physikalische Zeitstruktur.', NULL, 'direct', 'original', NULL, 'checked', 62),
(66, 'Bew. 3.4.7-R1', 61, NULL, 14, NULL, 'Beweis zu Lemma 3.4.8', 'In einem kohärenten Ausgangszustand ist jede kohärenztragende Relation realisiert. Ein kohärenzerhaltender Operator führt jede dieser Relationen funktional äquivalent fort. Daher sind alle geforderten Relationen auch im Folgezustand realisiert.', 'O_F(z_F)inOmega_F^{K}(mathcal S)', 'direct', 'original', NULL, 'checked', 63),
(67, 'Bew. 3.4.7-R2', 61, NULL, 15, NULL, 'Beweis zu Lemma 3.4.9', 'Der erste kohärenzerhaltende Operator bildet einen kohärenten Zustand auf einen kohärenten Zwischenzustand ab. Der zweite kohärenzerhaltende Operator bildet auch diesen Zwischenzustand auf einen kohärenten Zustand ab. Damit ist die Komposition kohärenzerhaltend.', 'left(O_{F,2}circ O_{F,1}\right)(z_F)inOmega_F^{K}(mathcal S)', 'direct', 'original', NULL, 'checked', 63),
(68, 'Bew. 3.4.7-R3', 61, 49, NULL, NULL, 'Beweis zu Satz 3.4.9', 'Die Abgeschlossenheit folgt aus Lemma 3.4.9. Die Assoziativität wird von der funktionalen Operatormenge übernommen. Der Identitätsoperator erhält jede Relation unverändert und gehört deshalb zur kohärenzerhaltenden Operatormenge.', 'I_Finmathcal O_F^{K}(mathcal S)', 'direct', 'adapted', 31, 'checked', 63),
(69, 'Bew. 3.4.7-R4', 61, 50, NULL, NULL, 'Beweis zu Satz 3.4.10', 'Der Ausgangszustand ist nach Definition kohärent. Unter der Induktionsannahme ist der aktuelle Zustand kohärent; der nächste Operator ist kohärenzerhaltend. Nach Lemma 3.4.8 ist deshalb auch der nächste Zustand kohärent. Die Aussage folgt durch vollständige Induktion.', 'z_F^{(k+1)}=O_{F,k+1}(z_F^{(k)})inOmega_F^{K}(mathcal S)', 'induction', 'original', NULL, 'checked', 63),
(70, 'Bew. 3.4.7-R5', 61, NULL, NULL, 13, 'Begründung zu Korollar 3.4.9', 'Der Gesamtoperator ist eine endliche Komposition kohärenzerhaltender Operatoren. Aufgrund der Abgeschlossenheit des Untermonoids ist auch der Gesamtoperator kohärenzerhaltend.', 'O_F^{[n]}inmathcal O_F^{K}(mathcal S)', 'direct', 'original', NULL, 'checked', 63),
(71, 'Bew. 3.4.8-R1', 62, NULL, 16, NULL, 'Beweis zu Lemma 3.4.10', 'Der Identitätsoperator gehört zum kohärenzerhaltenden Monoid und bildet jeden Zustand auf sich selbst ab.', 'I_F(z_F)=z_F', 'direct', 'original', NULL, 'checked', 64),
(72, 'Bew. 3.4.8-R2', 62, NULL, 17, NULL, 'Beweis zu Lemma 3.4.11', 'Zwei aufeinanderfolgende kohärenzerhaltende Pfade können durch Komposition ihrer Gesamtoperatoren zu einem kohärenzerhaltenden Pfad verkettet werden.', 'z_F^{(k)}=\\widetilde O_F^{[n]}\\circ O_F^{[m]}(z_F^{(i)})', 'direct', 'original', NULL, 'checked', 64),
(73, 'Bew. 3.4.8-R3', 62, 51, NULL, NULL, 'Beweis zu Satz 3.4.11', 'Reflexivität und Transitivität folgen aus Lemma 3.4.10 und Lemma 3.4.11; damit liegt eine Präordnung vor.', '(\\Omega_F^{K}(\\mathcal S),\\leadsto_F)', 'direct', 'adapted', 31, 'checked', 64),
(74, 'Bew. 3.4.8-R4', 62, NULL, 18, NULL, 'Beweis zu Lemma 3.4.12', 'Reflexivität und Transitivität werden von der Erreichbarkeit übernommen; Symmetrie ist Bestandteil der Definition wechselseitiger Erreichbarkeit.', '\\leftrightsquigarrow_F\\text{ ist eine Äquivalenzrelation}', 'direct', 'adapted', 31, 'checked', 64),
(75, 'Bew. 3.4.8-R5', 62, 52, NULL, NULL, 'Beweis zu Satz 3.4.12', 'Ein nichtleerer kohärenter Zustandsraum und der Identitätsoperator bestimmen mindestens eine reflexive und transitive Erreichbarkeitsrelation.', 'z_F\\leadsto_F z_F', 'direct', 'original', NULL, 'checked', 64),
(76, 'Bew. 3.4.8-R6', 62, NULL, 19, NULL, 'Beweis zu Lemma 3.4.13', 'Die Verkettung zweier kürzester Pfade liefert einen zulässigen Gesamtpfad, dessen Länge die Summe der Teillängen ist. Das Minimum kann nicht größer sein.', '\\ell_F(\\mathcal P_{ik})=\\ell_F(\\mathcal P_{ij})+\\ell_F(\\mathcal P_{jk})', 'direct', 'adapted', 47, 'checked', 64),
(77, 'Bew. 3.4.8-R7', 62, 53, NULL, NULL, 'Beweis zu Satz 3.4.13', 'Nichtnegativität, Identität der Ununterscheidbaren und Dreiecksungleichung gelten; Symmetrie ist wegen gerichteter Übergänge nicht allgemein gegeben.', '\\delta_F\\text{ ist eine Quasimetrik}', 'direct', 'adapted', 47, 'checked', 64),
(78, 'Bew. 3.4.8-R8', 62, NULL, NULL, 14, 'Begründung zu Korollar 3.4.10', 'Die Erreichbarkeitsstruktur enthält keine zusätzliche Festlegung eines numerischen Abstands, einer Norm oder von Koordinaten.', '\\mathfrak R_F^{K}(\\mathcal S)\\nRightarrow(\\Omega_F^{K}(\\mathcal S),d_F)', 'direct', 'original', NULL, 'checked', 64),
(79, 'Bew. 3.4.8-R9', 62, NULL, NULL, 15, 'Begründung zu Korollar 3.4.11', 'Reversible gleich lange Übergänge erzeugen zu jedem kürzesten Hinpfad einen gleich langen Rückpfad und damit Symmetrie.', '\\delta_F(z_i,z_j)=\\delta_F(z_j,z_i)', 'direct', 'adapted', 47, 'checked', 64),
(80, 'Bew. 3.4.9-R1', 63, NULL, 20, NULL, 'Beweis zu Lemma 3.4.14', 'Zwei endliche Nachfolgepfade können an ihrem gemeinsamen Zwischenzustand verkettet werden. Die verkettete Folge ist erneut endlich und besteht aus nichtidentischen Übergängen.', 'z_i\\prec_F^{*}z_j\\land z_j\\prec_F^{*}z_k\\Longrightarrow z_i\\prec_F^{*}z_k', 'direct', 'original', NULL, 'checked', 65),
(81, 'Bew. 3.4.9-R2', 63, 54, NULL, NULL, 'Beweis zu Satz 3.4.14', 'Reflexivität und Transitivität folgen aus der reflexiven Hülle und Lemma 3.4.14. Wechselseitige Vorordnung verschiedener Zustände würde einen Zyklus erzeugen und widerspricht daher der Azyklizität.', 'z_i\\preceq_F z_j\\land z_j\\preceq_F z_i\\Longrightarrow z_i=z_j', 'direct', 'adapted', 31, 'checked', 65),
(82, 'Bew. 3.4.9-R3', 63, NULL, 21, NULL, 'Beweis zu Lemma 3.4.15', 'Die Positionsindizes der Zustandsinstanzen liegen in einer endlichen Teilmenge der natürlichen Zahlen. Deren Ordnung ist reflexiv, antisymmetrisch, transitiv und total.', 'i\\leq j', 'direct', 'adapted', 31, 'checked', 65),
(83, 'Bew. 3.4.9-R4', 63, 55, NULL, NULL, 'Beweis zu Satz 3.4.15', 'Ein nichtidentischer Übergang erzeugt zwei verschiedene Zustandsinstanzen mit den Indizes null und eins. Daher besteht eine nichttriviale strikte Ordnung.', '\\zeta_F^{(0)}\\triangleleft_F\\zeta_F^{(1)}', 'direct', 'original', NULL, 'checked', 65),
(84, 'Bew. 3.4.9-R5', 63, NULL, 22, NULL, 'Beweis zu Lemma 3.4.16', 'Die Additivität folgt aus der elementaren Zerlegung k-i=(j-i)+(k-j).', 'k-i=(j-i)+(k-j)', 'direct', 'original', NULL, 'checked', 65),
(85, 'Bew. 3.4.9-R6', 63, 56, NULL, NULL, 'Beweis zu Satz 3.4.16', 'Die Abbildung jeder Zustandsinstanz auf ihren Positionsindex ist bijektiv und erhält die Ordnung in beide Richtungen.', '\\varphi_F(\\zeta_F^{(k)})=k', 'direct', 'adapted', 31, 'checked', 65),
(86, 'Bew. 3.4.9-R7', 63, NULL, NULL, 16, 'Begründung zu Korollar 3.4.12', 'Fehlt jede registrierte nichtidentische Zustandsänderung, kann aus der internen Organisation keine unterscheidbare Reihenfolge verschiedener Zustandsrealisierungen gewonnen werden.', 'z_F^{(k+1)}=z_F^{(k)}', 'direct', 'original', NULL, 'checked', 65),
(87, 'Bew. 3.4.9-R8', 63, NULL, NULL, 17, 'Begründung zu Korollar 3.4.13', 'Die Summe der Übergangsgewichte kann an jeder Zwischeninstanz in zwei Teilsummen zerlegt werden.', '\\sum_{k=i}^{l-1}w_k=\\sum_{k=i}^{j-1}w_k+\\sum_{k=j}^{l-1}w_k', 'direct', 'original', NULL, 'checked', 65),
(88, 'Bew. 3.4.9-R9', 63, 57, NULL, NULL, 'Beweis zu Satz 3.4.17', 'Ein Hinpfad belegt die gerichtete Entwicklung zum Folgezustand. Das Fehlen jedes Rückpfades schließt die Wiederherstellung des Ausgangszustands innerhalb der zulässigen Operatorstruktur aus.', 'z_i\\prec_F^{*}z_j\\land z_j\\not\\leadsto_F z_i', 'direct', 'original', NULL, 'checked', 65),
(89, 'Bew. 3.4.10-R1', 64, NULL, 23, NULL, 'Beweis zu Lemma 3.4.17', 'Die Indexbedingungen j=i+1 und i=j+1 können nicht zugleich gelten; außerdem folgt aus einem Hinoperator kein Rückoperator.', 'j=i+1\\nRightarrow i=j+1', 'direct', 'original', NULL, 'checked', 66),
(90, 'Bew. 3.4.10-R2', 64, 58, NULL, NULL, 'Beweis zu Satz 3.4.18', 'Ein nichtidentischer Übergang erzeugt zwei unterscheidbare Ereignisse und eine gerichtete Nachbarschaft zwischen ihnen.', '\\varepsilon_F^{(0)}\\blacktriangleright_F\\varepsilon_F^{(1)}', 'direct', 'original', NULL, 'checked', 66),
(91, 'Bew. 3.4.10-R3', 64, NULL, NULL, 18, 'Begründung zu Korollar 3.4.14', 'Dieselbe Operatorwirkung erzeugt sowohl die Zustandsverbindung als auch deren gerichtete Instanzfolge.', 'O_F:z_i\\mapsto z_j', 'direct', 'original', NULL, 'checked', 66),
(92, 'Bew. 3.4.10-R4', 64, NULL, 24, NULL, 'Beweis zu Lemma 3.4.18', 'Zwei Pfade über ein Zwischenereignis können verkettet werden; die Länge der Verkettung ist die Summe der Teillängen.', 'L(\\Gamma_{ik})\\leq L(\\Gamma_{ij})+L(\\Gamma_{jk})', 'direct', 'adapted', 47, 'checked', 66),
(93, 'Bew. 3.4.10-R5', 64, 59, NULL, NULL, 'Beweis zu Satz 3.4.19', 'Nichtnegativität, Definitheit und Dreiecksungleichung gelten; Symmetrie wird wegen der gerichteten Übergangsstruktur nicht verlangt.', 'd(x,y)\\neq d(y,x)', 'direct', 'adapted', 47, 'checked', 66),
(94, 'Bew. 3.4.10-R6', 64, NULL, NULL, 19, 'Begründung zu Korollar 3.4.15', 'Jeder deterministische lokale Operator erzeugt höchstens einen unmittelbaren Nachfolger.', '|\\operatorname{Succ}_F|\\leq|\\mathcal O_F^K|', 'other', 'original', NULL, 'checked', 66),
(95, 'Bew. 3.4.10-R7', 64, NULL, 25, NULL, 'Begründung zu Lemma 3.4.19', 'Partielle Ordnungen können mehrere Antiketten enthalten, denen dasselbe Ereignis angehört.', '\\Sigma_F^{(1)}\\neq\\Sigma_F^{(2)}', 'other', 'adapted', 31, 'checked', 66),
(96, 'Bew. 3.4.10-R8', 64, 60, NULL, NULL, 'Beweis zu Satz 3.4.20', 'Durch vollständige Induktion folgt aus einem kohärenten Ausgangszustand und kohärenzerhaltenden Operatoren die Kohärenz jedes Folgezustands.', 'z_k\\in\\Omega_F^K\\Longrightarrow z_{k+1}\\in\\Omega_F^K', 'induction', 'original', NULL, 'checked', 66),
(97, 'Bew. 3.4.10-R9', 64, NULL, NULL, 20, 'Begründung zu Korollar 3.4.16', 'Die Menge aller ausschließlich kohärenzerhaltend erreichbaren Ereignisse ist unter den zugelassenen Übergängen kohärent abgeschlossen.', '\\mathcal C_{RZ,F}^{K}(\\varepsilon_0)', 'direct', 'original', NULL, 'checked', 66),
(98, 'Bew. 3.4.10-R10', 64, 61, NULL, NULL, 'Beweis zu Satz 3.4.21', 'Ein Isomorphismus erhält die definierenden Relationen und Gewichte; alle ausschließlich daraus bestimmten Struktureigenschaften bleiben daher invariant.', '\\Phi_F:\\mathfrak{RZ}_F\\cong\\mathfrak{RZ}_F\'', 'equivalence', 'adapted', 31, 'checked', 66);
INSERT INTO `propositions` (`proposition_id`, `proposition_number`, `section_id`, `title`, `statement_text`, `statement_latex`, `word_latex`, `logical_derivation`, `based_on_axioms`, `status`, `created_revision_id`) VALUES
(1, '3.3.1', 30, 'Notwendigkeit funktionaler Differenz', 'Eine funktionale Organisation, die ausschließlich aus in allen Kontexten wirkungsgleichen Gehalten besteht, kann innerhalb des FRZK keine intern bestimmbare Differenzstruktur hervorbringen.', '\\bigl[\\forall f_i,f_j\\in\\mathcal{F}\\;\\forall c\\in\\mathcal{C}:\\omega_F(f_i,c)=\\omega_F(f_j,c)\\bigr]\\Rightarrow\\bigl[\\forall f_i,f_j\\in\\mathcal{F}:\\delta_F(f_i,f_j)=0\\bigr]', '\\bigl[\\forall f_i,f_j\\in\\mathcal{F}\\;\\forall c\\in\\mathcal{C}:\\omega_F(f_i,c)=\\omega_F(f_j,c)\\bigr]\\Rightarrow\\bigl[\\forall f_i,f_j\\in\\mathcal{F}:\\delta_F(f_i,f_j)=0\\bigr]', 'Aus der Definition der funktionalen Unterscheidungsfunktion folgt unmittelbar: Sind alle Wirksamkeiten in allen Kontexten gleich, existiert kein Kontext, in dem eine funktionale Differenz festgestellt werden kann. Dies widerspricht Axiom A1, sofern vollständige Unterschiedslosigkeit als alleinige Struktur angenommen wird.', 'A1', 'accepted', 28),
(2, '3.3.2', 31, 'Relationen erzeugen funktionale Struktur', 'Sei G_F das geordnete Paar aus funktionalem Trägerbereich F und funktionaler Relationsmenge R_F. Dann bildet jedes nichtleere relationale Paar eine funktionale Organisationsstruktur, die als funktionaler Organisationsgraph dargestellt werden kann.', '\\mathcal{G}_F=(\\mathcal{F},\\mathcal{R}_F),\\quad\\mathcal{R}_F\\neq\\varnothing\\;\\Longrightarrow\\;\\mathcal{G}_F\\text{ ist ein funktionaler Organisationsgraph}', '\\mathcal{G}_F=(\\mathcal{F},\\mathcal{R}_F),\\quad\\mathcal{R}_F\\neq\\varnothing\\;\\Longrightarrow\\;\\mathcal{G}_F\\text{ ist ein funktionaler Organisationsgraph}', 'Nach Gleichung (3.374) besteht R_F aus geordneten Paaren funktionaler Gehalte. Werden die Gehalte als Knoten und die Relationen als gerichtete Kanten repräsentiert, entsteht unmittelbar eine Graphstruktur. Die Proposition behauptet noch keine Dynamik, Stabilität oder Selbstorganisation.', 'A1,A2', 'accepted', 29),
(3, '3.3.3', 32, 'Transformation erzeugt funktionale Zustandsfolgen', 'Sei f_0 ein funktionaler Ausgangsgehalt und seien O_F,1 bis O_F,n miteinander kompatible funktionale Operationen. Dann entsteht durch ihre sukzessive Anwendung eine geordnete funktionale Zustandsfolge.', 'f_0\\xrightarrow{O_{F,1}}f_1\\xrightarrow{O_{F,2}}\\cdots\\xrightarrow{O_{F,n}}f_n', 'f_0\\xrightarrow{O_{F,1}}f_1\\xrightarrow{O_{F,2}}\\cdots\\xrightarrow{O_{F,n}}f_n', 'Die Proposition folgt durch wiederholte Anwendung von Axiom A3. Liegt jedes Ergebnis im Definitionsbereich der nachfolgenden Operation, kann die Folge schrittweise konstruiert werden. Die Ordnung ist zunächst funktional und setzt keine äußere Zeitvariable voraus.', 'A1,A2,A3', 'accepted', 30),
(4, '3.3.4', 33, 'Kompatibilität erzeugt rekonstruierbare Organisationspfade', 'Sei S_0 bis S_n eine Folge funktionaler Organisationen. Sind alle beteiligten Operationen kompatibel, existiert für jede Organisation eine rekonstruierbare funktionale Verbindung zur Ausgangsorganisation.', '\\mathcal{S}_{i+1}=O_{F,i}(\\mathcal{S}_i)\\land K_F(O_{F,i})=1\\;\\forall i\\;\\Longrightarrow\\;\\mathcal{S}_n\\text{ bleibt funktional auf }\\mathcal{S}_0\\text{ rekonstruierbar}', '\\mathcal{S}_{i+1}=O_{F,i}(\\mathcal{S}_i)\\land K_F(O_{F,i})=1\\;\\forall i\\;\\Longrightarrow\\;\\mathcal{S}_n\\text{ bleibt funktional auf }\\mathcal{S}_0\\text{ rekonstruierbar}', 'Nach Axiom A4 lässt jede kompatible Operation eine funktionale Rekonstruktionsbeziehung zu. Diese Eigenschaft kann entlang der Transformationsfolge fortgesetzt werden.', 'A1,A2,A3,A4', 'accepted', 31),
(10, '3.3.5', 39, 'Kohärenz begrenzt den funktionalen Zerfall', 'Sei S_0 bis S_n eine Folge funktionaler Organisationen mit S_i+1 gleich O_F,i von S_i. Gilt für alle Folgezustände C_F von S_i größer oder gleich C_krit, so bleibt die funktionale Organisation entlang des betrachteten Transformationspfades hinreichend zusammenhängend und rekonstruierbar.', '\\mathcal{S}_{i+1}=O_{F,i}(\\mathcal{S}_i)\\land C_F(\\mathcal{S}_i)\\geq C_{\\mathrm{krit}}\\;\\forall i\\Longrightarrow\\mathcal{S}_n\\text{ bleibt hinreichend kohärent und rekonstruierbar}', '\\mathcal{S}_{i+1}=O_{F,i}(\\mathcal{S}_i)\\land C_F(\\mathcal{S}_i)\\geq C_{\\mathrm{krit}}\\;\\forall i\\Longrightarrow\\mathcal{S}_n\\text{ bleibt hinreichend kohärent und rekonstruierbar}', 'Axiom A4 sichert die grundsätzliche Rekonstruierbarkeit kompatibler Transformationspfade. Axiom A5 fordert zusätzlich, dass der funktionale Zusammenhang jedes Zustands oberhalb des kritischen Mindestwertes bleibt. Solange beide Bedingungen erfüllt sind, wird der funktionale Zerfall begrenzt.', 'A1,A2,A3,A4,A5', 'accepted', 37),
(11, '3.3.6', 40, 'Zustandsbildung konkretisiert funktionale Organisation', 'Sei S eine hinreichend kohärente funktionale Organisation. Dann existiert mindestens ein funktional tragfähiger Zustand z_F in Omega_F plus von S.', 'C_F(mathcal{S})geq C_{mathrm{krit}}Longrightarrowexists z_FinOmega_F^{+}(mathcal{S})', 'C_F(mathcal{S})geq C_{mathrm{krit}}Longrightarrowexists z_FinOmega_F^{+}(mathcal{S})', 'Aus Axiom A5 folgt die hinreichende Kohärenz der Organisation. Axiom A6 fordert für eine solche Organisation die Ausbildung mindestens eines konkreten Zustands. Die Tragfähigkeitsbedingung grenzt die kohärent fortsetzbaren Zustände ein.', 'A5,A6', 'accepted', 38),
(12, '3.3.7', 41, 'Funktionale Dynamik entsteht aus zulässigen Zustandsübergängen', 'Sei Pi_F ein funktionaler Übergangspfad. Sind sämtliche Teilschritte zulässig und bleiben alle Zustände oberhalb der kritischen Kohärenzschwelle, so bildet der Übergangspfad eine tragfähige funktionale Dynamik.', 'Pi_F=left(z_F^{(0)},z_F^{(1)},dots,z_F^{(n)}\right),quad Lambda_Fleft(z_F^{(i)},z_F^{(i+1)}\right)=1,quad C_Fleft(z_F^{(i)}\right)geq C_{mathrm{krit}}', 'Pi_F=left(z_F^{(0)},z_F^{(1)},dots,z_F^{(n)}\right),quad Lambda_Fleft(z_F^{(i)},z_F^{(i+1)}\right)=1,quad C_Fleft(z_F^{(i)}\right)geq C_{mathrm{krit}}', 'Axiom A6 sichert die Existenz konkreter funktionaler Zustände. Axiom A7 bestimmt die Bedingungen ihrer operationsvermittelten Übergänge. Axiom A5 fordert den hinreichenden funktionalen Zusammenhang. Sind alle Einzelübergänge zulässig und bleiben sämtliche Zustände oberhalb der kritischen Kohärenzschwelle, ist der gesamte Übergangspfad funktional tragfähig.', 'A5,A6,A7', 'accepted', 39),
(13, '3.3.10', 45, 'Relative Konsistenz des FRZK-Axiomensystems', 'Das Axiomensystem des FRZK ist relativ konsistent, sofern ein Modell existiert, das sämtliche Axiome A1 bis A7 erfüllt.', 'existsmathcal{M}_F:mathcal{M}_Fmodelsmathcal{A}_FRightarrowoperatorname{Con}left(mathcal{A}_F\right)', 'existsmathcal{M}_F:mathcal{M}_Fmodelsmathcal{A}_FRightarrowoperatorname{Con}left(mathcal{A}_F\right)', 'Das konstruierte Minimalmodell erfüllt die Bedingungen der Axiome A1 bis A7. Die Konsistenz ist relativ zu den vorausgesetzten mathematischen und logischen Grundlagen.', 'A1,A2,A3,A4,A5,A6,A7', 'accepted', 43),
(14, '3.3.11', 46, 'Hierarchische Geschlossenheit des formalen Systems', 'Das formale System des FRZK ist hierarchisch geschlossen, wenn jede Definition auf bereits eingeführten Symbolen beruht und jede Proposition ausschließlich aus Axiomen, zulässigen Definitionen und logisch vorhergehenden Propositionen abgeleitet wird.', 'forall D_jinmathcal{D}!ef_F:operatorname{zul}left(D_j\right)quadlandquadforall P_minmathcal{P}_F:operatorname{Begr}left(P_m\right)', 'forall D_jinmathcal{D}!ef_F:operatorname{zul}left(D_j\right)quadlandquadforall P_minmathcal{P}_F:operatorname{Begr}left(P_m\right)', 'Die zulässigen Definitionen und formal begründeten Propositionen bilden einen gerichteten Abhängigkeitsgraphen. Ist dieser Graph azyklisch, kann jedem Element ein Rang zugewiesen werden. Dadurch liegt jede abgeleitete Aussage logisch oberhalb ihrer Voraussetzungen und das System ist hierarchisch geordnet.', 'A1,A2,A3,A4,A5,A6,A7', 'accepted', 44),
(15, '3.3.12', 47, 'Zielbezogene Vollständigkeit des FRZK', 'Das FRZK ist für die mathematische Rekonstruktion funktionaler Organisationen zielbezogen vollständig, wenn sämtliche in der Aufgabenmenge festgelegten Rekonstruktionsaufgaben durch endliche Teilmengen des formalen Systems bearbeitet werden können.', 'forall q_iinmathcal{Q}_F:existsGamma_isubseteq_{mathrm{fin}}mathfrak{L}_F:Gamma_ivdash q_i', 'forall q_iinmathcal{Q}_F:existsGamma_isubseteq_{mathrm{fin}}mathfrak{L}_F:Gamma_ivdash q_i', 'Die Vollständigkeit wird nicht als universelle formallogische Entscheidbarkeit, sondern relativ zur Menge der in Kapitel 3.4 erforderlichen Rekonstruktionsaufgaben bestimmt. Für jede Aufgabe muss eine endliche Menge zulässiger Axiome, Definitionen und Propositionen existieren, aus der die jeweilige Rekonstruktionsleistung ableitbar ist.', 'A1,A2,A3,A4,A5,A6,A7', 'accepted', 45),
(16, '3.3.13', 48, 'Metatheoretische Anschlussfähigkeit', 'Erfüllt das FRZK die Bedingungen relativer Unabhängigkeit, relativer Konsistenz, hierarchischer Ordnung und zielbezogener Vollständigkeit, dann ist das Axiomensystem hinreichend bestimmt, um als formale Grundlage der mathematischen Rekonstruktion zu dienen.', 'B_{mathrm{unabh}}land B_{mathrm{kons}}land B_{mathrm{hier}}land B_{mathrm{ziel}}Rightarrowoperatorname{Freig}_{3.4}', 'B_{mathrm{unabh}}land B_{mathrm{kons}}land B_{mathrm{hier}}land B_{mathrm{ziel}}Rightarrowoperatorname{Freig}_{3.4}', 'Die Proposition führt die zuvor einzeln bestimmten metatheoretischen Bedingungen in einer gemeinsamen Freigabebedingung zusammen. Aus der Freigabe folgt die endliche Ableitbarkeit jeder für Kapitel 3.4 zugelassenen Rekonstruktion aus dem formalen System.', 'A1,A2,A3,A4,A5,A6,A7', 'accepted', 46),
(17, '3.3.14', 49, 'Rekonstruktive Anschlussbedingung', 'Jede mathematische Struktur des FRZK ist nur dann als zulässige Rekonstruktion anzuerkennen, wenn sie aus einer endlichen Teilmenge des axiomatischen und definitorischen Systems ableitbar, eindeutig bestimmt und mit den bereits eingeführten Strukturen vereinbar ist.', 'S_iinmathfrak{S}_FLeftrightarrowexistsGamma_isubseteq_{mathrm{fin}}mathfrak{L}_F:Gamma_ivdash S_ilandoperatorname{DefEin}left(S_i\right)landoperatorname{Kompat}left(S_i,mathfrak{L}_F\right)', 'S_iinmathfrak{S}_FLeftrightarrowexistsGamma_isubseteq_{mathrm{fin}}mathfrak{L}_F:Gamma_ivdash S_ilandoperatorname{DefEin}left(S_i\right)landoperatorname{Kompat}left(S_i,mathfrak{L}_F\right)', 'Die Proposition verbindet die metatheoretische Freigabe aus Proposition 3.3.13 mit den konkreten Zulässigkeitsbedingungen für die mathematischen Konstruktionen des folgenden Kapitels.', 'A1,A2,A3,A4,A5,A6,A7', 'accepted', 47);
