(394, '\\mathcal{S}', '\\mathcal{S}', 'Simulationsstudienmenge', 'Gesamtheit der Simulationsstudien.', 'section', 122, 1551, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(395, '\\mathcal{E}', '\\mathcal{E}', 'Empirische Vergleichsbasis', 'Menge empirischer Vergleichsdaten.', 'section', 122, 1551, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(396, '\\Omega_{\\mathrm{valid}}', '\\Omega_{\\mathrm{valid}}', 'Modellgültigkeitsbereich', 'Bereich gültiger Modellanwendung.', 'section', 122, 1552, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(397, '\\mathcal{P}_{\\mathrm{valid}}', '\\mathcal{P}_{\\mathrm{valid}}', 'Gültiger Parameterbereich', 'Interpretierbarer Teil des Parameterraums.', 'section', 122, 1554, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(398, '\\Phi', '\\Phi', 'Empirische Anschlussabbildung', 'Abbildung zwischen Simulation und Beobachtung.', 'section', 122, 1556, NULL, NULL, NULL, 0, 0, 1, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(399, '\\partial\\Omega_{\\mathrm{valid}}', '\\partial\\Omega_{\\mathrm{valid}}', 'Modellgrenze', 'Rand des gültigen Modellbereichs.', 'section', 122, 1558, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(400, '\\mathcal{G}_{\\mathrm{interpret}}', '\\mathcal{G}_{\\mathrm{interpret}}', 'Interpretierbare Trajektorienmenge', 'Menge gültig interpretierbarer Trajektorien.', 'section', 122, 1561, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(401, '\\mathcal{F}_{\\mathrm{res}}', '\\mathcal{F}_{\\mathrm{res}}', 'Strukturelle Restmenge', 'Nicht im Modell abgebildete Merkmale.', 'section', 122, 1563, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(402, 'I_{\\mathrm{formal}}', 'I_{\\mathrm{formal}}', 'Formaler Konsistenzindex', 'Kennzeichnung der formalen Konsistenz.', 'section', 122, 1564, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(403, '\\widehat{\\Gamma}', '\\widehat{\\Gamma}', 'Numerische Trajektorie', 'Numerische Approximation der Modelltrajektorie.', 'section', 122, 1565, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(404, '\\varepsilon_{\\mathrm{num}}', '\\varepsilon_{\\mathrm{num}}', 'Numerischer Fehler', 'Zusammengefasster numerischer Fehler.', 'section', 122, 1565, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(405, '\\mathcal{P}_{\\mathrm{eq}}', '\\mathcal{P}_{\\mathrm{eq}}', 'Äquivalente Parametermenge', 'Menge äquifinaler Parametrisierungen.', 'section', 122, 1569, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(406, '\\mathcal{C}_{\\mathrm{model}}', '\\mathcal{C}_{\\mathrm{model}}', 'Modellinterne Kausalstruktur', 'Kausalstruktur innerhalb des Modells.', 'section', 122, 1572, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(407, '\\mathcal{C}_{\\mathrm{emp}}', '\\mathcal{C}_{\\mathrm{emp}}', 'Empirische Kausalstruktur', 'Empirisch bestätigter Kausalzusammenhang.', 'section', 122, 1572, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(408, 'T_{\\lambda_a\\rightarrow\\lambda_b}', 'T_{\\lambda_a\\rightarrow\\lambda_b}', 'Skalentransformation', 'Übertragung zwischen Modellskalen.', 'section', 122, 1575, NULL, NULL, NULL, 0, 0, 1, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(409, 'U_{\\mathrm{total}}', 'U_{\\mathrm{total}}', 'Gesamtunsicherheit', 'Zusammengefasste Unsicherheit.', 'section', 122, 1577, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(410, 'I_{\\mathrm{confidence}}', 'I_{\\mathrm{confidence}}', 'Vertrauensindex', 'Normiertes Maß wissenschaftlicher Absicherung.', 'section', 122, 1578, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(411, 'Z_{\\mathrm{valid}}', 'Z_{\\mathrm{valid}}', 'Gültigkeitsstatusvektor', 'Zusammengefasster Gültigkeitsstatus.', 'section', 122, 1580, NULL, NULL, NULL, 1, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117),
(412, 'z_{\\mathrm{interpret}}', 'z_{\\mathrm{interpret}}', 'Interpretationsstatus', 'Binärer Status wissenschaftlicher Interpretierbarkeit.', 'section', 122, 1582, NULL, NULL, NULL, 0, 0, 0, 'Abschnittssymbol 3.8.12.', 'draft', 117);
INSERT INTO `theorems` (`theorem_id`, `theorem_number`, `section_id`, `title`, `statement_text`, `statement_latex`, `word_latex`, `provenance`, `source_id`, `assumptions`, `validation_status`, `created_revision_id`) VALUES
(1, '3.2.1', 13, 'Cantors Satz', 'Für keine Menge M existiert eine surjektive Abbildung von M auf ihre Potenzmenge P(M). Folglich besitzt P(M) eine strikt größere Mächtigkeit als M.', '\nexists f:M	omathcal{P}(M)	ext{ surjektiv};qquad |M|<|mathcal{P}(M)|', '\nexists f:M	omathcal{P}(M)	ext{ surjektiv};qquad |M|<|mathcal{P}(M)|', 'literature', 66, 'Es gelten die üblichen Begriffe von Abbildung, Surjektivität, Teilmenge und Mächtigkeit.', 'checked', 10),
(2, '3.2.2', 14, 'Äquivalenzrelationen und Partitionen', 'Jede Äquivalenzrelation auf einer Menge M erzeugt eine Partition von M. Umgekehrt bestimmt jede Partition von M eine Äquivalenzrelation.', 'sim;longleftrightarrow;mathcal{C}', 'sim;longleftrightarrow;mathcal{C}', 'adapted', 71, 'Die Begriffe Äquivalenzrelation, Äquivalenzklasse und Partition sind definiert.', 'checked', 11),
(3, '3.2.3', 14, 'Assoziativität der relationalen Komposition', 'Für Relationen R⊆A×B, S⊆B×C und T⊆C×D gilt T∘(S∘R)=(T∘S)∘R.', 'Tcirc(Scirc R)=(Tcirc S)circ R', 'Tcirc(Scirc R)=(Tcirc S)circ R', 'literature', 75, 'Die beteiligten Relationen besitzen kompatible Definitions- und Zielmengen.', 'checked', 11),
(4, '3.2.4', 16, 'Handschlaglemma', 'Für jeden endlichen ungerichteten Graphen ist die Summe aller Knotengrade gleich dem Doppelten der Kantenzahl.', '\\sum_{v\\in V}\\deg(v)=2|E|', '\\sum_{v\\in V}\\deg(v)=2|E|', 'literature', 80, 'G ist endlich und ungerichtet.', 'checked', 13),
(5, '3.2.5', 16, 'Eindeutigkeit der Pfade in einem Baum', 'In einem Baum existiert zwischen je zwei verschiedenen Knoten genau ein Pfad.', '\\forall u,v\\in V,\\;u\\neq v:\\;\\exists!\\,P_{uv}', '\\forall u,v\\in V,\\;u\\neq v:\\;\\exists!\\,P_{uv}', 'literature', 80, 'T=(V,E) ist ein Baum.', 'checked', 13),
(6, '3.2.6', 17, 'Existenz der Umkehrfunktion', 'Eine Funktion besitzt genau dann eine Umkehrfunktion, wenn sie bijektiv ist.', 'f^{-1}	ext{ existiert}Longleftrightarrow f	ext{ ist bijektiv}', 'f^{-1}	ext{ existiert}Longleftrightarrow f	ext{ ist bijektiv}', 'literature', 71, 'f:A→B ist eine Funktion.', 'checked', 14),
(7, '3.2.7', 17, 'Assoziativität der Funktionskomposition', 'Für kompatibel definierte Funktionen f, g und h gilt h∘(g∘f)=(h∘g)∘f.', 'hcirc(gcirc f)=(hcirc g)circ f', 'hcirc(gcirc f)=(hcirc g)circ f', 'literature', 71, 'f:A→B, g:B→C und h:C→D sind Funktionen.', 'checked', 14),
(12, '3.2.8', 18, 'Eindeutigkeit des Nullvektors', 'In jedem Vektorraum existiert genau ein additives neutrales Element.', 'exists!,0in V;forall vin V:v+0=v', 'exists!,0in V;forall vin V:v+0=v', 'literature', 93, 'V ist ein Vektorraum.', 'checked', 17),
(13, '3.2.9', 18, 'Eindeutigkeit des inversen Vektors', 'Zu jedem Vektor eines Vektorraums existiert genau ein additives Inverses.', 'forall vin V;exists!,(-v)in V:v+(-v)=0', 'forall vin V;exists!,(-v)in V:v+(-v)=0', 'literature', 93, 'V ist ein Vektorraum.', 'checked', 17),
(14, '3.2.10', 19, 'Erhaltung des Nullvektors', 'Jede lineare Abbildung bildet den Nullvektor des Ausgangsraums auf den Nullvektor des Zielraums ab.', 'T(0_V)=0_W', 'T(0_V)=0_W', 'literature', 96, 'T:V→W ist linear.', 'checked', 18),
(15, '3.2.11', 19, 'Kern und Bild als Untervektorräume', 'Der Kern einer linearen Abbildung ist ein Untervektorraum des Ausgangsraums, und ihr Bild ist ein Untervektorraum des Zielraums.', 'ker(T)leq V,quadoperatorname{im}(T)leq W', 'ker(T)leq V,quadoperatorname{im}(T)leq W', 'literature', 96, 'T:V→W ist linear.', 'checked', 18),
(16, '3.2.12', 19, 'Dimensionssatz', 'Für eine lineare Abbildung mit endlichdimensionalem Ausgangsraum ist dessen Dimension gleich der Summe aus Rang und Nullität.', 'dim(V)=operatorname{rang}(T)+operatorname{null}(T)', 'dim(V)=operatorname{rang}(T)+operatorname{null}(T)', 'literature', 96, 'V ist endlichdimensional und T:V→W linear.', 'checked', 18),
(17, '3.2.13', 19, 'Charakterisierung der Invertierbarkeit', 'Für einen linearen Operator auf einem endlichdimensionalen Vektorraum sind Invertierbarkeit, trivialer Kern, Surjektivität und voller Rang äquivalent.', 'T	ext{ invertierbar}Longleftrightarrowker(T)={0}Longleftrightarrowoperatorname{im}(T)=VLongleftrightarrowoperatorname{rang}(T)=dim(V)', 'T	ext{ invertierbar}Longleftrightarrowker(T)={0}Longleftrightarrowoperatorname{im}(T)=VLongleftrightarrowoperatorname{rang}(T)=dim(V)', 'literature', 96, 'T:V→V ist linear und V endlichdimensional.', 'checked', 18),
(18, '3.2.14', 20, 'Cauchy-Schwarz-Ungleichung', 'Für alle Vektoren u und v eines reellen Skalarproduktraums ist der Betrag ihres Skalarprodukts höchstens gleich dem Produkt ihrer Normen.', '|langle u,v\rangle|leq|u||v|', '|langle u,v\rangle|leq|u||v|', 'literature', 98, 'V ist ein reeller Skalarproduktraum.', 'checked', 19),
(19, '3.2.15', 20, 'Dreiecksungleichung der induzierten Norm', 'Für alle Vektoren u und v eines Skalarproduktraums ist die Norm ihrer Summe höchstens gleich der Summe ihrer Normen.', '|u+v|leq|u|+|v|', '|u+v|leq|u|+|v|', 'literature', 98, 'Die Norm wird durch ein Skalarprodukt induziert.', 'checked', 19),
(20, '3.2.16', 21, 'Charakteristische Gleichung', 'Ein Skalar λ ist genau dann Eigenwert eines endlichdimensionalen Operators T, wenn det(T-λI)=0 gilt.', 'lambdainsigma(T)Longleftrightarrowdet(T-lambda I)=0', 'lambdainsigma(T)Longleftrightarrowdet(T-lambda I)=0', 'adapted', 101, 'V ist endlichdimensional.', 'checked', 20),
(21, '3.2.17', 21, 'Lineare Unabhängigkeit von Eigenvektoren', 'Eigenvektoren zu paarweise verschiedenen Eigenwerten sind linear unabhängig.', 'lambda_i\neqlambda_jRightarrow{v_1,ldots,v_k}	ext{ linear unabhängig}', 'lambda_i\neqlambda_jRightarrow{v_1,ldots,v_k}	ext{ linear unabhängig}', 'adapted', 101, 'T(v_i)=λ_i v_i und v_i≠0.', 'checked', 20),
(22, '3.2.18', 21, 'Charakterisierung der Diagonalisierbarkeit', 'Ein Operator auf einem n-dimensionalen Vektorraum ist genau dann diagonalisierbar, wenn eine Basis aus Eigenvektoren existiert; äquivalent ist die Summe der Dimensionen der Eigenräume gleich n.', 'T	ext{ diagonalisierbar}Longleftrightarrowsum_{lambdainsigma(T)}dim(E_lambda)=dim(V)', 'T	ext{ diagonalisierbar}Longleftrightarrowsum_{lambdainsigma(T)}dim(E_lambda)=dim(V)', 'adapted', 101, 'V ist endlichdimensional und das charakteristische Polynom zerfällt über K.', 'checked', 20),
(23, '3.2.19', 21, 'Spur als Summe der Eigenwerte', 'Die Spur eines endlichdimensionalen Operators ist gleich der Summe seiner mit algebraischer Vielfachheit gezählten Eigenwerte.', 'operatorname{tr}(T)=sum_ilambda_i', 'operatorname{tr}(T)=sum_ilambda_i', 'adapted', 101, 'Das charakteristische Polynom zerfällt über K.', 'checked', 20),
(24, '3.2.20', 21, 'Determinante als Produkt der Eigenwerte', 'Die Determinante eines endlichdimensionalen Operators ist gleich dem Produkt seiner mit algebraischer Vielfachheit gezählten Eigenwerte.', 'det(T)=prod_ilambda_i', 'det(T)=prod_ilambda_i', 'adapted', 101, 'Das charakteristische Polynom zerfällt über K.', 'checked', 20),
(25, '3.2.21', 22, 'Matrixdarstellung einer Bilinearform', 'Zu jeder Bilinearform B auf einem endlichdimensionalen Vektorraum existiert bezüglich einer gewählten Basis genau eine Matrix A mit B(u,v)=u^TAv.', 'B(u,v)=u^{T}Av', 'B(u,v)=u^{T}Av', 'adapted', 102, 'V ist endlichdimensional und eine Basis ist gewählt.', 'checked', 21),
(26, '3.2.22', 22, 'Sylvesters Trägheitsgesetz', 'Unter einem regulären Basiswechsel bleiben bei einer reellen symmetrischen Bilinearform die Anzahlen positiver, negativer und verschwindender Diagonaleinträge einer Diagonalform invariant.', '\\operatorname{inertia}(A)=(n_+,n_-,n_0)', '\\operatorname{inertia}(A)=(n_+,n_-,n_0)', 'adapted', 103, 'A ist reell und symmetrisch.', 'checked', 21),
(27, '3.2.23', 22, 'Zusammenhang mit Skalarprodukten', 'Jedes reelle Skalarprodukt ist eine symmetrische positiv definite Bilinearform. Umgekehrt definiert jede symmetrische positiv definite Bilinearform ein Skalarprodukt.', '\\langle u,v\\rangle=B(u,v)\\Longleftrightarrow B\\text{ symmetrisch und positiv definit}', '\\langle u,v\\rangle=B(u,v)\\Longleftrightarrow B\\text{ symmetrisch und positiv definit}', 'adapted', 102, 'V ist ein reeller Vektorraum.', 'checked', 21),
(28, '3.2.24', 22, 'Eindeutiges Minimum positiver Energieformen', 'Ist A symmetrisch positiv definit, dann besitzt E(v)=v^TAv ihr eindeutiges globales Minimum bei v=0.', 'A\\succ0\\Rightarrow E(v)=v^{T}Av\\geq0\\land(E(v)=0\\Longleftrightarrow v=0)', 'A\\succ0\\Rightarrow E(v)=v^{T}Av\\geq0\\land(E(v)=0\\Longleftrightarrow v=0)', 'adapted', 102, 'A ist symmetrisch und positiv definit.', 'checked', 21),
(29, '3.2.25', 23, 'Projektionszerlegung', 'Für jede orthogonale Projektion P besitzt jeder Vektor v die eindeutige Zerlegung v=Pv+(I-P)v, wobei Pv im Bild von P und (I-P)v im Kern von P liegt und beide Anteile orthogonal sind.', 'v=Pv+(I-P)v', 'v=Pv+(I-P)v', 'adapted', 105, 'P ist eine orthogonale Projektion.', 'checked', 22),
(30, '3.2.26', 23, 'Orthogonale Approximation', 'Ist P die orthogonale Projektion auf einen abgeschlossenen Unterraum U, dann ist Pv die eindeutig beste Approximation von v in U.', '|v-Pv|=min_{uin U}|v-u|', '|v-Pv|=min_{uin U}|v-u|', 'adapted', 105, 'U ist abgeschlossen.', 'checked', 22),
(31, '3.2.27', 23, 'Direkte orthogonale Summe', 'Für jeden abgeschlossenen Unterraum U eines Hilbertraums V gilt V=U⊕U^⊥.', 'V=Uoplus U^perp', 'V=Uoplus U^perp', 'adapted', 105, 'V ist ein Hilbertraum und U ist abgeschlossen.', 'checked', 22),
(32, '3.2.28', 23, 'Existenz einer Orthonormalbasis', 'Jeder endlichdimensionale Skalarproduktraum besitzt eine Orthonormalbasis.', 'V=operatorname{span}{e_1,ldots,e_n},quadlangle e_i,e_j\rangle=delta_{ij}', 'V=operatorname{span}{e_1,ldots,e_n},quadlangle e_i,e_j\rangle=delta_{ij}', 'adapted', 104, 'V ist endlichdimensional.', 'checked', 22),
(33, '3.2.29', 24, 'Charakteristisches Polynom', 'Ein Skalar λ ist genau dann Eigenwert einer quadratischen Matrix A, wenn det(A-λI)=0 gilt.', 'det(A-lambda I)=0', 'det(A-lambda I)=0', 'adapted', 97, 'A ist eine quadratische Matrix über einem Körper, in dem das charakteristische Polynom zerfällt.', 'checked', 23),
(34, '3.2.30', 24, 'Spektralsatz', 'Jede reelle symmetrische Matrix A ist orthogonal diagonalisierbar und besitzt eine Darstellung A=QΛQ^T.', 'A=QLambda Q^T', 'A=QLambda Q^T', 'adapted', 106, 'A ist reell und symmetrisch.', 'checked', 23),
(35, '3.2.31', 24, 'Orthogonalität verschiedener Eigenräume', 'Eigenvektoren einer reellen symmetrischen Matrix zu verschiedenen Eigenwerten sind orthogonal.', 'lambda_i\neqlambda_jRightarrow E_iperp E_j', 'lambda_i\neqlambda_jRightarrow E_iperp E_j', 'adapted', 106, 'A ist reell und symmetrisch beziehungsweise selbstadjungiert.', 'checked', 23),
(36, '3.2.32', 24, 'Langzeitverhalten iterierter Operatoren', 'Besitzt A einen betragsmäßig eindeutig dominanten Eigenwert λ_max und hat der Anfangsvektor eine von Null verschiedene Komponente im zugehörigen Eigenraum, dann wird die Richtung von A^n v asymptotisch durch diesen Eigenraum bestimmt.', 'A^nvsim clambda_{max}^nv_{max}', 'A^nvsim clambda_{max}^nv_{max}', 'adapted', 106, 'A ist diagonalisierbar; |λ_max|>|λ_i| für alle übrigen Eigenwerte und c≠0.', 'checked', 23),
(37, '3.4.1', 52, 'Unterscheidbarkeit funktionaler Zustände', 'Für zwei zulässige funktionale Zustände gilt: Sie sind genau dann verschieden, wenn sich mindestens eine der drei Komponenten funktionaler Gehalt, funktionale Relation oder funktionale Operation unterscheidet.', 'z_F^{(i)}\neq z_F^{(j)}Longleftrightarrow(mathcal{F}_{mathcal{S}}^{(i)}\neqmathcal{F}_{mathcal{S}}^{(j)})lor(mathcal{R}_{mathcal{S}}^{(i)}\neqmathcal{R}_{mathcal{S}}^{(j)})lor(mathcal{O}_{mathcal{S}}^{(i)}\neqmathcal{O}_{mathcal{S}}^{(j)})', 'z_F^{(i)}\neq z_F^{(j)}Longleftrightarrow(mathcal{F}_{mathcal{S}}^{(i)}\neqmathcal{F}_{mathcal{S}}^{(j)})lor(mathcal{R}_{mathcal{S}}^{(i)}\neqmathcal{R}_{mathcal{S}}^{(j)})lor(mathcal{O}_{mathcal{S}}^{(i)}\neqmathcal{O}_{mathcal{S}}^{(j)})', 'original', NULL, 'Definition 3.4.2 und klassische De-Morgan-Regeln.', 'checked', 49),
(38, '3.4.2', 55, 'Partition der Zustandsmenge', 'Die Menge der durch sim_F erzeugten funktionalen Zustandsklassen bildet eine Partition der funktionalen Zustandsmenge Omega_F(S).', 'Omega_F(mathcal{S})=iguplus_{[z_F]_{sim_F}inOmega_F(mathcal{S})/{sim_F}}[z_F]_{sim_F}', 'Omega_F(mathcal{S})=iguplus_{[z_F]_{sim_F}inOmega_F(mathcal{S})/{sim_F}}[z_F]_{sim_F}', 'original', NULL, 'Lemma 3.4.2 und klassische Eigenschaften von Äquivalenzklassen.', 'checked', 52),
(39, '3.4.3', 57, 'Notwendigkeit funktionaler Relationierung', 'Eine funktionale Zustandsmenge mit mindestens zwei Elementen bildet nur dann eine nichttriviale funktionale Zustandsstruktur, wenn die funktionale Relation nicht leer ist.', '\\left|\\Omega_F(\\mathcal{S})\\right|\\geq 2\\Longrightarrow\\left(\\mathfrak{Z}_F\\text{ nichttrivial}\\Rightarrow R_F\\neq\\varnothing\\right)', '\\left|\\Omega_F(\\mathcal{S})\\right|\\geq 2\\Longrightarrow\\left(\\mathfrak{Z}_F\\text{ nichttrivial}\\Rightarrow R_F\\neq\\varnothing\\right)', 'original', NULL, 'Definitionen 3.4.5 und 3.4.6.', 'checked', 54),
(40, '3.4.4', 58, 'Kriterium der Transformierbarkeit einer funktionalen Relation', 'Eine funktionale Relation bestimmt genau dann eine funktionale Transformation, wenn jedem Ausgangszustand genau ein relationaler Zielzustand zugeordnet ist.', 'R_F\\text{ bestimmt }T_F\\Longleftrightarrow\\forall z_F\\in\\Omega_F(\\mathcal{S}):\\left|R_F^{+}(z_F)\\right|=1', 'R_F\\text{ bestimmt }T_F\\Longleftrightarrow\\forall z_F\\in\\Omega_F(\\mathcal{S}):\\left|R_F^{+}(z_F)\\right|=1', 'original', NULL, 'Definition 3.4.8 und die ausgehende Relationsmenge aus Abschnitt 3.4.3.', 'checked', 55),
(41, '3.4.5', 59, 'Kriterium der Invertierbarkeit funktionaler Operatoren', 'Ein funktionaler Operator ist genau dann invertierbar, wenn er bijektiv ist.', 'O_F\\text{ invertierbar}\\Longleftrightarrow O_F\\text{ bijektiv}', 'O_F\\text{ invertierbar}\\Longleftrightarrow O_F\\text{ bijektiv}', 'original', NULL, 'Definition 3.4.14 sowie Injektivität und Surjektivität aus Abschnitt 3.2.5.', 'checked', 56),
(42, '3.4.6', 59, 'Monoidstruktur des funktionalen Operatorraums', 'Der funktionale Operatorraum bildet mit der Komposition und der Identität ein Monoid.', '\\left(\\mathcal{O}_F(\\mathcal{S}),\\circ,\\operatorname{id}_{\\Omega_F}\\right)\\text{ ist ein Monoid}', '\\left(\\mathcal{O}_F(\\mathcal{S}),\\circ,\\operatorname{id}_{\\Omega_F}\\right)\\text{ ist ein Monoid}', 'original', NULL, 'Lemma 3.4.5, Assoziativität der Abbildungskomposition und Identitätsoperator.', 'checked', 56),
(43, '3.4.7', 60, 'Bestimmtheit eines funktionalen Entwicklungspfads', 'Ein gegebener Anfangszustand und eine vollständige endliche Operatorfolge bestimmen die zugehörige funktionale Zustandsfolge eindeutig.', 'z_F^{(0)}\\land\\mathbf{O}_F^{[n]}\\Longrightarrow\\exists!\\,\\mathbf{Z}_F^{[n]}', 'z_F^{(0)}\\land\\mathbf{O}_F^{[n]}\\Longrightarrow\\exists!\\,\\mathbf{Z}_F^{[n]}', 'original', NULL, 'Definitionen 3.4.17 bis 3.4.19 und Abbildungseigenschaft der Operatoren.', 'checked', 57),
(44, '3.4.8', 60, 'Strikte Ordnung funktionaler Zustände entlang eines Entwicklungspfads', 'Die funktionale Übergangsordnung ist innerhalb eines gegebenen Entwicklungspfads irreflexiv, asymmetrisch und transitiv und bildet daher eine strikte Ordnung der Zustandspositionen.', '\\operatorname{Irreflexivitaet}(\\prec_F)\\land\\operatorname{Asymmetrie}(\\prec_F)\\land\\operatorname{Transitivitaet}(\\prec_F)', '\\operatorname{Irreflexivitaet}(\\prec_F)\\land\\operatorname{Asymmetrie}(\\prec_F)\\land\\operatorname{Transitivitaet}(\\prec_F)', 'original', NULL, 'Definition 3.4.20 und Lemma 3.4.7.', 'checked', 57),
(45, 'Satz 3.4.5', 59, 'Assoziativität funktionaler Operatorkompositionen', 'Die Komposition funktionaler Operatoren ist assoziativ.', 'O_{F,3}\\circ(O_{F,2}\\circ O_{F,1})=(O_{F,3}\\circ O_{F,2})\\circ O_{F,1}', 'O_{F,3}\\circ(O_{F,2}\\circ O_{F,1})=(O_{F,3}\\circ O_{F,2})\\circ O_{F,1}', 'adapted', 31, 'Komposition von Selbstabbildungen.', 'checked', 61),
(46, 'Satz 3.4.6', 59, 'Monoidstruktur der funktionalen Operatormenge', 'Die funktionale Operatormenge bildet mit Komposition und Identitätsoperator ein Monoid.', '(\\mathcal O_F(\\mathcal S),\\circ,I_F)', '(\\mathcal O_F(\\mathcal S),\\circ,I_F)', 'adapted', 31, 'Abgeschlossenheit, Assoziativität und Identitätsoperator.', 'checked', 61),
(47, 'Satz 3.4.7', 60, 'Bestimmtheit eines funktionalen Entwicklungspfads', 'Sind ein funktionaler Ausgangszustand und eine vollständige endliche Operatorfolge gegeben, so ist die zugehörige funktionale Zustandsfolge eindeutig bestimmt.', 'z_F^{(0)},\\boldsymbol O_F^{(n)}\\Longrightarrow!\\boldsymbol z_F^{(n)}', 'z_F^{(0)},\\boldsymbol O_F^{(n)}\\Longrightarrow!\\boldsymbol z_F^{(n)}', 'original', NULL, 'Jeder funktionale Operator ist eine eindeutige Abbildung.', 'checked', 62),
(48, 'Satz 3.4.8', 60, 'Strikte Ordnung funktionaler Zustände entlang eines Entwicklungspfads', 'Für einen funktionalen Entwicklungspfad mit paarweise verschiedenen Zuständen bildet die strikte funktionale Übergangsrelation eine strikte lineare Ordnung.', '\\left(\\{z_F^{(0)},\\ldots,z_F^{(n)}\\},\\prec_F\\right)', '\\left(\\{z_F^{(0)},\\ldots,z_F^{(n)}\\},\\prec_F\\right)', 'adapted', 31, 'Paarweise verschiedene Zustände und Definition 3.4.20.', 'checked', 62),
(49, 'Satz 3.4.9', 61, 'Monoid kohärenzerhaltender Operatoren', 'Die kohärenzerhaltenden Operatoren bilden mit der Komposition und dem Identitätsoperator ein Untermonoid der funktionalen Operatormenge.', 'left(mathcal O_F^{K}(mathcal S),circ,I_F\right)leqleft(mathcal O_F(mathcal S),circ,I_F\right)', 'left(mathcal O_F^{K}(mathcal S),circ,I_F\right)leqleft(mathcal O_F(mathcal S),circ,I_F\right)', 'adapted', 31, 'Lemma 3.4.9, Assoziativität und Identitätsoperator.', 'checked', 63),
(50, 'Satz 3.4.10', 61, 'Zustandserhaltung entlang kohärenter Entwicklungspfade', 'In einem funktional kohärenten Entwicklungspfad sind sämtliche durchlaufenen Zustände funktional kohärent.', 'mathcal P_F^{(n)}inmathfrak P_F^{K}(mathcal S)Longrightarrowforall kin{0,ldots,n}:z_F^{(k)}inOmega_F^{K}(mathcal S)', 'mathcal P_F^{(n)}inmathfrak P_F^{K}(mathcal S)Longrightarrowforall kin{0,ldots,n}:z_F^{(k)}inOmega_F^{K}(mathcal S)', 'original', NULL, 'Definition 3.4.25 und Lemma 3.4.8.', 'checked', 63),
(51, 'Satz 3.4.11', 62, 'Präordnungsstruktur der funktionalen Erreichbarkeit', 'Die funktionale Erreichbarkeit bildet auf dem kohärenten Zustandsraum eine Präordnung.', '\\left(\\Omega_F^{K}(\\mathcal S),\\leadsto_F\\right)', '\\left(\\Omega_F^{K}(\\mathcal S),\\leadsto_F\\right)', 'original', NULL, 'Definitionen und Lemmata des Abschnitts 3.4.8.', 'checked', 64),
(52, 'Satz 3.4.12', 62, 'Existenz funktionaler Raumstrukturen', 'Ein nichtleerer kohärenter Zustandsraum mit Identitätsoperator bestimmt eine funktionale Raumstruktur.', '\\Omega_F^{K}(\\mathcal S)\\neq\\varnothing\\Longrightarrow\\mathfrak R_F^{K}(\\mathcal S)', '\\Omega_F^{K}(\\mathcal S)\\neq\\varnothing\\Longrightarrow\\mathfrak R_F^{K}(\\mathcal S)', 'original', NULL, 'Definitionen und Lemmata des Abschnitts 3.4.8.', 'checked', 64),
(53, 'Satz 3.4.13', 62, 'Quasimetrische Struktur der funktionalen Übergangsdistanz', 'Auf jeder funktionalen Zusammenhangskomponente bildet die minimale gerichtete Pfadlänge im Allgemeinen eine Quasimetrik.', '\\delta_F\\text{ ist eine Quasimetrik}', '\\delta_F\\text{ ist eine Quasimetrik}', 'adapted', 47, 'Definitionen und Lemmata des Abschnitts 3.4.8.', 'checked', 64),
(54, 'Satz 3.4.14', 63, 'Partielle Ordnung in azyklischen Bereichen', 'Auf einem azyklischen funktionalen Bereich bildet die reflexive funktionale Vorordnung eine partielle Ordnung.', '(\\Omega_F^{A}(\\mathcal S),\\preceq_F)', '(\\Omega_F^{A}(\\mathcal S),\\preceq_F)', 'adapted', 31, 'Definition 3.4.40 und Lemma 3.4.14.', 'checked', 65),
(55, 'Satz 3.4.15', 63, 'Existenz funktionaler Zeit aus nichtidentischer Veränderung', 'Jeder nichtidentische kohärenzerhaltende Übergang erzeugt mindestens zwei geordnete Zustandsinstanzen und damit eine nichttriviale funktionale Zeitstruktur.', 'z_F^{(0)}\\prec_F z_F^{(1)}\\Longrightarrow\\mathfrak T_F\\text{ nichttrivial}', 'z_F^{(0)}\\prec_F z_F^{(1)}\\Longrightarrow\\mathfrak T_F\\text{ nichttrivial}', 'original', NULL, 'Definitionen 3.4.41 bis 3.4.43.', 'checked', 65),
(56, 'Satz 3.4.16', 63, 'Isomorphie endlicher Pfadzeiten mit diskreten Ordnungen', 'Die Zustandsinstanzen eines Pfades mit n Übergängen sind ordnungsisomorph zur natürlichen Ordnung von 0 bis n.', '(\\mathcal Z_F(\\mathcal P_F^{(n)}),\\unlhd_F)\\cong(\\{0,\\ldots,n\\},\\leq)', '(\\mathcal Z_F(\\mathcal P_F^{(n)}),\\unlhd_F)\\cong(\\{0,\\ldots,n\\},\\leq)', 'adapted', 31, 'Definitionen 3.4.41 bis 3.4.44.', 'checked', 65),
(57, 'Satz 3.4.17', 63, 'Irreversibilität als fehlende Rückerreichbarkeit', 'Ein funktionaler Übergang ist irreversibel, wenn ein gerichteter Hinpfad, aber kein kohärenzerhaltender Rückpfad existiert.', 'z_F^{(i)}\\prec_F^{*}z_F^{(j)}\\land z_F^{(j)}\\not\\leadsto_F z_F^{(i)}', 'z_F^{(i)}\\prec_F^{*}z_F^{(j)}\\land z_F^{(j)}\\not\\leadsto_F z_F^{(i)}', 'original', NULL, 'Funktionale Vorordnung und Erreichbarkeit.', 'checked', 65),
(58, 'Satz 3.4.18', 64, 'Existenz einer funktionalen Raum-Zeit-Struktur', 'Ein kohärenter Zustandsraum mit mindestens einem nichtidentischen kohärenzerhaltenden Übergang besitzt mindestens eine nichttriviale funktionale Raum-Zeit-Struktur.', 'z_F^{(0)}\\prec_F z_F^{(1)}\\Longrightarrow\\exists\\mathfrak{RZ}_F', 'z_F^{(0)}\\prec_F z_F^{(1)}\\Longrightarrow\\exists\\mathfrak{RZ}_F', 'original', NULL, 'Definitionen 3.4.50 bis 3.4.54.', 'checked', 66),
(59, 'Satz 3.4.19', 64, 'Quasimetrische Struktur', 'Bei positiven Übergangsgewichten bildet der gerichtete Raum-Zeit-Abstand auf stark zusammenhängenden Ereigniskomponenten eine Quasimetrik.', '(\\mathcal E_F,d_{RZ,F})', '(\\mathcal E_F,d_{RZ,F})', 'adapted', 47, 'Definition 3.4.55 und Lemma 3.4.18.', 'checked', 66),
(60, 'Satz 3.4.20', 64, 'Kohärenzerhaltung entlang funktionaler Raum-Zeit-Pfade', 'Sind alle Operatoren eines Raum-Zeit-Pfades kohärenzerhaltend und ist der Ausgangszustand kohärent, dann bleiben sämtliche Pfadzustände kohärent.', 'z_F^{(0)}\\in\\Omega_F^K\\land O_{F,k}\\in\\mathcal O_F^K\\Longrightarrow z_F^{(k)}\\in\\Omega_F^K', 'z_F^{(0)}\\in\\Omega_F^K\\land O_{F,k}\\in\\mathcal O_F^K\\Longrightarrow z_F^{(k)}\\in\\Omega_F^K', 'original', NULL, 'Definition 3.4.59.', 'checked', 66),
(61, 'Satz 3.4.21', 64, 'Invarianz funktionaler Raum-Zeit-Eigenschaften', 'Unter einem funktionalen Raum-Zeit-Isomorphismus bleiben Erreichbarkeit, Vorordnung, Zyklizität, Azyklizität, Pfadlänge und Kohärenzzusammenhang erhalten.', '\\mathfrak{RZ}_F\\cong\\mathfrak{RZ}_F\'', '\\mathfrak{RZ}_F\\cong\\mathfrak{RZ}_F\'', 'adapted', 31, 'Definition 3.4.62.', 'checked', 66),
(63, 'Satz 3.4.22', 50, 'Existenz einer dynamischen Raum-Zeit-Struktur', 'Existiert ein kohärenzerhaltender Dynamikoperator, dann existiert eine dynamische Erweiterung der funktionalen Raum-Zeit-Struktur.', '\\mathfrak{RZ}_F\\Rightarrow\\mathfrak{RZ}_F^{dyn}', '\\mathfrak{RZ}_F\\Rightarrow\\mathfrak{RZ}_F^{dyn}', 'original', NULL, 'Definition 3.4.67.', 'checked', 69),
(64, 'Satz 3.4.23', 50, 'Stabilität durch funktionale Attraktoren', 'Besitzt eine funktionale Dynamik einen Attraktor, können unterschiedliche Anfangszustände dieselbe funktionale Organisation erreichen.', '\\mathcal D_F^n(z_F)\\rightarrow\\mathcal A_F', '\\mathcal D_F^n(z_F)\\rightarrow\\mathcal A_F', 'original', NULL, 'Definition 3.4.70.', 'checked', 70),
(65, 'Satz 3.4.24', 50, 'Übergang zwischen funktionalen Attraktoren', 'Nach Überschreiten eines Kipppunktes kann eine Dynamik von einem Attraktor zu einem anderen übergehen.', '\\mathcal A_F^{(1)}\\rightarrow\\mathcal A_F^{(2)}', '\\mathcal A_F^{(1)}\\rightarrow\\mathcal A_F^{(2)}', 'original', NULL, 'Definition 3.4.74.', 'checked', 71),
(66, 'Satz 3.4.25', 50, 'Emergenz durch funktionale Rekonfiguration', 'Gekoppelte kohärente Strukturen können eine neue stabile Organisationsebene erzeugen.', '\\exists\\mathcal E_F^{new}', '\\exists\\mathcal E_F^{new}', 'original', NULL, 'Stabile Kopplung.', 'checked', 72),
(67, 'Satz 3.4.27', 50, 'Funktionale Raum-Zeit als Organisationsprinzip', 'Eine funktionale Raum-Zeit-Struktur mit kohärenzerhaltendem Dynamikoperator bildet ein geschlossenes Organisationssystem.', '\\mathfrak{FRZ}_F+\\mathcal D_F\\Rightarrow\\mathcal O_F^{global}', '\\mathfrak{FRZ}_F+\\mathcal D_F\\Rightarrow\\mathcal O_F^{global}', 'original', NULL, 'Dynamikoperator und funktionale Raum-Zeit-Struktur vorhanden.', 'checked', 73);
